do -- 00_kernel.lua
-- ============================================================================
--  00 kernel   services, ownership, signals, error boundaries, files, helpers
-- ============================================================================
local genv = (type(getgenv) == "function" and getgenv()) or _G
B.genv = genv

-- A second execution replaces the first: the old hub unloads itself completely.
if type(genv.BASED) == "table" and type(genv.BASED.unload) == "function" then
  pcall(genv.BASED.unload, true)
end
genv.BASED = B
B.alive = true
B.bootClock = os.clock()

local cloneref = type(cloneref) == "function" and cloneref or function(x) return x end
B.cloneref = cloneref
B.S = setmetatable({}, { __index = function(t, name)
  local ok, service = pcall(game.GetService, game, name)
  if not ok or not service then error("BASED: no service " .. tostring(name), 2) end
  service = cloneref(service)
  rawset(t, name, service)
  return service
end })
local S = B.S
B.LP = S.Players.LocalPlayer

-- ---------------------------------------------------------------- signals
local Signal = {}
Signal.__index = Signal
function Signal.new() return setmetatable({ list = {} }, Signal) end
function Signal:connect(fn)
  local link = { fn = fn, live = true }
  local list = self.list
  list[#list + 1] = link
  return { disconnect = function()
    if not link.live then return end
    link.live = false
    local at = table.find(list, link)
    if at then table.remove(list, at) end
  end }
end
function Signal:fire(...)
  local list = self.list
  if #list == 0 then return end
  for _, link in ipairs(table.clone(list)) do
    if link.live then B.try("signal", link.fn, ...) end
  end
end
B.Signal = Signal

-- ---------------------------------------------------------------- faults
-- Everything user-facing runs inside B.try: a failing feature logs here and the
-- rest of the hub keeps running. Settings > About shows this list.
B.faults = {}
B.onFault = Signal.new()
local lastFault = {}
function B.fault(scope, err)
  scope = tostring(scope)
  -- something failing every frame must not flood the log: one entry a second per scope
  local now = os.clock()
  local previous = lastFault[scope]
  if previous and now - previous.at < 1 then previous.entry.repeats = (previous.entry.repeats or 0) + 1; return end
  local entry = { scope = scope, message = tostring(err), at = now - B.bootClock }
  lastFault[scope] = { at = now, entry = entry }
  local faults = B.faults
  faults[#faults + 1] = entry
  if #faults > 60 then table.remove(faults, 1) end
  warn("[BASED] " .. entry.scope .. ": " .. entry.message)
  if B.onFault and #B.onFault.list > 0 then
    for _, link in ipairs(table.clone(B.onFault.list)) do pcall(link.fn, entry) end
  end
end
local function trace(e) return tostring(e) .. "\n" .. debug.traceback("", 2) end
function B.try(scope, fn, ...)
  local result = table.pack(xpcall(fn, trace, ...))
  if not result[1] then B.fault(scope, result[2]); return nil end
  return table.unpack(result, 2, result.n)
end
function B.safe(scope, fn)
  return function(...) return B.try(scope, fn, ...) end
end
-- Potassium: calling into game modules drops the thread's Plugin capability and
-- every gethui instance then throws. Callbacks the game invokes call this first.
function B.identity()
  if type(setthreadidentity) == "function" then pcall(setthreadidentity, 8) end
end

-- ---------------------------------------------------------------- ownership
local owned = {}
function B.own(thing)
  owned[#owned + 1] = thing
  return thing
end
-- What every hooked function costs, by name, while measuring (B.measure): nil the rest of the time,
-- and then a hook costs one look at it. Read with B.measure(seconds) -> lines, worst first.
B.prof = nil
local function charge(scope, seconds)
  local prof = B.prof
  if not prof then return end
  local entry = prof[scope]
  if not entry then entry = { 0, 0, 0 }; prof[scope] = entry end
  entry[1] += seconds
  entry[2] += 1
  if seconds > entry[3] then entry[3] = seconds end
end
B.charge = charge
function B.connect(signal, fn, scope)
  scope = scope or "event"
  local safe = B.safe(scope, fn)
  return B.own(signal:Connect(function(...)
    if not B.prof then return safe(...) end
    local started = os.clock()
    safe(...)
    charge(scope, os.clock() - started)
  end))
end
function B.measure(seconds)
  B.prof = {}
  local frames, started = 0, os.clock()
  local counter = S.RunService.Heartbeat:Connect(function() frames += 1 end)
  task.wait(seconds or 5)
  counter:Disconnect()
  local prof, span = B.prof, os.clock() - started
  B.prof = nil
  local rows = {}
  for scope, entry in pairs(prof) do rows[#rows + 1] = { scope, entry[1], entry[2], entry[3] } end
  table.sort(rows, function(a, b) return a[2] > b[2] end)
  local out = { string.format("%d frames in %.1f s (%.0f fps)", frames, span, frames / math.max(span, 1e-3)) }
  for _, row in ipairs(rows) do
    out[#out + 1] = string.format("%-28s %6.3f ms/frame  %6d calls  worst %.2f ms", row[1], row[2] * 1000 / math.max(frames, 1), row[3], row[4] * 1000)
  end
  return out
end
B.onUnload = Signal.new()
function B.unload()
  if not B.alive then return end
  B.alive = false
  pcall(function() B.onUnload:fire() end)
  for index = #owned, 1, -1 do
    local thing = owned[index]
    pcall(function()
      local kind = typeof(thing)
      if kind == "RBXScriptConnection" then thing:Disconnect()
      elseif kind == "Instance" then thing:Destroy()
      elseif kind == "function" then thing()
      elseif kind == "table" and type(thing.destroy) == "function" then thing:destroy() end
    end)
  end
  table.clear(owned)
  if genv.BASED == B then genv.BASED = nil end
end

-- ---------------------------------------------------------------- files
local fs = { root = "BasedHub" }
fs.ok = type(writefile) == "function" and type(readfile) == "function" and type(isfile) == "function"
  and type(makefolder) == "function" and type(isfolder) == "function"
function fs.path(relative) return fs.root .. "/" .. relative end
function fs.exists(path)
  if not fs.ok then return false end
  local ok, present = pcall(isfile, path)
  return ok and present == true
end
function fs.isdir(path)
  if not fs.ok then return false end
  local ok, present = pcall(isfolder, path)
  return ok and present == true
end
function fs.mkdir(path)
  if not fs.ok then return false end
  local built = ""
  for part in string.gmatch(path, "[^/\\]+") do
    built = built == "" and part or (built .. "/" .. part)
    if not fs.isdir(built) then pcall(makefolder, built) end
  end
  return fs.isdir(path)
end
function fs.read(path)
  if not fs.exists(path) then return nil end
  local ok, data = pcall(readfile, path)
  return ok and data or nil
end
function fs.write(path, data)
  if not fs.ok then return false end
  local folder = string.match(path, "^(.*)[/\\][^/\\]+$")
  if folder and not fs.isdir(folder) then fs.mkdir(folder) end
  local ok = pcall(writefile, path, data)
  return ok
end
function fs.remove(path)
  if type(delfile) ~= "function" or not fs.exists(path) then return false end
  return (pcall(delfile, path))
end
function fs.list(path)
  if type(listfiles) ~= "function" or not fs.isdir(path) then return {} end
  local ok, files = pcall(listfiles, path)
  if not ok or type(files) ~= "table" then return {} end
  local out = {}
  for _, file in ipairs(files) do out[#out + 1] = (string.gsub(tostring(file), "\\", "/")) end
  table.sort(out)
  return out
end
function fs.readJson(path)
  local data = fs.read(path)
  if not data or data == "" then return nil end
  local ok, value = pcall(S.HttpService.JSONDecode, S.HttpService, data)
  return ok and value or nil
end
function fs.writeJson(path, value)
  local ok, data = pcall(S.HttpService.JSONEncode, S.HttpService, value)
  return ok and fs.write(path, data) or false
end
B.fs = fs

-- ---------------------------------------------------------------- helpers
local util = {}
function util.clamp01(x) return x < 0 and 0 or (x > 1 and 1 or x) end
function util.lerp(a, b, t) return a + (b - a) * t end
function util.map(x, a, b, c, d, clamp)
  local t = (x - a) / (b - a)
  if clamp then t = util.clamp01(t) end
  return c + (d - c) * t
end
function util.round(x, step)
  step = step or 1
  return math.floor(x / step + 0.5) * step
end
function util.hex(text)
  text = string.gsub(text, "#", "")
  return Color3.fromRGB(tonumber(string.sub(text, 1, 2), 16), tonumber(string.sub(text, 3, 4), 16), tonumber(string.sub(text, 5, 6), 16))
end
function util.toHex(color)
  return string.format("%02X%02X%02X", math.floor(color.R * 255 + 0.5), math.floor(color.G * 255 + 0.5), math.floor(color.B * 255 + 0.5))
end
function util.luma(color) return 0.2126 * color.R + 0.7152 * color.G + 0.0722 * color.B end
function util.mix(a, b, t) return a:Lerp(b, t) end
function util.format(value, decimals)
  if decimals and decimals > 0 then return string.format("%." .. decimals .. "f", value) end
  return tostring(math.floor(value + 0.5))
end
function util.comma(n)
  local text = tostring(math.floor(n))
  local out = string.reverse((string.gsub(string.reverse(text), "(%d%d%d)", "%1,")))
  return (string.gsub(out, "^,", ""))
end
function util.copy(value)
  if type(value) ~= "table" then return value end
  local out = {}
  for k, v in pairs(value) do out[k] = util.copy(v) end
  return out
end
function util.keys(t)
  local out = {}
  for k in pairs(t) do out[#out + 1] = k end
  return out
end
-- Cheap fuzzy score for the command palette: every query character must appear
-- in order; contiguous runs and word starts score higher. nil = no match.
function util.fuzzy(query, text)
  query, text = string.lower(query), string.lower(text)
  if query == "" then return 0 end
  local score, at, run = 0, 1, 0
  for i = 1, #query do
    local ch = string.sub(query, i, i)
    local found = string.find(text, ch, at, true)
    if not found then return nil end
    if found == at then run += 1; score += 2 + run else run = 0 end
    if found == 1 or string.find(string.sub(text, found - 1, found - 1), "[%s%p]") then score += 3 end
    score -= (found - at) * 0.05
    at = found + 1
  end
  return score - #text * 0.01
end
function util.debounce(seconds, fn)
  local token = 0
  return function(...)
    token += 1
    local mine = token
    local args = table.pack(...)
    task.delay(seconds, function()
      if mine == token and B.alive then B.try("debounce", fn, table.unpack(args, 1, args.n)) end
    end)
  end
end
-- A ray from one point to another, however far apart. Measured on the client: one ray finds
-- nothing more than 15,000 studs away however long it is asked to be, and says so with nil, not
-- an error. So a long one is cast in lengths the engine can see along. nil means the way is
-- clear (or, past `lengths` of them, further than it is worth looking).
local RAY_REACH = 14000
function util.ray(from, to, params, lengths)
  local offset = to - from
  local distance = offset.Magnitude
  if distance <= RAY_REACH then return workspace:Raycast(from, offset, params) end
  local unit = offset / distance
  local at = 0
  for _ = 1, lengths or 8 do
    local reach = math.min(RAY_REACH, distance - at)
    local hit = workspace:Raycast(from + unit * at, unit * reach, params)
    if hit then return hit end
    at += reach
    if at >= distance - 0.01 then break end
  end
  return nil
end
util.RAY_REACH = RAY_REACH
-- a distance for a label: whole studs with a comma, then thousands, then millions
function util.studs(distance)
  if distance >= 99.95e6 then return string.format("%.0fM", distance / 1e6) end
  if distance >= 999500 then return string.format("%.1fM", distance / 1e6) end
  if distance >= 99950 then return string.format("%.0fk", distance / 1000) end
  if distance >= 9995 then return string.format("%.1fk", distance / 1000) end
  return util.comma(distance + 0.5)
end
function util.randomName()
  local chars = {}
  for i = 1, 12 do chars[i] = string.char(math.random(97, 122)) end
  return table.concat(chars)
end
B.util = util

-- ---------------------------------------------------------------- environment
function B.camera() return workspace.CurrentCamera end
function B.viewport()
  local camera = workspace.CurrentCamera
  return camera and camera.ViewportSize or Vector2.new(1920, 1080)
end
function B.character(player)
  player = player or B.LP
  return player and player.Character
end
function B.humanoid(player)
  local character = B.character(player)
  return character and character:FindFirstChildOfClass("Humanoid")
end
function B.root(player)
  local character = B.character(player)
  if not character then return nil end
  return character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
end
function B.clipboard(text)
  local set = (type(setclipboard) == "function" and setclipboard) or (type(toclipboard) == "function" and toclipboard)
  if not set then return false end
  return (pcall(set, tostring(text)))
end
B.executor = "Unknown"
pcall(function()
  if type(identifyexecutor) == "function" then B.executor = tostring((identifyexecutor())) end
end)
B.touch = false
pcall(function() B.touch = S.UserInputService.TouchEnabled and not S.UserInputService.MouseEnabled end)

-- The GUI parent: the executor's hidden container when it has one.
function B.host()
  if B._host and B._host.Parent then return B._host end
  local host
  if type(gethui) == "function" then
    local ok, hidden = pcall(gethui)
    if ok and typeof(hidden) == "Instance" then host = hidden end
  end
  if not host then
    local ok, core = pcall(function() return cloneref(game:GetService("CoreGui")) end)
    if ok and core and pcall(function() return core.Name end) then host = core end
  end
  if not host and B.LP then host = B.LP:FindFirstChildOfClass("PlayerGui") or B.LP:WaitForChild("PlayerGui", 5) end
  B._host = host
  return host
end
B.screens = {}
function B.screen(order, name)
  local gui = Instance.new("ScreenGui")
  table.insert(B.screens, gui)
  gui.Name = name or util.randomName()
  gui.ResetOnSpawn = false
  gui.IgnoreGuiInset = true
  gui.ZIndexBehavior = Enum.ZIndexBehavior.Sibling
  gui.DisplayOrder = order or 9000
  pcall(function() gui.ScreenInsets = Enum.ScreenInsets.None end)
  pcall(function() gui.ClipToDeviceSafeArea = false end)
  gui.Parent = B.host()
  return B.own(gui)
end
end
do -- 01_motion.lua
-- ============================================================================
--  01 motion   one render loop: analytic springs, timelines, jobs
--
--  Springs are described the way SwiftUI does it: a duration (how long the move
--  feels) and a bounce (0 = critically damped, 0.3 = lively). They are solved in
--  closed form, so a 20 fps hitch and a 240 fps frame land on the same curve and
--  nothing ever explodes. A spring at rest is removed from the loop: an idle hub
--  costs one empty table scan per frame.
-- ============================================================================
local S, util = B.S, B.util
local Motion = { speed = 1, reduced = false, frame = 0, dt = 1 / 60, smoothDt = 1 / 60, now = os.clock() }
B.Motion = Motion

Motion.presets = {
  quick  = { 0.16, 0 },     -- hover tints, tiny state changes
  snappy = { 0.24, 0.10 },  -- presses, toggles
  smooth = { 0.34, 0 },     -- panels, pages
  gentle = { 0.52, 0 },     -- large surfaces
  bouncy = { 0.40, 0.24 },  -- things that should feel alive
  liquid = { 0.46, 0.30 },  -- the trailing edge of a moving pill
  lazy   = { 0.90, 0 },     -- ambient drift
}

local awake = {}       -- springs that are moving
local stepping = {}    -- the ones being stepped this frame, in a list of their own (see the loop)
local jobs = {}        -- per-frame callbacks
local tweens = {}      -- fixed-duration timelines

-- ---------------------------------------------------------------- springs
local Spring = {}
Spring.__index = Spring

local function tune(spring, preset)
  local p = type(preset) == "table" and preset or Motion.presets[preset or "smooth"] or Motion.presets.smooth
  local duration, bounce = p[1], p[2] or 0
  if Motion.reduced then duration, bounce = duration * 0.55, 0 end
  duration = math.max(duration / Motion.speed, 0.02)
  spring.w0 = 2 * math.pi / duration
  spring.zeta = math.clamp(1 - bounce, 0.08, 1)
end

function Motion.spring(n, preset, onStep, eps)
  local spring = setmetatable({ n = n, x = table.create(n, 0), v = table.create(n, 0), g = table.create(n, 0),
    onStep = onStep, eps = eps or 0.001 }, Spring)
  tune(spring, preset)
  return spring
end
function Spring:snap(values)
  for i = 1, self.n do self.x[i], self.g[i], self.v[i] = values[i], values[i], 0 end
  awake[self] = nil
  if self.onStep then self.onStep(self.x) end
end
function Spring:to(values, preset)
  if preset then tune(self, preset) end
  local g = self.g
  for i = 1, self.n do g[i] = values[i] end
  awake[self] = true
end
function Spring:impulse(index, velocity)
  self.v[index] += velocity
  awake[self] = true
end
function Spring:moving() return awake[self] == true end
function Spring:stop() awake[self] = nil end

local function stepSpring(spring, dt)
  local w0, zeta, eps = spring.w0, spring.zeta, spring.eps
  local x, v, g = spring.x, spring.v, spring.g
  local rest = true
  if zeta < 0.999 then
    local wd = w0 * math.sqrt(1 - zeta * zeta)
    local decay = math.exp(-zeta * w0 * dt)
    local c, s = math.cos(wd * dt), math.sin(wd * dt)
    for i = 1, spring.n do
      local a = x[i] - g[i]
      local b = (v[i] + zeta * w0 * a) / wd
      local y = decay * (a * c + b * s)
      local nv = decay * ((b * wd - a * zeta * w0) * c - (a * wd + b * zeta * w0) * s)
      x[i], v[i] = g[i] + y, nv
      local tolerance = type(eps) == "table" and eps[i] or eps
      if rest and (math.abs(y) > tolerance or math.abs(nv) > tolerance * 20) then rest = false end
    end
  else
    local decay = math.exp(-w0 * dt)
    for i = 1, spring.n do
      local a = x[i] - g[i]
      local k = v[i] + w0 * a
      local y = decay * (a + k * dt)
      local nv = decay * (v[i] - k * w0 * dt)
      x[i], v[i] = g[i] + y, nv
      local tolerance = type(eps) == "table" and eps[i] or eps
      if rest and (math.abs(y) > tolerance or math.abs(nv) > tolerance * 20) then rest = false end
    end
  end
  if rest then
    for i = 1, spring.n do x[i], v[i] = g[i], 0 end
    awake[spring] = nil
  end
  if spring.onStep then spring.onStep(x) end
  if rest and spring.onRest then
    local done = spring.onRest
    spring.onRest = nil
    done()
  end
end

-- ---------------------------------------------------------------- properties
local PX, UNIT = 0.08, 0.0008
local packers = {
  number = { 1, function(value) return { value } end, function(x) return x[1] end, UNIT },
  UDim2 = { 4, function(value) return { value.X.Scale, value.X.Offset, value.Y.Scale, value.Y.Offset } end,
    function(x) return UDim2.new(x[1], x[2], x[3], x[4]) end, { UNIT, PX, UNIT, PX } },
  UDim = { 2, function(value) return { value.Scale, value.Offset } end, function(x) return UDim.new(x[1], x[2]) end, { UNIT, PX } },
  Vector2 = { 2, function(value) return { value.X, value.Y } end, function(x) return Vector2.new(x[1], x[2]) end, UNIT },
  Vector3 = { 3, function(value) return { value.X, value.Y, value.Z } end, function(x) return Vector3.new(x[1], x[2], x[3]) end, UNIT },
  Color3 = { 3, function(value) return { value.R, value.G, value.B } end,
    function(x) return Color3.new(util.clamp01(x[1]), util.clamp01(x[2]), util.clamp01(x[3])) end, 0.002 },
}
-- Properties that must stay inside 0..1: a bouncy spring overshoots, the engine rejects it.
local unitProps = { BackgroundTransparency = true, TextTransparency = true, ImageTransparency = true, Transparency = true,
  GroupTransparency = true, TextStrokeTransparency = true, ScrollBarImageTransparency = true, FillTransparency = true,
  OutlineTransparency = true }

local bound = setmetatable({}, { __mode = "k" })
-- Spring `instance[property]` toward `target`. The spring is kept per
-- (instance, property) and re-aimed in flight, so interrupted motion never jumps.
function Motion.to(instance, property, target, preset, done)
  local packer = packers[typeof(target)]
  if not packer then instance[property] = target; if done then done() end; return nil end
  local map = bound[instance]
  if not map then map = {}; bound[instance] = map end
  local spring = map[property]
  if not spring then
    local unpack, clampUnit = packer[3], unitProps[property]
    spring = Motion.spring(packer[1], preset, function(x)
      local value = unpack(x)
      if clampUnit then value = util.clamp01(value) end
      instance[property] = value
    end, packer[4])
    local current = packer[2](instance[property])
    for i = 1, spring.n do spring.x[i], spring.g[i] = current[i], current[i] end
    map[property] = spring
  end
  spring.onRest = done
  spring:to(packer[2](target), preset)
  return spring
end
function Motion.snap(instance, property, value)
  local map = bound[instance]
  local spring = map and map[property]
  local packer = packers[typeof(value)]
  if spring and packer then
    spring.onRest = nil
    spring:snap(packer[2](value))
  else
    instance[property] = value
  end
end
function Motion.kick(instance, property, index, velocity)
  local map = bound[instance]
  local spring = map and map[property]
  if spring then spring:impulse(index or 1, velocity) end
end
function Motion.target(instance, property)
  local map = bound[instance]
  local spring = map and map[property]
  if not spring then return instance[property] end
  local packer = packers[typeof(instance[property])]
  return packer and packer[3](spring.g) or instance[property]
end

-- ---------------------------------------------------------------- easing + timelines
local ease = {}
function ease.linear(t) return t end
function ease.outCubic(t) return 1 - (1 - t) ^ 3 end
function ease.inCubic(t) return t * t * t end
function ease.inOutCubic(t) return t < 0.5 and 4 * t * t * t or 1 - (-2 * t + 2) ^ 3 / 2 end
function ease.outQuint(t) return 1 - (1 - t) ^ 5 end
function ease.inOutQuint(t) return t < 0.5 and 16 * t ^ 5 or 1 - (-2 * t + 2) ^ 5 / 2 end
function ease.outExpo(t) return t >= 1 and 1 or 1 - 2 ^ (-10 * t) end
function ease.inExpo(t) return t <= 0 and 0 or 2 ^ (10 * t - 10) end
function ease.outBack(t) local c = 1.70158; return 1 + (c + 1) * (t - 1) ^ 3 + c * (t - 1) ^ 2 end
function ease.outSine(t) return math.sin(t * math.pi / 2) end
Motion.ease = ease
-- progress of `t` through the window [from, from + length], eased and clamped
function Motion.window(t, from, length, curve)
  local p = util.clamp01((t - from) / length)
  return curve and curve(p) or p
end

function Motion.tween(duration, curve, step, done)
  local tween = { t = 0, duration = math.max(duration / Motion.speed, 0.001), curve = curve or ease.outCubic, step = step, done = done }
  if Motion.reduced then tween.duration *= 0.5 end
  tweens[#tweens + 1] = tween
  function tween.cancel() tween.dead = true end
  step(tween.curve(0))
  return tween
end

-- ---------------------------------------------------------------- jobs
-- fn(elapsed) every frame, or at `hz` with the time since it last ran.
function Motion.every(fn, hz, scope)
  local job = { fn = fn, interval = hz and 1 / hz or 0, acc = 0, scope = scope or "job" }
  jobs[#jobs + 1] = job
  function job.cancel() job.dead = true end
  return job
end
function Motion.after(seconds, fn, scope)
  local job
  local left = seconds
  job = Motion.every(function(dt)
    left -= dt
    if left <= 0 then job.dead = true; fn() end
  end, nil, scope or "after")
  return job
end

-- ---------------------------------------------------------------- the loop
Motion.stats = { springs = 0, jobs = 0, ms = 0 }
local function frame(dt)
  if not B.alive then return end
  local started = os.clock()
  dt = math.min(dt, 0.1)
  Motion.frame += 1
  Motion.dt = dt
  Motion.smoothDt += (dt - Motion.smoothDt) * 0.08
  Motion.now = started

  -- A spring's step runs code that may start other springs, and a table cannot be given new keys
  -- while it is being walked ("invalid key to 'next'", one frame in thousands): so this frame's
  -- springs are listed first. One started during the frame is stepped from the next; one put to
  -- rest by another before its turn is left alone.
  local measuring = B.prof ~= nil
  local springCount = 0
  for spring in pairs(awake) do
    springCount += 1
    stepping[springCount] = spring
  end
  for index = 1, springCount do
    local spring = stepping[index]
    stepping[index] = nil
    if awake[spring] then
      local ok, err = pcall(stepSpring, spring, dt)
      if not ok then awake[spring] = nil; B.fault("spring", err) end
    end
  end

  local mark = measuring and os.clock()
  if measuring then B.charge("motion.springs", mark - started) end
  local count = #tweens
  if count > 0 then
    for index = count, 1, -1 do
      local tween = tweens[index]
      if tween.dead then
        table.remove(tweens, index)
      else
        tween.t += dt
        local p = util.clamp01(tween.t / tween.duration)
        local ok, err = pcall(tween.step, tween.curve(p))
        if not ok then tween.dead = true; B.fault("tween", err) end
        if p >= 1 and not tween.dead then
          tween.dead = true
          table.remove(tweens, index)
          if tween.done then B.try("tween.done", tween.done) end
        end
      end
    end
  end

  if measuring then B.charge("motion.tweens", os.clock() - mark) end
  count = #jobs
  if count > 0 then
    for index = 1, count do
      local job = jobs[index]
      if job and not job.dead then
        local elapsed = dt
        local run = true
        if job.interval > 0 then
          job.acc += dt
          if job.acc < job.interval then run = false else elapsed = math.min(job.acc, 0.5); job.acc = 0 end
        end
        if run then
          local before = measuring and os.clock()
          local ok, err = pcall(job.fn, elapsed)
          if not ok then job.dead = true; B.fault(job.scope, err) end
          if measuring then B.charge("job." .. job.scope, os.clock() - before) end
        end
      end
    end
    for index = #jobs, 1, -1 do
      if jobs[index].dead then table.remove(jobs, index) end
    end
  end
  local stats = Motion.stats
  stats.springs, stats.jobs, stats.ms = springCount, #jobs, (os.clock() - started) * 1000
end
B.own(S.RunService.RenderStepped:Connect(frame))
Motion._frame = frame
end
do -- 02_theme.lua
-- ============================================================================
--  02 theme    tokens, live bindings
--
--  Surfaces are not solid colours: every fill is the scheme's ink at a low alpha
--  laid over glass, so one set of numbers works on a dark, a black and a light
--  scheme. B.T holds the resolved values; Theme.bind keeps an instance property
--  in step with a token, so accent, scheme and the glass slider all change the
--  whole hub live without rebuilding anything.
-- ============================================================================
local util = B.util
local hex = util.hex
local Theme = { changed = B.Signal.new() }
B.Theme = Theme
local T = {}
B.T = T

Theme.schemes = {
  dark = { label = "Graphite", base = hex("0B0B0F"), ink = hex("F5F4EF"), sub = hex("A9A8B4"), faint = hex("6C6B77"),
    shadow = 0.42, fill = { 0.045, 0.075, 0.115 }, stroke = { 0.085, 0.16 }, dark = true },
  midnight = { label = "Midnight", base = hex("000000"), ink = hex("F5F4EF"), sub = hex("9E9DA9"), faint = hex("62616C"),
    shadow = 0.3, fill = { 0.055, 0.09, 0.13 }, stroke = { 0.10, 0.18 }, dark = true },
  light = { label = "Porcelain", base = hex("F3F2EE"), ink = hex("121216"), sub = hex("56555F"), faint = hex("8C8B95"),
    shadow = 0.72, fill = { 0.05, 0.08, 0.12 }, stroke = { 0.10, 0.18 }, dark = false },
}
Theme.schemeOrder = { "dark", "midnight", "light" }
Theme.accents = {
  { id = "ultraviolet", label = "Ultraviolet", color = hex("8E7DFF") },
  { id = "azure", label = "Azure", color = hex("4DA3FF") },
  { id = "mint", label = "Mint", color = hex("45DDA8") },
  { id = "ember", label = "Ember", color = hex("FF7A45") },
  { id = "rose", label = "Rose", color = hex("FF5C93") },
  { id = "gold", label = "Gold", color = hex("F2C14E") },
  { id = "blood", label = "Blood", color = hex("FF4B4B") },
  { id = "bone", label = "Bone", color = hex("EDEBE4") },
}

Theme.state = { scheme = "dark", accent = hex("8E7DFF"), glass = 0.6, radius = 1, blur = false }

-- type ramp: font key (resolved in B.F by 03 assets) and size in design px
Theme.type = {
  display = { "serifItalic", 34 },
  title = { "serif", 25 },
  heading = { "text600", 15 },
  label = { "text500", 14 },
  body = { "text400", 13 },
  caption = { "text400", 12 },
  eyebrow = { "wideBold", 10 },
  mono = { "mono400", 12 },
  monoBold = { "mono500", 12 },
  button = { "text600", 13 },
  brand = { "wideBlack", 18 },
}

local function resolve()
  local state = Theme.state
  local scheme = Theme.schemes[state.scheme] or Theme.schemes.dark
  local glass = util.clamp01(state.glass)
  T.dark = scheme.dark
  T.base, T.ink, T.sub, T.faint = scheme.base, scheme.ink, scheme.sub, scheme.faint
  -- the iOS 27 control: clear glass at 0, tinted glass at 1. Without real blur
  -- behind it a clear panel is unreadable, so the range tightens.
  local alpha = state.blur and util.lerp(0.5, 0.94, glass) or util.lerp(0.84, 0.975, glass)
  T.baseA = 1 - alpha
  T.panelA = 1 - util.lerp(0.34, 0.62, glass)       -- inner panels: sidebar, popovers
  T.fill1A, T.fill2A, T.fill3A = 1 - scheme.fill[1], 1 - scheme.fill[2], 1 - scheme.fill[3]
  T.strokeA, T.stroke2A = 1 - scheme.stroke[1], 1 - scheme.stroke[2]
  T.shadowA = scheme.shadow
  T.accent = state.accent
  T.accentInk = util.luma(state.accent) > 0.62 and hex("101014") or hex("FFFFFF")
  T.accentSoftA = 0.84
  T.accentDim = state.accent:Lerp(scheme.base, 0.55)
  T.ok, T.warn, T.bad = hex("52D6A0"), hex("F4B45F"), hex("FF6577")
  T.white, T.black = Color3.new(1, 1, 1), Color3.new(0, 0, 0)
  T.rim = scheme.dark and Color3.new(1, 1, 1) or Color3.new(1, 1, 1)
  T.rimA = scheme.dark and 0.5 or 0.1
  T.popover = scheme.base:Lerp(scheme.ink, scheme.dark and 0.07 or 0.0)
  local r = state.radius
  T.rWindow, T.rPanel, T.rCard, T.rControl, T.rSmall = math.floor(26 * r), math.floor(19 * r), math.floor(16 * r), math.floor(11 * r), math.floor(7 * r)
end
resolve()

-- Strong references on purpose. A weak-keyed table of Instances loses entries whenever Lua holds
-- no other reference to that instance's wrapper, even though the instance is alive in the game:
-- measured as labels that kept their dark-scheme colour after switching to the light scheme.
-- Destroyed instances are swept out instead (their Parent is nil for good).
local bindings = {}
local boundAt = {}
-- Keep instance[property] equal to token `key` (optionally through `map`).
function Theme.bind(instance, property, key, map)
  local list = bindings[instance]
  if not list then list = {}; bindings[instance] = list; boundAt[instance] = os.clock() end
  list[property] = { key, map }
  local value = T[key]
  if map then value = map(value, T) end
  instance[property] = value
  return instance
end
function Theme.unbind(instance, property)
  local list = bindings[instance]
  if list then list[property] = nil end
end
-- forget instances that were destroyed (not ones still being assembled)
function Theme.sweep()
  local now = os.clock()
  for instance in pairs(bindings) do
    if instance.Parent == nil and now - boundAt[instance] > 5 then
      bindings[instance], boundAt[instance] = nil, nil
    end
  end
end
function Theme.apply()
  resolve()
  Theme.sweep()
  for instance, list in pairs(bindings) do
    for property, binding in pairs(list) do
      local value = T[binding[1]]
      if binding[2] then value = binding[2](value, T) end
      pcall(function() instance[property] = value end)
    end
  end
  Theme.changed:fire()
end
B.Motion.every(Theme.sweep, 1 / 20, "theme.sweep")
function Theme.set(changes)
  local state = Theme.state
  for key, value in pairs(changes) do state[key] = value end
  Theme.apply()
end
function Theme.corner(key) return UDim.new(0, T[key] or 10) end
end
do -- 03_assets.lua
-- ============================================================================
--  03 assets   files on disk -> content ids, fonts, icons, sounds
--
--  Measured on Potassium (2026-10-06): getcustomasset costs 3-5 ms per call on
--  the main thread whatever the file size, the files it copies stay in the
--  client's content folder between sessions, and the id is always
--  <prefix>/<basename>. So a file is registered ONCE, ever; after that its id is
--  built by hand for free. A sentinel is checked at boot because a client update
--  can empty that folder.
-- ============================================================================
local S, fs, util = B.S, B.fs, B.util
local Assets = { ready = false, lite = false, calls = 0 }
B.Assets = Assets
local manifest = B.MANIFEST or { files = {}, icons = { map = {} } }
Assets.manifest = manifest

local canRegister = type(getcustomasset) == "function" and fs.ok
local REGISTRY = fs.path("cache/registry.json")
local registry = { files = {}, seq = {} }
local ids = {}            -- relative path -> content id, or false when unavailable
local seqIds = {}         -- sequence prefix -> { [index] = id }
local seqKnown = {}       -- sequence prefix -> { [index] = true } registered in an earlier session
local dirty = false

local function basename(path) return string.match(path, "[^/\\]+$") or path end
local function prefixOf(id) return string.match(id, "^(rbxasset://[^/]+/)") end

local saveSoon = util.debounce(1.5, function()
  if not dirty then return end
  dirty = false
  local seq = {}
  for key, known in pairs(seqKnown) do
    -- compress the registered indices into [from, to] runs
    local runs, from, last = {}, nil, nil
    local indices = util.keys(known)
    table.sort(indices)
    for _, index in ipairs(indices) do
      if from and index == last + 1 then last = index
      else
        if from then runs[#runs + 1] = { from, last } end
        from, last = index, index
      end
    end
    if from then runs[#runs + 1] = { from, last } end
    seq[key] = runs
  end
  fs.writeJson(REGISTRY, { prefix = registry.prefix, sentinel = registry.sentinel, files = registry.files, seq = seq })
end)
local function touch() dirty = true; saveSoon() end

local function register(path)
  Assets.calls += 1
  local ok, id = pcall(getcustomasset, path)
  if not ok or type(id) ~= "string" or id == "" then return nil end
  local prefix = prefixOf(id)
  if prefix and registry.prefix ~= prefix then
    -- a different content folder: nothing registered before is reachable
    registry.prefix = prefix
    registry.files = {}
    table.clear(seqKnown)
  end
  return id
end

-- Content id for a file under BasedHub/, or nil when it is not installed.
function Assets.id(relative)
  local cached = ids[relative]
  if cached ~= nil then return cached or nil end
  if not canRegister then ids[relative] = false; return nil end
  local name = basename(relative)
  local stamp = manifest.files[relative] or "x"
  local id
  if registry.prefix and registry.files[name] == stamp then
    id = registry.prefix .. name
  else
    id = register(fs.path(relative))
    if id then
      registry.files[name] = stamp
      -- the sentinel must be something PreloadAsync can load and report on: an image
      if string.match(name, "%.png$") or string.match(name, "%.jpg$") then registry.sentinel = name end
      touch()
    end
  end
  ids[relative] = id or false
  return id
end

-- Content id for frame `index` of a numbered sequence ("film/hd/bhf1_h_", 4 digits).
function Assets.frame(pathPrefix, index, digits, extension)
  local cache = seqIds[pathPrefix]
  if not cache then cache = {}; seqIds[pathPrefix] = cache end
  local id = cache[index]
  if id ~= nil then return id or nil end
  if not canRegister then return nil end
  local file = pathPrefix .. string.format("%0" .. (digits or 4) .. "d", index) .. (extension or ".jpg")
  local known = seqKnown[pathPrefix]
  if known and known[index] and registry.prefix then
    id = registry.prefix .. basename(file)
  else
    id = register(fs.path(file))
    if id then
      if not known then known = {}; seqKnown[pathPrefix] = known end
      known[index] = true
      touch()
    end
  end
  cache[index] = id or false
  return id
end
-- true when frame `index` can be had without a getcustomasset call
function Assets.frameIsFree(pathPrefix, index)
  local cache = seqIds[pathPrefix]
  if cache and cache[index] then return true end
  local known = seqKnown[pathPrefix]
  return known ~= nil and known[index] == true and registry.prefix ~= nil
end

function Assets.has(relative) return fs.exists(fs.path(relative)) end

-- ---------------------------------------------------------------- fonts
local FONT_FILES = {
  text400 = { "Inter", "fonts/Inter-Regular.ttf", 400 }, text500 = { "Inter", "fonts/Inter-Medium.ttf", 500 },
  text600 = { "Inter", "fonts/Inter-SemiBold.ttf", 600 }, text700 = { "Inter", "fonts/Inter-Bold.ttf", 700 },
  mono400 = { "GeistMono", "fonts/GeistMono-Regular.ttf", 400 }, mono500 = { "GeistMono", "fonts/GeistMono-Medium.ttf", 500 },
  serif = { "InstrumentSerif", "fonts/InstrumentSerif-Regular.ttf", 400 },
  serifItalic = { "InstrumentSerifItalic", "fonts/InstrumentSerif-Italic.ttf", 400 },
  wideBold = { "ArchivoExpanded", "fonts/Archivo-ExpandedBold.ttf", 700 },
  wideBlack = { "ArchivoExpanded", "fonts/Archivo-ExpandedBlack.ttf", 900 },
  -- the Unnamed menu's: Monocraft (the Minecraft letters), and the two Proggy pixel fonts
  craft = { "Monocraft", "fonts/Monocraft.ttf", 400 },
  proggy = { "ProggyClean", "fonts/ProggyClean.ttf", 400 },
  proggyTiny = { "ProggyTiny", "fonts/ProggyTiny.ttf", 400 },
}
local WEIGHTS = { [400] = "Regular", [500] = "Medium", [600] = "SemiBold", [700] = "Bold", [900] = "Heavy" }
local function builtin(name, weight, style)
  local ok, font = pcall(Font.fromName, name, weight or Enum.FontWeight.Regular, style or Enum.FontStyle.Normal)
  if ok and font then return font end
  return Font.fromEnum(Enum.Font.Gotham)
end
local FALLBACK = {
  text400 = function() return builtin("BuilderSans", Enum.FontWeight.Regular) end,
  text500 = function() return builtin("BuilderSans", Enum.FontWeight.Medium) end,
  text600 = function() return builtin("BuilderSans", Enum.FontWeight.SemiBold) end,
  text700 = function() return builtin("BuilderSans", Enum.FontWeight.Bold) end,
  mono400 = function() return builtin("RobotoMono", Enum.FontWeight.Regular) end,
  mono500 = function() return builtin("RobotoMono", Enum.FontWeight.Medium) end,
  serif = function() return builtin("Merriweather", Enum.FontWeight.Regular) end,
  serifItalic = function() return builtin("Merriweather", Enum.FontWeight.Regular, Enum.FontStyle.Italic) end,
  wideBold = function() return builtin("BuilderExtended", Enum.FontWeight.Bold) end,
  wideBlack = function() return builtin("BuilderExtended", Enum.FontWeight.Heavy) end,
  -- (without the files, the closest Roblox has: its own pixel font, and Arial)
  craft = function() return Font.fromEnum(Enum.Font.Arcade) end,
  proggy = function() return Font.fromEnum(Enum.Font.Code) end,
  proggyTiny = function() return Font.fromEnum(Enum.Font.Code) end,
}
B.F = {}

local function loadFonts()
  -- one family file per family, listing each face's registered .ttf
  local families = {}
  for key, spec in pairs(FONT_FILES) do
    local ttf = Assets.id(spec[2])
    if ttf then
      local family = families[spec[1]]
      if not family then family = { name = spec[1], faces = {}, keys = {} }; families[spec[1]] = family end
      family.faces[#family.faces + 1] = { name = WEIGHTS[spec[3]] or "Regular", weight = spec[3], style = "normal", assetId = ttf }
      family.keys[key] = spec[3]
    end
  end
  for name, family in pairs(families) do
    table.sort(family.faces, function(a, b) return a.weight < b.weight end)
    local relative = "fonts/" .. name .. ".json"
    local ok, json = pcall(S.HttpService.JSONEncode, S.HttpService, { name = name, faces = family.faces })
    if ok then
      local path = fs.path(relative)
      local changed = fs.read(path) ~= json
      if changed then fs.write(path, json) end
      -- the stamp is the json itself: a new prefix or face list re-registers the family file
      manifest.files[relative] = tostring(#json) .. ":" .. tostring(registry.prefix)
      if changed then ids[relative] = nil; registry.files[basename(relative)] = nil end
      local id = Assets.id(relative)
      if id then
        for key, weight in pairs(family.keys) do
          local okFont, font = pcall(Font.new, id, Enum.FontWeight[WEIGHTS[weight] or "Regular"], Enum.FontStyle.Normal)
          if okFont then B.F[key] = font end
        end
      end
    end
  end
  local missing = 0
  for key, make in pairs(FALLBACK) do
    if not B.F[key] then B.F[key] = make(); missing += 1 end
  end
  return missing
end

-- ---------------------------------------------------------------- icons, images, sounds
-- Icons live in one atlas (a single registration): returns image, offset, size.
function Assets.icon(name)
  local atlas = manifest.icons
  local index = atlas and atlas.map and atlas.map[name]
  if not index then return nil end
  local id = Assets.id(atlas.image)
  if not id then return nil end
  local cell = atlas.cell
  return id, Vector2.new((index % atlas.cols) * cell, math.floor(index / atlas.cols) * cell), Vector2.new(cell, cell)
end
-- Images are deployed under a content-hashed file name (a changed picture gets a
-- new id, so a cached texture can never be stale); manifest.img maps name -> file.
function Assets.image(name)
  local file = manifest.img and manifest.img[name]
  return file and Assets.id(file) or nil
end
function Assets.sound(name)
  local file = manifest.sfx and manifest.sfx[name]
  return file and Assets.id(file) or nil
end

-- ---------------------------------------------------------------- boot
function Assets.preload(list, timeout)
  local done = false
  task.spawn(function()
    pcall(function() S.ContentProvider:PreloadAsync(list) end)
    done = true
  end)
  local waited = 0
  while not done and waited < (timeout or 3) do waited += task.wait() end
  return done
end

function Assets.init()
  if not canRegister then
    Assets.lite = true
  else
    local saved = fs.readJson(REGISTRY)
    if type(saved) == "table" and type(saved.prefix) == "string" and type(saved.files) == "table" and type(saved.sentinel) == "string" then
      -- is the content folder we registered into still there?
      local status
      local finished = false
      task.spawn(function()
        pcall(function()
          S.ContentProvider:PreloadAsync({ saved.prefix .. saved.sentinel }, function(_, result) status = result end)
        end)
        finished = true
      end)
      local waited = 0
      while not finished and waited < 2 do waited += task.wait() end
      if status == Enum.AssetFetchStatus.Success then
        registry.prefix, registry.files, registry.sentinel = saved.prefix, saved.files, saved.sentinel
        for key, runs in pairs(type(saved.seq) == "table" and saved.seq or {}) do
          local known = {}
          for _, run in ipairs(runs) do
            for index = run[1], run[2] do known[index] = true end
          end
          seqKnown[key] = known
        end
      end
    end
    Assets.lite = not (manifest.icons and manifest.icons.image and Assets.id(manifest.icons.image))
  end
  Assets.fontsMissing = loadFonts()
  -- the hub's own letters, kept: Settings > Font swaps B.F, and Inter is these again
  B.F0 = table.clone(B.F)
  Assets.ready = true
  return not Assets.lite
end
function Assets.registry() return registry end
end
do -- 04_ui.lua
-- ============================================================================
--  04 ui       instance factory, glass, text, icons, input, popovers, scroll
-- ============================================================================
local S, util, Motion, Theme, T, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.Assets
local UIS = S.UserInputService
local UI = { fx = { canvas = true, shadow = false, innerStroke = false }, sfxVolume = 0.5, sfxOn = true }
B.UI = UI

-- ---------------------------------------------------------------- capabilities
pcall(function()
  local probe = Instance.new("UIShadow")
  probe.BlurRadius = UDim.new(0, 4)
  probe:Destroy()
  UI.fx.shadow = true
end)
pcall(function()
  local probe = Instance.new("UIStroke")
  probe.BorderStrokePosition = Enum.BorderStrokePosition.Inner
  probe:Destroy()
  UI.fx.innerStroke = true
end)
pcall(function()
  -- a CanvasGroup is drawn at reduced resolution on the lowest quality levels: text goes soft
  local saved = UserSettings():GetService("UserGameSettings").SavedQualityLevel
  if saved ~= Enum.SavedQualitySetting.Automatic and saved.Value <= 2 then UI.fx.canvas = false end
end)

-- ---------------------------------------------------------------- factory
local function applyTheme(instance, map)
  for property, spec in pairs(map) do
    if type(spec) == "table" then Theme.bind(instance, property, spec[1], spec[2]) else Theme.bind(instance, property, spec) end
  end
end
function UI.new(class, props, children)
  local instance = Instance.new(class)
  local parent
  if props then
    for key, value in pairs(props) do
      if key == "Parent" then parent = value
      elseif key == "Theme" then applyTheme(instance, value)
      else instance[key] = value end
    end
  end
  if children then
    for _, child in ipairs(children) do child.Parent = instance end
  end
  if parent then instance.Parent = parent end
  return instance
end
local new = UI.new

function UI.frame(parent, props)
  local frame = Instance.new("Frame")
  frame.BackgroundTransparency = 1
  frame.BorderSizePixel = 0
  if props then
    for key, value in pairs(props) do
      if key == "Theme" then applyTheme(frame, value) else frame[key] = value end
    end
  end
  frame.Parent = parent
  return frame
end
-- radius: a token name ("rCard"), a pixel count, or true for a full pill
function UI.corner(instance, radius)
  local corner = Instance.new("UICorner")
  if radius == true then corner.CornerRadius = UDim.new(1, 0)
  elseif type(radius) == "string" then Theme.bind(corner, "CornerRadius", radius, function(value) return UDim.new(0, value) end)
  else corner.CornerRadius = UDim.new(0, radius or 8) end
  corner.Parent = instance
  return corner
end
function UI.stroke(instance, token, alphaToken, thickness)
  local stroke = Instance.new("UIStroke")
  stroke.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  stroke.Thickness = thickness or 1
  Theme.bind(stroke, "Color", token or "ink")
  if type(alphaToken) == "number" then stroke.Transparency = alphaToken else Theme.bind(stroke, "Transparency", alphaToken or "strokeA") end
  if UI.fx.innerStroke then stroke.BorderStrokePosition = Enum.BorderStrokePosition.Inner end
  stroke.Parent = instance
  return stroke
end
function UI.pad(instance, top, right, bottom, left)
  local pad = Instance.new("UIPadding")
  right = right or top
  bottom = bottom or top
  left = left or right
  pad.PaddingTop, pad.PaddingRight, pad.PaddingBottom, pad.PaddingLeft = UDim.new(0, top), UDim.new(0, right), UDim.new(0, bottom), UDim.new(0, left)
  pad.Parent = instance
  return pad
end
function UI.list(instance, direction, gap, align)
  local layout = Instance.new("UIListLayout")
  layout.FillDirection = direction == "x" and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
  layout.Padding = UDim.new(0, gap or 0)
  layout.SortOrder = Enum.SortOrder.LayoutOrder
  if align then
    if align.h then layout.HorizontalAlignment = Enum.HorizontalAlignment[align.h] end
    if align.v then layout.VerticalAlignment = Enum.VerticalAlignment[align.v] end
  end
  layout.Parent = instance
  return layout
end
function UI.scaleOf(instance)
  local scale = instance:FindFirstChildOfClass("UIScale")
  if not scale then scale = Instance.new("UIScale"); scale.Parent = instance end
  return scale
end
function UI.gradient(instance, props)
  local gradient = Instance.new("UIGradient")
  for key, value in pairs(props) do gradient[key] = value end
  gradient.Parent = instance
  return gradient
end
function UI.alphaSeq(...)
  local points, args = {}, { ... }
  for i = 1, #args, 2 do points[#points + 1] = NumberSequenceKeypoint.new(args[i], args[i + 1]) end
  return NumberSequence.new(points)
end

-- ---------------------------------------------------------------- text + icons
local STYLE = Theme.type
-- style: a key of Theme.type; color: a token name
function UI.text(parent, text, style, color, props)
  local spec = STYLE[style or "body"] or STYLE.body
  local label = Instance.new("TextLabel")
  label.BackgroundTransparency = 1
  label.BorderSizePixel = 0
  label.FontFace = B.F[spec[1]]
  if UI.fontKey then UI.fontKey[label] = spec[1] end
  label.TextSize = spec[2]
  label.Text = text or ""
  label.TextXAlignment = Enum.TextXAlignment.Left
  label.TextYAlignment = Enum.TextYAlignment.Center
  label.AutomaticSize = Enum.AutomaticSize.XY
  label.Size = UDim2.new()
  Theme.bind(label, "TextColor3", color or "ink")
  if props then
    for key, value in pairs(props) do label[key] = value end
  end
  label.Parent = parent
  return label
end
function UI.icon(parent, name, size, color, props)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency = 1
  image.BorderSizePixel = 0
  image.Size = UDim2.fromOffset(size or 18, size or 18)
  image.ScaleType = Enum.ScaleType.Fit
  Theme.bind(image, "ImageColor3", color or "ink")
  local id, offset, rect = Assets.icon(name)
  if id then
    image.Image, image.ImageRectOffset, image.ImageRectSize = id, offset, rect
  end
  if props then
    for key, value in pairs(props) do image[key] = value end
  end
  image.Parent = parent
  return image
end
function UI.setIcon(image, name)
  local id, offset, rect = Assets.icon(name)
  if id then image.Image, image.ImageRectOffset, image.ImageRectSize = id, offset, rect end
end
function UI.image(parent, name, props)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency = 1
  image.BorderSizePixel = 0
  image.Image = Assets.image(name) or ""
  if props then
    for key, value in pairs(props) do
      if key == "Theme" then applyTheme(image, value) else image[key] = value end
    end
  end
  image.Parent = parent
  return image
end

-- ---------------------------------------------------------------- glass
-- A translucent surface: tinted fill, fine grain, a top sheen and a rim that
-- catches light. level: "window" (reads the glass slider), "panel", "popover".
function UI.glass(parent, opts)
  opts = opts or {}
  local level = opts.level or "panel"
  local radius = opts.radius or "rPanel"
  local frame = Instance.new("Frame")
  frame.BorderSizePixel = 0
  frame.Name = opts.name or "Glass"
  if level == "window" then
    Theme.bind(frame, "BackgroundColor3", "base")
    Theme.bind(frame, "BackgroundTransparency", "baseA")
  elseif level == "popover" then
    Theme.bind(frame, "BackgroundColor3", "popover")
    frame.BackgroundTransparency = 0.04
  else
    Theme.bind(frame, "BackgroundColor3", "ink")
    Theme.bind(frame, "BackgroundTransparency", opts.fill or "fill1A")
  end
  UI.corner(frame, radius)
  if opts.grain ~= false and Assets.image("noise") then
    local grain = UI.image(frame, "noise", { Name = "Grain", Size = UDim2.fromScale(1, 1), ScaleType = Enum.ScaleType.Tile,
      TileSize = UDim2.fromOffset(128, 128), ImageTransparency = opts.grainAlpha or 0.955, ZIndex = 0, Interactable = false })
    UI.corner(grain, radius)
  end
  if opts.sheen ~= false then
    local sheen = Instance.new("Frame")
    sheen.Name = "Sheen"
    sheen.BorderSizePixel = 0
    sheen.BackgroundColor3 = Color3.new(1, 1, 1)
    sheen.Size = UDim2.fromScale(1, 1)
    sheen.ZIndex = 0
    sheen.Interactable = false
    UI.corner(sheen, radius)
    UI.gradient(sheen, { Rotation = 90, Transparency = UI.alphaSeq(0, opts.sheenAlpha or 0.93, 0.45, 1, 1, 1) })
    sheen.Parent = frame
  end
  local rim = Instance.new("UIStroke")
  rim.ApplyStrokeMode = Enum.ApplyStrokeMode.Border
  rim.Thickness = 1
  rim.Color = Color3.new(1, 1, 1)
  if UI.fx.innerStroke then rim.BorderStrokePosition = Enum.BorderStrokePosition.Inner end
  local rimGradient = UI.gradient(rim, { Rotation = 52,
    Transparency = UI.alphaSeq(0, opts.rimHi or 0.55, 0.32, 0.9, 0.68, 0.93, 1, opts.rimLo or 0.72) })
  rim.Parent = frame
  if opts.shadow and UI.fx.shadow then
    local shadow = Instance.new("UIShadow")
    shadow.BlurRadius = UDim.new(0, opts.shadow == true and 56 or opts.shadow)
    shadow.Offset = UDim2.fromOffset(0, opts.shadowY or 22)
    shadow.Color = Color3.new(0, 0, 0)
    Theme.bind(shadow, "Transparency", "shadowA")
    pcall(function() shadow.ShowBehindParent = false end)
    shadow.Parent = frame
  end
  if opts.props then
    for key, value in pairs(opts.props) do frame[key] = value end
  end
  frame.Parent = parent
  return frame, rimGradient
end

-- A quiet filled surface (cards, rows): ink at a low alpha with a hairline.
function UI.surface(parent, props, radius, fill)
  local frame = Instance.new("Frame")
  frame.BorderSizePixel = 0
  Theme.bind(frame, "BackgroundColor3", "ink")
  Theme.bind(frame, "BackgroundTransparency", fill or "fill1A")
  UI.corner(frame, radius or "rCard")
  if props then
    for key, value in pairs(props) do frame[key] = value end
  end
  frame.Parent = parent
  return frame
end

-- A container that can fade as one. Falls back to a plain frame where a
-- CanvasGroup would soften text; UI.fade then just shows or hides it.
function UI.group(parent, props)
  local group = Instance.new(UI.fx.canvas and "CanvasGroup" or "Frame")
  group.BackgroundTransparency = 1
  group.BorderSizePixel = 0
  if props then
    for key, value in pairs(props) do group[key] = value end
  end
  group.Parent = parent
  return group
end
function UI.fade(group, alpha, preset, done)
  if group:IsA("CanvasGroup") then
    if alpha > 0 then group.Visible = true end
    Motion.to(group, "GroupTransparency", 1 - alpha, preset or "quick", function()
      if alpha <= 0 then group.Visible = false end
      if done then done() end
    end)
  else
    group.Visible = alpha > 0
    if done then done() end
  end
end
function UI.setFade(group, alpha)
  if group:IsA("CanvasGroup") then Motion.snap(group, "GroupTransparency", 1 - alpha) end
  group.Visible = alpha > 0
end

-- ---------------------------------------------------------------- sound
local sounds = {}
function UI.sfx(name, volume)
  if not UI.sfxOn or UI.sfxVolume <= 0 or not UI.soundHost then return end
  local id = Assets.sound(name)
  if not id then return end
  local now = os.clock()
  local entry = sounds[name]
  if entry and now - entry.at < 0.04 then return end
  if not entry then
    local sound = Instance.new("Sound")
    sound.SoundId = id
    sound.Parent = UI.soundHost
    entry = { sound = sound, at = 0 }
    sounds[name] = entry
  end
  entry.at = now
  entry.sound.Volume = (volume or 1) * UI.sfxVolume * 0.5
  entry.sound.PlaybackSpeed = 0.97 + math.random() * 0.06
  entry.sound:Play()
end

-- ---------------------------------------------------------------- input
local function isPress(input)
  return input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch
end
UI.isPress = isPress
-- One coordinate space everywhere: the one AbsolutePosition reports. Measured on the client:
-- a ScreenGui that ignores the inset sits at AbsolutePosition (0, -58), InputObject.Position is
-- in that same space, and GetMouseLocation / the camera's viewport are 58 px further down.
function UI.inset() return S.GuiService:GetGuiInset() end
function UI.mouse() return UIS:GetMouseLocation() - S.GuiService:GetGuiInset() end
function UI.point(input) return Vector2.new(input.Position.X, input.Position.Y) end
-- design units -> screen pixels for anything inside the window (set by 06 window)
function UI.unit() return 1 end
function UI.inside(gui, point)
  local p, s = gui.AbsolutePosition, gui.AbsoluteSize
  return point.X >= p.X and point.X <= p.X + s.X and point.Y >= p.Y and point.Y <= p.Y + s.Y
end

-- Attach hover / press / click / alt (right click) handlers to a GuiButton.
function UI.wire(button, handlers)
  local pressing = false
  if handlers.hover then
    button.MouseEnter:Connect(B.safe("ui.hover", function() handlers.hover(true) end))
    button.MouseLeave:Connect(B.safe("ui.hover", function()
      handlers.hover(false)
      if pressing and handlers.press then pressing = false; handlers.press(false) end
    end))
  end
  button.InputBegan:Connect(B.safe("ui.press", function(input)
    if isPress(input) then
      pressing = true
      if handlers.press then handlers.press(true) end
    elseif input.UserInputType == Enum.UserInputType.MouseButton2 and handlers.alt then
      handlers.alt(input)
    end
  end))
  button.InputEnded:Connect(B.safe("ui.press", function(input)
    if isPress(input) and pressing then
      pressing = false
      if handlers.press then handlers.press(false) end
    end
  end))
  if handlers.click then button.Activated:Connect(B.safe("ui.click", function(input) handlers.click(input) end)) end
  return button
end
-- An invisible button laid over `parent`. Only for parents WITHOUT a list layout or automatic
-- width: a full-size child there is laid out as an item and inflates the parent (measured:
-- a 60 px dropdown pill became 550 px). Those use UI.pressable instead.
function UI.button(parent, handlers, props)
  local button = Instance.new("TextButton")
  button.Name = "Hit"
  button.Text = ""
  button.BackgroundTransparency = 1
  button.BorderSizePixel = 0
  button.AutoButtonColor = false
  button.Size = UDim2.fromScale(1, 1)
  button.ZIndex = 5
  if props then
    for key, value in pairs(props) do button[key] = value end
  end
  UI.wire(button, handlers)
  button.Parent = parent
  return button
end
-- A container that is itself the button: children (labels, icons, layouts) go inside it.
function UI.pressable(parent, props, handlers)
  local button = Instance.new("TextButton")
  button.Text = ""
  button.AutoButtonColor = false
  button.BorderSizePixel = 0
  button.BackgroundTransparency = 1
  if props then
    for key, value in pairs(props) do
      if key == "Theme" then applyTheme(button, value) else button[key] = value end
    end
  end
  if handlers then UI.wire(button, handlers) end
  button.Parent = parent
  return button
end

-- Drag with mouse or finger. onMove(position, deltaFromStart); returns nothing.
function UI.drag(handle, onStart, onMove, onEnd)
  handle.InputBegan:Connect(B.safe("ui.drag", function(input)
    if not isPress(input) then return end
    local start = UI.point(input)
    if onStart and onStart(start) == false then return end
    local touch = input.UserInputType == Enum.UserInputType.Touch
    local moved, ended
    local function finish()
      if moved then moved:Disconnect() end
      if ended then ended:Disconnect() end
      moved, ended = nil, nil
      if onEnd then B.try("ui.drag.end", onEnd) end
    end
    moved = UIS.InputChanged:Connect(B.safe("ui.drag.move", function(change)
      if (touch and change == input) or (not touch and change.UserInputType == Enum.UserInputType.MouseMovement) then
        local p = UI.point(change)
        onMove(p, p - start)
      end
    end))
    ended = UIS.InputEnded:Connect(function(finished)
      if finished == input or (not touch and finished.UserInputType == Enum.UserInputType.MouseButton1) then finish() end
    end)
  end))
end

-- ---------------------------------------------------------------- overlay layer
-- Popovers, menus and tooltips live in one full-screen layer above the window.
local popovers = {}
function UI.mountOverlay(gui, scaleSource)
  UI.overlay = UI.frame(gui, { Name = "Overlay", Size = UDim2.fromScale(1, 1), ZIndex = 50 })
  UI.overlayScale = scaleSource
  -- a click anywhere outside the open popover closes it
  B.connect(UIS.InputBegan, function(input)
    if #popovers == 0 then return end
    if isPress(input) or input.UserInputType == Enum.UserInputType.MouseButton2 then
      local point = UI.point(input)
      for index = #popovers, 1, -1 do
        local pop = popovers[index]
        if not UI.inside(pop.frame, point) and not (pop.anchor and UI.inside(pop.anchor, point)) then pop.close() else break end
      end
    elseif input.KeyCode == Enum.KeyCode.Escape then
      popovers[#popovers].close()
    end
  end, "ui.overlay")
end
function UI.closePopovers()
  for index = #popovers, 1, -1 do popovers[index].close(true) end
end
function UI.popoverOpen() return #popovers > 0 end

-- Open a glass panel next to `anchor`. build(content, close) fills it.
-- opts: width, align ("left" | "right" | "center"), gap, side ("below" | "above")
function UI.popover(anchor, opts, build)
  opts = opts or {}
  local scale = UI.overlayScale and UI.overlayScale() or 1
  local width = opts.width or 220
  local pop = { anchor = anchor }
  local holder = UI.frame(UI.overlay, { Name = "Popover", Size = UDim2.fromOffset(width, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 60 })
  local sizer = Instance.new("UIScale")
  sizer.Scale = scale * 0.92
  sizer.Parent = holder
  local glass = UI.glass(holder, { level = "popover", radius = "rCard", shadow = 34, shadowY = 14, rimHi = 0.62, name = "Panel",
    props = { Size = UDim2.fromScale(1, 0), AutomaticSize = Enum.AutomaticSize.Y } })
  local group = UI.group(glass, { Size = UDim2.fromScale(1, 0), AutomaticSize = Enum.AutomaticSize.Y })
  UI.pad(group, opts.pad or 6)
  UI.list(group, "y", opts.gap or 2)
  pop.frame = holder
  local closed = false
  function pop.close(instant)
    if closed then return end
    closed = true
    local at = table.find(popovers, pop)
    if at then table.remove(popovers, at) end
    if opts.onClose then B.try("popover.close", opts.onClose) end
    if instant then holder:Destroy(); return end
    Motion.to(sizer, "Scale", scale * 0.94, "quick")
    UI.fade(group, 0, "quick")
    Motion.to(glass, "BackgroundTransparency", 1, "quick", function() holder:Destroy() end)
  end
  B.try("popover.build", build, group, pop.close)
  -- place it once its height is known
  local function place()
    local view = B.viewport()
    local a, s = anchor.AbsolutePosition, anchor.AbsoluteSize
    local size = holder.AbsoluteSize
    local w, h = width * scale, math.max(size.Y, 1)
    local x
    if opts.align == "left" then x = a.X elseif opts.align == "center" then x = a.X + s.X / 2 - w / 2 else x = a.X + s.X - w end
    local y = a.Y + s.Y + 6 * scale
    local above = opts.side == "above" or (y + h > view.Y - 8 and a.Y - h - 6 * scale > 8)
    if above then y = a.Y - h - 6 * scale end
    local origin = UI.overlay.AbsolutePosition
    x = math.clamp(x - origin.X, 8, math.max(8, view.X - w - 8))
    y = math.clamp(y - origin.Y, 8, math.max(8, view.Y - h - 8))
    holder.Position = UDim2.fromOffset(x, y)
    return above
  end
  place()
  holder:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() if not closed then place() end end)
  UI.setFade(group, 0)
  UI.fade(group, 1, "quick")
  Motion.to(sizer, "Scale", scale, "snappy")
  popovers[#popovers + 1] = pop
  UI.sfx("open", 0.5)
  return pop
end

-- A simple menu: items = { { label, icon?, hint?, danger?, checked?, run } | "divider" }
-- A long one (more than opts.rows of them, 11 unless said) scrolls, and opens on the one that is checked.
function UI.menu(anchor, items, opts)
  opts = opts or {}
  return UI.popover(anchor, { width = opts.width or 208, align = opts.align, side = opts.side }, function(content, close)
    local rows = opts.rows or 11
    if #items > rows then
      local holder = UI.frame(content, { Name = "Long", Size = UDim2.new(1, 0, 0, rows * 34 - 2) })
      local scroller, scroll = UI.scroll(holder, { Size = UDim2.fromScale(1, 1), Name = "Scroll" })
      content = UI.frame(scroller, { Name = "Rows", Size = UDim2.new(1, -9, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(content, "y", 2)
      for index, item in ipairs(items) do
        if type(item) == "table" and item.checked then
          task.defer(function() if holder.Parent then scroll.to((index - 4) * 34, true) end end)
          break
        end
      end
    end
    for index, item in ipairs(items) do
      if item == "divider" then
        local line = UI.frame(content, { Size = UDim2.new(1, -12, 0, 1), LayoutOrder = index, Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
        line.Position = UDim2.fromOffset(6, 0)
      else
        local row = UI.frame(content, { Size = UDim2.new(1, 0, 0, 32), LayoutOrder = index, Theme = { BackgroundColor3 = "ink" } })
        UI.corner(row, "rSmall")
        local x = 10
        if item.icon then
          UI.icon(row, item.icon, 16, item.danger and "bad" or "sub", { Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
          x = 34
        end
        UI.text(row, item.label, "label", item.danger and "bad" or "ink", { Position = UDim2.new(0, x, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
        if item.checked then
          UI.icon(row, "check", 15, "accent", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
        elseif item.hint then
          UI.text(row, item.hint, "mono", "faint", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11 })
        end
        UI.button(row, {
          hover = function(on) Motion.to(row, "BackgroundTransparency", on and T.fill2A or 1, "quick") end,
          click = function()
            UI.sfx("click", 0.6)
            if not item.keepOpen then close() end
            if item.run then item.run() end
          end,
        })
      end
    end
  end)
end

-- ---------------------------------------------------------------- tooltip
local tip
function UI.tooltip(target, text)
  if not text or text == "" then return end
  local token = 0
  target.MouseEnter:Connect(function()
    token += 1
    local mine = token
    task.delay(0.55, function()
      if mine ~= token or not B.alive or not UI.overlay or not target:IsDescendantOf(game) then return end
      if tip then tip:Destroy() end
      local scale = UI.overlayScale and UI.overlayScale() or 1
      local holder = UI.frame(UI.overlay, { Name = "Tip", AutomaticSize = Enum.AutomaticSize.XY, ZIndex = 80 })
      local sizer = Instance.new("UIScale"); sizer.Scale = scale; sizer.Parent = holder
      local body = UI.glass(holder, { level = "popover", radius = "rSmall", sheen = false, grain = false,
        props = { AutomaticSize = Enum.AutomaticSize.XY } })
      UI.pad(body, 6, 9)
      local label = UI.text(body, text, "caption", "sub", { TextWrapped = true, AutomaticSize = Enum.AutomaticSize.XY })
      local limit = Instance.new("UISizeConstraint"); limit.MaxSize = Vector2.new(260, math.huge); limit.Parent = label
      local mouse = UIS:GetMouseLocation()
      local view = B.viewport()
      holder.Position = UDim2.fromOffset(math.clamp(mouse.X + 14, 8, view.X - 280 * scale), math.clamp(mouse.Y + 18, 8, view.Y - 60))
      tip = holder
    end)
  end)
  target.MouseLeave:Connect(function()
    token += 1
    if tip then tip:Destroy(); tip = nil end
  end)
end
function UI.hideTip()
  if tip then tip:Destroy(); tip = nil end
end

-- ---------------------------------------------------------------- scroll
-- A vertical scroller with a spring-driven wheel and a scrollbar: a thumb that says how far down
-- the page is, grows under the pointer, and can be dragged; a press on the track beside it goes
-- there. UI.scrollbar: "always" (it rests faint), "auto" (only while the page moves), "off".
UI.scrollbar = "always"
local scrollers = setmetatable({}, { __mode = "k" })
function UI.setScrollbar(mode)
  UI.scrollbar = mode
  for _, paint in pairs(scrollers) do B.try("ui.scrollbar", paint) end
end
local BAR_REST, BAR_WIDE, BAR_GRIP = 3, 6, 14     -- the thumb at rest and under the pointer, and the strip that takes the pointer
function UI.scroll(parent, props)
  local scroller = Instance.new("ScrollingFrame")
  scroller.BackgroundTransparency = 1
  scroller.BorderSizePixel = 0
  scroller.ScrollBarThickness = 0
  scroller.ScrollingDirection = Enum.ScrollingDirection.Y
  scroller.AutomaticCanvasSize = Enum.AutomaticSize.Y
  scroller.CanvasSize = UDim2.new()
  scroller.ElasticBehavior = Enum.ElasticBehavior.Never
  scroller.ScrollingEnabled = B.touch
  if props then
    for key, value in pairs(props) do scroller[key] = value end
  end
  scroller.Parent = parent
  local thumb = UI.frame(parent, { Name = "Thumb", Size = UDim2.fromOffset(BAR_REST, 40), AnchorPoint = Vector2.new(1, 0), ZIndex = 8,
    Theme = { BackgroundColor3 = "ink" }, BackgroundTransparency = 1 })
  UI.corner(thumb, true)
  local grip = UI.new("TextButton", { Name = "Scrollbar", Text = "", AutoButtonColor = false, BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0),
    Size = UDim2.fromOffset(BAR_GRIP, 40), ZIndex = 9, Visible = false, Parent = parent })
  local target = 0
  local spring = Motion.spring(1, "smooth", function(x)
    scroller.CanvasPosition = Vector2.new(0, x[1])
  end, 0.2)
  local function limit()
    return math.max(0, scroller.AbsoluteCanvasSize.Y - scroller.AbsoluteWindowSize.Y)
  end
  local hideToken = 0
  local hovered, dragging, flashing, width = false, false, false, BAR_REST
  local bar = { top = 0, size = 0, span = 0 }       -- the thumb as it was last laid out, in screen pixels
  -- false when there is nothing to scroll, or the bar is switched off
  local function refresh()
    local window, canvas = scroller.AbsoluteWindowSize.Y, scroller.AbsoluteCanvasSize.Y
    local needed = canvas > window + 1 and window > 0 and UI.scrollbar ~= "off"
    if grip.Visible ~= needed then grip.Visible = needed end
    if not needed then thumb.BackgroundTransparency = 1; return false end
    local track = scroller.AbsoluteSize.Y - 12
    local size = math.max(28, track * window / canvas)
    local ratio = scroller.CanvasPosition.Y / math.max(1, canvas - window)
    local unit = UI.unit()
    local right = (scroller.AbsolutePosition.X - parent.AbsolutePosition.X + scroller.AbsoluteSize.X) / unit
    local top = scroller.AbsolutePosition.Y - parent.AbsolutePosition.Y
    thumb.Size = UDim2.fromOffset(width, size / unit)
    thumb.Position = UDim2.new(0, right - 3, 0, (top + 6 + (track - size) * ratio) / unit)
    grip.Size = UDim2.fromOffset(BAR_GRIP, scroller.AbsoluteSize.Y / unit)
    grip.Position = UDim2.new(0, right, 0, top / unit)
    bar.top, bar.size, bar.span = scroller.AbsolutePosition.Y + 6, size, track - size
    return true
  end
  local widen = Motion.spring(1, "snappy", function(x)
    width = x[1]
    refresh()
  end, 0.05)
  widen:snap({ BAR_REST })
  -- how solid the thumb is: held, under the pointer, while the page moves, or at rest
  local function paint()
    if not refresh() then return end
    local alpha = dragging and 0.35 or hovered and 0.5 or flashing and 0.62 or (UI.scrollbar == "always" and 0.82 or 1)
    Motion.to(thumb, "BackgroundTransparency", alpha, alpha >= 0.8 and "gentle" or "quick")
    widen:to({ (dragging or hovered) and BAR_WIDE or BAR_REST })
  end
  scrollers[scroller] = paint
  local function flash()
    flashing = true
    paint()
    hideToken += 1
    local mine = hideToken
    task.delay(0.9, function()
      if mine == hideToken and thumb.Parent then flashing = false; paint() end
    end)
  end
  scroller:GetPropertyChangedSignal("CanvasPosition"):Connect(flash)
  scroller:GetPropertyChangedSignal("AbsoluteCanvasSize"):Connect(function()
    if target > limit() then target = limit(); spring:to({ target }) end
    paint()
  end)
  scroller:GetPropertyChangedSignal("AbsoluteWindowSize"):Connect(paint)
  -- the thumb held: the page goes with the pointer, with no spring between them
  local grab = 0
  local function follow(y)
    local ratio = bar.span > 0 and math.clamp((y - grab - bar.top) / bar.span, 0, 1) or 0
    target = ratio * limit()
    spring:snap({ target })
  end
  UI.drag(grip, function(point)
    if not refresh() then return false end
    local at = bar.top + bar.span * (scroller.CanvasPosition.Y / math.max(1, limit()))
    -- on the thumb it is taken where it was pressed; beside it, the thumb comes to the pointer
    grab = (point.Y >= at and point.Y <= at + bar.size) and (point.Y - at) or bar.size * 0.5
    dragging = true
    follow(point.Y)
    paint()
    return true
  end, function(point) follow(point.Y) end, function()
    dragging = false
    paint()
  end)
  grip.MouseEnter:Connect(function() hovered = true; paint() end)
  grip.MouseLeave:Connect(function() hovered = false; paint() end)
  local wheel = B.safe("ui.wheel", function(input)
    if input.UserInputType ~= Enum.UserInputType.MouseWheel or B.touch then return end
    -- An open list (any popover) holds the page under it still: the wheel over it scrolls the list
    -- alone. Before, the page went on scrolling under an open dropdown and left it behind.
    local top = popovers[#popovers]
    if top and not (top.frame and scroller:IsDescendantOf(top.frame)) then return end
    if not spring:moving() then
      spring.x[1], spring.g[1] = scroller.CanvasPosition.Y, scroller.CanvasPosition.Y
      target = scroller.CanvasPosition.Y
    end
    target = math.clamp(target - input.Position.Z * 92, 0, limit())
    spring:to({ target })
  end)
  scroller.InputChanged:Connect(wheel)
  grip.InputChanged:Connect(wheel)        -- (the strip lies over the page's edge: the wheel works there too)
  -- (painted once it is laid out, not only when something about it changes)
  task.defer(function() if scroller.Parent then B.try("ui.scrollbar", paint) end end)
  local api = { frame = scroller, thumb = thumb, grip = grip }
  function api.to(y, instant)
    target = math.clamp(y, 0, limit())
    if instant then spring:snap({ target }) else
      spring.x[1] = scroller.CanvasPosition.Y
      spring:to({ target })
    end
  end
  function api.top(instant) api.to(0, instant) end
  return scroller, api
end

-- ---------------------------------------------------------------- the interface's letters
-- Settings > Font: every word the BASED look writes in one family (its wordmark keeps its own).
-- Done where the letters come from: B.F's keys take the family at their own weight, so whatever is
-- drawn from now on has it, and what is on screen already is moved across once, matched by the
-- face it wore. The other looks keep their own letters (Unnamed has its own font setting).
UI.FAMILIES = {
  { "inter", "Inter (BASED)" },
  { "monocraft", "Monocraft (Minecraft)", function() return B.F0 and B.F0.craft end },
  { "builder", "Builder Sans", "BuilderSans" },
  { "gotham", "Gotham", "GothamSSm" },
  { "montserrat", "Montserrat", "Montserrat" },
  { "nunito", "Nunito", "Nunito" },
  { "ubuntu", "Ubuntu", "Ubuntu" },
  { "titillium", "Titillium", "TitilliumWeb" },
  { "jura", "Jura", "Jura" },
  { "sarpanch", "Sarpanch", "Sarpanch" },
  { "michroma", "Michroma", "Michroma" },
  { "oswald", "Oswald", "Oswald" },
  { "fredoka", "Fredoka", "FredokaOne" },
  { "roboto", "Roboto Mono", "RobotoMono" },
  { "arial", "Arial", function() return Font.fromEnum(Enum.Font.Arial) end },
  { "source", "Source Sans", "SourceSansPro" },
}
-- the keys that follow the pick (the wordmark, wideBlack, stays BASED)
local LETTER_KEYS = { "text400", "text500", "text600", "mono400", "mono500", "wideBold", "serif", "serifItalic" }
local function faceSig(face) return tostring(face.Family) .. "|" .. tostring(face.Weight) .. "|" .. tostring(face.Style) end
function UI.familyOf(id)
  for _, spec in ipairs(UI.FAMILIES) do
    if spec[1] == id then
      local source = spec[3]
      if source == nil then return nil end
      local ok, face = pcall(function()
        if type(source) == "function" then return source() end
        return Font.fromName(source)
      end)
      return ok and typeof(face) == "Font" and face.Family or nil
    end
  end
  return nil
end
-- Which key each text on screen was drawn from (strong, swept): told by its face the first time it
-- is seen, from the hub's own faces (all different), or from the faces in use now. The second can be
-- two keys at once (in one family Inter 400 and Geist 400 are the same face): the body text wins,
-- and texts drawn by UI.text say their key outright. (Matching by face alone turned 381 labels into
-- the serif on the way back to Inter.)
UI.fontKey = {}
function UI.sweepFonts()
  for label in pairs(UI.fontKey) do
    if not label.Parent then UI.fontKey[label] = nil end
  end
end
function UI.setLetters(id)
  if not B.F0 then return end
  local family = UI.familyOf(id)
  local own, now = {}, {}
  for _, key in ipairs(LETTER_KEYS) do
    if B.F0[key] then own[faceSig(B.F0[key])] = own[faceSig(B.F0[key])] or key end
    if B.F[key] then now[faceSig(B.F[key])] = now[faceSig(B.F[key])] or key end
  end
  for label in pairs(UI.fontKey) do
    if not label.Parent then UI.fontKey[label] = nil end
  end
  for _, key in ipairs(LETTER_KEYS) do
    local own = B.F0[key]
    if own then
      if family then
        local ok, face = pcall(Font.new, family, own.Weight, own.Style)
        B.F[key] = ok and face or own
      else
        B.F[key] = own
      end
    end
  end
  -- what is on screen now: each text moved to its key's new face
  -- (the other looks keep their own letters, also where they draw on the HUD)
  local function owns(item) return (B.Unnamed ~= nil and B.Unnamed.owns(item)) or (B.Novoline ~= nil and B.Novoline.owns(item)) end
  for _, gui in ipairs(B.screens or {}) do
    if gui.Parent and not gui:GetAttribute("OwnLetters") then
      for _, item in ipairs(gui:GetDescendants()) do
        if (item:IsA("TextLabel") or item:IsA("TextButton") or item:IsA("TextBox")) and not owns(item) then
          local key = UI.fontKey[item]
          if not key then
            local sig = faceSig(item.FontFace)
            key = own[sig] or now[sig]
            if key then UI.fontKey[item] = key end
          end
          if key and B.F[key] and item.FontFace ~= B.F[key] then item.FontFace = B.F[key] end
        end
      end
    end
  end
end

-- ---------------------------------------------------------------- misc
function UI.divider(parent, order)
  local line = UI.frame(parent, { Name = "Divider", Size = UDim2.new(1, 0, 0, 1), LayoutOrder = order or 0,
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
  return line
end
-- Small rounded tag: "NEW", "BETA", a key name...
function UI.badge(parent, text, color, props)
  local badge = UI.frame(parent, { AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 18), Theme = { BackgroundColor3 = color or "accent" },
    BackgroundTransparency = 0.82 })
  UI.corner(badge, 6)
  UI.pad(badge, 0, 6)
  UI.text(badge, text, "eyebrow", color or "accent", { TextSize = 9, Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X })
  if props then
    for key, value in pairs(props) do badge[key] = value end
  end
  return badge
end
end
do -- 05_config.lua
-- ============================================================================
--  05 config   flags, profiles, keybinds
--
--  Every setting is a flag with an id. Ids under "app." are the hub's own
--  preferences (theme, intro, scale) and live in prefs.json; everything else is
--  a feature setting and lives in the active profile, which can be one file for
--  every game or one per game. Writes are debounced; nothing saves per frame.
-- ============================================================================
local S, fs, util = B.S, B.fs, B.util
local UIS = S.UserInputService
local Config = { profile = "default", changed = B.Signal.new(), loaded = B.Signal.new() }
B.Config = Config

local values, defaults, listeners = {}, {}, {}
local binds = {}            -- flag id -> { key = "E", mode = "toggle" | "hold" }
local actions = {}          -- id -> function, for bindable buttons
local stored = { app = {}, profile = {} }   -- raw decoded files, kept so unknown ids survive a save
local storedBinds = {}
Config.values, Config.defaults, Config.binds = values, defaults, binds

local function isApp(id) return string.sub(id, 1, 4) == "app." end
local function encode(value)
  local kind = typeof(value)
  if kind == "Color3" then return { __c = util.toHex(value) } end
  if kind == "EnumItem" then return { __e = tostring(value.EnumType), v = value.Name } end
  if kind == "table" then
    local out = {}
    for k, v in pairs(value) do out[k] = encode(v) end
    return out
  end
  return value
end
local function decode(value)
  if type(value) ~= "table" then return value end
  if type(value.__c) == "string" then
    local ok, color = pcall(util.hex, value.__c)
    return ok and color or nil
  end
  if value.__e then
    local ok, item = pcall(function() return Enum[value.__e][value.v] end)
    return ok and item or nil
  end
  local out = {}
  for k, v in pairs(value) do out[k] = decode(v) end
  return out
end
local function sameType(a, b)
  return typeof(a) == typeof(b)
end

-- What the hub ships with (based/shipped.json, baked in by the build): the settings a fresh
-- executor starts from. A shipped value takes the place of the default written in the code, so
-- a setting someone has saved still wins and Reset comes back to what shipped.
local shipped = type(B.SHIPPED) == "table" and B.SHIPPED or {}
local shippedValues = type(shipped.values) == "table" and shipped.values or {}
local shippedBinds = type(shipped.binds) == "table" and shipped.binds or {}

local function profilePath(name) return fs.path("config/" .. name .. ".json") end
local PREFS = fs.path("prefs.json")

-- Saving. Only what changed here is written, onto what is on disk at that moment: every account
-- open on this PC shares these files, and writing the whole of one client's memory undid what
-- another had just saved. A change made quietly (a test, a bot starting itself) is never written.
-- Whatever is waiting goes out at once on unload and on a teleport, not 0.6 s later or never.
local dirty, dirtyBinds = {}, {}
local pending = false
local function isDefault(id)
  local a, b = values[id], defaults[id]
  if type(a) ~= "table" or type(b) ~= "table" then return a == b end
  for k, v in pairs(a) do if b[k] ~= v then return false end end
  for k, v in pairs(b) do if a[k] ~= v then return false end end
  return true
end
local function flush()
  pending = false
  if next(dirty) == nil and next(dirtyBinds) == nil then return end
  local appTouched = false
  local prefs = fs.readJson(PREFS)
  prefs = type(prefs) == "table" and prefs or {}
  local app = type(prefs.values) == "table" and prefs.values or stored.app
  local bindOut = type(prefs.binds) == "table" and prefs.binds or nil
  if not bindOut then
    -- (nothing on disk yet: every key there is, the ones that shipped too, or they would be lost)
    bindOut = {}
    for id, bind in pairs(binds) do bindOut[id] = { key = bind.key, mode = bind.mode } end
    appTouched = true
  end
  local disk = fs.readJson(profilePath(Config.profile))
  local profile = (type(disk) == "table" and type(disk.values) == "table") and disk.values or stored.profile
  local profileTouched = false
  for id in pairs(dirty) do
    local bucket = isApp(id) and app or profile
    if values[id] == nil or isDefault(id) then bucket[id] = nil else bucket[id] = encode(values[id]) end
    if isApp(id) then appTouched = true else profileTouched = true end
  end
  for id in pairs(dirtyBinds) do
    local bind = binds[id]
    bindOut[id] = bind and { key = bind.key, mode = bind.mode } or nil
    appTouched = true
  end
  table.clear(dirty)
  table.clear(dirtyBinds)
  stored.app, stored.profile = app, profile
  if appTouched or prefs.profile ~= Config.profileMode then
    fs.writeJson(PREFS, { values = app, binds = bindOut, profile = Config.profileMode })
  end
  if profileTouched then
    fs.writeJson(profilePath(Config.profile), { values = profile, game = game.GameId, saved = os.time() })
  end
  Config.saved:fire()
end
Config.saved = B.Signal.new()
local later = util.debounce(0.6, function() if pending then B.try("config.save", flush) end end)
local function save() pending = true; later() end
function Config.save() save() end
-- write what is waiting now (unload, teleport, a profile switch)
function Config.flush() if pending or next(dirty) or next(dirtyBinds) then B.try("config.flush", flush) end end
function Config.touch(id) dirty[id] = true; save() end
B.onUnload:connect(function() Config.flush() end)

-- Register a flag. Returns its current value (the saved one when there is one).
function Config.define(id, default)
  if defaults[id] ~= nil then return values[id] end
  local ships = decode(shippedValues[id])
  if ships ~= nil and sameType(ships, default) then default = ships end
  defaults[id] = default
  local bucket = isApp(id) and stored.app or stored.profile
  local saved = decode(bucket[id])
  if saved ~= nil and sameType(saved, default) then values[id] = saved else values[id] = default end
  local savedBind = storedBinds[id]
  if savedBind and savedBind.key and not binds[id] then
    binds[id] = { key = savedBind.key, mode = savedBind.mode or "toggle" }
    -- (a switch made after the keys started listening, on a tab built later: its key works at once)
    if Config.reindex then Config.reindex() end
  end
  return values[id]
end
function Config.get(id) return values[id] end
function Config.set(id, value, quiet)
  if defaults[id] == nil then defaults[id] = value end
  local old = values[id]
  if old == value and type(value) ~= "table" then return end
  values[id] = value
  local list = listeners[id]
  if list then
    for _, fn in ipairs(table.clone(list)) do B.try("config." .. id, fn, value, old) end
  end
  if not quiet then
    dirty[id] = true
    Config.changed:fire(id, value)
    save()
  end
end
function Config.reset(id) if defaults[id] ~= nil then Config.set(id, util.copy(defaults[id])) end end
function Config.isDefault(id) return isDefault(id) end
-- fn(value, old) on every change; `now` also calls it once with the current value.
function Config.on(id, fn, now)
  local list = listeners[id]
  if not list then list = {}; listeners[id] = list end
  list[#list + 1] = fn
  if now and values[id] ~= nil then B.try("config." .. id, fn, values[id], nil) end
  return function()
    local at = table.find(list, fn)
    if at then table.remove(list, at) end
  end
end
-- Mirror a set of flags into a plain table that feature loops can read for free:
--   local O = Config.mirror({ enabled = "esp.enabled", range = "esp.range" })
function Config.mirror(map, onChange)
  local out = {}
  for key, id in pairs(map) do
    out[key] = values[id]
    Config.on(id, function(value)
      out[key] = value
      if onChange then onChange(key, value) end
    end)
  end
  return out
end

-- ---------------------------------------------------------------- profiles
Config.profileMode = "global"     -- "global": one config everywhere; "game": one per game
function Config.profiles()
  local out = {}
  for _, file in ipairs(fs.list(fs.path("config"))) do
    local name = string.match(file, "([^/]+)%.json$")
    if name then out[#out + 1] = name end
  end
  if not table.find(out, "default") then table.insert(out, 1, "default") end
  return out
end
local function readProfile(name)
  local data = fs.readJson(profilePath(name))
  return type(data) == "table" and type(data.values) == "table" and data.values or {}
end
function Config.init()
  local prefs = fs.readJson(PREFS)
  if type(prefs) == "table" then
    stored.app = type(prefs.values) == "table" and prefs.values or {}
    storedBinds = type(prefs.binds) == "table" and prefs.binds or {}
    if prefs.profile == "game" then Config.profileMode = "game" end
  else
    -- nothing saved here yet: the keys that ship. Only then, or a key someone cleared would come back.
    storedBinds = shippedBinds
    -- (and the first launch on this machine: the look is picked before the hub opens, src/13_picker)
    Config.firstRun = true
  end
  Config.profile = Config.profileMode == "game" and ("game_" .. tostring(game.GameId)) or "default"
  stored.profile = readProfile(Config.profile)
  -- (a teleport ends this client: what is waiting is written as it starts)
  pcall(function()
    B.connect(B.LP.OnTeleport, function(state)
      if state == Enum.TeleportState.Started or state == Enum.TeleportState.InProgress then Config.flush() end
    end, "config.teleport")
  end)
end
-- Switch to another profile: every feature flag takes the value saved there.
function Config.load(name)
  Config.flush()                          -- (what is waiting belongs to the profile being left)
  Config.profile = name
  stored.profile = readProfile(name)
  for id, default in pairs(defaults) do
    if not isApp(id) then
      local saved = decode(stored.profile[id])
      if saved == nil or not sameType(saved, default) then saved = util.copy(default) end
      Config.set(id, saved, true)
    end
  end
  Config.loaded:fire(name)
  -- (the mode lives in prefs.json)
  local prefs = fs.readJson(PREFS)
  if type(prefs) == "table" and prefs.profile ~= Config.profileMode then
    prefs.profile = Config.profileMode
    fs.writeJson(PREFS, prefs)
  end
end
function Config.saveAs(name)
  name = string.gsub(name, "[^%w_%-]", "")
  if name == "" then return false end
  Config.flush()
  Config.profile = name
  stored.profile = {}
  for id in pairs(defaults) do
    if not isApp(id) then dirty[id] = true end
  end
  save()
  return true
end
function Config.delete(name)
  if name == "default" then return false end
  return fs.remove(profilePath(name))
end
function Config.setMode(mode)
  Config.profileMode = mode
  Config.load(mode == "game" and ("game_" .. tostring(game.GameId)) or "default")
end
function Config.resetAll(includeApp)
  for id, default in pairs(defaults) do
    if includeApp or not isApp(id) then Config.set(id, util.copy(default)) end
  end
end
-- The share code: EVERY setting (the look too: colours, font, menu style, intro) and every key,
-- as "BASED2:" and base64. Pasted in, the other hub becomes this one: what the code has is set,
-- and what it leaves out is put back to its default, so nothing of theirs is left mixed in.
-- (The first version carried feature settings only, and only ones changed from their defaults:
-- a colour, a key, or a setting the other person had changed and this one had not stayed theirs.)
local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local function toBase64(data)
  return ((string.gsub(data, ".", function(x)
    local r, byte = "", string.byte(x)
    for i = 8, 1, -1 do r ..= (byte % 2 ^ i - byte % 2 ^ (i - 1) > 0 and "1" or "0") end
    return r
  end) .. "0000"):gsub("%d%d%d?%d?%d?%d?", function(x)
    if #x < 6 then return "" end
    local c = 0
    for i = 1, 6 do c += (string.sub(x, i, i) == "1" and 2 ^ (6 - i) or 0) end
    return string.sub(B64, c + 1, c + 1)
  end) .. ({ "", "==", "=" })[#data % 3 + 1])
end
local function fromBase64(data)
  data = string.gsub(data, "[^" .. B64 .. "=]", "")
  return (data:gsub(".", function(x)
    if x == "=" then return "" end
    local r, f = "", (string.find(B64, x, 1, true) - 1)
    for i = 6, 1, -1 do r ..= (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0") end
    return r
  end):gsub("%d%d%d?%d?%d?%d?%d?%d?", function(x)
    if #x ~= 8 then return "" end
    local c = 0
    for i = 1, 8 do c += (string.sub(x, i, i) == "1" and 2 ^ (8 - i) or 0) end
    return string.char(c)
  end))
end
Config.toBase64, Config.fromBase64 = toBase64, fromBase64
-- where windows sit is the screen's business, not a setup's
local PLACE = { ["app.window.x"] = true, ["app.window.y"] = true, ["app.unnamed.x"] = true, ["app.unnamed.y"] = true, ["app.keyHudX"] = true, ["app.keyHudY"] = true }
-- (and some things are yours alone: a share code leaves them out, and pasting one leaves yours be)
function Config.unshared(id) PLACE[id] = true end
function Config.export()
  local out, keys = {}, {}
  for id, value in pairs(values) do
    if not PLACE[id] and defaults[id] ~= nil and not isDefault(id) then out[id] = encode(value) end
  end
  for id, bind in pairs(binds) do
    if bind.key then keys[id] = { key = bind.key, mode = bind.mode } end
  end
  local ok, json = pcall(S.HttpService.JSONEncode, S.HttpService, { based = 2, values = out, binds = keys, full = true })
  return ok and ("BASED2:" .. toBase64(json)) or nil
end
function Config.import(text)
  text = tostring(text or "")
  local json = text
  local coded = string.match(text, "BASED2:(%S+)")
  if coded then json = fromBase64(coded) end
  local ok, data = pcall(S.HttpService.JSONDecode, S.HttpService, json)
  if not ok or type(data) ~= "table" or type(data.values) ~= "table" then return false, 0 end
  local count = 0
  -- (an old code holds feature settings only, changed ones: those alone are set)
  if data.full then
    for id, default in pairs(defaults) do
      if data.values[id] == nil and not PLACE[id] and not isDefault(id) then Config.set(id, util.copy(default)) end
    end
  end
  for id, raw in pairs(data.values) do
    local default = defaults[id]
    local value = decode(raw)
    if default ~= nil and value ~= nil and sameType(value, default) and not PLACE[id] and (data.full or not isApp(id)) then
      Config.set(id, value)
      count += 1
    end
  end
  if type(data.binds) == "table" then
    for id in pairs(table.clone(binds)) do
      if data.binds[id] == nil then Config.bind(id, nil) end
    end
    for id, bind in pairs(data.binds) do
      if type(bind) == "table" and type(bind.key) == "string" then Config.bind(id, bind.key, bind.mode == "hold" and "hold" or "toggle"); count += 1 end
    end
  end
  return true, count
end

-- ---------------------------------------------------------------- keybinds
local byKey = {}
local function keyName(input)
  if input.UserInputType == Enum.UserInputType.Keyboard then return input.KeyCode.Name end
  if input.UserInputType == Enum.UserInputType.MouseButton2 then return "MouseButton2" end
  if input.UserInputType == Enum.UserInputType.MouseButton3 then return "MouseButton3" end
  return nil
end
Config.keyName = keyName
local function reindex()
  table.clear(byKey)
  for id, bind in pairs(binds) do
    if bind.key then
      local list = byKey[bind.key]
      if not list then list = {}; byKey[bind.key] = list end
      list[#list + 1] = id
    end
  end
end
Config.reindex = reindex
Config.bindsChanged = B.Signal.new()
function Config.bind(id, key, mode)
  if not key then binds[id] = nil else binds[id] = { key = key, mode = mode or (binds[id] and binds[id].mode) or "toggle" } end
  reindex()
  dirtyBinds[id] = true
  Config.bindsChanged:fire(id)
  save()
end
function Config.bindOf(id) return binds[id] end
-- A button that can be bound (an emote, mark the one looked at...). Its saved key comes back here:
-- before, only switches took theirs back (in define), and every key on a button was lost on rejoin.
function Config.action(id, fn)
  actions[id] = fn
  local savedBind = storedBinds[id]
  if savedBind and savedBind.key and not binds[id] then
    binds[id] = { key = savedBind.key, mode = savedBind.mode or "toggle" }
    reindex()
    Config.bindsChanged:fire(id)
  end
end
function Config.isAction(id) return actions[id] ~= nil end
-- Whether a button's work is going on, for the key list to light it like a switch that is on: its
-- own say if it has one (an emote: while it plays), else for a moment after its key was pressed.
local actionStates = {}
Config.ranAt = {}
Config.actionRan = B.Signal.new()
function Config.actionState(id, fn) actionStates[id] = fn end
function Config.isActive(id)
  local state = actionStates[id]
  if state then
    local ok, on = pcall(state)
    if ok and on then return true end
    if ok and on == false then return false end
  end
  local at = Config.ranAt[id]
  return at ~= nil and os.clock() - at < 0.6
end
local SHORT = { LeftControl = "LCtrl", RightControl = "RCtrl", LeftShift = "LShift", RightShift = "RShift", LeftAlt = "LAlt", RightAlt = "RAlt",
  MouseButton2 = "RMB", MouseButton3 = "MMB", Return = "Enter", Backspace = "Bksp", CapsLock = "Caps", Escape = "Esc", Delete = "Del",
  Insert = "Ins", PageUp = "PgUp", PageDown = "PgDn", Semicolon = ";", Quote = "'", Comma = ",", Period = ".", Slash = "/", BackSlash = "\\",
  LeftBracket = "[", RightBracket = "]", Minus = "-", Equals = "=", Backquote = "`", Space = "Space", Unknown = "None",
  One = "1", Two = "2", Three = "3", Four = "4", Five = "5", Six = "6", Seven = "7", Eight = "8", Nine = "9", Zero = "0" }
function Config.keyLabel(key)
  if not key then return "None" end
  return SHORT[key] or (string.gsub(key, "^Keypad", "Num"))
end
Config.capturing = false   -- true while a keybind control is listening for a key
-- A switch can have a quick panel: its key tapped flips it as always, its key HELD (0.3 s) opens the
-- panel instead and letting go closes it (the ragebot's: who to hunt). { open = fn, close = fn }
Config.holdPanels = {}
local held = {}
local HOLD = 0.3

function Config.listen()
  reindex()
  B.connect(UIS.InputBegan, function(input, processed)
    if Config.capturing then return end
    local key = keyName(input)
    if not key then return end
    if input.UserInputType == Enum.UserInputType.Keyboard then
      if UIS:GetFocusedTextBox() then return end
    elseif processed then
      return
    end
    local list = byKey[key]
    if not list then return end
    for _, id in ipairs(list) do
      local bind = binds[id]
      local panel = Config.holdPanels[id]
      if actions[id] then
        B.try("bind." .. id, actions[id])
        Config.ranAt[id] = os.clock()
        Config.actionRan:fire(id)
      elseif type(values[id]) == "boolean" and panel and bind.mode ~= "hold" then
        -- (decided when it is let go: a tap flips it, a hold opened the panel)
        local mine = { at = os.clock(), key = key }
        held[id] = mine
        task.delay(HOLD, function()
          if held[id] == mine and Config.keyDown(key) then
            mine.opened = true
            B.try("hold." .. id, panel.open, key)
          end
        end)
      elseif type(values[id]) == "boolean" then
        if bind.mode == "hold" then Config.set(id, true) else Config.set(id, not values[id]) end
      end
    end
  end, "keybinds")
  B.connect(UIS.InputEnded, function(input)
    local key = keyName(input)
    local list = key and byKey[key]
    if not list then return end
    for _, id in ipairs(list) do
      local bind = binds[id]
      local press = held[id]
      if press and press.key == key then
        held[id] = nil
        if press.opened then
          local panel = Config.holdPanels[id]
          if panel and panel.close then B.try("hold.close." .. id, panel.close) end
        elseif type(values[id]) == "boolean" then
          Config.set(id, not values[id])
        end
      elseif bind.mode == "hold" and type(values[id]) == "boolean" and not actions[id] then
        Config.set(id, false)
      end
    end
  end, "keybinds")
end
-- true while the key bound to `id` (or `key`) is physically down
function Config.keyDown(key)
  if not key then return false end
  if key == "MouseButton2" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) end
  if key == "MouseButton3" then return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton3) end
  local ok, code = pcall(function() return Enum.KeyCode[key] end)
  return ok and code ~= nil and UIS:IsKeyDown(code)
end
end
do -- 06_controls.lua
-- ============================================================================
--  06 controls  rows and the things on their right-hand side
--
--  A control is a row inside a card: label (and description) on the left, the
--  control on the right. Every control is backed by a Config flag, so it saves,
--  reloads with a profile, can be reset from its context menu and, for toggles
--  and buttons, bound to a key.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config
local UIS = S.UserInputService
local Controls = { bindables = {} }   -- bindables: flag id -> { label, kind, page }, everything a key can be given
B.Controls = Controls

-- ---------------------------------------------------------------- key capture
function Controls.captureKey(done)
  if Config.capturing then return end
  Config.capturing = true
  local connection
  connection = UIS.InputBegan:Connect(function(input)
    local key = Config.keyName(input)
    if not key then return end
    connection:Disconnect()
    -- the press that sets a key must not also fire the bind it just made
    task.delay(0.15, function() Config.capturing = false end)
    if key == "Escape" then B.try("capture", done, nil, true)
    elseif key == "Backspace" or key == "Delete" then B.try("capture", done, nil, false)
    else B.try("capture", done, key, false) end
  end)
  B.own(connection)
end

-- ---------------------------------------------------------------- row
-- section: { body = Frame, count = number, index = function(entry) }
local function makeRow(section, spec, controlWidth)
  section.count = (section.count or 0) + 1
  local row = UI.frame(section.body, { Name = spec.label or "Row", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    LayoutOrder = section.count })
  if section.count > 1 then
    UI.frame(row, { Name = "Rule", Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0),
      Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
  end
  local wash = UI.frame(row, { Name = "Wash", Size = UDim2.new(1, -8, 1, -6), Position = UDim2.fromOffset(4, 3), Theme = { BackgroundColor3 = "ink" },
    BackgroundTransparency = 1, ZIndex = 0 })
  UI.corner(wash, "rSmall")
  local left = UI.frame(row, { Name = "Left", Size = UDim2.new(1, -((controlWidth or 150) + 30), 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    Position = UDim2.fromOffset(0, 0) })
  UI.pad(left, 12, 0, 12, spec.icon and 42 or 14)
  UI.list(left, "y", 2)
  if spec.icon then
    UI.icon(row, spec.icon, 17, "sub", { Position = UDim2.fromOffset(14, 13), Name = "Icon" })
  end
  local titleLine = UI.frame(left, { Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 1 })
  UI.list(titleLine, "x", 7, { v = "Center" })
  local label = UI.text(titleLine, spec.label or "", "label", "ink", { TextTruncate = Enum.TextTruncate.AtEnd, LayoutOrder = 1,
    AutomaticSize = Enum.AutomaticSize.X, Size = UDim2.fromOffset(0, 20) })
  if spec.badge then UI.badge(titleLine, spec.badge, spec.badgeColor, { LayoutOrder = 2 }) end
  if spec.desc and spec.desc ~= "" then
    UI.text(left, spec.desc, "caption", "sub", { TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0),
      LayoutOrder = 2, LineHeight = 1.15 })
  end
  local slot = UI.frame(row, { Name = "Slot", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -14, 0, 0), Size = UDim2.fromOffset(0, 44),
    AutomaticSize = Enum.AutomaticSize.X, ZIndex = 6 })
  UI.list(slot, "x", 8, { h = "Right", v = "Center" })
  local api = { frame = row, left = left, slot = slot, label = label, wash = wash }
  function api.hover(on) Motion.to(wash, "BackgroundTransparency", on and 0.965 or 1, "quick") end
  function api.flash()
    wash.BackgroundTransparency = 0.86
    Theme.unbind(wash, "BackgroundColor3")
    wash.BackgroundColor3 = T.accent
    Motion.to(wash, "BackgroundTransparency", 1, "lazy", function() Theme.bind(wash, "BackgroundColor3", "ink") end)
  end
  if section.index then
    section.index({ label = spec.label or "", desc = spec.desc or "", row = api, id = spec.id })
  end
  return api
end
Controls.row = makeRow

-- the small chip showing which key a flag is bound to
local function bindChip(slot, id, order)
  local chip = UI.frame(slot, { Name = "Bind", Size = UDim2.fromOffset(0, 20), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = order or 1,
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" }, Visible = false })
  UI.corner(chip, 6)
  UI.pad(chip, 0, 6)
  local text = UI.text(chip, "", "mono", "sub", { TextSize = 11, Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X })
  local function refresh()
    local bind = Config.bindOf(id)
    chip.Visible = bind ~= nil and bind.key ~= nil
    if bind and bind.key then text.Text = Config.keyLabel(bind.key) .. (bind.mode == "hold" and " ·hold" or "") end
  end
  Config.bindsChanged:connect(function(changed) if changed == id and chip.Parent then refresh() end end)
  refresh()
  return chip
end

local function contextMenu(anchor, spec, extra)
  local items = {}
  local id = spec.id
  if id then
    items[#items + 1] = { label = "Reset to default", icon = "rotate-ccw", run = function() Config.reset(id) end }
  end
  if spec.bindable and id then
    local bind = Config.bindOf(id)
    items[#items + 1] = { label = bind and "Change key…" or "Bind to a key…", icon = "keyboard", run = function()
      B.Window.toast({ title = "Press a key", text = "Esc cancels · Backspace clears", icon = "keyboard", time = 2.2 })
      Controls.captureKey(function(key, cancelled)
        if cancelled then return end
        Config.bind(id, key)
        B.Window.toast({ title = key and ("Bound to " .. Config.keyLabel(key)) or "Key cleared", text = spec.label, icon = "keyboard" })
      end)
    end }
    if bind then
      if spec.kind == "toggle" then
        items[#items + 1] = { label = "Hold to activate", icon = "hand", checked = bind.mode == "hold", run = function()
          Config.bind(id, bind.key, bind.mode == "hold" and "toggle" or "hold")
        end }
      end
      items[#items + 1] = { label = "Clear key", icon = "x", run = function() Config.bind(id, nil) end }
    end
  end
  if extra then
    for _, item in ipairs(extra) do items[#items + 1] = item end
  end
  if #items > 0 then UI.menu(anchor, items, { align = "right" }) end
end

-- ---------------------------------------------------------------- toggle
function Controls.toggle(section, spec)
  spec.kind = "toggle"
  spec.bindable = spec.bindable ~= false
  local id = spec.id
  local value = id and Config.define(id, spec.default == true) or (spec.default == true)
  local row = makeRow(section, spec, spec.children and 92 or 62)
  if id and spec.bindable then
    bindChip(row.slot, id, 1)
    Controls.bindables[id] = { label = spec.label or id, kind = "toggle", page = section.page }
  end

  local track = UI.frame(row.slot, { Name = "Switch", Size = UDim2.fromOffset(42, 24), LayoutOrder = 3, BackgroundTransparency = 0 })
  UI.corner(track, true)
  local knob = UI.frame(track, { Name = "Knob", Size = UDim2.fromOffset(18, 18), Position = UDim2.new(0, 3, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5),
    BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0 })
  UI.corner(knob, true)
  if UI.fx.shadow then
    local shadow = Instance.new("UIShadow")
    shadow.BlurRadius = UDim.new(0, 5); shadow.Offset = UDim2.fromOffset(0, 1); shadow.Transparency = 0.7
    shadow.Parent = knob
  end
  local pressed = false
  local function paint(instant)
    local on = value
    local color = on and T.accent or T.ink
    local alpha = on and 0 or T.fill3A - 0.05
    local width = pressed and 23 or 18
    local x = on and (42 - 3 - width) or 3
    if instant then
      track.BackgroundColor3, track.BackgroundTransparency = color, alpha
      Motion.snap(knob, "Position", UDim2.new(0, x, 0.5, 0)); Motion.snap(knob, "Size", UDim2.fromOffset(width, 18))
    else
      Motion.to(track, "BackgroundColor3", color, "quick")
      Motion.to(track, "BackgroundTransparency", alpha, "quick")
      Motion.to(knob, "Position", UDim2.new(0, x, 0.5, 0), pressed and "quick" or "bouncy")
      Motion.to(knob, "Size", UDim2.fromOffset(width, 18), "snappy")
    end
  end
  paint(true)
  Theme.changed:connect(function() if track.Parent then paint(true) end end)

  local api = { row = row, id = id }
  function api.get() return value end
  function api.set(next, quiet)
    next = next == true
    if next == value then return end
    if id then Config.set(id, next, quiet) else
      value = next
      paint()
      if spec.changed then B.try("toggle", spec.changed, value) end
    end
  end
  if id then
    Config.on(id, function(next)
      value = next == true
      if track.Parent then paint() end
      if spec.changed then spec.changed(value) end
    end)
    if spec.changed and value then task.defer(B.safe("toggle.init", function() spec.changed(value) end)) end
  end

  -- nested options that only matter when the toggle is on
  local sub
  if spec.children then
    local chevron = UI.frame(row.slot, { Name = "More", Size = UDim2.fromOffset(22, 22), LayoutOrder = 2 })
    local icon = UI.icon(chevron, "chevron-down", 15, "faint", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
    local holder = UI.frame(section.body, { Name = "Sub", Size = UDim2.new(1, 0, 0, 0), ClipsDescendants = true, LayoutOrder = section.count })
    section.count += 1
    holder.LayoutOrder = section.count
    local inner = UI.frame(holder, { Name = "Inner", Size = UDim2.new(1, -18, 0, 0), Position = UDim2.fromOffset(18, 0), AutomaticSize = Enum.AutomaticSize.Y })
    UI.list(inner, "y", 0)
    UI.frame(holder, { Name = "Guide", Size = UDim2.new(0, 1, 1, -12), Position = UDim2.fromOffset(22, 2),
      Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
    sub = { body = inner, count = 0, index = section.index, page = section.page, nested = true }
    local open = false
    local built = false
    local function size(instant)
      local h = open and (inner.AbsoluteSize.Y / UI.unit()) or 0
      if instant then Motion.snap(holder, "Size", UDim2.new(1, 0, 0, h)) else Motion.to(holder, "Size", UDim2.new(1, 0, 0, h), "smooth") end
      Motion.to(icon, "Rotation", open and 180 or 0, "snappy")
    end
    local function setOpen(next)
      open = next
      if open and not built then
        built = true
        B.try("toggle.children", spec.children, B.Window.sectionApi(sub))
      end
      size()
    end
    inner:GetPropertyChangedSignal("AbsoluteSize"):Connect(function() if open then size(true) end end)
    UI.button(chevron, {
      hover = function(on) Theme.bind(icon, "ImageColor3", on and "ink" or "faint") end,
      click = function() UI.sfx("click", 0.5); setOpen(not open) end,
    })
    api.open = setOpen
  end

  UI.button(row.frame, {
    hover = row.hover,
    press = function(on) pressed = on; paint() end,
    click = function()
      UI.sfx(value and "toggle_off" or "toggle_on", 0.7)
      api.set(not value)
    end,
    alt = function() contextMenu(track, spec) end,
  })
  if spec.tip then UI.tooltip(row.frame, spec.tip) end
  return api
end

-- ---------------------------------------------------------------- slider
function Controls.slider(section, spec)
  local id = spec.id
  local min, max, step = spec.min or 0, spec.max or 100, spec.step or 1
  local decimals = spec.decimals or (step < 1 and math.max(0, math.ceil(-math.log10(step))) or 0)
  -- curve: 1 is a straight track. Above 1 the low end of the range gets most of it
  -- (value = min + t ^ curve * span), for a range too wide to set by hand otherwise.
  local curve = spec.curve or 1
  local wide = spec.valueWidth or 64
  local value = id and Config.define(id, spec.default or min) or (spec.default or min)
  local row = makeRow(section, spec, wide + 12)
  row.frame.Name = "Slider"
  local suffix = spec.suffix or ""
  local function text(v) return (spec.format and spec.format(v)) or (util.format(v, decimals) .. suffix) end

  local field = UI.new("TextBox", { Name = "Value", Size = UDim2.fromOffset(wide, 24), BackgroundTransparency = 1, Text = text(value), FontFace = B.F.mono400,
    TextSize = 12, TextXAlignment = Enum.TextXAlignment.Right, ClearTextOnFocus = true, LayoutOrder = 2, Theme = { TextColor3 = "sub" },
    PlaceholderText = "", Parent = row.slot })

  -- the track sits under the label, the full width of the row
  local bar = UI.frame(row.left, { Name = "Bar", Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 5 })
  row.left.Size = UDim2.new(1, 0, 0, 0)
  UI.pad(bar, 0, 14, 0, 0)
  local track = UI.frame(bar, { Name = "Track", Size = UDim2.new(1, 0, 0, 4), Position = UDim2.new(0, 0, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5),
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill3A" } })
  UI.corner(track, true)
  local fill = UI.frame(track, { Name = "Fill", Size = UDim2.fromScale(0, 1), Theme = { BackgroundColor3 = "accent" }, BackgroundTransparency = 0 })
  UI.corner(fill, true)
  local knob = UI.frame(track, { Name = "Knob", Size = UDim2.fromOffset(14, 14), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0, 0.5),
    BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0, ZIndex = 3 })
  UI.corner(knob, true)
  if UI.fx.shadow then
    local shadow = Instance.new("UIShadow")
    shadow.BlurRadius = UDim.new(0, 6); shadow.Offset = UDim2.fromOffset(0, 1); shadow.Transparency = 0.62
    shadow.Parent = knob
  end

  local dragging = false
  local function place(instant)
    local alpha = util.clamp01((value - min) / (max - min)) ^ (1 / curve)
    if instant then
      Motion.snap(fill, "Size", UDim2.fromScale(alpha, 1)); Motion.snap(knob, "Position", UDim2.fromScale(alpha, 0.5))
    else
      Motion.to(fill, "Size", UDim2.fromScale(alpha, 1), "quick"); Motion.to(knob, "Position", UDim2.fromScale(alpha, 0.5), "quick")
    end
    if not field:IsFocused() then field.Text = text(value) end
  end
  place(true)

  local api = { row = row, id = id }
  function api.get() return value end
  function api.set(next, quiet)
    next = math.clamp(util.round(next, step), min, max)
    if decimals > 0 then next = tonumber(string.format("%." .. decimals .. "f", next)) or next end
    if next == value then return end
    if id then Config.set(id, next, quiet) else
      value = next; place()
      if spec.changed then B.try("slider", spec.changed, value) end
    end
  end
  if id then
    Config.on(id, function(next)
      value = next
      if track.Parent then place(dragging) end
      if spec.changed then spec.changed(value) end
    end)
    if spec.changed then task.defer(B.safe("slider.init", function() spec.changed(value) end)) end
  end

  local hit = UI.new("TextButton", { Name = "Hit", Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.new(1, 14, 1, 0),
    Position = UDim2.fromOffset(-7, 0), ZIndex = 6, Parent = bar })
  local function at(point)
    local x = track.AbsolutePosition.X
    local w = math.max(1, track.AbsoluteSize.X)
    api.set(min + util.clamp01((point.X - x) / w) ^ curve * (max - min))
  end
  UI.drag(hit, function(point)
    dragging = true
    Motion.to(knob, "Size", UDim2.fromOffset(20, 16), "snappy")
    at(point)
  end, function(point) at(point) end, function()
    dragging = false
    Motion.to(knob, "Size", UDim2.fromOffset(14, 14), "bouncy")
    UI.sfx("click", 0.35)
  end)
  hit.MouseEnter:Connect(function() if not dragging then Motion.to(knob, "Size", UDim2.fromOffset(16, 16), "quick") end; row.hover(true) end)
  hit.MouseLeave:Connect(function() if not dragging then Motion.to(knob, "Size", UDim2.fromOffset(14, 14), "quick") end; row.hover(false) end)
  hit.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton2 then contextMenu(knob, spec) end
  end)
  field.FocusLost:Connect(B.safe("slider.field", function()
    local typed = tonumber((string.gsub(field.Text, "[^%d%.%-]", "")))
    if typed then api.set(typed) end
    field.Text = text(value)
    Theme.bind(field, "TextColor3", "sub")
  end))
  field.Focused:Connect(function() Theme.bind(field, "TextColor3", "ink") end)
  return api
end

-- ---------------------------------------------------------------- dropdown / multi-select
local function optionList(options)
  local out = {}
  for _, option in ipairs(options) do
    if type(option) == "table" then out[#out + 1] = { value = option.value or option[1], label = option.label or option[2] or tostring(option.value or option[1]), icon = option.icon }
    else out[#out + 1] = { value = option, label = tostring(option) } end
  end
  return out
end
local function pill(slot, order)
  local button = UI.pressable(slot, { Name = "Select", Size = UDim2.fromOffset(0, 28), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = order or 3,
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(button, "rSmall")
  UI.pad(button, 0, 9, 0, 11)
  UI.list(button, "x", 6, { v = "Center" })
  local label = UI.text(button, "", "label", "ink", { TextSize = 13, LayoutOrder = 1, TextTruncate = Enum.TextTruncate.AtEnd })
  local limit = Instance.new("UISizeConstraint"); limit.MaxSize = Vector2.new(132, 28); limit.Parent = label
  local chevron = UI.icon(button, "chevrons-up-down", 13, "faint", { LayoutOrder = 2 })
  return button, label, chevron
end

function Controls.dropdown(section, spec)
  local id = spec.id
  local options = optionList(spec.options)
  local value = id and Config.define(id, spec.default ~= nil and spec.default or options[1].value) or (spec.default ~= nil and spec.default or options[1].value)
  local row = makeRow(section, spec, 150)
  local button, label = pill(row.slot)
  local function labelOf(v)
    for _, option in ipairs(options) do if option.value == v then return option.label end end
    return tostring(v)
  end
  label.Text = labelOf(value)
  local api = { row = row, id = id }
  function api.get() return value end
  function api.set(next, quiet)
    if next == value then return end
    if id then Config.set(id, next, quiet) else
      value = next; label.Text = labelOf(value)
      if spec.changed then B.try("dropdown", spec.changed, value) end
    end
  end
  function api.options(list)
    options = optionList(list)
    label.Text = labelOf(value)
  end
  if id then
    Config.on(id, function(next)
      value = next
      if label.Parent then label.Text = labelOf(value) end
      if spec.changed then spec.changed(value) end
    end)
    if spec.changed then task.defer(B.safe("dropdown.init", function() spec.changed(value) end)) end
  end
  local function open()
    local items = {}
    for _, option in ipairs(options) do
      items[#items + 1] = { label = option.label, icon = option.icon, checked = option.value == value, run = function() api.set(option.value) end }
    end
    UI.menu(button, items, { align = "right", width = spec.menuWidth })
  end
  UI.wire(button, {
    hover = function(on) Motion.to(button, "BackgroundTransparency", on and T.fill3A or T.fill2A, "quick"); row.hover(on) end,
    click = function() UI.sfx("click", 0.6); open() end,
    alt = function() contextMenu(button, spec) end,
  })
  return api
end

-- value is a set stored as an array of the selected option values
function Controls.multi(section, spec)
  local id = spec.id
  local options = optionList(spec.options)
  local value = id and Config.define(id, spec.default or {}) or (spec.default or {})
  local row = makeRow(section, spec, 150)
  local button, label = pill(row.slot)
  local function has(v) return table.find(value, v) ~= nil end
  local function summary()
    if #value == 0 then return spec.empty or "None" end
    if #value == #options then return "All" end
    if #value <= 2 then
      local names = {}
      for _, option in ipairs(options) do if has(option.value) then names[#names + 1] = option.label end end
      return table.concat(names, ", ")
    end
    return #value .. " selected"
  end
  label.Text = summary()
  local api = { row = row, id = id }
  function api.get() return value end
  function api.has(v) return has(v) end
  function api.set(next, quiet)
    if id then Config.set(id, next, quiet) else
      value = next; label.Text = summary()
      if spec.changed then B.try("multi", spec.changed, value) end
    end
  end
  if id then
    Config.on(id, function(next)
      value = next
      if label.Parent then label.Text = summary() end
      if spec.changed then spec.changed(value) end
    end)
    if spec.changed then task.defer(B.safe("multi.init", function() spec.changed(value) end)) end
  end
  local function flip(v)
    local next = table.clone(value)
    local at = table.find(next, v)
    if at then table.remove(next, at) else next[#next + 1] = v end
    -- keep option order, so two identical selections compare equal
    local ordered = {}
    for _, option in ipairs(options) do if table.find(next, option.value) then ordered[#ordered + 1] = option.value end end
    api.set(ordered)
  end
  local function open()
    UI.popover(button, { width = spec.menuWidth or 212, align = "right" }, function(content)
      local checks = {}
      local function refresh()
        for v, icon in pairs(checks) do icon.ImageTransparency = has(v) and 0 or 1 end
      end
      for index, option in ipairs(options) do
        local item = UI.frame(content, { Size = UDim2.new(1, 0, 0, 32), LayoutOrder = index, Theme = { BackgroundColor3 = "ink" } })
        UI.corner(item, "rSmall")
        local x = 10
        if option.icon then
          UI.icon(item, option.icon, 16, "sub", { Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
          x = 34
        end
        UI.text(item, option.label, "label", "ink", { Position = UDim2.new(0, x, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
        local box = UI.frame(item, { Size = UDim2.fromOffset(16, 16), Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5),
          Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill3A" } })
        UI.corner(box, 5)
        checks[option.value] = UI.icon(box, "check", 13, "accent", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
        UI.button(item, {
          hover = function(on) Motion.to(item, "BackgroundTransparency", on and T.fill2A or 1, "quick") end,
          click = function() UI.sfx("click", 0.6); flip(option.value); refresh() end,
        })
      end
      UI.divider(content, #options + 1)
      local footer = UI.frame(content, { Size = UDim2.new(1, 0, 0, 30), LayoutOrder = #options + 2 })
      for index, action in ipairs({ { "All", function() local all = {}; for _, o in ipairs(options) do all[#all + 1] = o.value end; api.set(all) end },
        { "None", function() api.set({}) end } }) do
        local link = UI.new("TextButton", { Text = action[1], FontFace = B.F.text500, TextSize = 12, BackgroundTransparency = 1, AutoButtonColor = false,
          AutomaticSize = Enum.AutomaticSize.XY, Position = UDim2.new(index == 1 and 0 or 1, index == 1 and 10 or -10, 0.5, 0),
          AnchorPoint = Vector2.new(index == 1 and 0 or 1, 0.5), Theme = { TextColor3 = "sub" }, Parent = footer })
        UI.wire(link, { click = function() UI.sfx("click", 0.5); action[2](); refresh() end,
          hover = function(on) Theme.bind(link, "TextColor3", on and "ink" or "sub") end })
      end
      refresh()
    end)
  end
  UI.wire(button, {
    hover = function(on) Motion.to(button, "BackgroundTransparency", on and T.fill3A or T.fill2A, "quick"); row.hover(on) end,
    click = function() UI.sfx("click", 0.6); open() end,
    alt = function() contextMenu(button, spec) end,
  })
  return api
end

-- ---------------------------------------------------------------- segmented
-- A row of mutually exclusive choices with a pill that slides like liquid:
-- its leading edge arrives first, the trailing edge catches up.
function Controls.segmentedBar(parent, options, initial, onPick, props)
  options = optionList(options)
  local bar = UI.frame(parent, { Name = "Segmented", Size = UDim2.new(1, 0, 0, 30), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(bar, "rSmall")
  if props then
    for key, value in pairs(props) do bar[key] = value end
  end
  local count = #options
  local thumb = UI.frame(bar, { Name = "Thumb", Size = UDim2.new(1 / count, -4, 1, -4), Position = UDim2.new(0, 2, 0, 2),
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill3A" } })
  UI.corner(thumb, "rSmall")
  local labels = {}
  local current
  -- left and right edges are separate springs (scale units)
  local edges = Motion.spring(2, "snappy", function(x)
    local a, b = math.min(x[1], x[2]), math.max(x[1], x[2])
    thumb.Position = UDim2.new(a, 2, 0, 2)
    thumb.Size = UDim2.new(b - a, -4, 1, -4)
  end, 0.0004)
  local function select(index, instant)
    local previous = current
    current = index
    for i, label in ipairs(labels) do Theme.bind(label, "TextColor3", i == index and "ink" or "sub") end
    local a, b = (index - 1) / count, index / count
    if instant or not previous then edges:snap({ a, b }); return end
    -- the edge in the direction of travel leads
    if index > previous then
      edges.g[2] = b; edges:to({ edges.g[1], b }, "snappy")
      task.delay(0.045, function() edges:to({ a, b }, "liquid") end)
    else
      edges.g[1] = a; edges:to({ a, edges.g[2] }, "snappy")
      task.delay(0.045, function() edges:to({ a, b }, "liquid") end)
    end
  end
  for index, option in ipairs(options) do
    local cell = UI.frame(bar, { Size = UDim2.new(1 / count, 0, 1, 0), Position = UDim2.fromScale((index - 1) / count, 0), ZIndex = 2 })
    labels[index] = UI.text(cell, option.label, "label", "sub", { TextSize = 12.5, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
    UI.button(cell, { click = function()
      if current == index then return end
      UI.sfx("tab", 0.6)
      select(index)
      onPick(option.value, index)
    end })
  end
  local startIndex = 1
  for index, option in ipairs(options) do if option.value == initial then startIndex = index end end
  select(startIndex, true)
  return bar, function(v)
    for index, option in ipairs(options) do if option.value == v then select(index) end end
  end
end

function Controls.segmented(section, spec)
  local id = spec.id
  local options = optionList(spec.options)
  local value = id and Config.define(id, spec.default ~= nil and spec.default or options[1].value) or (spec.default ~= nil and spec.default or options[1].value)
  local width = spec.width or math.min(64 * #options, 220)
  local row = makeRow(section, spec, width)
  local holder = UI.frame(row.slot, { Size = UDim2.fromOffset(width, 30), LayoutOrder = 3 })
  local api = { row = row, id = id }
  local _, show = Controls.segmentedBar(holder, options, value, function(v)
    if id then Config.set(id, v) else
      value = v
      if spec.changed then B.try("segmented", spec.changed, v) end
    end
  end)
  function api.get() return value end
  function api.set(v) if id then Config.set(id, v) else value = v; show(v) end end
  if id then
    Config.on(id, function(next)
      value = next
      if holder.Parent then show(next) end
      if spec.changed then spec.changed(next) end
    end)
    if spec.changed then task.defer(B.safe("segmented.init", function() spec.changed(value) end)) end
  end
  return api
end

-- ---------------------------------------------------------------- button
function Controls.pillButton(parent, text, style, run, props)
  local primary, danger = style == "primary", style == "danger"
  local button = UI.pressable(parent, { Name = "Button", Size = UDim2.fromOffset(0, 28), AutomaticSize = Enum.AutomaticSize.X })
  local function rest() return primary and 0 or (danger and 0.84 or T.fill2A) end
  Theme.bind(button, "BackgroundColor3", primary and "accent" or (danger and "bad" or "ink"))
  button.BackgroundTransparency = rest()
  if not primary and not danger then Theme.bind(button, "BackgroundTransparency", "fill2A") end
  UI.corner(button, "rSmall")
  UI.pad(button, 0, 13)
  local label = UI.text(button, text, "button", primary and "accentInk" or (danger and "bad" or "ink"),
    { Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X })
  local scale = UI.scaleOf(button)
  if props then
    for key, value in pairs(props) do button[key] = value end
  end
  UI.wire(button, {
    hover = function(on)
      local base = rest()
      Motion.to(button, "BackgroundTransparency", on and (primary and 0.14 or math.max(0, base - 0.06)) or base, "quick")
    end,
    press = function(on) Motion.to(scale, "Scale", on and 0.95 or 1, on and "quick" or "bouncy") end,
    click = function() UI.sfx("click", 0.8); if run then run() end end,
  })
  return button, label
end

function Controls.button(section, spec)
  local row = makeRow(section, spec, 110)
  local id = spec.id
  if id then
    Config.action(id, function() if spec.run then spec.run() end end)
    spec.bindable = spec.bindable ~= false
    if spec.bindable then
      bindChip(row.slot, id, 1)
      Controls.bindables[id] = { label = spec.label or id, kind = "button", page = section.page }
    end
  end
  local button, label = Controls.pillButton(row.slot, spec.text or "Run", spec.style, function()
    if spec.run then B.try("button." .. (spec.label or "?"), spec.run) end
  end, { LayoutOrder = 3 })
  button.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.MouseButton2 and id then contextMenu(button, { id = id, bindable = spec.bindable, label = spec.label, kind = "button" }) end
  end)
  return { row = row, button = button, setText = function(text) label.Text = text end }
end

-- ---------------------------------------------------------------- keybind
function Controls.keybind(section, spec)
  local id = spec.id
  local value = id and Config.define(id, spec.default or "None") or (spec.default or "None")
  local row = makeRow(section, spec, 100)
  local chip = UI.pressable(row.slot, { Name = "Key", Size = UDim2.fromOffset(0, 28), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = 3,
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(chip, "rSmall")
  UI.pad(chip, 0, 11)
  local floor = Instance.new("UISizeConstraint"); floor.MinSize = Vector2.new(46, 28); floor.Parent = chip
  local label = UI.text(chip, Config.keyLabel(value ~= "None" and value or nil), "monoBold", "ink", { Size = UDim2.fromScale(1, 1),
    AutomaticSize = Enum.AutomaticSize.X, TextXAlignment = Enum.TextXAlignment.Center })
  local stroke = UI.stroke(chip, "accent", 1, 1)
  local api = { row = row, id = id }
  function api.get() return value end
  local function show() label.Text = Config.keyLabel(value ~= "None" and value or nil) end
  if id then
    Config.on(id, function(next)
      value = next
      if label.Parent then show() end
      if spec.changed then spec.changed(next) end
    end)
    if spec.changed then task.defer(B.safe("keybind.init", function() spec.changed(value) end)) end
  end
  UI.wire(chip, {
    hover = function(on) Motion.to(chip, "BackgroundTransparency", on and T.fill3A or T.fill2A, "quick"); row.hover(on) end,
    click = function()
      UI.sfx("click", 0.6)
      label.Text = "…"
      Motion.to(stroke, "Transparency", 0, "quick")
      Controls.captureKey(function(key, cancelled)
        Motion.to(stroke, "Transparency", 1, "smooth")
        if not cancelled then
          local next = key or "None"
          if id then Config.set(id, next) else value = next; if spec.changed then spec.changed(next) end end
        end
        show()
      end)
    end,
    alt = function() contextMenu(chip, spec) end,
  })
  return api
end

-- ---------------------------------------------------------------- text input
function Controls.field(parent, props, onSubmit)
  local field = UI.frame(parent, { Name = "Field", Size = UDim2.fromOffset(150, 28), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(field, "rSmall")
  local stroke = UI.stroke(field, "accent", 1, 1)
  local box = UI.new("TextBox", { Name = "Box", BackgroundTransparency = 1, Size = UDim2.new(1, -20, 1, 0), Position = UDim2.fromOffset(10, 0), Text = "",
    FontFace = B.F.text400, TextSize = 13, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, ClipsDescendants = true,
    Theme = { TextColor3 = "ink", PlaceholderColor3 = "faint" }, Parent = field })
  if props then
    for key, value in pairs(props) do
      if key == "Width" then field.Size = UDim2.fromOffset(value, 28) else box[key] = value end
    end
  end
  box.Focused:Connect(function() Motion.to(stroke, "Transparency", 0.25, "quick") end)
  box.FocusLost:Connect(B.safe("field", function(enter)
    Motion.to(stroke, "Transparency", 1, "smooth")
    if onSubmit then onSubmit(box.Text, enter) end
  end))
  return field, box
end

function Controls.input(section, spec)
  local id = spec.id
  local value = id and Config.define(id, spec.default or "") or (spec.default or "")
  local row = makeRow(section, spec, spec.width or 150)
  local api = { row = row, id = id }
  local _, box = Controls.field(row.slot, { Width = spec.width or 150, PlaceholderText = spec.placeholder or "", Text = tostring(value) }, function(text)
    if spec.numeric then
      local n = tonumber(text)
      if not n then api.box.Text = tostring(value); return end
      text = n
    end
    if id then Config.set(id, text) else
      value = text
      if spec.changed then B.try("input", spec.changed, text) end
    end
  end)
  api.box = box
  function api.get() return value end
  if id then
    Config.on(id, function(next)
      value = next
      if box.Parent and not box:IsFocused() then box.Text = tostring(next) end
      if spec.changed then spec.changed(next) end
    end)
  end
  return api
end

-- ---------------------------------------------------------------- colour
local function hueColor(h) return Color3.fromHSV(h, 1, 1) end
function Controls.colorPopover(anchor, initial, onChange)
  local h, s, v = initial:ToHSV()
  return UI.popover(anchor, { width = 224, align = "right", pad = 10, gap = 10 }, function(content)
    local square = UI.frame(content, { Name = "SV", Size = UDim2.new(1, 0, 0, 132), BackgroundTransparency = 0, BackgroundColor3 = hueColor(h), LayoutOrder = 1 })
    UI.corner(square, 9)
    local white = UI.frame(square, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0 })
    UI.corner(white, 9)
    UI.gradient(white, { Transparency = UI.alphaSeq(0, 0, 1, 1) })
    local black = UI.frame(square, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0, ZIndex = 2 })
    UI.corner(black, 9)
    UI.gradient(black, { Rotation = 90, Transparency = UI.alphaSeq(0, 1, 1, 0) })
    local dot = UI.frame(square, { Size = UDim2.fromOffset(12, 12), AnchorPoint = Vector2.new(0.5, 0.5), ZIndex = 4, BackgroundTransparency = 1 })
    UI.corner(dot, true)
    local ring = Instance.new("UIStroke"); ring.Color = Color3.new(1, 1, 1); ring.Thickness = 2; ring.Parent = dot

    local hueBar = UI.frame(content, { Name = "Hue", Size = UDim2.new(1, 0, 0, 12), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0, LayoutOrder = 2 })
    UI.corner(hueBar, true)
    local stops = {}
    for i = 0, 6 do stops[#stops + 1] = ColorSequenceKeypoint.new(i / 6, Color3.fromHSV(i / 6 % 1, 1, 1)) end
    UI.gradient(hueBar, { Color = ColorSequence.new(stops) })
    local hueKnob = UI.frame(hueBar, { Size = UDim2.fromOffset(14, 14), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundColor3 = Color3.new(1, 1, 1),
      BackgroundTransparency = 0, ZIndex = 3 })
    UI.corner(hueKnob, true)
    local hueRing = Instance.new("UIStroke"); hueRing.Color = Color3.new(0, 0, 0); hueRing.Transparency = 0.7; hueRing.Parent = hueKnob

    local bottom = UI.frame(content, { Size = UDim2.new(1, 0, 0, 28), LayoutOrder = 3 })
    local preview = UI.frame(bottom, { Size = UDim2.fromOffset(28, 28), BackgroundTransparency = 0, BackgroundColor3 = initial })
    UI.corner(preview, 8)
    local hexField, hexBox
    local function emit(fromHex)
      local color = Color3.fromHSV(h, s, v)
      square.BackgroundColor3 = hueColor(h)
      dot.Position = UDim2.fromScale(s, 1 - v)
      hueKnob.Position = UDim2.fromScale(h, 0.5)
      preview.BackgroundColor3 = color
      if hexBox and not fromHex and not hexBox:IsFocused() then hexBox.Text = "#" .. util.toHex(color) end
      onChange(color)
    end
    hexField, hexBox = Controls.field(bottom, { Width = 96, Text = "#" .. util.toHex(initial), FontFace = B.F.mono400, TextSize = 12 }, function(text)
      local clean = string.gsub(text, "[^%x]", "")
      if #clean == 6 then
        h, s, v = util.hex(clean):ToHSV()
        emit(true)
      end
      hexBox.Text = "#" .. util.toHex(Color3.fromHSV(h, s, v))
    end)
    hexField.Position = UDim2.fromOffset(36, 0)
    -- quick picks: the accent family
    local picks = UI.frame(content, { Size = UDim2.new(1, 0, 0, 18), LayoutOrder = 4 })
    UI.list(picks, "x", 7)
    for index, accent in ipairs(Theme.accents) do
      local swatch = UI.frame(picks, { Size = UDim2.fromOffset(18, 18), BackgroundTransparency = 0, BackgroundColor3 = accent.color, LayoutOrder = index })
      UI.corner(swatch, true)
      UI.button(swatch, { click = function() h, s, v = accent.color:ToHSV(); emit() end })
    end
    local svHit = UI.new("TextButton", { Text = "", BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 6, AutoButtonColor = false, Parent = square })
    local function sv(point)
      local p, size = square.AbsolutePosition, square.AbsoluteSize
      s = util.clamp01((point.X - p.X) / size.X)
      v = 1 - util.clamp01((point.Y - p.Y) / size.Y)
      emit()
    end
    UI.drag(svHit, sv, sv)
    local hueHit = UI.new("TextButton", { Text = "", BackgroundTransparency = 1, Size = UDim2.new(1, 0, 1, 12), Position = UDim2.fromOffset(0, -6), ZIndex = 6,
      AutoButtonColor = false, Parent = hueBar })
    local function hue(point)
      h = util.clamp01((point.X - hueBar.AbsolutePosition.X) / hueBar.AbsoluteSize.X)
      emit()
    end
    UI.drag(hueHit, hue, hue)
    dot.Position = UDim2.fromScale(s, 1 - v)
    hueKnob.Position = UDim2.fromScale(h, 0.5)
  end)
end

function Controls.color(section, spec)
  local id = spec.id
  local value = id and Config.define(id, spec.default or Color3.new(1, 1, 1)) or (spec.default or Color3.new(1, 1, 1))
  local row = makeRow(section, spec, 60)
  local swatch = UI.frame(row.slot, { Name = "Swatch", Size = UDim2.fromOffset(34, 22), BackgroundTransparency = 0, BackgroundColor3 = value, LayoutOrder = 3 })
  UI.corner(swatch, 7)
  UI.stroke(swatch, "ink", "stroke2A")
  local api = { row = row, id = id }
  function api.get() return value end
  function api.set(next, quiet)
    if id then Config.set(id, next, quiet) else
      value = next; swatch.BackgroundColor3 = next
      if spec.changed then B.try("color", spec.changed, next) end
    end
  end
  if id then
    Config.on(id, function(next)
      value = next
      if swatch.Parent then swatch.BackgroundColor3 = next end
      if spec.changed then spec.changed(next) end
    end)
    if spec.changed then task.defer(B.safe("color.init", function() spec.changed(value) end)) end
  end
  local scale = UI.scaleOf(swatch)
  UI.button(swatch, {
    hover = function(on) Motion.to(scale, "Scale", on and 1.08 or 1, "snappy"); row.hover(on) end,
    click = function() UI.sfx("click", 0.6); Controls.colorPopover(swatch, value, function(color) api.set(color) end) end,
    alt = function() contextMenu(swatch, spec) end,
  })
  return api
end

-- ---------------------------------------------------------------- static rows
function Controls.note(section, spec)
  section.count = (section.count or 0) + 1
  local tone = spec.tone or "sub"
  local box = UI.frame(section.body, { Name = "Note", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = section.count })
  UI.pad(box, 10, 14, 12, 14)
  local inner = UI.frame(box, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
  UI.list(inner, "x", 9)
  if spec.icon then UI.icon(inner, spec.icon, 15, tone, { LayoutOrder = 1 }) end
  local text = UI.text(inner, spec.text or "", "caption", tone, { TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 2,
    Size = UDim2.new(1, spec.icon and -24 or 0, 0, 0), LineHeight = 1.2, RichText = spec.rich == true })
  return { frame = box, set = function(value) text.Text = value end }
end
function Controls.custom(section, spec)
  section.count = (section.count or 0) + 1
  local frame = UI.frame(section.body, { Name = spec.name or "Custom", Size = UDim2.new(1, 0, 0, spec.height or 100), LayoutOrder = section.count })
  if spec.height == nil then frame.AutomaticSize = Enum.AutomaticSize.Y end
  B.try("custom", spec.build, frame)
  return frame
end
end
do -- 07_window.lua
-- ============================================================================
--  07 window   the shell: glass, sidebar, pages, cards, toasts, palette, blur
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Controls
local UIS = S.UserInputService
local Window = { open = false, built = false, pages = {}, order = {}, index = {}, scale = 1, onShow = B.Signal.new(), onPage = B.Signal.new() }
B.Window = Window

local W, H = 980, 624
local SIDE = 206
local CONTENT_X = SIDE + 20
local CONTENT_W = W - CONTENT_X - 10
local HEADER = 84

-- ---------------------------------------------------------------- real blur
-- Measured: a Glass part a hair in front of the camera plus a DepthOfField with
-- nothing in its focus range blurs the 3D scene inside the part's rectangle only.
-- A rounded window is five rectangles: the body and two steps per end.
local Blur = { enabled = false, parts = {}, visible = false }
B.Blur = Blur
local DEPTH = 0.012
local function blurPart()
  local part = Instance.new("Part")
  part.Name = util.randomName()
  part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch = true, false, false, false
  part.CastShadow = false
  part.Locked = true
  part.Material = Enum.Material.Glass
  part.Color = Color3.new(0, 0, 0)
  part.Transparency = 0.98
  part.Size = Vector3.new(1, 1, 0.001)
  local mesh = Instance.new("SpecialMesh")
  mesh.MeshType = Enum.MeshType.Brick
  mesh.Offset = Vector3.new(0, 0, -0.000001)
  mesh.Parent = part
  return part, mesh
end
function Blur.supported()
  local ok, level = pcall(function() return settings().Rendering.QualityLevel.Value end)
  -- level 0 is Automatic; the effect needs the post-processing tiers
  return ok and (level == 0 or level >= 8)
end
function Blur.start()
  if Blur.dof then return end
  local dof = Instance.new("DepthOfFieldEffect")
  dof.Name = util.randomName()
  dof.FarIntensity, dof.NearIntensity, dof.InFocusRadius, dof.FocusDistance = 0, 1, 0.1, 0.05
  dof.Enabled = false
  dof.Parent = S.Lighting
  Blur.dof = B.own(dof)
  for index = 1, 5 do
    local part, mesh = blurPart()
    Blur.parts[index] = { part = B.own(part), mesh = mesh }
  end
  -- runs after the camera has moved this frame, so the glass never trails it
  S.RunService:BindToRenderStep("BasedBlur", Enum.RenderPriority.Camera.Value + 2, function()
    if not Blur.visible or not B.alive then return end
    B.try("blur", Blur.update)
  end)
  B.own(function() pcall(function() S.RunService:UnbindFromRenderStep("BasedBlur") end) end)
end
local function placePart(camera, slot, x, y, w, h)
  if w < 1 or h < 1 then slot.part.Parent = nil; return end
  local a = camera:ViewportPointToRay(x, y)
  local b = camera:ViewportPointToRay(x + w, y + h)
  local c = camera:ViewportPointToRay(x + w, y)
  local p1, p2, p3 = a.Origin + a.Direction * DEPTH, b.Origin + b.Direction * DEPTH, c.Origin + c.Direction * DEPTH
  local cf = camera.CFrame
  -- A game that clears the camera's children takes the glass with them (Da Hood's own client calls
  -- ClearAllChildren on the camera), and a destroyed part cannot be parented again: make it anew.
  if slot.part.Parent ~= camera and not pcall(function() slot.part.Parent = camera end) then
    local part, mesh = blurPart()
    slot.part, slot.mesh = B.own(part), mesh
    part.Parent = camera
  end
  slot.part.CFrame = CFrame.fromMatrix((p1 + p2) / 2, cf.XVector, cf.YVector, cf.ZVector)
  slot.mesh.Scale = Vector3.new((p3 - p1).Magnitude, (p3 - p2).Magnitude, 0) / slot.part.Size
end
function Blur.update()
  local camera = workspace.CurrentCamera
  local holder = Window.holder
  if not camera or not holder then return end
  -- read the rectangle this frame: a dragged window must not outrun its blur
  local p, s = holder.AbsolutePosition, holder.AbsoluteSize
  local inset = S.GuiService:GetGuiInset()
  local x, y, w, h, r = p.X + inset.X, p.Y + inset.Y, s.X, s.Y, T.rWindow * Window.sizer.Scale
  local parts = Blur.parts
  placePart(camera, parts[1], x, y + r, w, h - 2 * r)
  placePart(camera, parts[2], x + 0.063 * r, y + 0.30 * r, w - 0.126 * r, 0.70 * r)
  placePart(camera, parts[3], x + 0.42 * r, y + 0.07 * r, w - 0.84 * r, 0.23 * r)
  placePart(camera, parts[4], x + 0.063 * r, y + h - r, w - 0.126 * r, 0.70 * r)
  placePart(camera, parts[5], x + 0.42 * r, y + h - 0.30 * r, w - 0.84 * r, 0.23 * r)
end
function Blur.show(on)
  Blur.visible = on and Blur.enabled
  if Blur.dof then Blur.dof.Enabled = Blur.visible end
  if not Blur.visible then
    for _, slot in ipairs(Blur.parts) do slot.part.Parent = nil end
  end
end
function Blur.set(on)
  on = on and Blur.supported()
  Blur.enabled = on
  if on then Blur.start() end
  Theme.set({ blur = on })
  Blur.show(Window.open)
end

-- ---------------------------------------------------------------- toasts
local toasts = {}
local function layoutToasts()
  local y = 0
  for _, toast in ipairs(toasts) do
    Motion.to(toast.holder, "Position", UDim2.new(1, -18, 0, 18 + y), "smooth")
    y += toast.height + 10
  end
end
-- opts: title, text, icon, tone ("accent" | "ok" | "warn" | "bad"), time
function Window.toast(opts)
  if Window.toastHook then
    local taken = Window.toastHook(opts)
    if taken then return taken end
  end
  if not Window.hud then return end
  local tone = opts.tone or "accent"
  local hasText = opts.text ~= nil and opts.text ~= ""
  local toast = { height = hasText and 62 or 46 }
  local holder = UI.frame(Window.hud, { Name = "Toast", AnchorPoint = Vector2.new(1, 0), Size = UDim2.fromOffset(318, toast.height),
    Position = UDim2.new(1, 360, 0, 18) })
  local sizer = Instance.new("UIScale"); sizer.Scale = Window.scale; sizer.Parent = holder
  local glass = UI.glass(holder, { level = "popover", radius = "rCard", shadow = 30, shadowY = 12, props = { Size = UDim2.fromScale(1, 1) } })
  local chip = UI.frame(glass, { Size = UDim2.fromOffset(30, 30), Position = UDim2.new(0, 10, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5),
    Theme = { BackgroundColor3 = tone }, BackgroundTransparency = 0.84 })
  UI.corner(chip, 9)
  UI.icon(chip, opts.icon or "sparkles", 16, tone, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
  UI.text(glass, opts.title or "", "heading", "ink", { TextSize = 13.5, Position = UDim2.fromOffset(50, hasText and 12 or 14), Size = UDim2.new(1, -64, 0, 18),
    AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.AtEnd })
  if hasText then
    UI.text(glass, opts.text, "caption", "sub", { Position = UDim2.fromOffset(50, 31), Size = UDim2.new(1, -64, 0, 18), AutomaticSize = Enum.AutomaticSize.None,
      TextTruncate = Enum.TextTruncate.AtEnd })
  end
  local timer = UI.frame(glass, { Size = UDim2.new(1, -28, 0, 2), Position = UDim2.new(0, 14, 1, -5), Theme = { BackgroundColor3 = tone }, BackgroundTransparency = 0.45 })
  UI.corner(timer, true)
  toast.holder = holder
  table.insert(toasts, 1, toast)
  while #toasts > 4 do
    local old = table.remove(toasts)
    old.holder:Destroy()
  end
  layoutToasts()
  local life = opts.time or 3.6
  Motion.tween(life, Motion.ease.linear, function(p) timer.Size = UDim2.new(1 - p, -28 * (1 - p), 0, 2) end)
  local function dismiss()
    if toast.gone then return end
    toast.gone = true
    local at = table.find(toasts, toast)
    if at then table.remove(toasts, at) end
    Motion.to(holder, "Position", UDim2.new(1, 380, 0, holder.Position.Y.Offset), "smooth", function() holder:Destroy() end)
    layoutToasts()
  end
  task.delay(life, function() if B.alive then dismiss() end end)
  UI.button(glass, { click = dismiss })
  UI.sfx(tone == "bad" and "close" or "saved", 0.6)
  return dismiss
end

-- ---------------------------------------------------------------- sections
local SectionApi = {}
SectionApi.__index = SectionApi
for _, kind in ipairs({ "toggle", "slider", "dropdown", "multi", "segmented", "color", "keybind", "button", "input", "note", "custom" }) do
  SectionApi[kind] = function(self, spec) return Controls[kind](self.raw, spec) end
end
function Window.sectionApi(raw) return setmetatable({ raw = raw, body = raw.body }, SectionApi) end

local Page = {}
Page.__index = Page
local function band(page, full)
  page.bandCount += 1
  local frame = UI.frame(page.content, { Name = full and "Full" or "Columns", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
    LayoutOrder = page.bandCount })
  if full then
    UI.list(frame, "y", 12)
    return { full = true, frame = frame }
  end
  local columns = {}
  for i = 1, 2 do
    local column = UI.frame(frame, { Name = "Column" .. i, Size = UDim2.new(0.5, -6, 0, 0), Position = UDim2.new(i == 1 and 0 or 0.5, i == 1 and 0 or 6, 0, 0),
      AutomaticSize = Enum.AutomaticSize.Y })
    UI.list(column, "y", 12)
    columns[i] = { frame = column, count = 0 }
  end
  return { full = false, frame = frame, columns = columns }
end
-- spec: title, desc, icon, full (span both columns), column (1 | 2)
function Page:section(spec)
  spec = spec or {}
  -- built in the background, a tab is assembled one card per frame (see Window.prebuild)
  if self.slicing then task.wait() end
  local current = self.band
  if spec.full then
    current = band(self, true)
    self.band = nil
  elseif not current or current.full then
    current = band(self, false)
    self.band = current
  end
  local host
  if current.full then host = current.frame else
    local column = spec.column and current.columns[spec.column]
      or (current.columns[1].count <= current.columns[2].count and current.columns[1] or current.columns[2])
    column.count += spec.weight or 1
    host = column.frame
  end
  self.sectionCount += 1
  local card = UI.surface(host, { Name = spec.title or "Card", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = self.sectionCount })
  UI.stroke(card, "ink", "strokeA")
  local stack = UI.frame(card, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
  UI.list(stack, "y", 0)
  UI.pad(stack, 0, 0, 4, 0)
  if spec.title then
    local head = UI.frame(stack, { Name = "Head", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 0 })
    UI.pad(head, 14, 14, 8, 14)
    UI.list(head, "y", 3)
    local line = UI.frame(head, { Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 1 })
    UI.list(line, "x", 8, { v = "Center" })
    if spec.icon then UI.icon(line, spec.icon, 16, "accent", { LayoutOrder = 1 }) end
    UI.text(line, spec.title, "heading", "ink", { LayoutOrder = 2 })
    if spec.badge then UI.badge(line, spec.badge, spec.badgeColor, { LayoutOrder = 3 }) end
    if spec.desc then
      UI.text(head, spec.desc, "caption", "sub", { TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0), LayoutOrder = 2, LineHeight = 1.15 })
    end
  end
  local body = UI.frame(stack, { Name = "Body", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1 })
  UI.list(body, "y", 0)
  local page = self
  local raw = { body = body, count = spec.title and 1 or 0, page = self, card = card }
  function raw.index(entry)
    entry.page, entry.section = page, spec.title or page.title
    Window.index[#Window.index + 1] = entry
  end
  local api = Window.sectionApi(raw)
  api.card = card
  return api
end
-- a full-width block the caller draws itself
function Page:custom(height, build)
  if self.slicing then task.wait() end
  local current = band(self, true)
  self.band = nil
  local frame = UI.frame(current.frame, { Name = "Custom", Size = UDim2.new(1, 0, 0, height or 0) })
  if not height then frame.AutomaticSize = Enum.AutomaticSize.Y end
  B.try("page.custom", build, frame)
  return frame
end
function Page:empty(icon, title, text)
  return self:custom(380, function(frame)
    local box = UI.frame(frame, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.46), Size = UDim2.fromOffset(420, 0),
      AutomaticSize = Enum.AutomaticSize.Y })
    UI.list(box, "y", 10, { h = "Center" })
    local orb = UI.frame(box, { Size = UDim2.fromOffset(64, 64), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" }, LayoutOrder = 1 })
    UI.corner(orb, true)
    UI.stroke(orb, "ink", "strokeA")
    UI.icon(orb, icon or "package", 26, "sub", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
    UI.text(box, title or "Nothing here yet", "title", "ink", { LayoutOrder = 2, TextXAlignment = Enum.TextXAlignment.Center })
    UI.text(box, text or "", "body", "sub", { LayoutOrder = 3, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(1, 0, 0, 0),
      AutomaticSize = Enum.AutomaticSize.Y, LineHeight = 1.25 })
  end)
end

-- ---------------------------------------------------------------- pages
-- spec: id, title, icon, group, eyebrow, build(page), order
function Window.page(spec)
  local page = setmetatable({ id = spec.id, title = spec.title, icon = spec.icon or "circle", group = spec.group or "", eyebrow = spec.eyebrow,
    build = spec.build, built = false, bandCount = 0, sectionCount = 0, order = spec.order or (#Window.order + 1) * 10 }, Page)
  Window.pages[spec.id] = page
  Window.order[#Window.order + 1] = page
  table.sort(Window.order, function(a, b) return a.order < b.order end)
  if Window.built then Window.rebuildNav() end
  return page
end
function Window.removePage(id)
  local page = Window.pages[id]
  if not page then return end
  Window.pages[id] = nil
  table.remove(Window.order, table.find(Window.order, page))
  if page.frame then page.holder:Destroy() end
  for index = #Window.index, 1, -1 do
    if Window.index[index].page == page then table.remove(Window.index, index) end
  end
  if Window.built then Window.rebuildNav() end
end
-- background = true builds the tab a card at a time across frames. Measured: built in one go a
-- tab costs 5-25 ms, which is a visible hitch; sliced, no frame carries more than one card.
local function ensureBuilt(page, background)
  if page.built then return end
  page.built = true
  page.slicing = background == true
  local holder = UI.group(Window.pageHost, { Name = page.id, Size = UDim2.fromScale(1, 1), Visible = false })
  local scroller, api = UI.scroll(holder, { Size = UDim2.new(1, 0, 1, 0), Name = "Scroll" })
  local content = UI.frame(scroller, { Name = "Content", Size = UDim2.new(1, -8, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
  UI.list(content, "y", 12)
  UI.pad(content, 2, 0, 18, 0)
  page.holder, page.frame, page.scroll, page.content = holder, scroller, api, content
  local started = os.clock()
  if page.build then B.try("page." .. page.id, page.build, page) end
  if page.sectionCount == 0 and page.bandCount == 0 then
    page:empty("package", "Nothing here yet", "This tab is ready for its controls.")
  end
  page.slicing = false
  page.ready = true
  page.buildMs = (os.clock() - started) * 1000
end
-- Build every tab that has not been opened yet, quietly, so the first visit never stutters and
-- search can find every control. Runs during the intro when there is one.
function Window.prebuild()
  if Window.prebuilding then return end
  Window.prebuilding = true
  for _, page in ipairs(table.clone(Window.order)) do
    if not B.alive then return end
    if Window.pages[page.id] == page and not page.built then
      B.try("page.prebuild", ensureBuilt, page, true)
      task.wait(0.05)
    end
  end
  Window.prebuilding = false
  -- (the key list on screen names each feature by its switch: they are all known now)
  if B.Keys and B.Keys.repaint then B.Keys.repaint() end
end
Window.ensureBuilt = ensureBuilt

function Window.go(id, instant)
  local page = Window.pages[id]
  if not page or not Window.built then return end
  local previous = Window.current
  if previous == page then return end
  ensureBuilt(page)
  Window.current = page
  UI.closePopovers()
  UI.hideTip()
  if previous and previous.holder then
    local old = previous.holder
    UI.fade(old, 0, "quick")
    Motion.to(old, "Position", UDim2.fromOffset(0, -8), "quick")
  end
  page.holder.Visible = true
  if instant then
    UI.setFade(page.holder, 1)
    page.holder.Position = UDim2.new()
  else
    UI.setFade(page.holder, 0)
    Motion.snap(page.holder, "Position", UDim2.fromOffset(0, 14))
    UI.fade(page.holder, 1, "smooth")
    Motion.to(page.holder, "Position", UDim2.new(), "smooth")
  end
  Window.setTitle(page, instant)
  Window.selectNav(page, instant)
  Window.onPage:fire(page)
  if not instant then UI.sfx("tab", 0.6) end
end

-- ---------------------------------------------------------------- build
local navItems = {}
function Window.build()
  if Window.built then return end
  Window.built = true
  local gui = B.screen(9000)
  local hudGui = B.screen(9100)
  Window.gui, Window.hudGui = gui, hudGui
  Window.hud = UI.frame(hudGui, { Name = "Hud", Size = UDim2.fromScale(1, 1) })
  UI.soundHost = UI.frame(hudGui, { Name = "Sound" })

  -- frees the cursor in first person while the hub is open
  Window.modal = UI.new("TextButton", { Name = "Modal", Text = "", BackgroundTransparency = 1, Size = UDim2.fromOffset(0, 0), Modal = true, Visible = false, Parent = gui })

  local stage = UI.frame(gui, { Name = "Stage", Size = UDim2.fromScale(1, 1) })
  local holder = UI.frame(stage, { Name = "Window", Size = UDim2.fromOffset(W, H), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Visible = false })
  local sizer = Instance.new("UIScale")
  sizer.Parent = holder
  Window.holder, Window.sizer = holder, sizer
  UI.unit = function() return sizer.Scale end

  -- shadow lives outside the canvas: a canvas clips whatever leaves its bounds
  local shadowHost = UI.frame(holder, { Name = "Shadow", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1 })
  UI.corner(shadowHost, "rWindow")
  if UI.fx.shadow then
    local shadow = Instance.new("UIShadow")
    shadow.BlurRadius = UDim.new(0, 70)
    shadow.Offset = UDim2.fromOffset(0, 28)
    shadow.Color = Color3.new(0, 0, 0)
    shadow.Transparency = 1
    pcall(function() shadow.ShowBehindParent = false end)
    shadow.Parent = shadowHost
    Window.shadow = shadow
  end

  local root = UI.group(holder, { Name = "Root", Size = UDim2.fromScale(1, 1) })
  UI.corner(root, "rWindow")
  Window.root = root
  local glass, rim = UI.glass(root, { level = "window", radius = "rWindow", name = "Glass", props = { Size = UDim2.fromScale(1, 1), Active = true },
    rimHi = 0.42, rimLo = 0.7, sheenAlpha = 0.95 })
  Window.glass, Window.rim = glass, rim

  -- ---- sidebar
  local side = UI.glass(glass, { level = "panel", radius = "rPanel", name = "Sidebar", fill = "fill1A",
    props = { Size = UDim2.new(0, SIDE, 1, -20), Position = UDim2.fromOffset(10, 10) }, rimHi = 0.72, rimLo = 0.9 })
  Window.side = side
  local brand = UI.frame(side, { Name = "Brand", Size = UDim2.new(1, 0, 0, 58) })
  local mark = UI.frame(brand, { Size = UDim2.fromOffset(0, 26), Position = UDim2.fromOffset(18, 18), AutomaticSize = Enum.AutomaticSize.X })
  UI.list(mark, "x", 3, { v = "Bottom" })
  UI.text(mark, "BASED", "brand", "ink", { LayoutOrder = 1, TextSize = 17 })
  UI.text(mark, "hub", "display", "accent", { LayoutOrder = 2, TextSize = 21 })
  -- The tabs scroll, between the brand and the user chip (a game with tabs of its own, Music and the
  -- rest of the hub ran past the bottom: Keys sat under the chip and Settings could not be reached).
  local navHost, navScroll = UI.scroll(side, { Name = "Nav", Size = UDim2.new(1, -16, 1, -128), Position = UDim2.fromOffset(8, 60),
    AutomaticCanvasSize = Enum.AutomaticSize.None, ClipsDescendants = true })
  Window.navHost, Window.navScroll = navHost, navScroll
  Window.navPill = UI.frame(Window.navHost, { Name = "Pill", Size = UDim2.new(1, 0, 0, 34), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" }, Visible = false })
  UI.corner(Window.navPill, "rControl")
  UI.stroke(Window.navPill, "ink", "strokeA")

  -- user chip
  local user = UI.frame(side, { Name = "User", Size = UDim2.new(1, -16, 0, 50), Position = UDim2.new(0, 8, 1, -58), Theme = { BackgroundColor3 = "ink" }, BackgroundTransparency = 1 })
  UI.corner(user, "rControl")
  local avatar = UI.new("ImageLabel", { Name = "Avatar", Size = UDim2.fromOffset(32, 32), Position = UDim2.new(0, 9, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5),
    BackgroundTransparency = 0, Theme = { BackgroundColor3 = "ink" }, Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(B.LP.UserId) .. "&w=150&h=150", Parent = user })
  avatar.BackgroundTransparency = 0.9
  UI.corner(avatar, true)
  UI.text(user, B.LP.DisplayName, "label", "ink", { Position = UDim2.fromOffset(50, 9), Size = UDim2.new(1, -78, 0, 17), AutomaticSize = Enum.AutomaticSize.None,
    TextTruncate = Enum.TextTruncate.AtEnd, TextSize = 13 })
  Window.userLine = UI.text(user, "@" .. B.LP.Name, "caption", "faint", { Position = UDim2.fromOffset(50, 26), Size = UDim2.new(1, -78, 0, 15),
    AutomaticSize = Enum.AutomaticSize.None, TextTruncate = Enum.TextTruncate.AtEnd, TextSize = 11 })
  local more = UI.icon(user, "ellipsis", 16, "faint", { Position = UDim2.new(1, -12, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
  UI.button(user, {
    hover = function(on) Motion.to(user, "BackgroundTransparency", on and T.fill2A or 1, "quick") end,
    click = function()
      UI.menu(more, {
        { label = "Settings", icon = "settings", run = function() Window.go("settings") end },
        { label = "Search", icon = "search", hint = "Ctrl K", run = function() Window.palette() end },
        { label = "Unnamed menu", icon = "app-window", run = function() Config.set("app.gui", "unnamed") end },
        { label = "Novoline menu", icon = "layout-grid", run = function() Config.set("app.gui", "novoline") end },
        "divider",
        { label = "Hide hub", icon = "eye-off", hint = Config.keyLabel(Config.get("app.key.menu")), run = function() Window.show(false) end },
        { label = "Unload BASED", icon = "power", danger = true, run = function() B.unload() end },
      }, { side = "above", align = "left", width = 214 })
    end,
  })

  -- ---- header
  local header = UI.frame(glass, { Name = "Header", Size = UDim2.new(0, CONTENT_W, 0, HEADER), Position = UDim2.fromOffset(CONTENT_X, 6) })
  Window.header = header
  Window.eyebrow = UI.text(header, "", "eyebrow", "faint", { Position = UDim2.fromOffset(2, 13) })
  local titleClip = UI.frame(header, { Name = "TitleClip", Size = UDim2.new(1, -250, 0, 46), Position = UDim2.fromOffset(0, 27), ClipsDescendants = true })
  Window.titleClip = titleClip
  -- search pill
  local search = UI.frame(header, { Name = "Search", Size = UDim2.fromOffset(170, 32), AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -78, 0, 22),
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill1A" } })
  UI.corner(search, true)
  UI.stroke(search, "ink", "strokeA")
  UI.icon(search, "search", 15, "faint", { Position = UDim2.new(0, 12, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
  UI.text(search, "Search", "body", "faint", { Position = UDim2.new(0, 34, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
  local hint = UI.frame(search, { Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -8, 0.5, 0),
    Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
  UI.corner(hint, 6); UI.pad(hint, 0, 6)
  UI.text(hint, "Ctrl K", "mono", "faint", { TextSize = 10.5, Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X })
  UI.button(search, {
    hover = function(on) Motion.to(search, "BackgroundTransparency", on and T.fill2A or T.fill1A, "quick") end,
    click = function() Window.palette() end,
  })
  -- window buttons
  local function roundButton(icon, x, tone, run, tip)
    local button = UI.frame(header, { Size = UDim2.fromOffset(30, 30), AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, x, 0, 23),
      Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill1A" } })
    UI.corner(button, true)
    local glyph = UI.icon(button, icon, 15, "sub", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
    local scale = UI.scaleOf(button)
    local hit = UI.button(button, {
      hover = function(on)
        Motion.to(button, "BackgroundTransparency", on and (tone and 0.8 or T.fill3A) or T.fill1A, "quick")
        Theme.bind(button, "BackgroundColor3", on and tone or "ink")
        Theme.bind(glyph, "ImageColor3", on and (tone or "ink") or "sub")
      end,
      press = function(on) Motion.to(scale, "Scale", on and 0.9 or 1, on and "quick" or "bouncy") end,
      click = run,
    })
    UI.tooltip(hit, tip)
  end
  roundButton("x", -4, "bad", function() Window.show(false) end, "Hide (" .. Config.keyLabel(Config.get("app.key.menu")) .. ")")
  roundButton("minus", -40, nil, function() Window.show(false) end, "Minimise to the island")

  -- ---- pages
  Window.pageHost = UI.frame(glass, { Name = "Pages", Size = UDim2.new(0, CONTENT_W, 1, -(HEADER + 16)), Position = UDim2.fromOffset(CONTENT_X, HEADER + 6), ClipsDescendants = true })
  -- soft edge where content scrolls under the header
  local fade = UI.frame(glass, { Name = "EdgeTop", Size = UDim2.new(0, CONTENT_W, 0, 14), Position = UDim2.fromOffset(CONTENT_X, HEADER + 6), ZIndex = 7,
    Theme = { BackgroundColor3 = "base" }, BackgroundTransparency = 0, Interactable = false })
  UI.gradient(fade, { Rotation = 90, Transparency = UI.alphaSeq(0, 0.25, 1, 1) })
  Window.edgeTop = fade

  UI.mountOverlay(gui, function() return sizer.Scale end)

  -- ---- drag (header and sidebar brand), spring-followed
  local position = Motion.spring(2, "snappy", function(x) holder.Position = UDim2.fromOffset(x[1], x[2]) end, 0.2)
  Window.position = position
  local function clampTo(x, y)
    local view = B.viewport()
    local hw, hh = W * sizer.Scale / 2, H * sizer.Scale / 2
    return math.clamp(x, 140 - hw, view.X + hw - 140), math.clamp(y, hh * 0.25, view.Y + hh - 80)
  end
  Window.clampTo = clampTo
  local startX, startY
  local function dragFrom(handle)
    UI.drag(handle, function()
      UI.closePopovers()
      startX, startY = position.g[1], position.g[2]
    end, function(_, delta)
      local x, y = clampTo(startX + delta.X, startY + delta.Y)
      position:to({ x, y }, "quick")
    end, function()
      local view = B.viewport()
      Config.set("app.window.x", position.g[1] / view.X)
      Config.set("app.window.y", position.g[2] / view.Y)
    end)
  end
  local grip = UI.new("TextButton", { Name = "Grip", Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.new(1, -260, 1, 0), ZIndex = 2, Parent = header })
  dragFrom(grip)
  local grip2 = UI.new("TextButton", { Name = "Grip", Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.fromScale(1, 1), ZIndex = 2, Parent = brand })
  dragFrom(grip2)

  -- the rim highlight leans toward the pointer: glass catching a light
  local rimAngle = Motion.spring(1, "gentle", function(x) rim.Rotation = x[1] end, 0.05)
  rimAngle:snap({ 52 })
  Motion.every(function()
    if not Window.open then return end
    local mouse = UI.mouse()
    local p, s = holder.AbsolutePosition, holder.AbsoluteSize
    local dx, dy = mouse.X - (p.X + s.X / 2), mouse.Y - (p.Y + s.Y / 2)
    -- the gradient's bright end sits at angle+180: point it at the cursor
    local angle = math.deg(math.atan2(dy, dx)) + 180
    local current = rimAngle.g[1]
    local diff = (angle - current + 180) % 360 - 180
    if math.abs(diff) > 1.5 then rimAngle:to({ current + diff }) end
  end, 30, "window.rim")

  Window.rebuildNav()
  Window.rescale()
  B.connect(workspace.CurrentCamera:GetPropertyChangedSignal("ViewportSize"), function() Window.rescale() end, "window.viewport")
end

function Window.rescale()
  if not Window.built then return end
  local view = B.viewport()
  local auto = math.clamp(math.min(view.Y / 1090, view.X / 1500), 0.55, 1.5)
  local user = (Config.get("app.scale") or 100) / 100
  local scale = math.min(auto * user, (view.X - 24) / W, (view.Y - 24) / H)
  Window.scale = scale
  Motion.to(Window.sizer, "Scale", scale * (Window.open and 1 or 0.95), "smooth")
  local fx, fy = Config.get("app.window.x") or 0.5, Config.get("app.window.y") or 0.5
  local x, y = Window.clampTo(fx * view.X, fy * view.Y)
  Window.position:snap({ x, y })
end

-- ---------------------------------------------------------------- nav
local selected = Motion.spring(2, "snappy", function(x)
  local pill = Window.navPill
  if not pill then return end
  local a, b = math.min(x[1], x[2]), math.max(x[1], x[2])
  pill.Position = UDim2.fromOffset(0, a)
  pill.Size = UDim2.new(1, 0, 0, math.max(8, b - a))
end, 0.15)
function Window.rebuildNav()
  local host = Window.navHost
  for _, item in ipairs(navItems) do item.frame:Destroy() end
  for _, child in ipairs(host:GetChildren()) do
    if child.Name == "Group" then child:Destroy() end
  end
  table.clear(navItems)
  local y = 0
  local lastGroup
  for _, page in ipairs(Window.order) do
    if not page.hidden then
      if page.group ~= lastGroup then
        lastGroup = page.group
        if page.group ~= "" then
          y += 10
          local label = UI.text(host, string.upper(page.group), "eyebrow", "faint", { Name = "Group", Position = UDim2.fromOffset(12, y), TextSize = 9 })
          label.Name = "Group"
          y += 22
        end
      end
      local item = UI.frame(host, { Name = "Item", Size = UDim2.new(1, 0, 0, 34), Position = UDim2.fromOffset(0, y), Theme = { BackgroundColor3 = "ink" }, ZIndex = 2 })
      UI.corner(item, "rControl")
      local icon = UI.icon(item, page.icon, 17, "sub", { Position = UDim2.new(0, 12, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      local label = UI.text(item, page.title, "label", "sub", { Position = UDim2.new(0, 39, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13.5 })
      if page.badge then UI.badge(item, page.badge, "accent", { Position = UDim2.new(1, -10, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) }) end
      local entry = { frame = item, icon = icon, label = label, page = page, y = y }
      navItems[#navItems + 1] = entry
      UI.button(item, {
        hover = function(on)
          if Window.current == page then return end
          Motion.to(item, "BackgroundTransparency", on and 0.955 or 1, "quick")
        end,
        click = function() Window.go(page.id) end,
      })
      y += 36
    end
  end
  host.CanvasSize = UDim2.fromOffset(0, y + 6)
  if Window.current then Window.selectNav(Window.current, true) end
end
function Window.selectNav(page, instant)
  local target
  for _, entry in ipairs(navItems) do
    local on = entry.page == page
    Theme.bind(entry.icon, "ImageColor3", on and "accent" or "sub")
    Theme.bind(entry.label, "TextColor3", on and "ink" or "sub")
    Motion.to(entry.frame, "BackgroundTransparency", 1, "quick")
    if on then target = entry end
  end
  if not target then Window.navPill.Visible = false; return end
  local a, b = target.y, target.y + 34
  -- (scrolled so the chosen tab is in view)
  local host, scroll = Window.navHost, Window.navScroll
  if host and scroll then
    local view = host.AbsoluteWindowSize.Y / math.max(UI.unit(), 0.01)
    local at = host.CanvasPosition.Y / math.max(UI.unit(), 0.01)
    if a < at + 4 then scroll.to((a - 12) * UI.unit(), instant) elseif b > at + view - 4 then scroll.to((b - view + 12) * UI.unit(), instant) end
  end
  if instant or not Window.navPill.Visible then
    Window.navPill.Visible = true
    selected:snap({ a, b })
    return
  end
  -- liquid: the edge facing the destination moves first, the other one follows
  local down = a > selected.g[1]
  if down then selected:to({ selected.g[1], b }, "snappy") else selected:to({ a, selected.g[2] }, "snappy") end
  task.delay(0.05, function() if Window.current == page then selected:to({ a, b }, "liquid") end end)
end

-- title: the old one slides up out of a mask, the new one rises into it
function Window.setTitle(page, instant)
  local clip = Window.titleClip
  local old = Window.titleLabel
  local label = UI.text(clip, page.title, "display", "ink", { Position = UDim2.fromOffset(0, instant and 2 or 46), Name = "Title" })
  Window.titleLabel = label
  Window.eyebrow.Text = string.upper(page.eyebrow or (page.group ~= "" and page.group or "BASED"))
  if instant then
    if old then old:Destroy() end
    return
  end
  Motion.to(label, "Position", UDim2.fromOffset(0, 2), "smooth")
  if old then Motion.to(old, "Position", UDim2.fromOffset(0, -46), "smooth", function() old:Destroy() end) end
end

-- ---------------------------------------------------------------- show / hide
function Window.show(on, instant)
  if not Window.built or Window.open == on then return end
  Window.open = on
  UI.closePopovers()
  UI.hideTip()
  local holder, root, sizer = Window.holder, Window.root, Window.sizer
  Window.modal.Visible = on and Config.get("app.freeCursor") ~= false
  if on then
    holder.Visible = true
    if not Window.current and Window.order[1] then Window.go(Window.startPage or Window.order[1].id, true) end
    if instant then
      UI.setFade(root, 1); Motion.snap(sizer, "Scale", Window.scale)
      if Window.shadow then Window.shadow.Transparency = T.shadowA end
    else
      UI.setFade(root, 0)
      Motion.snap(sizer, "Scale", Window.scale * 0.94)
      UI.fade(root, 1, "smooth")
      Motion.to(sizer, "Scale", Window.scale, "bouncy")
      if Window.shadow then Motion.to(Window.shadow, "Transparency", T.shadowA, "gentle") end
      UI.sfx("open", 0.8)
    end
    Blur.show(true)
  else
    if Window.shadow then Motion.to(Window.shadow, "Transparency", 1, "quick") end
    Motion.to(sizer, "Scale", Window.scale * 0.96, "quick")
    Blur.show(false)
    UI.fade(root, 0, "quick", function() if not Window.open then holder.Visible = false end end)
    if not root:IsA("CanvasGroup") then holder.Visible = false end
    UI.sfx("close", 0.7)
  end
  Window.onShow:fire(on)
end
function Window.toggle() Window.show(not Window.open) end
-- any look of the hub is up: the BASED window, the Unnamed menu (src/52) or the Novoline one (src/53)
function Window.anyOpen()
  return Window.open or (B.Unnamed ~= nil and B.Unnamed.open == true) or (B.Novoline ~= nil and B.Novoline.open == true)
end
-- a tab on screen in any look. (Live parts of a tab asked the BASED window alone, and stood still
-- in the other looks.)
function Window.showing(id)
  if Window.open and Window.current ~= nil and Window.current.id == id then return true end
  local unnamed, novoline = B.Unnamed, B.Novoline
  if unnamed ~= nil and unnamed.open == true and unnamed.current == id then return true end
  return novoline ~= nil and novoline.open == true and novoline.current == id
end
-- which look is in use, and opening or closing it (the menu key)
function Window.look()
  local look = Config.get("app.gui")
  if look == "unnamed" and B.Unnamed then return "unnamed" end
  if look == "novoline" and B.Novoline then return "novoline" end
  return "based"
end
function Window.showActive(on)
  local look = Window.look()
  if look == "unnamed" then B.Unnamed.show(on) elseif look == "novoline" then B.Novoline.show(on) else Window.show(on) end
end
function Window.toggleActive()
  local look = Window.look()
  if look == "unnamed" then B.Unnamed.toggle() elseif look == "novoline" then B.Novoline.toggle() else Window.toggle() end
end

-- ---------------------------------------------------------------- the look kit
-- A tab that draws part of itself (the music player, a preview) takes its colours, letters and
-- corners from the look it is drawn in: Window.kit(frame). The BASED one is here; the Unnamed and
-- Novoline looks put theirs in Window.kits with an `owns(frame)` that says a frame is theirs.
--   kit.paint(instance, property, role)  set a colour and keep it in step (theme, accent)
--   kit.fill(instance, role)             a surface: colour and see-through together
--   kit.text(parent, value, props, bold, size), kit.entry(parent, size)  in the look's letters
--   kit.clear(instance)                  no surface (after a hover)
--   kit.outline(frame), kit.corner(frame, radius), kit.menu(anchor, items)
-- roles: card field hover line back text dim faint accent onAccent good bad
local ROLES = {
  card = { "ink", "fill1A" }, field = { "ink", "fill2A" }, hover = { "ink", "fill3A" }, line = { "ink", "strokeA" }, back = { "base", "baseA" },
  text = { "ink" }, dim = { "sub" }, faint = { "faint" }, accent = { "accent" }, onAccent = { "accentInk" }, good = { "ok" }, bad = { "bad" },
}
local kit = { look = "based", radius = 14, small = 9, size = 13 }
function kit.color(role)
  local r = ROLES[role] or ROLES.text
  return T[r[1]], r[2] and T[r[2]] or 0
end
function kit.paint(instance, property, role)
  Theme.bind(instance, property, (ROLES[role] or ROLES.text)[1])
end
function kit.fill(instance, role)
  local r = ROLES[role] or ROLES.card
  Theme.bind(instance, "BackgroundColor3", r[1])
  if r[2] then Theme.bind(instance, "BackgroundTransparency", r[2]) else
    Theme.unbind(instance, "BackgroundTransparency")
    instance.BackgroundTransparency = 0
  end
end
-- no surface at all (after a hover): the theme lets go of it too
function kit.clear(instance)
  Theme.unbind(instance, "BackgroundTransparency")
  instance.BackgroundTransparency = 1
end
function kit.font(bold) return bold and B.F.text600 or B.F.text500 end
function kit.text(parent, value, props, bold, size)
  local label = UI.text(parent, value, bold and "heading" or "label", "ink", { AutomaticSize = Enum.AutomaticSize.None, TextSize = size or 13 })
  if props then for key, v in pairs(props) do label[key] = v end end
  return label
end
function kit.entry(parent, size)
  local entry = Instance.new("TextBox")
  entry.BackgroundTransparency, entry.BorderSizePixel = 1, 0
  entry.FontFace = B.F.text500
  UI.fontKey[entry] = "text500"
  entry.TextSize = size or 13
  entry.TextXAlignment, entry.ClearTextOnFocus, entry.ClipsDescendants = Enum.TextXAlignment.Left, false, true
  Theme.bind(entry, "TextColor3", "ink")
  Theme.bind(entry, "PlaceholderColor3", "faint")
  entry.Parent = parent
  return entry
end
function kit.outline(frame) return UI.stroke(frame, "ink", "strokeA") end
function kit.corner(frame, radius) return UI.corner(frame, radius or kit.radius) end
function kit.menu(anchor, items) return UI.menu(anchor, items, { align = "right" }) end
Window.kits = { based = kit }
function Window.kit(frame)
  for name, other in pairs(Window.kits) do
    if name ~= "based" and other.owns and frame and other.owns(frame) then return other end
  end
  return kit
end
-- the kit of the look in use (for what sits on the HUD, outside any window)
function Window.activeKit() return Window.kits[Window.look()] or kit end

-- ---------------------------------------------------------------- command palette
local palette
function Window.palette()
  if palette then palette.close(); return end
  if not Window.built then return end
  if not Window.open then Window.show(true) end
  -- everything has to exist before it can be found
  for _, page in ipairs(Window.order) do ensureBuilt(page) end
  local scale = Window.scale
  local view = B.viewport()
  local veil = UI.new("TextButton", { Name = "Veil", Text = "", AutoButtonColor = false, Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 1, ZIndex = 70, Parent = UI.overlay })
  Motion.to(veil, "BackgroundTransparency", 0.62, "smooth")
  -- over the hub, wherever the hub has been dragged to
  local at, size = Window.holder.AbsolutePosition - UI.overlay.AbsolutePosition, Window.holder.AbsoluteSize
  local half = 270 * scale
  local holder = UI.frame(veil, { Name = "Palette", Size = UDim2.fromOffset(540, 0), AutomaticSize = Enum.AutomaticSize.Y, AnchorPoint = Vector2.new(0.5, 0),
    Position = UDim2.fromOffset(math.clamp(at.X + size.X * 0.5, half + 12, math.max(half + 12, view.X - half - 12)), math.clamp(at.Y + 72 * scale, 16, math.max(16, view.Y - 420 * scale))),
    ZIndex = 71 })
  local sizer = Instance.new("UIScale"); sizer.Scale = scale * 0.95; sizer.Parent = holder
  Motion.to(sizer, "Scale", scale, "bouncy")
  local glass = UI.glass(holder, { level = "popover", radius = "rPanel", shadow = 60, shadowY = 26, props = { Size = UDim2.fromScale(1, 0), AutomaticSize = Enum.AutomaticSize.Y, Active = true } })
  local stack = UI.frame(glass, { Size = UDim2.fromScale(1, 0), AutomaticSize = Enum.AutomaticSize.Y })
  UI.list(stack, "y", 0)
  local top = UI.frame(stack, { Size = UDim2.new(1, 0, 0, 54), LayoutOrder = 1 })
  UI.icon(top, "search", 18, "sub", { Position = UDim2.new(0, 18, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
  local box = UI.new("TextBox", { BackgroundTransparency = 1, Size = UDim2.new(1, -110, 1, 0), Position = UDim2.fromOffset(48, 0), Text = "", PlaceholderText = "Search every setting and tab",
    FontFace = B.F.text500, TextSize = 16, TextXAlignment = Enum.TextXAlignment.Left, ClearTextOnFocus = false, Theme = { TextColor3 = "ink", PlaceholderColor3 = "faint" }, Parent = top })
  UI.text(top, "esc", "mono", "faint", { Position = UDim2.new(1, -18, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11 })
  UI.divider(stack, 2)
  local list = UI.frame(stack, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 3 })
  UI.pad(list, 6)
  UI.list(list, "y", 2)
  local rows, results, cursor = {}, {}, 1
  local connection
  local api = {}
  function api.close()
    if not palette then return end
    palette = nil
    if connection then connection:Disconnect() end
    Motion.to(veil, "BackgroundTransparency", 1, "quick", function() veil:Destroy() end)
    holder:Destroy()
  end
  local function highlight()
    for index, row in ipairs(rows) do
      Motion.to(row, "BackgroundTransparency", index == cursor and T.fill2A or 1, "quick")
    end
  end
  local function run(result)
    if not result then return end
    api.close()
    if result.kind == "page" then Window.go(result.page.id); return end
    Window.go(result.page.id)
    task.delay(0.12, function()
      local entry = result.entry
      if not entry.row.frame.Parent then return end
      local scroller = result.page.frame
      local offset = (entry.row.frame.AbsolutePosition.Y - scroller.AbsolutePosition.Y + scroller.CanvasPosition.Y) - 90 * Window.scale
      result.page.scroll.to(offset)
      entry.row.flash()
    end)
  end
  local function refresh()
    for _, row in ipairs(rows) do row:Destroy() end
    table.clear(rows); table.clear(results)
    local query = box.Text
    local scored = {}
    for _, page in ipairs(Window.order) do
      local score = util.fuzzy(query, page.title)
      if score then scored[#scored + 1] = { kind = "page", page = page, label = page.title, sub = "Tab", icon = page.icon, score = score + 1.5 } end
    end
    for _, entry in ipairs(Window.index) do
      local score = util.fuzzy(query, entry.label)
      if not score and query ~= "" and entry.desc ~= "" then
        local other = util.fuzzy(query, entry.desc)
        score = other and other - 4 or nil
      end
      if score then
        scored[#scored + 1] = { kind = "control", page = entry.page, entry = entry, label = entry.label, sub = entry.page.title .. "  ›  " .. tostring(entry.section),
          icon = entry.page.icon, score = score }
      end
    end
    table.sort(scored, function(a, b) return a.score > b.score end)
    for index = 1, math.min(8, #scored) do
      local result = scored[index]
      results[index] = result
      local row = UI.frame(list, { Size = UDim2.new(1, 0, 0, 40), LayoutOrder = index, Theme = { BackgroundColor3 = "ink" } })
      UI.corner(row, "rSmall")
      UI.icon(row, result.icon, 16, result.kind == "page" and "accent" or "sub", { Position = UDim2.new(0, 12, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      UI.text(row, result.label, "label", "ink", { Position = UDim2.new(0, 40, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13.5 })
      UI.text(row, result.sub, "caption", "faint", { Position = UDim2.new(1, -12, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11.5 })
      UI.button(row, { hover = function(on) if on then cursor = index; highlight() end end, click = function() run(result) end })
      rows[index] = row
    end
    if #scored == 0 then
      local row = UI.frame(list, { Size = UDim2.new(1, 0, 0, 56) })
      UI.text(row, "No setting matches “" .. query .. "”", "body", "faint", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      rows[1] = row
    end
    cursor = 1
    highlight()
  end
  box:GetPropertyChangedSignal("Text"):Connect(B.safe("palette", refresh))
  connection = UIS.InputBegan:Connect(B.safe("palette.key", function(input)
    if input.KeyCode == Enum.KeyCode.Down then cursor = math.min(#results, cursor + 1); highlight()
    elseif input.KeyCode == Enum.KeyCode.Up then cursor = math.max(1, cursor - 1); highlight()
    elseif input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.KeypadEnter then run(results[cursor])
    elseif input.KeyCode == Enum.KeyCode.Escape then api.close() end
  end))
  veil.Activated:Connect(function() api.close() end)
  palette = api
  refresh()
  box:CaptureFocus()
  UI.sfx("open", 0.6)
end
end
do -- 08_film.lua
-- ============================================================================
--  08 film     frame-sequence player
--
--  The client cannot play a local video file (measured: VideoFrame and
--  VideoPlayer both refuse), and caps a local image at 1024 px. So a film is a
--  numbered run of JPEGs, and a frame above 1024 px wide is two textures side by
--  side. Each frame is decoded ahead of time in a pool of image slots. A slot
--  waits as a 1 px image; the two frames due next are made full size at alpha
--  0.001 ("primed") so the client has really drawn them; showing a frame is then
--  nothing but an alpha change.
--
--  That priming step is not optional. Measured with a 60 fps screen recording
--  and on-screen frame counters (tools/probes/present_test.lua): resizing a
--  frame to full size at the moment it is shown left the picture BLANK in 45%
--  of the recorded frames, while IsLoaded and every counter in Lua said all was
--  well. Primed, the frame on screen matched the frame Lua had presented in
--  every recorded frame, with no blanks.
--
--  Measured headroom on the test machine (10 slots): 1024x576 decodes at 337
--  frames/s and two-tile 1820x1024 at 171 frames/s against the 60 needed; both
--  presented 240/240 frames with none skipped.
--
--  The clock is wall time from the moment playback starts, so a slow frame
--  skips pictures instead of drifting away from the sound. Frames are counted
--  in an unwrapped sequence (0, 1, 2 ... across loops), which keeps every
--  "is this one newer" comparison a plain integer test.
--
--  Window mode (opts.window) is for a film that is part of the interface rather
--  than the whole screen: it needs rounded corners and may fade into what is
--  behind it, and a clip can do neither. Measured in this client's hidden UI: a
--  CanvasGroup neither clips its children nor takes a gradient, while a UICorner
--  and a UIGradient on the image itself both work, and a corner radius can be
--  set one corner at a time. So in window mode each tile is exactly the part of
--  the picture that shows, cut out of its texture by ImageRect, rounded on its
--  outer corners only and carrying its share of the fade.
-- ============================================================================
local S, Assets, fs = B.S, B.Assets, B.fs
local Film = { spec = B.FILM }
B.Film = Film

local HIDDEN = 0.999   -- a fully transparent image is never decoded; this one is
-- A waiting slot is a 1 px image parked at the CENTRE of the picture. Measured: an image that is
-- clipped out of view is never loaded, and a picture that covers a wider container overflows it,
-- so slots parked at its top-left corner sat off screen and the film stayed black.

function Film.has(setName, spec)
  spec = spec or Film.spec
  local set = spec and spec.sets and spec.sets[setName]
  if not set then return false end
  for _, tile in ipairs(set.tiles) do
    for _, index in ipairs({ 0, spec.count - 1 }) do
      if not Assets.frameIsFree(tile.path, index) and not fs.exists(fs.path(tile.path .. string.format("%0" .. set.digits .. "d.jpg", index))) then
        return false
      end
    end
  end
  return true
end
-- which set to play: the preference, falling back to whatever is installed
function Film.pick(preference, spec)
  local want = preference
  if want ~= "ultra" and want ~= "hd" then want = B.viewport().Y >= 800 and "ultra" or "hd" end
  if Film.has(want, spec) then return want end
  local other = want == "ultra" and "hd" or "ultra"
  if Film.has(other, spec) then return other end
  return nil
end
-- the part of a transparency ramp ({ { at, value }, ... }) between two fractions of its length
local function slice(points, a, b)
  local function at(t)
    local before = points[1]
    for _, point in ipairs(points) do
      if point[1] >= t then
        local span = point[1] - before[1]
        return span <= 0 and point[2] or before[2] + (point[2] - before[2]) * (t - before[1]) / span
      end
      before = point
    end
    return before[2]
  end
  local out = { NumberSequenceKeypoint.new(0, at(a)) }
  for _, point in ipairs(points) do
    if point[1] > a + 1e-3 and point[1] < b - 1e-3 then out[#out + 1] = NumberSequenceKeypoint.new((point[1] - a) / (b - a), point[2]) end
  end
  out[#out + 1] = NumberSequenceKeypoint.new(1, at(b))
  return NumberSequence.new(out)
end

-- opts: spec (which film: the intro unless given), set, slots, from / to (frame range), start
--       (film seconds), loop, audio, muted, volume, zIndex, window (see the header), backdrop,
--       budget (getcustomasset calls allowed per rendered frame), warmTo (last frame to pre-register),
--       clock (a function giving seconds: two players handed the same one are always on the same
--       frame, and one of them can be stopped and started without the other noticing)
function Film.new(parent, opts)
  local spec = opts.spec or Film.spec
  local set = spec and spec.sets[opts.set or "hd"]
  if not set then return nil end
  local fps, digits = spec.fps, set.digits
  local first, last = opts.from or 0, opts.to or (spec.count - 1)
  local length = last - first + 1
  local gapA, gapB = -1, -2          -- a film with no blackout: no frame is ever inside it
  if spec.gap then gapA, gapB = spec.gap[1], spec.gap[2] end
  local windowed = opts.window == true
  local slotCount = opts.slots or 10
  local budget = opts.budget or 2
  local tiles = set.tiles
  local self = { time = opts.start or first / fps, shown = -1, playing = false, ended = false, dead = false, volume = opts.volume or 0.5,
    muted = opts.muted == true, stats = { presented = 0, skipped = 0, late = 0, registered = 0 }, fps = fps, set = opts.set or "hd",
    length = length / fps, fresh = 0 }

  local frame = Instance.new("Frame")
  frame.Name = "Film"
  frame.BackgroundColor3 = Color3.new(0, 0, 0)
  frame.BackgroundTransparency = opts.backdrop == false and 1 or 0
  frame.BorderSizePixel = 0
  frame.Size = UDim2.fromScale(1, 1)
  frame.ClipsDescendants = true
  frame.ZIndex = opts.zIndex or 1
  frame.Parent = parent
  self.frame = frame
  -- the picture covers the container at the film's own aspect
  local picture = Instance.new("Frame")
  picture.Name = "Picture"
  picture.BackgroundTransparency = 1
  picture.BorderSizePixel = 0
  picture.AnchorPoint = Vector2.new(0.5, 0.5)
  picture.Position = UDim2.fromScale(0.5, 0.5)
  if windowed then picture.Size = UDim2.fromScale(1, 1) end
  picture.Parent = frame
  self.picture = picture
  local zoom = Instance.new("UIScale")
  zoom.Parent = picture
  self.zoom = zoom

  local rects = {}
  local slots = {}
  local current
  -- window mode: per tile, the part of it that shows (nil when none of it does)
  local cuts = {}
  local look = { tl = 0, tr = 0, br = 0, bl = 0, fade = nil, focusX = 0.5, focusY = 0.5 }
  self.look = look
  local function place(slot)
    for index, image in ipairs(slot.images) do
      if windowed then
        local cut = cuts[index]
        if cut then
          image.Position = UDim2.fromScale(cut.x, 0)
          image.Size = UDim2.fromScale(cut.w, 1)
          image.ImageRectOffset = Vector2.new(cut.rectX, cut.rectY)
          image.ImageRectSize = Vector2.new(cut.rectW, cut.rectH)
        else
          -- out of the window, but it still has to load for its frame to count as ready
          image.Position = UDim2.fromScale(0.5, 0.5)
          image.Size = UDim2.fromOffset(1, 1)
        end
      else
        image.Position = UDim2.fromOffset(rects[index][1], 0)
        image.Size = UDim2.new(0, rects[index][2], 1, 0)
      end
    end
  end
  local function dress()
    for _, slot in ipairs(slots) do
      for index in ipairs(slot.images) do
        local cut = cuts[index]
        if cut then
          local corner, fade = slot.corners[index], slot.fades[index]
          corner.TopLeftRadius, corner.BottomLeftRadius = UDim.new(0, cut.first and look.tl or 0), UDim.new(0, cut.first and look.bl or 0)
          corner.TopRightRadius, corner.BottomRightRadius = UDim.new(0, cut.last and look.tr or 0), UDim.new(0, cut.last and look.br or 0)
          if look.fade then
            fade.Transparency = slice(look.fade, cut.x, cut.x + cut.w)
            fade.Enabled = true
          elseif fade.Enabled then
            fade.Enabled = false
          end
        end
      end
    end
  end
  local function layout()
    local size = frame.AbsoluteSize
    if size.X < 2 or size.Y < 2 then return end
    if windowed then
      local W, H = math.floor(size.X + 0.5), math.floor(size.Y + 0.5)
      local scale = math.max(W / set.width, H / set.height)             -- screen pixels per film pixel
      local vw, vh = math.min(W / scale, set.width), math.min(H / scale, set.height)
      local vx, vy = (set.width - vw) * look.focusX, (set.height - vh) * look.focusY
      for index, tile in ipairs(tiles) do
        local t0, t1 = tile.x * set.width, (tile.x + tile.w) * set.width
        local a, b = math.max(t0, vx), math.min(t1, vx + vw)
        if b - a < 0.5 then
          cuts[index] = nil
        else
          -- Whole screen pixels, written as fractions of the container: exact under any UIScale,
          -- and both tiles round the seam between them from the same number. The rect follows
          -- the rounded pixel, and may reach a hair into the overlap the tiles were cut with.
          local x0 = a <= vx + 0.01 and 0 or math.floor((a - vx) * scale + 0.5)
          local x1 = b >= vx + vw - 0.01 and W or math.floor((b - vx) * scale + 0.5)
          cuts[index] = { x = x0 / W, w = (x1 - x0) / W, first = x0 == 0, last = x1 == W,
            rectX = tile.rectX + (vx + x0 / scale - t0), rectY = vy, rectW = (x1 - x0) / scale, rectH = vh }
        end
      end
      dress()
      for _, slot in ipairs(slots) do
        if slot == current or slot.primed then place(slot) end
      end
      return
    end
    local scale = math.max(size.X / set.width, size.Y / set.height)
    local w, h = math.ceil(set.width * scale), math.ceil(set.height * scale)
    picture.Size = UDim2.fromOffset(w, h)
    -- whole pixels per tile, so two halves never leave a seam or overlap
    local x = 0
    for index, tile in ipairs(tiles) do
      local right = index == #tiles and w or math.floor((tile.x + tile.w) * w + 0.5)
      rects[index] = { x, right - x }
      x = right
    end
    for _, slot in ipairs(slots) do
      if slot == current or slot.primed then place(slot) end
    end
  end
  for index = 1, slotCount do
    local slot = { images = {}, corners = {}, fades = {}, seq = nil }
    for t, tile in ipairs(tiles) do
      local image = Instance.new("ImageLabel")
      image.Name = "T" .. t
      image.BackgroundTransparency = 1
      image.BorderSizePixel = 0
      image.ScaleType = Enum.ScaleType.Stretch
      image.ImageRectOffset = Vector2.new(tile.rectX, 0)
      image.ImageRectSize = Vector2.new(tile.rectW, set.height)
      image.Size = UDim2.fromOffset(1, 1)
      image.Position = UDim2.fromScale(0.5, 0.5)
      image.ImageTransparency = HIDDEN
      if windowed then
        local corner = Instance.new("UICorner")
        corner.CornerRadius = UDim.new(0, 0)
        corner.Parent = image
        local fade = Instance.new("UIGradient")
        fade.Enabled = false
        fade.Parent = image
        slot.corners[t], slot.fades[t] = corner, fade
      end
      image.Parent = picture
      slot.images[t] = image
    end
    slots[index] = slot
  end
  layout()
  -- corner radii (tl, tr, br, bl, in the container's own units), a fade ({ { at, transparency }, ... }
  -- across the width, or false for none) and which part of the picture shows when it is cropped
  function self:setLook(next)
    local moved = false
    for key, value in pairs(next) do
      if (key == "focusX" or key == "focusY") and look[key] ~= value then moved = true end
      look[key] = value
    end
    if next.fade == false then look.fade = nil end
    if not windowed then return end
    if moved then layout() else dress() end
  end
  if opts.look then self:setLook(opts.look) end
  local resized = frame:GetPropertyChangedSignal("AbsoluteSize"):Connect(layout)

  local black = Instance.new("Frame")
  black.Name = "Black"
  black.BackgroundColor3 = Color3.new(0, 0, 0)
  black.BorderSizePixel = 0
  black.Size = UDim2.fromScale(1, 1)
  black.ZIndex = 2
  black.Visible = false
  black.Parent = frame

  local function indexOf(seq)
    return first + (opts.loop and seq % length or math.min(seq, length - 1))
  end
  local function inGap(index) return index >= gapA and index <= gapB end
  -- step a sequence number forward until it is on a frame that exists
  local function playable(seq)
    local index = indexOf(seq)
    if inGap(index) then seq += gapB - index + 1 end
    if not opts.loop and seq >= length then return nil end
    return seq
  end
  local function loaded(slot)
    for _, image in ipairs(slot.images) do
      if not image.IsLoaded then return false end
    end
    return true
  end
  local renderFrame = 0
  -- full size but invisible: drawn for real, so showing it later cannot blank
  local function prime(slot)
    if slot.primed then return end
    place(slot)
    slot.primed = renderFrame
  end
  local function reveal(slot, on)
    if on then
      if not slot.primed then place(slot) end
      local alpha = self.alpha or 1
      for index, image in ipairs(slot.images) do image.ImageTransparency = (windowed and not cuts[index]) and HIDDEN or 1 - alpha end
    else
      slot.primed = nil
      for _, image in ipairs(slot.images) do
        image.Size = UDim2.fromOffset(1, 1)
        image.Position = UDim2.fromScale(0.5, 0.5)
        image.ImageTransparency = HIDDEN
      end
    end
  end
  local function cost(index)
    local calls = 0
    for _, tile in ipairs(tiles) do
      if not Assets.frameIsFree(tile.path, index) then calls += 1 end
    end
    return calls
  end

  local assignedSeq, warmSeq, shownSeq = nil, nil, -1
  local spend = 0
  self.missing = false

  local function fill(horizon)
    for _, slot in ipairs(slots) do
      if not slot.seq and slot ~= current then
        local candidate = playable(math.max(assignedSeq and assignedSeq + 1 or horizon, horizon))
        if not candidate or candidate - horizon > slotCount + 1 then return end
        local index = indexOf(candidate)
        local need = cost(index)
        if need > spend then return end
        spend -= need
        self.stats.registered += need
        for t, tile in ipairs(tiles) do
          local id = Assets.frame(tile.path, index, digits)
          if not id then self.missing = true; return end
          slot.images[t].Image = id
        end
        slot.seq = candidate
        assignedSeq = candidate
      end
    end
  end
  local function warm()
    -- spare budget registers what comes next: those frames are free on every later launch
    local cursor = warmSeq or assignedSeq
    local guard = 0
    while spend > 0 and cursor and guard < 6 do
      guard += 1
      cursor = playable(cursor + 1)
      if not cursor then break end
      local index = indexOf(cursor)
      if opts.warmTo and index > opts.warmTo then break end
      if opts.loop and cursor >= length then break end
      local need = cost(index)
      if need > spend then break end
      if need > 0 then
        for _, tile in ipairs(tiles) do Assets.frame(tile.path, index, digits) end
        spend -= need
        self.stats.registered += need
      end
      warmSeq = cursor
    end
  end
  local function present(want)
    if inGap(indexOf(want)) then
      if not black.Visible then black.Visible = true end
      return
    end
    local best, waiting
    for _, slot in ipairs(slots) do
      local seq = slot.seq
      if seq and slot ~= current and seq <= want and seq > shownSeq and loaded(slot) then
        if slot.primed and renderFrame - slot.primed >= 1 then
          if not best or seq > best.seq then best = slot end
        elseif not waiting or seq > waiting.seq then
          waiting = slot
        end
      end
    end
    -- a frame that is due but was never primed (after a skip) gets one frame at full size first
    if waiting and (not best or waiting.seq > best.seq) then prime(waiting) end
    if best then
      reveal(best, true)
      if current then reveal(current, false); current.seq = nil end
      local jumped = best.seq - shownSeq - 1
      -- (the first picture after a start is not a skip: what lies before it was never due)
      if shownSeq >= 0 and jumped > 0 and jumped < 30 and self.fresh > 0 and not inGap(indexOf(shownSeq + 1)) then self.stats.skipped += jumped end
      current, shownSeq = best, best.seq
      self.current, self.shown = best, indexOf(best.seq)
      self.stats.presented += 1
      self.fresh += 1
      if black.Visible then black.Visible = false end
    elseif shownSeq >= 0 and shownSeq < want then
      self.stats.late += 1
    end
  end
  local function recycle(want)
    for _, slot in ipairs(slots) do
      local seq = slot.seq
      if seq and slot ~= current then
        -- already superseded, or so far behind the clock it will never be the newest
        if seq <= shownSeq or (seq < want - 3 and not loaded(slot)) then
          slot.seq = nil
          if slot.primed then reveal(slot, false) end
        end
      end
    end
  end
  -- make the two frames due next full size now
  local function primeAhead()
    local a, b
    for _, slot in ipairs(slots) do
      local seq = slot.seq
      if seq and slot ~= current and seq > shownSeq then
        if not a or seq < a.seq then b = a; a = slot
        elseif not b or seq < b.seq then b = slot end
      end
    end
    if a then prime(a) end
    if b then prime(b) end
  end
  local function pump(want)
    spend = budget
    renderFrame += 1
    present(want)
    recycle(want)
    fill(playable(want) or want)
    primeAhead()
    if spend > 0 then warm() end
  end

  local sound
  if opts.audio and spec.audio then
    local id = Assets.id(spec.audio)
    if id then
      sound = Instance.new("Sound")
      sound.Name = "Track"
      sound.SoundId = id
      sound.Volume = 0
      sound.Looped = opts.loop == true
      -- not under the picture: the picture is moved between containers, and a sound that
      -- changes parent starts over
      sound.Parent = opts.soundHost or frame
      self.sound = sound
    end
  end
  function self:setVolume(volume)
    self.volume = volume
    if sound then sound.Volume = volume end
  end
  -- Silent means the sound is not running at all, not running at volume 0. Unmuted, it joins
  -- at the picture's own time.
  function self:setMuted(muted)
    muted = muted == true
    if self.muted == muted then return end
    self.muted = muted
    if sound and muted then sound:Pause() end
  end
  function self:setAlpha(alpha)
    self.alpha = alpha
    if current then
      for index, image in ipairs(current.images) do image.ImageTransparency = (windowed and not cuts[index]) and HIDDEN or 1 - alpha end
    end
  end

  local function seqAt(seconds) return math.max(0, math.floor((seconds - first / fps) * fps + 1e-6)) end
  -- Decode the opening frames before the clock starts; returns when `count` are ready.
  function self:prepare(count, timeout, onProgress)
    local startSeq = playable(seqAt(self.time)) or 0
    count = math.min(count or 6, slotCount)
    local waited = 0
    while waited < (timeout or 4) and not self.dead do
      spend = math.max(budget, 4)
      fill(startSeq)
      local ready = 0
      for _, slot in ipairs(slots) do
        if slot.seq and loaded(slot) then ready += 1 end
      end
      if onProgress then onProgress(math.min(1, ready / count)) end
      renderFrame += 1
      primeAhead()
      if ready >= count or self.missing then break end
      waited += S.RunService.RenderStepped:Wait()
    end
    -- one more rendered frame, so the first pictures have been drawn at full size
    S.RunService.RenderStepped:Wait()
    renderFrame += 1
    if sound then
      local soundWait = 0
      while not sound.IsLoaded and soundWait < 1.5 and not self.dead do soundWait += S.RunService.RenderStepped:Wait() end
    end
    return not self.missing
  end

  -- `held` is how far the clock had run when it was paused. A looping film cannot take that
  -- from its time, which wraps: the frame sequence does not, and would never catch up.
  local started, held, lastJoin = 0, nil, 0
  function self:play()
    if self.dead or self.playing then return end
    self.playing, self.ended = true, false
    started = os.clock() - (held or (self.time - first / fps))
    held = nil
    -- how many pictures it has shown since it was last started: on someone else's clock, what it
    -- holds from before is old, and the one still on show is not to be trusted until this moves
    self.fresh = 0
    if opts.clock then
      for _, slot in ipairs(slots) do
        if slot ~= current then
          slot.seq = nil
          if slot.primed then reveal(slot, false) end
        end
      end
      assignedSeq, warmSeq = nil, nil
    end
    if sound and sound.IsLoaded and not self.muted then
      sound.TimePosition = self.time
      sound.Volume = self.volume
      sound:Play()
      lastJoin = os.clock()
    end
  end
  function self:pause()
    if self.playing then held = os.clock() - started end
    self.playing = false
    if sound then sound:Pause() end
  end
  local lastSync = 0
  local connection = S.RunService.RenderStepped:Connect(function()
    if self.dead then return end
    if not frame.Parent then self:destroy(); return end
    if not self.playing then return end
    local now = os.clock()
    local elapsed = opts.clock and opts.clock() or now - started
    local loopLength = length / fps
    if sound and not self.muted then
      if not sound.IsPlaying then
        -- unmuted, or loaded late, or back from a pause: join at the picture's own time
        local at = first / fps + (opts.loop and elapsed % loopLength or elapsed)
        if sound.IsLoaded and now - lastJoin > 0.25 and (opts.loop or at < sound.TimeLength - 0.05) then
          sound.TimePosition = at
          sound.Volume = self.volume
          sound:Play()
          lastSync, lastJoin = now, now
        end
      elseif now - lastSync > 0.5 then
        -- follow the sound if the two drift apart (its position only updates in coarse steps)
        lastSync = now
        local drift = sound.TimePosition - (first / fps + (opts.loop and elapsed % loopLength or elapsed))
        if opts.loop then drift = (drift + loopLength / 2) % loopLength - loopLength / 2 end
        if math.abs(drift) > 0.12 and math.abs(drift) < 2 then
          if opts.clock then
            -- the clock is not ours to move: bring the sound to the picture instead
            sound.TimePosition = first / fps + (opts.loop and elapsed % loopLength or elapsed)
          else
            started -= drift * 0.5
            elapsed = now - started
          end
        end
      end
    end
    local want = math.floor(elapsed * fps)
    if not opts.loop and want >= length then
      self.time = (last + 1) / fps
      self.playing, self.ended = false, true
      if sound then sound:Stop() end
      if self.onEnded then B.try("film.ended", self.onEnded) end
      return
    end
    self.time = first / fps + (opts.loop and elapsed % (length / fps) or elapsed)
    local ok, err = pcall(pump, want)
    if not ok then B.fault("film", err); self:destroy() end
  end)

  function self:destroy()
    if self.dead then return end
    self.dead, self.playing = true, false
    connection:Disconnect()
    resized:Disconnect()
    if sound then
      pcall(function() sound:Stop() end)
      if sound.Parent ~= frame then sound:Destroy() end
    end
    frame:Destroy()
  end
  B.own(self)
  return self
end
end
do -- 09_loader.lua
-- ============================================================================
--  09 loader   the intro, cut to the film
--
--  Cinematic plays the whole edit, all 18.7 seconds of it, in three acts. Every
--  cue is a time in the film, read from the player's own clock, so type and
--  picture cannot drift apart.
--
--    opening    0.00   the film opens under letterbox bars, with a greeting
--    blackout   2.90   the edit goes black for three seconds: the wordmark
--                      assembles in the dark while the track builds
--    drop       5.93   the picture slams back under the wordmark, bars fly open
--    lines      9.22   the wordmark leaves on the edit's white flash; one line
--                      of type per cut, changing on the cut
--    finale    15.52   the wordmark returns with the key that opens the hub
--    out       18.62   white, and the hub is there when it clears
--
--    quick      4.75 -> 6.88 s of the film (wordmark, drop, out)
--    off        straight to the hub
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Assets, Film = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Assets, B.Film
local UIS = S.UserInputService
local Loader = { active = false }
B.Loader = Loader
local ease = Motion.ease
local win = Motion.window

local DROP = 5.9333
-- Each mode plays one film: "intro" (B.FILM, the BASED edit) or "reel" (B.REEL, the author's own
-- edit, tools/film.py --name reel). `drop` is that film's drop; `calm` where its picture settles
-- before it; `greet` when the greeting comes in and goes.
local MODES = {
  -- (type: how its words are set. editorial: serif italic rising out of a mask, side to side;
  -- impact: heavy wide capitals, spaced out, slammed in on the hit, a bar wiping under them)
  cinematic = { film = "intro", type = "editorial", drop = DROP, calm = 2.9, greet = { 0.7, 2.3 }, start = 0, exit = 18.62, word = 3.05, stagger = 0.11, rise = 0.78, hub = 3.78, rule = 4.2,
    status = 4.5, wordOut = 9.2167, wordBack = 15.5167, greeting = true,
    -- one line per cut of the edit, from the flash at 9.22 to the finale
    lines = {
      { 9.2167, "One hub." }, { 10.05, "Every game." }, { 10.75, "Engineered" }, { 11.3833, "for the game" }, { 12.3333, "you’re in." },
      { 13.15, "Universal" }, { 13.95, "everywhere else." }, { 14.65, "Aim. See. Move." },
    }, linesEnd = 15.5167 },
  quick = { film = "intro", drop = DROP, calm = 2.9, start = 4.75, exit = 6.8833, word = 4.8, stagger = 0.06, rise = 0.5, hub = 5.12, rule = 5.3, status = 5.42 },
  -- The author's edit (17.23 s), whole and with its own track, to its last frame (asked for: the full
  -- version). Two hits, a quiet build in space from 1.9 s, the drop at 4.62 s, then a hit every 1.15 s:
  -- the greeting in the quiet, the wordmark assembled over the build and hit on the drop, a line on
  -- each hit, and the wordmark back for the end.
  reel = { film = "reel", type = "impact", drop = 4.6167, calm = 4.4, greet = { 2.0, 3.35 }, margin = 0.125, start = 0, exit = 17.2333, whole = true, word = 3.35, stagger = 0.1, rise = 0.7, hub = 3.95,
    rule = 4.15, status = 4.35, wordOut = 7.0, wordBack = 15.05, greeting = true,
    lines = {
      { 7.0, "One hub." }, { 8.1667, "Every game." }, { 9.3, "Engineered for" }, { 10.4667, "the game you’re in." },
      { 11.6167, "Universal" }, { 12.7667, "everywhere else." }, { 13.9167, "Aim. See. Move." },
    }, linesEnd = 15.05 },
}
local function specOf(plan) return (plan and plan.film == "reel") and B.REEL or Film.spec end
-- installed, at some size?
function Loader.has(mode)
  local plan = MODES[mode]
  if not plan then return Loader.others[mode] ~= nil end
  local spec = specOf(plan)
  return spec ~= nil and not Assets.lite and Film.pick(Config.get("app.filmQuality"), spec) ~= nil
end
function Loader.spec(mode) return MODES[mode] end

local BONE, SOFT = Color3.fromRGB(245, 244, 239), Color3.fromRGB(158, 157, 166)

local function label(parent, text, font, size, color, props)
  local item = Instance.new("TextLabel")
  item.BackgroundTransparency = 1
  item.BorderSizePixel = 0
  item.FontFace = B.F[font]
  item.TextSize = size
  item.Text = text
  item.TextColor3 = color or BONE
  item.AutomaticSize = Enum.AutomaticSize.XY
  item.TextXAlignment = Enum.TextXAlignment.Left
  if props then
    for key, value in pairs(props) do item[key] = value end
  end
  item.Parent = parent
  return item
end
-- A line of type that rises out of a mask and leaves through the top of it.
-- side: "left" or "right" (which edge `position` anchors)
local function maskLine(parent, text, font, size, color, side, position)
  local right = side == "right"
  local clip = Instance.new("Frame")
  clip.BackgroundTransparency = 1
  clip.ClipsDescendants = true
  clip.AnchorPoint = Vector2.new(right and 1 or 0, 1)
  clip.Position = position
  clip.Size = UDim2.fromOffset(10, 10)
  clip.Parent = parent
  local item = label(clip, text, font, size, color)
  local function fit()
    local bounds, unit = item.AbsoluteSize, Loader.unit or 1
    clip.Size = UDim2.fromOffset(bounds.X / unit + 14, bounds.Y / unit + 6)
  end
  item:GetPropertyChangedSignal("AbsoluteSize"):Connect(fit)
  fit()
  local api = { clip = clip, label = item }
  -- enter 0..1 rises in from below; leave 0..1 carries it out through the top
  function api.set(enter, leave)
    local height = clip.Size.Y.Offset
    item.Position = UDim2.fromOffset(4, height * (1 - enter) - height * (leave or 0))
    item.TextTransparency = math.clamp(1 - enter * 1.6 + (leave or 0), 0, 1)
  end
  api.set(0, 0)
  return api
end

-- A line of heavy wide capitals, spaced out, centred: slammed in (from a third bigger, in a tenth
-- of a second and a half), a bar of the accent wiping in under it, and gone up and out. Same shape
-- as maskLine's: { clip, label, set(enter, leave) }.
local HAIR = utf8.char(0x200A)
local function spaced(text)
  local out = {}
  for _, code in utf8.codes(string.upper(text)) do out[#out + 1] = utf8.char(code) end
  return table.concat(out, HAIR)
end
local function impactLine(parent, text, font, size, color, position)
  local clip = Instance.new("Frame")
  clip.BackgroundTransparency = 1
  clip.AnchorPoint = Vector2.new(0.5, 1)
  clip.Position = position
  clip.Size = UDim2.fromOffset(10, 10)
  clip.AutomaticSize = Enum.AutomaticSize.XY
  clip.Parent = parent
  local scale = Instance.new("UIScale")
  scale.Parent = clip
  local item = label(clip, spaced(text), font, size, color, { TextXAlignment = Enum.TextXAlignment.Center })
  local bar = Instance.new("Frame")
  bar.BorderSizePixel = 0
  bar.BackgroundColor3 = B.T.accent
  bar.AnchorPoint = Vector2.new(0.5, 0)
  bar.Position = UDim2.new(0.5, 0, 1, 6)
  bar.Size = UDim2.new(0, 0, 0, 3)
  bar.Parent = clip
  local api = { clip = clip, label = item, bar = bar }
  function api.set(enter, leave)
    leave = leave or 0
    local hit = math.clamp(enter * 1.8, 0, 1)
    scale.Scale = 1 + 0.32 * (1 - hit) ^ 3 + 0.04 * leave
    item.Position = UDim2.fromOffset(0, -22 * leave)
    item.TextTransparency = math.clamp(1 - hit + leave * 1.4, 0, 1)
    bar.Size = UDim2.new(math.clamp(enter, 0, 1) * (1 - leave), 0, 0, 3)
    bar.BackgroundTransparency = math.clamp(0.1 + leave, 0, 1)
  end
  api.set(0, 0)
  return api
end

-- the intros there are (src/09b: "signal"), and the one Shuffle picks from
Loader.others = {}
Loader.SHUFFLE = { "reel", "cinematic", "signal" }
function Loader.run(done, override)
  -- getgenv().BASED_INTRO = "signal" | "cinematic" | "quick" | "shuffle" | "off" forces a mode for one launch (testing)
  local forced = B.genv.BASED_INTRO
  override = override or ((MODES[forced] or Loader.others[forced] or forced == "off" or forced == "shuffle") and forced or nil)
  local mode = override or Config.get("app.intro")
  if mode == "shuffle" then
    -- (a different one from last time, when there is a choice)
    local pool = {}
    for _, name in ipairs(Loader.SHUFFLE) do
      if (MODES[name] or Loader.others[name]) and name ~= Loader.lastShuffle then pool[#pool + 1] = name end
    end
    mode = pool[math.random(1, math.max(#pool, 1))] or "cinematic"
    Loader.lastShuffle = mode
  end
  if Loader.others[mode] then
    if Loader.active then return end
    Loader.active = true
    return Loader.others[mode](function()
      Loader.active = false
      done()
    end)
  end
  if mode == "off" or not MODES[mode] then
    done()
    return
  end
  if Loader.active then return end
  Loader.active = true
  -- (a film that is not installed: the other one, or the wordmark alone)
  if MODES[mode] and not Loader.has(mode) then
    if mode == "reel" and Loader.has("cinematic") then mode = "cinematic" elseif mode ~= "quick" then mode = "quick" end
  end
  local plan = MODES[mode]
  local spec = specOf(plan)
  local DROP = plan.drop or DROP
  local gui = B.screen(9500)
  gui:SetAttribute("OwnLetters", true)       -- (its words keep the film's letters whatever the hub's font)
  local view = B.viewport()
  local k = math.clamp(view.Y / 1080, 0.55, 2)
  Loader.unit = k

  local root = UI.frame(gui, { Name = "Intro", Size = UDim2.fromScale(1, 1) })
  -- a modal button: frees the cursor, and swallows clicks so nothing reaches the game
  local veil = UI.new("TextButton", { Name = "Veil", Text = "", AutoButtonColor = false, Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 1, BorderSizePixel = 0, Modal = true, Parent = root })
  Motion.to(veil, "BackgroundTransparency", 0, "smooth")
  local stage = UI.frame(root, { Name = "Stage", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local filmHost = UI.frame(stage, { Name = "FilmHost", Size = UDim2.fromScale(1, 1), ZIndex = 1 })

  -- ---- the player
  local setName = (not Assets.lite) and spec and Film.pick(Config.get("app.filmQuality"), spec) or nil
  local volume = Config.get("app.introVolume") / 100
  local player
  if setName then
    local exitFrame = math.min(spec.count - 1, math.floor(plan.exit * spec.fps) + 12)
    player = Film.new(filmHost, { spec = spec, set = setName, slots = 10, audio = volume > 0, volume = 0, start = plan.start, to = exitFrame, warmTo = exitFrame, budget = 2 })
  end
  local cuts = spec and spec.cuts or {}

  -- ---- grade: vignette, grain, bars
  UI.image(stage, "vignette", { Name = "Vignette", Size = UDim2.fromScale(1, 1), ImageTransparency = 0.25, ZIndex = 3 })
  local grain = UI.image(stage, "grain", { Name = "Grain", Size = UDim2.new(1, 600, 1, 600), Position = UDim2.fromOffset(-300, -300), ScaleType = Enum.ScaleType.Tile,
    TileSize = UDim2.fromOffset(512, 512), ImageTransparency = 0.925, ZIndex = 4 })
  local dim = UI.frame(stage, { Name = "Dim", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1, ZIndex = 5 })
  local barHeight = math.floor(view.Y * 0.085)
  local barTop = UI.frame(stage, { Name = "BarTop", Size = UDim2.new(1, 0, 0, barHeight), Position = UDim2.fromOffset(0, -barHeight), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 0, ZIndex = 6 })
  local barBottom = UI.frame(stage, { Name = "BarBottom", Size = UDim2.new(1, 0, 0, barHeight), Position = UDim2.new(0, 0, 1, 0), BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 0, ZIndex = 6 })

  -- ---- type, laid out in 1080p units and scaled to the screen
  local typeLayer = UI.frame(stage, { Name = "Type", Size = UDim2.fromScale(1 / k, 1 / k), ZIndex = 8 })
  local typeScale = Instance.new("UIScale"); typeScale.Scale = k; typeScale.Parent = typeLayer
  local W, H = view.X / k, view.Y / k
  -- (the author's edit has its own monitor strips down both sides: the type keeps inside them)
  local margin = plan.margin and math.floor(W * plan.margin) or 56
  local shadowed = { TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.72 }
  local function small(text, font, color, props)
    local item = label(typeLayer, text, font, 11, color, props)
    for key, value in pairs(shadowed) do item[key] = value end
    item.TextTransparency = 1
    return item
  end
  local topLeft = small("BASED HUB", "wideBold", BONE, { Position = UDim2.fromOffset(margin, 34) })
  local timecode = small("", "mono400", SOFT, { Position = UDim2.new(1, -margin, 0, 34), AnchorPoint = Vector2.new(1, 0) })
  local registry = B.Registry and B.Registry.status() or { engineered = false }
  local gameLine = registry.engineered and ("ENGINEERED FOR  ·  " .. string.upper(registry.name or "THIS GAME")) or "NO SCRIPT ENGINEERED FOR THIS GAME YET  ·  UNIVERSAL LOADED"
  local bottomLeft = small("V" .. B.VERSION .. "  ·  " .. (registry.engineered and "ENGINEERED" or "UNIVERSAL"), "mono400", SOFT, { Position = UDim2.new(0, margin, 1, -44) })
  local skip = small("SPACE TO SKIP", "mono400", SOFT, { Position = UDim2.new(1, -margin, 1, -44), AnchorPoint = Vector2.new(1, 0) })
  local progress = UI.frame(typeLayer, { Name = "Progress", Size = UDim2.new(0, 0, 0, 1), Position = UDim2.new(0, 0, 1, -1), BackgroundColor3 = BONE, BackgroundTransparency = 0.35 })

  local baseline = -(barHeight / k) - 30
  local greeting1, greeting2
  local impact = plan.type == "impact"
  if plan.greeting and impact then
    greeting1 = impactLine(typeLayer, "Good to see you", "wideBold", 22, SOFT, UDim2.new(0.5, 0, 1, baseline - 84))
    greeting2 = impactLine(typeLayer, B.LP.DisplayName, "wideBlack", 66, BONE, UDim2.new(0.5, 0, 1, baseline))
  elseif plan.greeting then
    greeting1 = maskLine(typeLayer, "Good to see you,", "serifItalic", 62, BONE, "left", UDim2.new(0, margin, 1, baseline - 70))
    greeting2 = maskLine(typeLayer, B.LP.DisplayName .. ".", "serifItalic", 62, BONE, "left", UDim2.new(0, margin, 1, baseline))
  end
  -- the per-cut lines alternate sides, so the eye is carried across the frame
  local lines = {}
  -- In a game that has a script of its own, the edit's two lines about Universal ("Universal",
  -- "everywhere else.") would be about somewhere else: they name the game instead, and the last
  -- line is the game's own if it has one.
  local words = {}
  for index, cue in ipairs(plan.lines or {}) do words[index] = cue[2] end
  local universal = table.find(words, "Universal")
  if registry.engineered and universal then
    words[universal], words[universal + 1] = registry.name or "This game", "is loaded."
    if words[universal + 2] then words[universal + 2] = registry.tagline or words[universal + 2] end
  end
  for index, cue in ipairs(plan.lines or {}) do
    local right = index % 2 == 0
    local line = impact and impactLine(typeLayer, words[index], "wideBlack", 64, BONE, UDim2.new(0.5, 0, 1, baseline))
      or maskLine(typeLayer, words[index], "serifItalic", 92, BONE, right and "right" or "left", UDim2.new(right and 1 or 0, right and -margin or margin, 1, baseline))
    line.clip.Visible = false
    line.label.TextStrokeColor3 = Color3.new(0, 0, 0)
    line.label.TextStrokeTransparency = 0.8
    lines[index] = { at = cue[1], untilTime = (plan.lines[index + 1] and plan.lines[index + 1][1]) or plan.linesEnd, line = line }
  end

  -- ---- wordmark: five glyph images that rise out of their own masks, then "hub"
  local mark = UI.frame(typeLayer, { Name = "Wordmark", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.47) })
  local markScale = Instance.new("UIScale"); markScale.Parent = mark
  local wm = Assets.manifest.wordmark
  local letters = {}
  local hubImage
  local markWidth, capPx = 0, math.min(H * 0.16, W * 0.085)
  if wm and wm.glyphs and Assets.id(wm.glyphs[1].image) then
    local s = capPx / wm.cap
    local x = 0
    for index, glyph in ipairs(wm.glyphs) do
      local w, h = glyph.w * s, glyph.h * s
      local clip = UI.frame(mark, { Name = glyph.char, Size = UDim2.fromOffset(w, h), Position = UDim2.fromOffset(x - wm.pad * s, 0), ClipsDescendants = true })
      local image = UI.new("ImageLabel", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Position = UDim2.fromScale(0, 1.05), Image = Assets.id(glyph.image) or "",
        ImageColor3 = BONE, Parent = clip })
      letters[index] = { image = image }
      x += glyph.advance * s * 0.972
    end
    local hub = wm.hub
    local hs = s * (wm.size / 560) * 0.98
    local hw, hh = hub.w * hs, hub.h * hs
    hubImage = UI.new("ImageLabel", { Name = "Hub", BackgroundTransparency = 1, Size = UDim2.fromOffset(hw, hh),
      Position = UDim2.fromOffset(x + 4 * s, (wm.pad + wm.cap) * s - hub.baseline * hs), Image = Assets.id(hub.image) or "", ImageColor3 = T.accent, ImageTransparency = 1, Parent = mark })
    markWidth = x + 4 * s + hw - hub.pad * hs * 2
    mark.Size = UDim2.fromOffset(markWidth, (wm.cap + wm.pad * 2) * s)
  else
    -- no art installed: set the wordmark in type
    local row = UI.frame(mark, { AutomaticSize = Enum.AutomaticSize.XY })
    UI.list(row, "x", 6, { v = "Bottom" })
    letters[1] = { text = label(row, "BASED", "wideBlack", 92, BONE, { LayoutOrder = 1, TextTransparency = 1 }) }
    hubImage = label(row, "hub", "serifItalic", 100, T.accent, { LayoutOrder = 2, TextTransparency = 1 })
    markWidth, capPx = 560, 70
    mark.Size = UDim2.fromOffset(markWidth, 110)
  end
  local glow = UI.image(typeLayer, "glow", { Name = "Glow", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.47), Size = UDim2.fromOffset(markWidth * 1.7, capPx * 5.5),
    ImageColor3 = T.accent, ImageTransparency = 1, ZIndex = 0 })
  local below = UI.frame(typeLayer, { Name = "Below", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.47, capPx * 0.5 + 34), Size = UDim2.fromOffset(markWidth, 60) })
  local rule = UI.frame(below, { Name = "Rule", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.fromScale(0.5, 0), Size = UDim2.new(0, 0, 0, 1), BackgroundColor3 = BONE, BackgroundTransparency = 0.45 })
  local statusLine = label(below, gameLine, "wideBold", 10.5, registry.engineered and BONE or SOFT, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 16),
    TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center, TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.75 })
  local keyHint = string.upper(Config.keyLabel(Config.get("app.key.menu"))) .. "  ·  OPENS AND CLOSES THE HUB"
  local flash = UI.frame(root, { Name = "Flash", Size = UDim2.fromScale(1, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, ZIndex = 20 })

  -- ---- prelude: decode the opening frames, and say how far along that is
  local ring = UI.image(typeLayer, "ring", { Name = "Ring", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(34, 34), ImageTransparency = 1 })
  local sweep = UI.gradient(ring, { Transparency = UI.alphaSeq(0, 0, 0.5, 0.2, 1, 1), Rotation = 0 })
  local percent = label(typeLayer, "00", "mono400", 11, SOFT, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.5, 30), TextTransparency = 1,
    TextXAlignment = Enum.TextXAlignment.Center })
  local spinning = true
  local spin = Motion.every(function(dt)
    if spinning then sweep.Rotation = (sweep.Rotation + dt * 300) % 360 end
  end, nil, "loader.spin")
  -- only show the spinner if this takes long enough to be noticed
  local showSpinner = Motion.after(0.3, function()
    if spinning then ring.ImageTransparency = 0.2; percent.TextTransparency = 0.3 end
  end, "loader.spinner")
  local wordImages = {}
  for _, entry in ipairs(letters) do
    if entry.image then wordImages[#wordImages + 1] = entry.image end
  end
  task.spawn(function() pcall(function() S.ContentProvider:PreloadAsync(wordImages) end) end)
  if player then
    player:prepare(8, 5, function(p) percent.Text = string.format("%02d", math.floor(p * 99)) end)
    if player.missing then player:destroy(); player = nil end
  else
    task.wait(0.25)
  end
  if not player then
    -- no film installed: the wordmark alone, on the quick cut's timing, then the hub
    plan = MODES.quick
    DROP = plan.drop
    for _, entry in ipairs(lines) do entry.line.clip:Destroy() end
    table.clear(lines)
    if greeting1 then greeting1.clip:Destroy(); greeting2.clip:Destroy(); greeting1, greeting2 = nil, nil end
  end
  spinning = false
  showSpinner.cancel(); spin.cancel()
  ring:Destroy(); percent:Destroy()
  if not B.alive then return end

  -- ---- run
  local clockStart = os.clock()
  local finished, exiting = false, false
  local punch = Motion.spring(1, "bouncy", function(x) markScale.Scale = x[1] end, 0.0005)
  punch:snap({ 1 })
  local shake = Motion.spring(2, { 0.5, 0.55 }, function(x) stage.Position = UDim2.fromOffset(x[1], x[2]) end, 0.05)
  local lastCut = plan.start
  local dropped = false
  local grainAt = 0
  local job, inputConnection
  local total = (spec and spec.duration or plan.exit)

  local function cleanup()
    if job then job.cancel() end
    if inputConnection then inputConnection:Disconnect() end
    Loader.active = false
    Loader.unit = nil
  end
  local function exit(skipped)
    if exiting then return end
    exiting = true
    -- out on white: a flash covers the swap from film to hub
    Motion.tween(0.07, ease.linear, function(p) flash.BackgroundTransparency = 1 - p end, function()
      local track = player and player.sound
      if track then
        track.Parent = gui
        player.sound = nil
        local from = track.Volume
        Motion.tween(skipped and 0.9 or 1.6, ease.outSine, function(p) track.Volume = from * (1 - p) end, function() track:Destroy() end)
      end
      Loader.last = { mode = mode, set = setName, skipped = skipped, stats = player and player.stats or nil, seconds = os.clock() - clockStart }
      if player then player:destroy() end
      stage:Destroy()
      veil:Destroy()
      cleanup()
      B.try("loader.done", done)
      Motion.tween(0.6, ease.outCubic, function(p) flash.BackgroundTransparency = p end, function() gui:Destroy() end)
    end)
  end
  inputConnection = UIS.InputBegan:Connect(function(input)
    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.Escape then
      if os.clock() - clockStart > 0.35 and not B.genv.BASED_NOSKIP then exit(true) end
    end
  end)
  B.own(inputConnection)

  if player then
    player:setAlpha(0)
    player:play()
  end
  local wordOut, wordBack = plan.wordOut, plan.wordBack
  job = Motion.every(function()
    local since = os.clock() - clockStart
    local t = player and player.time or (plan.start + since)
    -- picture and sound come up together
    local fadeIn = win(since, 0, 0.55, ease.outCubic)
    if player then
      player:setAlpha(fadeIn)
      if not exiting then player:setVolume(volume * fadeIn) end
      player.zoom.Scale = t < DROP and util.lerp(1.07, 1.0, win(t, plan.start, (plan.calm or 2.9) - plan.start + 0.01, ease.outCubic)) or util.lerp(1.05, 1.0, win(t, DROP, 0.7, ease.outExpo))
    end
    -- letterbox: in for the opening, thrown open by the drop
    local bars = win(since, 0.05, 0.7, ease.outQuint) * (1 - win(t, DROP - 0.02, 0.32, ease.outExpo))
    barTop.Position = UDim2.fromOffset(0, -barHeight * (1 - bars))
    barBottom.Position = UDim2.new(0, 0, 1, -barHeight * bars)
    local chrome = win(since, 0.3, 0.6, ease.outCubic)
    topLeft.TextTransparency = 1 - chrome
    timecode.TextTransparency = 1 - chrome * 0.8
    bottomLeft.TextTransparency = 1 - chrome * 0.75
    skip.TextTransparency = 1 - chrome * 0.6
    timecode.Text = string.format("%05.2f  /  %05.2f", t, total)
    progress.Size = UDim2.new(util.clamp01((t - plan.start) / (plan.exit - plan.start)), 0, 0, 1)

    -- opening greeting
    if greeting1 then
      local inAt, outAt = plan.greet and plan.greet[1] or 0.7, plan.greet and plan.greet[2] or 2.3
      greeting1.set(win(t, inAt, 0.85, ease.outExpo), win(t, outAt, 0.45, ease.inCubic))
      greeting2.set(win(t, inAt + 0.2, 0.85, ease.outExpo), win(t, outAt + 0.08, 0.45, ease.inCubic))
    end
    -- one line per cut: in on the cut, out just before the next
    for _, entry in ipairs(lines) do
      local on = t >= entry.at - 0.02 and t < entry.untilTime + 0.05
      if entry.line.clip.Visible ~= on then entry.line.clip.Visible = on end
      if on then
        entry.line.set(win(t, entry.at, 0.36, ease.outExpo), win(t, entry.untilTime - 0.16, 0.16, ease.inCubic))
      end
    end

    -- wordmark: in during the blackout, out on the flash, back for the finale
    local inhale = t < DROP and win(t, DROP - 0.16, 0.14, ease.inCubic) or 0
    local leaving = wordOut and t >= wordOut and (not wordBack or t < wordBack)
    local returned = wordBack and t >= wordBack
    for index, entry in ipairs(letters) do
      local y, alpha
      if returned then
        local p = win(t, wordBack + (index - 1) * 0.06, 0.6, ease.outExpo)
        y, alpha = 1.05 * (1 - p), 1
      elseif leaving then
        local p = win(t, wordOut + (index - 1) * 0.035, 0.34, ease.inCubic)
        y, alpha = -1.05 * p, 1
      else
        local p = win(t, plan.word + (index - 1) * plan.stagger, plan.rise, ease.outExpo)
        y, alpha = 1.05 * (1 - p), p
      end
      if entry.image then
        entry.image.Position = UDim2.fromScale(0, y)
        entry.image.ImageTransparency = inhale * 0.7
      else
        entry.text.TextTransparency = 1 - alpha * (1 - inhale * 0.7) * ((leaving and 1 - win(t, wordOut, 0.3)) or 1)
      end
    end
    local hubP, ruleP, statusP
    if returned then
      hubP, ruleP, statusP = win(t, wordBack + 0.32, 0.6, ease.outExpo), win(t, wordBack + 0.5, 0.7, ease.outExpo), win(t, wordBack + 0.72, 0.6, ease.outCubic)
      if statusLine.Text ~= keyHint then statusLine.Text = keyHint; statusLine.TextColor3 = BONE end
    elseif leaving then
      local gone = 1 - win(t, wordOut, 0.3, ease.inCubic)
      hubP, ruleP, statusP = gone, gone, gone
    else
      hubP, ruleP, statusP = win(t, plan.hub, 0.8, ease.outExpo), win(t, plan.rule, 0.75, ease.outExpo), win(t, plan.status, 0.6, ease.outCubic)
    end
    if hubImage:IsA("ImageLabel") then hubImage.ImageTransparency = 1 - hubP * (1 - inhale * 0.7) else hubImage.TextTransparency = 1 - hubP * (1 - inhale * 0.7) end
    rule.Size = UDim2.new(ruleP, 0, 0, 1)
    statusLine.TextTransparency = 1 - statusP * (1 - inhale * 0.6)
    local glowBase = (leaving and 0) or (returned and win(t, wordBack, 0.8, ease.outCubic) * 0.2) or win(t, plan.word + 0.2, 1.4, ease.outCubic) * 0.2
    glow.ImageTransparency = 1 - (glowBase + (t >= DROP and not leaving and 0.16 * (1 - win(t, DROP, 1.2, ease.outCubic)) or 0))
    dim.BackgroundTransparency = 1 - inhale * 0.5

    if not dropped then
      -- anticipation: the mark leans in before the hit
      if t < DROP and t > DROP - 0.75 then punch:snap({ 1 + 0.03 * win(t, DROP - 0.75, 0.75, ease.inCubic) }) end
      if t >= DROP then
        dropped = true
        punch:snap({ 1.11 }); punch:to({ 1 }, "bouncy")
        shake:impulse(1, 900 * k); shake:impulse(2, -520 * k)
        flash.BackgroundTransparency = 0.12
        Motion.tween(0.5, ease.outCubic, function(p) if not exiting then flash.BackgroundTransparency = 0.12 + 0.88 * p end end)
        lastCut = DROP
      end
    else
      -- every later cut of the edit gives the frame a small kick
      for _, cut in ipairs(cuts) do
        if cut > lastCut + 0.05 and cut <= t and cut < plan.exit - 0.05 then
          lastCut = cut
          punch:impulse(1, 0.9)
          shake:impulse(1, (math.random() - 0.5) * 420 * k); shake:impulse(2, (math.random() - 0.5) * 300 * k)
          if not exiting then
            flash.BackgroundTransparency = 0.88
            Motion.tween(0.28, ease.outCubic, function(p) if not exiting then flash.BackgroundTransparency = 0.88 + 0.12 * p end end)
          end
        end
      end
    end
    -- film grain drifts at film cadence, not at the display's
    if since - grainAt > 1 / 24 then
      grainAt = since
      grain.Position = UDim2.fromOffset(-300 + math.random(-250, 250), -300 + math.random(-250, 250))
    end
    if not finished and (t >= plan.exit or (player and player.ended)) then
      finished = true
      exit(false)
    end
  end, nil, "loader")
end
end
do -- 09b_signal.lua
-- ============================================================================
--  09b signal  the second intro: the live game in black and white, framed like
--              a broadcast monitor, cut to the track
--
--  The film intro (09 loader) plays an edit. This one plays nothing recorded:
--  for seven seconds the camera is taken and pointed at the player's own
--  avatar, wherever they stand, in whatever game, with the picture graded to
--  black and white. Shots of it (a close-up that pushes in, low from the
--  ground, backlit from behind, overhead and turning, a dutch tilt, the eyes)
--  cut faster and faster as the track builds; on the drop the wordmark is hit
--  onto the screen. Down both sides run two monitor strips, like the edit the
--  author sent as the look to beat: waveform traces, red level blocks and a
--  twisting ribbon, all driven by the loudness of the track as it plays.
--  Letterbox bars cover the game's own buttons and bars.
--
--  Cues are times in the hub's film track (film.json: the drop at 5.93, the
--  white flash at 9.22); it is played from 2.0. With no track installed the
--  same cues run on the clock, silent, the strips driven by a beat of their own.
-- ============================================================================
local S, util, Motion, Config, Assets = B.S, B.util, B.Motion, B.Config, B.Assets
local UIS, RunService = S.UserInputService, S.RunService
local ease, win = Motion.ease, Motion.window
local Intro = { active = false }
B.SignalIntro = Intro

local BONE = Color3.fromRGB(245, 244, 239)
local DIM = Color3.fromRGB(150, 150, 158)
local RED = Color3.fromRGB(236, 96, 98)
local VIOLET = Color3.fromRGB(132, 124, 255)
local CYAN = Color3.fromRGB(90, 230, 255)
local BLACK = Color3.new(0, 0, 0)

local START, DROP, LEAVE, OUT = 2.0, 5.9333, 8.3833, 9.2167
-- the cuts: faster and faster as the track builds, then the edit's own after the drop
local CUTS = { 2.0, 2.88, 3.62, 4.25, 4.75, 5.15, 5.45, 5.7, 5.9333, 6.8833, 7.6167, 8.3833 }
local ORDER = { "face", "low", "behind", "orbit", "dolly", "dutch", "crane", "eyes", "hero", "orbitWide", "low", "face" }
local LINES = { "SIGNAL ACQUIRED", "SUBJECT  //  %NAME%", "LOCATION  //  %GAME%", "THREAT LEVEL  //  MAXIMUM", "STATUS  //  ARMED",
  "ALL SYSTEMS  //  ONLINE", "LOCKING ON", "" }
Intro.CUTS, Intro.DROP, Intro.OUT, Intro.START = CUTS, DROP, OUT, START

local STRIP = 168            -- design px (the screen's height is 1080 of them) of each monitor strip
local BAR = 112              -- letterbox bars over the game's own top buttons and bottom bars
local TRACE_N, RIBBON_N, STRIPES = 30, 26, 13

-- ---------------------------------------------------------------- the shots
-- Each: from the avatar `s` (root, head, feet, forward, right, yaw) and how far through the shot it
-- is (0..1) -> where the camera is, what it looks at, and the field of view.
local SHOTS = {
  face = function(s, p) return s.head + s.forward * util.lerp(4.4, 2.7, p) + s.right * 0.45 - Vector3.yAxis * 0.35, s.head + Vector3.yAxis * 0.1, 38 end,
  low = function(s, p) return s.feet + s.forward * util.lerp(9.5, 7.2, p) + s.right * 1.6 + Vector3.yAxis * 0.5, s.head + Vector3.yAxis * 2.2, 64 end,
  behind = function(s, p) return s.root - s.forward * util.lerp(7.5, 5.6, p) - s.right * 1.3 - Vector3.yAxis * 1.1, s.head + s.forward * 7 + Vector3.yAxis * 3.2, 56 end,
  orbit = function(s, p)
    local a = s.yaw + p * 1.25
    return s.root + Vector3.new(math.cos(a) * 9, util.lerp(26, 19, p), math.sin(a) * 9), s.root, 50
  end,
  dolly = function(s, p) return s.root + s.right * 7.5 + s.forward * util.lerp(-3.2, 3.2, p) + Vector3.yAxis * 0.8, s.root + Vector3.yAxis * 0.9, 44 end,
  dutch = function(s, p) return s.head + s.forward * 5.2 - s.right * 2.3 + Vector3.yAxis * 0.6, s.head, 40, math.rad(util.lerp(-13, -19, p)) end,
  crane = function(s, p) return s.root + s.forward * 8 + s.right * -1 + Vector3.yAxis * util.lerp(-2, 6.5, p), s.root + Vector3.yAxis * util.lerp(0, 2.2, p), 50 end,
  eyes = function(s, p) return s.head + s.forward * util.lerp(2.5, 1.95, p) + Vector3.yAxis * 0.18, s.head + Vector3.yAxis * 0.18, 30 end,
  hero = function(s, p)
    local a = s.yaw + 0.55 + p * 0.55
    local out = util.lerp(9, 16, ease.outCubic(p))
    return s.root + Vector3.new(math.cos(a) * out, util.lerp(0.6, 4.2, p), math.sin(a) * out), s.root + Vector3.yAxis * 1.6, 72
  end,
  orbitWide = function(s, p)
    local a = s.yaw - 0.9 - p * 0.8
    return s.root + Vector3.new(math.cos(a) * 15, util.lerp(7, 10, p), math.sin(a) * 15), s.root + Vector3.yAxis * 1.2, 60
  end,
}

-- the avatar, or (no body yet) wherever the camera was looking
local function subject(camera, fallback)
  local character = B.LP.Character
  local root = character and character:FindFirstChild("HumanoidRootPart")
  local head = character and character:FindFirstChild("Head")
  if root and head then
    local look = Vector3.new(root.CFrame.LookVector.X, 0, root.CFrame.LookVector.Z)
    look = look.Magnitude > 1e-3 and look.Unit or Vector3.new(0, 0, -1)
    local right = look:Cross(Vector3.yAxis).Unit
    return { root = root.Position, head = head.Position, feet = root.Position - Vector3.yAxis * 3, forward = look, right = right,
      yaw = math.atan2(look.Z, look.X), body = character }
  end
  local at = fallback or (camera.Focus.Position)
  local look = Vector3.new(camera.CFrame.LookVector.X, 0, camera.CFrame.LookVector.Z)
  look = look.Magnitude > 1e-3 and -look.Unit or Vector3.new(0, 0, 1)
  return { root = at, head = at + Vector3.yAxis * 1.5, feet = at - Vector3.yAxis * 3, forward = look, right = look:Cross(Vector3.yAxis).Unit,
    yaw = math.atan2(look.Z, look.X) }
end

-- ---------------------------------------------------------------- pieces
local function frame(parent, props)
  local item = Instance.new("Frame")
  item.BorderSizePixel = 0
  item.BackgroundColor3 = BONE
  for key, value in pairs(props or {}) do item[key] = value end
  item.Parent = parent
  return item
end
local function label(parent, text, font, size, color, props)
  local item = Instance.new("TextLabel")
  item.BackgroundTransparency = 1
  item.BorderSizePixel = 0
  item.FontFace = B.F[font] or B.F.mono400
  item.TextSize = size
  item.Text = text
  item.TextColor3 = color or BONE
  item.AutomaticSize = Enum.AutomaticSize.XY
  item.TextXAlignment = Enum.TextXAlignment.Left
  for key, value in pairs(props or {}) do item[key] = value end
  item.Parent = parent
  return item
end
-- a straight piece of line from a to b (design px)
local function segment(item, a, b, thick)
  local d = b - a
  local length = d.Magnitude
  item.Position = UDim2.fromOffset((a.X + b.X) / 2, (a.Y + b.Y) / 2)
  item.Size = UDim2.fromOffset(length + 1, thick)
  item.Rotation = math.deg(math.atan2(d.Y, d.X))
end

-- One monitor strip: two waveform traces, three red level blocks, a twisting ribbon, ticks and
-- read-outs. `step(t, level, beat)` moves all of it.
local function strip(parent, right, height)
  local holder = frame(parent, { Name = right and "StripRight" or "StripLeft", BackgroundColor3 = BLACK, Size = UDim2.new(0, STRIP, 1, 0),
    AnchorPoint = Vector2.new(right and 1 or 0, 0), Position = UDim2.fromScale(right and 1 or 0, 0), ClipsDescendants = true, ZIndex = 10 })
  frame(holder, { Name = "Edge", Size = UDim2.new(0, 1, 1, 0), Position = UDim2.fromScale(right and 0 or 1, 0), AnchorPoint = Vector2.new(right and 0 or 1, 0),
    BackgroundColor3 = Color3.fromRGB(52, 52, 60), ZIndex = 11 })
  local traces = {}
  for index = 1, 2 do
    local list = {}
    for i = 1, TRACE_N do
      list[i] = frame(holder, { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = index == 1 and 0.02 or 0.5, ZIndex = 12 })
    end
    traces[index] = { segs = list, x = (index == 1) == right and STRIP * 0.72 or STRIP * 0.3, seed = math.random() * 1000, gain = index == 1 and 1 or 0.6 }
  end
  -- red level blocks: stacks of stripes, each stripe as wide as its band is loud
  local blocks = {}
  for index = 1, 3 do
    local top = height * (index == 1 and 0.12 or (index == 2 and 0.47 or 0.78))
    local list = {}
    for i = 1, STRIPES do
      list[i] = frame(holder, { AnchorPoint = Vector2.new(0.5, 0), BackgroundColor3 = RED, BackgroundTransparency = 0.12, ZIndex = 13,
        Position = UDim2.fromOffset(STRIP * (right and 0.4 or 0.6), top + (i - 1) * 6), Size = UDim2.fromOffset(4, 3) })
    end
    blocks[index] = { stripes = list, seed = math.random() * 1000, centre = STRIP * (right and 0.4 or 0.6) }
  end
  -- the ribbon: a twist seen from the side, each rung as wide as the twist is turned toward us
  local ribbon = {}
  for i = 1, RIBBON_N do
    ribbon[i] = frame(holder, { AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 0.18, ZIndex = 12, Size = UDim2.fromOffset(4, 2) })
  end
  local ribbonX = STRIP * (right and 0.22 or 0.8)
  -- ticks across it, and its read-outs
  local ticks = {}
  for i = 1, 6 do
    ticks[i] = frame(holder, { BackgroundColor3 = VIOLET, BackgroundTransparency = 0.25, ZIndex = 14, Size = UDim2.fromOffset(STRIP * 0.5, 1),
      AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromOffset(STRIP / 2, height * math.random()) })
  end
  local reads = {}
  for i = 1, 4 do
    reads[i] = label(holder, "", "mono400", 10, DIM, { ZIndex = 15, Position = UDim2.fromOffset(right and 10 or 12, i <= 2 and (14 + (i - 1) * 14) or (height - 44 + (i - 3) * 14)),
      TextTransparency = 0.15 })
  end
  local api = { holder = holder }
  function api.step(t, level, beat, readout)
    -- traces: noise along the strip, its reach the loudness, a kick on each beat
    for _, trace in ipairs(traces) do
      local prev
      local reach = (8 + 46 * level + 30 * beat) * trace.gain
      for i = 1, TRACE_N + 1 do
        local y = (i - 1) / TRACE_N * height
        local n = math.noise(trace.seed + i * 0.37, t * 7.5) + 0.45 * math.noise(trace.seed * 0.5 + i * 1.9, t * 17)
        local point = Vector2.new(trace.x + n * reach, y)
        if prev then segment(trace.segs[i - 1], prev, point, trace.gain == 1 and 2 or 1) end
        prev = point
      end
    end
    -- blocks: each stripe a band, wider with the level, flaring on the beat
    for _, block in ipairs(blocks) do
      for i, stripe in ipairs(block.stripes) do
        local band = 0.5 + 0.5 * math.noise(block.seed + i * 0.61, t * 9)
        local width = math.clamp((0.1 + 0.9 * level * band + 0.35 * beat) * STRIP * 0.78, 3, STRIP * 0.86)
        stripe.Size = UDim2.fromOffset(width, 3)
        stripe.BackgroundTransparency = 0.05 + 0.5 * (1 - band) * (1 - beat)
      end
    end
    -- the ribbon turns at the tempo of the track
    for i, rung in ipairs(ribbon) do
      local y = (i - 0.5) / RIBBON_N * height
      local turn = math.sin(i * 0.55 + t * (3.2 + 4 * level))
      rung.Position = UDim2.fromOffset(ribbonX, y)
      rung.Size = UDim2.fromOffset(math.max(math.abs(turn) * (22 + 26 * level), 2), turn > 0 and 2 or 1)
      rung.BackgroundTransparency = turn > 0 and 0.08 or 0.55
    end
    -- ticks hop about now and then
    for _, tick in ipairs(ticks) do
      if math.random() < 0.06 + 0.3 * beat then tick.Position = UDim2.fromOffset(STRIP / 2 + (math.random() - 0.5) * 30, height * math.random()) end
      tick.BackgroundTransparency = 0.2 + 0.6 * math.random() * (1 - beat)
    end
    for i, item in ipairs(reads) do item.Text = readout[i] or "" end
  end
  return api
end

-- ---------------------------------------------------------------- the run
function Intro.run(done)
  if Intro.active then return end
  Intro.active = true
  local camera = workspace.CurrentCamera
  local view = B.viewport()
  local k = math.clamp(view.Y / 1080, 0.5, 2.5)
  local W, H = view.X / k, view.Y / k
  local gui = B.screen(9500)
  gui:SetAttribute("OwnLetters", true)       -- (its words keep the film's letters whatever the hub's font)
  local root = frame(gui, { Name = "Signal", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1 })
  -- (a modal button frees the cursor and keeps clicks from the game)
  local veil = Instance.new("TextButton")
  veil.Text, veil.AutoButtonColor, veil.Modal, veil.BorderSizePixel = "", false, true, 0
  veil.Size, veil.BackgroundColor3, veil.BackgroundTransparency = UDim2.fromScale(1, 1), BLACK, 0
  veil.Parent = root
  local layer = frame(root, { Name = "Layer", BackgroundTransparency = 1, Size = UDim2.fromOffset(W, H), ZIndex = 2 })
  local scale = Instance.new("UIScale"); scale.Scale = k; scale.Parent = layer

  -- ---- the grade: black and white, hard, a little bloom on the highlights
  local grade = Instance.new("ColorCorrectionEffect")
  grade.Name = util.randomName()
  grade.Saturation, grade.Contrast, grade.Brightness, grade.TintColor = -1, 0.72, -0.07, Color3.fromRGB(238, 240, 248)
  grade.Enabled = false
  grade.Parent = S.Lighting
  local bloom = Instance.new("BloomEffect")
  bloom.Name = util.randomName()
  bloom.Intensity, bloom.Size, bloom.Threshold, bloom.Enabled = 0.55, 30, 0.86, false
  bloom.Parent = S.Lighting
  local blur = Instance.new("BlurEffect")
  blur.Name = util.randomName()
  blur.Size, blur.Enabled = 0, true
  blur.Parent = S.Lighting

  -- ---- the frame: strips, bars, grain
  local height = H
  local left, right = strip(layer, false, height), strip(layer, true, height)
  local barTop = frame(layer, { Name = "BarTop", BackgroundColor3 = BLACK, Size = UDim2.new(1, 0, 0, BAR), ZIndex = 8 })
  local barBottom = frame(layer, { Name = "BarBottom", BackgroundColor3 = BLACK, Size = UDim2.new(1, 0, 0, BAR), AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1), ZIndex = 8 })
  local grain = Instance.new("ImageLabel")
  grain.BackgroundTransparency, grain.Image, grain.ScaleType, grain.TileSize = 1, Assets.image("grain") or "", Enum.ScaleType.Tile, UDim2.fromOffset(384, 384)
  grain.Size, grain.Position, grain.ImageTransparency, grain.ZIndex = UDim2.new(1, 600, 1, 600), UDim2.fromOffset(-300, -300), 0.86, 30
  grain.Parent = layer
  local vignette = Instance.new("ImageLabel")
  vignette.BackgroundTransparency, vignette.Image, vignette.Size, vignette.ImageTransparency, vignette.ZIndex = 1, Assets.image("vignette") or "", UDim2.fromScale(1, 1), 0.2, 7
  vignette.Parent = layer
  local flash = frame(root, { Name = "Flash", BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 50 })

  -- ---- type
  local inner = STRIP + 34
  local registry = B.Registry and B.Registry.status() or {}
  local gameName = string.upper(registry.name or "this game")
  local name = string.upper(B.LP.DisplayName)
  local head = label(layer, "BASED  //  SIGNAL", "wideBold", 13, BONE, { Position = UDim2.fromOffset(inner, BAR / 2), AnchorPoint = Vector2.new(0, 0.5), ZIndex = 20, TextTransparency = 1 })
  local rec = label(layer, "", "mono500", 12, BONE, { Position = UDim2.new(1, -inner, 0, BAR / 2), AnchorPoint = Vector2.new(1, 0.5), ZIndex = 20, TextTransparency = 1,
    TextXAlignment = Enum.TextXAlignment.Right })
  local dot = frame(layer, { BackgroundColor3 = RED, Size = UDim2.fromOffset(9, 9), AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -inner - 168, 0, BAR / 2), ZIndex = 20,
    BackgroundTransparency = 1 })
  local corner = Instance.new("UICorner"); corner.CornerRadius = UDim.new(1, 0); corner.Parent = dot
  local channel = label(layer, "CH 01  //  " .. gameName, "mono400", 12, DIM, { Position = UDim2.new(0, inner, 1, -BAR / 2), AnchorPoint = Vector2.new(0, 0.5), ZIndex = 20, TextTransparency = 1 })
  local skip = label(layer, "SPACE TO SKIP", "mono400", 12, DIM, { Position = UDim2.new(1, -inner, 1, -BAR / 2), AnchorPoint = Vector2.new(1, 0.5), ZIndex = 20, TextTransparency = 1,
    TextXAlignment = Enum.TextXAlignment.Right })
  local line = label(layer, "", "mono500", 17, BONE, { Position = UDim2.new(0, inner, 1, -BAR - 26), AnchorPoint = Vector2.new(0, 1), ZIndex = 20, TextStrokeTransparency = 0.55 })
  local lineBar = frame(layer, { BackgroundColor3 = RED, Size = UDim2.fromOffset(0, 3), Position = UDim2.new(0, inner, 1, -BAR - 18), ZIndex = 20 })
  -- the name, huge, letter by letter while the track builds
  local big = label(layer, "", "wideBlack", math.clamp(1200 / math.max(#name, 4), 70, 150), BONE, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    ZIndex = 21, TextStrokeTransparency = 0.5, TextTransparency = 0.05, TextXAlignment = Enum.TextXAlignment.Center })
  local bigScale = Instance.new("UIScale"); bigScale.Parent = big
  -- the wordmark, and its two coloured ghosts for the hit
  local wm = Assets.manifest.wordmark
  local function wordmark(color, z)
    local holder = frame(layer, { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.46), ZIndex = z })
    local capPx = math.min(H * 0.17, W * 0.09)
    local width = 0
    if wm and wm.glyphs and Assets.id(wm.glyphs[1].image) then
      local s = capPx / wm.cap
      local x = 0
      for _, glyph in ipairs(wm.glyphs) do
        local image = Instance.new("ImageLabel")
        image.BackgroundTransparency, image.Image, image.ImageColor3, image.ZIndex = 1, Assets.id(glyph.image) or "", color, z
        image.Size, image.Position = UDim2.fromOffset(glyph.w * s, glyph.h * s), UDim2.fromOffset(x - wm.pad * s, 0)
        image.Parent = holder
        x += glyph.advance * s * 0.972
      end
      width = x
      holder.Size = UDim2.fromOffset(width, (wm.cap + wm.pad * 2) * s)
    else
      local text = label(holder, "BASED", "wideBlack", 150, color, { ZIndex = z, AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      local _ = text
      holder.Size = UDim2.fromOffset(620, 170)
    end
    local sizer = Instance.new("UIScale"); sizer.Parent = holder
    holder.Visible = false
    return holder, sizer
  end
  local ghostR, ghostRScale = wordmark(RED, 22)
  local ghostC, ghostCScale = wordmark(CYAN, 22)
  local mark, markScale = wordmark(BONE, 23)
  local tag = label(layer, "ENGINEERED FOR  //  " .. gameName, "wideBold", 15, BONE, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.46, math.min(H * 0.17, W * 0.09) * 0.75 + 18),
    ZIndex = 23, TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center })
  local rule = frame(layer, { BackgroundColor3 = RED, AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.46, math.min(H * 0.17, W * 0.09) * 0.75 + 48), Size = UDim2.fromOffset(0, 3), ZIndex = 23 })
  local keyName = Config.keyLabel(Config.get("app.key.menu"))
  local hint = label(layer, string.upper(keyName) .. "  //  OPENS THE HUB", "mono500", 14, BONE, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0.46, math.min(H * 0.17, W * 0.09) * 0.75 + 66),
    ZIndex = 23, TextTransparency = 1, TextXAlignment = Enum.TextXAlignment.Center })

  -- ---- the track
  local volume = (Config.get("app.introVolume") or 50) / 100
  local film = B.Film and B.Film.spec
  local trackId = film and film.audio and not Assets.lite and Assets.id(film.audio) or nil
  local sound
  if trackId and volume > 0 then
    sound = Instance.new("Sound")
    sound.SoundId, sound.Volume, sound.Looped = trackId, volume, false
    sound.Parent = gui
    local waited = 0
    while not sound.IsLoaded and waited < 1.5 do waited += task.wait() end
    if not sound.IsLoaded then sound:Destroy(); sound = nil end
  end

  -- ---- the camera
  local saved = { type = camera.CameraType, subject = camera.CameraSubject, fov = camera.FieldOfView }
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.IgnoreWater = true
  local focusAt = camera.Focus.Position
  local shake = Motion.spring(3, { 0.42, 0.5 }, function() end, 0.02)
  local shot = { index = 0, turn = 0 }
  -- A shot is taken from the side of the avatar that is open: the one asked for, or that one
  -- turned a quarter, a half or three quarters round, whichever has the most room at both ends.
  local function room(from, look)
    local hit = workspace:Raycast(look, from - look, params)
    return hit and hit.Distance / math.max((from - look).Magnitude, 1e-3) or 1
  end
  local function turned(from, look, turn)
    if turn == 0 then return from end
    local offset = from - look
    return look + CFrame.Angles(0, turn, 0):VectorToWorldSpace(offset)
  end
  local function cutTo(index)
    shot.index = index
    local s = subject(camera, focusAt)
    if s.body then params.FilterDescendantsInstances = { s.body } end
    local kind = ORDER[(index - 1) % #ORDER + 1]
    local best, bestRoom = 0, -1
    for _, turn in ipairs({ 0, math.pi / 2, -math.pi / 2, math.pi }) do
      local a1, l1 = SHOTS[kind](s, 0)
      local a2, l2 = SHOTS[kind](s, 1)
      local open = math.min(room(turned(a1, l1, turn), l1), room(turned(a2, l2, turn), l2))
      if open > bestRoom + 0.05 then best, bestRoom = turn, open end
      if open >= 0.999 then break end
    end
    shot.turn = best
  end
  local clock = START
  local function aim()
    local s = subject(camera, focusAt)
    local index = math.max(shot.index, 1)
    local kind = ORDER[(index - 1) % #ORDER + 1]
    local a, b = CUTS[index], CUTS[index + 1] or OUT
    local p = util.clamp01((clock - a) / math.max(b - a, 0.05))
    local from, look, fov, roll = SHOTS[kind](s, p)
    from = turned(from, look, shot.turn)
    -- (still never inside a wall: the camera is brought in front of anything left in the way)
    if s.body then params.FilterDescendantsInstances = { s.body } end
    local origin = look
    local hit = workspace:Raycast(origin, from - origin, params)
    if hit then from = hit.Position + (origin - hit.Position).Unit * 0.6 end
    local x = shake.x
    local cframe = CFrame.lookAt(from, look) * CFrame.Angles(x[2] * 0.004, x[1] * 0.004, (roll or 0) + x[3] * 0.003)
    camera.CameraType = Enum.CameraType.Scriptable
    camera.CFrame = cframe
    camera.FieldOfView = fov
  end
  RunService:BindToRenderStep("BasedSignalCamera", Enum.RenderPriority.Camera.Value + 10, function()
    if Intro.active then pcall(aim) end
  end)

  -- ---- leaving
  local finished = false
  local inputConnection, job
  local function restore()
    pcall(function() RunService:UnbindFromRenderStep("BasedSignalCamera") end)
    pcall(function()
      camera.CameraType = saved.type
      camera.CameraSubject = saved.subject
      camera.FieldOfView = saved.fov
    end)
    for _, effect in ipairs({ grade, bloom, blur }) do pcall(function() effect:Destroy() end) end
  end
  local function finish(skipped)
    if finished then return end
    finished = true
    flash.BackgroundTransparency = 0
    if job then job.cancel() end
    if inputConnection then inputConnection:Disconnect() end
    restore()
    Intro.active = false
    Intro.last = { skipped = skipped, sound = sound ~= nil, seconds = clock - START }
    if sound then
      local from = sound.Volume
      Motion.tween(skipped and 0.8 or 1.4, ease.outSine, function(p) if sound.Parent then sound.Volume = from * (1 - p) end end, function() pcall(function() sound:Destroy() end) end)
    end
    layer:Destroy()
    veil:Destroy()
    B.try("signal.done", done)
    Motion.tween(0.55, ease.outCubic, function(p) flash.BackgroundTransparency = p end, function()
      if sound and sound.Parent then sound.Parent = nil end
      gui:Destroy()
    end)
  end
  B.onUnload:connect(function() if Intro.active then restore(); Intro.active = false end end)
  inputConnection = UIS.InputBegan:Connect(function(input)
    if input.KeyCode == Enum.KeyCode.Space or input.KeyCode == Enum.KeyCode.Return or input.KeyCode == Enum.KeyCode.Escape then
      if clock - START > 0.35 and not B.genv.BASED_NOSKIP then finish(true) end
    end
  end)

  -- ---- run
  grade.Enabled, bloom.Enabled = true, true
  local started = os.clock()
  if sound then
    sound.TimePosition = START
    sound:Play()
  end
  local level, lastCut, beat, grainAt, typedFor = 0, 0, 0, 0, 0
  local dropped = false
  local frames = 0
  job = Motion.every(function(dt)
    if finished then return end
    if not B.alive then finish(true); return end
    frames += 1
    clock = START + (os.clock() - started)
    -- (tests: getgenv().BASED_SIGNAL_FREEZE = a film time holds the picture there)
    local freeze = B.genv.BASED_SIGNAL_FREEZE
    if type(freeze) == "number" and clock >= freeze then
      started += clock - freeze
      clock = freeze
    end
    -- the level: the track's own loudness when it plays, a beat of its own when it does not
    local loud
    if sound and sound.IsPlaying then loud = util.clamp01(sound.PlaybackLoudness / 520)
    else loud = 0.35 + 0.35 * math.abs(math.sin(clock * math.pi * 2.9)) end
    level += (loud - level) * (loud > level and 0.55 or 0.12)
    beat = math.max(beat - dt * 3.2, 0)
    -- cuts
    for index = lastCut + 1, #CUTS do
      if clock >= CUTS[index] then
        lastCut = index
        cutTo(index)
        beat = 1
        shake:impulse(1, (math.random() - 0.5) * 260); shake:impulse(2, (math.random() - 0.5) * 200); shake:impulse(3, (math.random() - 0.5) * 140)
        -- a frame of white or black on the cut, like the edit's
        if index > 1 and index ~= 9 then
          flash.BackgroundColor3 = (index % 2 == 0) and Color3.new(1, 1, 1) or BLACK
          flash.BackgroundTransparency = (index % 2 == 0) and 0.55 or 0.25
          task.delay(1 / 30, function() if not finished then flash.BackgroundTransparency = 1 end end)
        end
        blur.Size = index < 9 and 10 or 16
        typedFor = clock
      else
        break
      end
    end
    blur.Size = math.max(blur.Size - dt * 90, 0)
    -- the drop: white, the hit, the wordmark
    if not dropped and clock >= DROP then
      dropped = true
      flash.BackgroundColor3, flash.BackgroundTransparency = Color3.new(1, 1, 1), 0
      Motion.tween(0.5, ease.outCubic, function(p) if not finished then flash.BackgroundTransparency = p end end)
      shake:impulse(1, 900); shake:impulse(2, -700); shake:impulse(3, 500)
      for _, holder in ipairs({ mark, ghostR, ghostC }) do holder.Visible = true end
    end
    -- chrome
    local chrome = win(clock, START + 0.1, 0.4, ease.outCubic)
    head.TextTransparency, channel.TextTransparency, skip.TextTransparency = 1 - chrome, 1 - chrome * 0.85, 1 - chrome * 0.7
    rec.TextTransparency = 1 - chrome
    local seconds = clock - START
    rec.Text = string.format("REC  %02d:%02d:%02d", math.floor(seconds / 60), math.floor(seconds % 60), math.floor((seconds % 1) * 30))
    dot.BackgroundTransparency = (math.floor(clock * 2.5) % 2 == 0) and 0.05 or 0.8
    veil.BackgroundTransparency = win(clock, START, 0.25, ease.outCubic)
    -- the line of the shot, typed out
    local text = LINES[lastCut] or ""
    text = string.gsub(text, "%%NAME%%", name)
    text = string.gsub(text, "%%GAME%%", gameName)
    local typed = math.floor((clock - typedFor) * 46)
    line.Text = string.sub(text, 1, math.max(typed, 0)) .. ((typed < #text and math.floor(clock * 12) % 2 == 0) and "_" or "")
    line.Visible = not dropped
    lineBar.Size = UDim2.fromOffset(dropped and 0 or math.min(typed, #text) * 10.2, 3)
    -- the name, letter by letter while the track builds, gone on the drop
    if clock >= 4.25 and not dropped then
      local count = math.clamp(math.floor((clock - 4.25) / 1.45 * #name) + 1, 1, #name)
      big.Text = string.sub(name, 1, count)
      bigScale.Scale = 1 + 0.06 * win(clock, 4.25, 1.68) + 0.03 * beat
      big.Position = UDim2.new(0.5, (math.random() - 0.5) * 6 * beat, 0.5, (math.random() - 0.5) * 6 * beat)
      big.TextTransparency = 0.05 + 0.4 * (1 - win(clock, 4.25, 0.3))
    else
      big.Text = ""
    end
    -- the wordmark: hit, held, broken up on the way out
    if dropped then
      local hit = win(clock, DROP, 0.55, ease.outExpo)
      markScale.Scale = util.lerp(1.28, 1, hit) * (1 + 0.025 * beat)
      local split = (1 - win(clock, DROP, 0.45, ease.outCubic)) * 16 + 5 * beat
      local leaving = win(clock, LEAVE + 0.15, 0.55, ease.inCubic)
      local jitter = leaving > 0 and (math.random() - 0.5) * 40 * leaving or 0
      mark.Position = UDim2.new(0.5, jitter, 0.46, 0)
      ghostR.Position = UDim2.new(0.5, -split + jitter * 1.6, 0.46, 0)
      ghostC.Position = UDim2.new(0.5, split - jitter * 1.3, 0.46, 0)
      ghostRScale.Scale, ghostCScale.Scale = markScale.Scale, markScale.Scale
      for _, holder in ipairs({ mark, ghostR, ghostC }) do
        local fade = holder == mark and leaving or math.max(leaving, 1 - (split / 21) * 1.3)
        for _, image in ipairs(holder:GetChildren()) do
          if image:IsA("ImageLabel") then image.ImageTransparency = fade + (holder == mark and 0 or 0.35) end
          if image:IsA("TextLabel") then image.TextTransparency = fade + (holder == mark and 0 or 0.35) end
        end
      end
      local under = win(clock, DROP + 0.25, 0.6, ease.outCubic) * (1 - leaving)
      tag.TextTransparency = 1 - under
      rule.Size = UDim2.fromOffset(util.lerp(0, 420, win(clock, DROP + 0.2, 0.7, ease.outExpo)) * (1 - leaving), 3)
      hint.TextTransparency = 1 - win(clock, LEAVE - 0.6, 0.4, ease.outCubic) * (1 - win(clock, OUT - 0.25, 0.25))
    end
    -- the strips
    local readout = {
      string.format("CH.%02d  %s", math.max(lastCut, 1), (math.floor(clock * 2) % 2 == 0) and "REC" or ""),
      string.format("LV %03d", math.floor(level * 999)),
      string.format("T %06.2f", clock),
      string.format("FPS %03d", math.floor(frames / math.max(os.clock() - started, 0.05))),
    }
    left.step(clock, level, beat, readout)
    right.step(clock + 3.7, level, beat, { string.format("SIG %s", string.rep("|", math.floor(level * 8))), string.format("%+05.1f dB", (level - 1) * 24),
      string.format("CUT %02d/%02d", lastCut, #CUTS), "BASED" })
    -- grain at film cadence
    if clock - grainAt > 1 / 24 then
      grainAt = clock
      grain.Position = UDim2.fromOffset(-300 + math.random(-240, 240), -300 + math.random(-240, 240))
      grain.ImageTransparency = 0.84 + 0.05 * math.random()
    end
    barTop.Size, barBottom.Size = UDim2.new(1, 0, 0, BAR), UDim2.new(1, 0, 0, BAR)
    if clock >= OUT then finish(false) end
  end, nil, "signal")
end
if B.Loader then B.Loader.others.signal = Intro.run end
end
do -- 10_registry.lua
-- ============================================================================
--  10 registry  the tree that holds the apples
--
--  A game module is one table handed to BASED.game{...}. When the hub starts it
--  looks the current game up by universe id, then by place id:
--
--    * a module with `tabs`   -> its tabs are built into the hub, under the
--                                game's own heading, above Universal
--    * a module with `script` -> that script is run (a function, a file inside
--                                BasedHub/, or a URL)
--    * no module              -> Universal, and the player is told that no
--                                script has been engineered for this game yet
--
--  Modules compiled into the build live in based/games/*.lua. A .lua file
--  dropped into the executor's BasedHub/games/ folder is picked up the same way
--  with no rebuild: it is called with the hub table and calls hub.game{...}.
-- ============================================================================
local S, fs, Window, Config = B.S, B.fs, B.Window, B.Config
local Registry = { games = {}, active = nil, gameName = nil }
B.Registry = Registry

-- spec: id, name, places = {..}, universes = {..}, icon, tabs = function(hub), script,
--       universal (default true; false = the Universal tabs and the systems behind them are never started;
--       a list such as { "visuals" } = only those of visuals / combat / movement / players / world are)
function B.game(spec)
  if type(spec) ~= "table" or type(spec.id) ~= "string" then error("BASED.game needs a table with an id", 2) end
  spec.name = spec.name or spec.id
  spec.places, spec.universes = spec.places or {}, spec.universes or {}
  Registry.games[#Registry.games + 1] = spec
  return spec
end

local function loadDropIns()
  for _, file in ipairs(fs.list(fs.path("games"))) do
    if string.match(file, "%.lua$") or string.match(file, "%.luau$") then
      local source = fs.read(file)
      local name = string.match(file, "([^/]+)$") or file
      if source then
        local chunk, problem = loadstring(source, "=" .. name)
        if chunk then B.try("game file " .. name, chunk, B) else B.fault("game file " .. name, problem) end
      end
    end
  end
end

local function match()
  local universe, place = game.GameId, game.PlaceId
  for _, spec in ipairs(Registry.games) do
    if table.find(spec.universes, universe) then return spec end
  end
  for _, spec in ipairs(Registry.games) do
    if table.find(spec.places, place) then return spec end
  end
  return nil
end

local function runScript(spec)
  local script = spec.script
  if type(script) == "function" then
    task.spawn(B.safe("game script " .. spec.id, script), B)
    return
  end
  if type(script) ~= "string" then return end
  task.spawn(B.safe("game script " .. spec.id, function()
    local source
    if string.match(script, "^https?://") then source = game:HttpGet(script) else source = fs.read(fs.path(script)) end
    if not source then error("script not found: " .. script) end
    local chunk, problem = loadstring(source, "=" .. spec.id)
    if not chunk then error(problem) end
    chunk(B)
  end))
end

-- The module for this game, looked up before any page is registered: a module that says
-- `universal = false` keeps the Universal systems from starting at all, not just out of sight.
function Registry.pick()
  if Registry.picked then return Registry.active end
  Registry.picked = true
  loadDropIns()
  Registry.active = match()
  return Registry.active
end
function Registry.universal()
  local spec = Registry.active
  return not (spec and (spec.universal == false or type(spec.universal) == "table"))
end
-- is this one of Universal's tabs loaded in this game?
function Registry.keeps(name)
  local spec = Registry.active
  if not spec or spec.universal == nil or spec.universal == true then return true end
  return type(spec.universal) == "table" and table.find(spec.universal, name) ~= nil
end

function Registry.resolve()
  local spec = Registry.pick()
  -- the game's public name, for the intro and the home card (a web call: never wait on it)
  task.spawn(function()
    local ok, info = pcall(function() return S.MarketplaceService:GetProductInfo(game.PlaceId) end)
    if ok and type(info) == "table" and type(info.Name) == "string" then
      Registry.gameName = info.Name
      if Registry.onName then B.try("registry.name", Registry.onName, info.Name) end
    end
  end)
  if not spec then return end
  if spec.tabs then
    local order = 100
    local hub = { game = spec, B = B, Config = Config, toast = Window.toast }
    -- hub:page{ id, title, icon, build = function(page) ... end }
    function hub:page(pageSpec)
      order += 1
      pageSpec.id = spec.id .. "." .. (pageSpec.id or tostring(order))
      -- in a game that has a script, its first tab is where the hub opens
      if order == 101 then Window.startPage = pageSpec.id end
      pageSpec.group = spec.name
      pageSpec.order = order
      pageSpec.eyebrow = pageSpec.eyebrow or spec.name
      return Window.page(pageSpec)
    end
    B.try("game tabs " .. spec.id, spec.tabs, hub)
  end
  if spec.universal == false then
    for _, page in ipairs(Window.order) do
      if page.group == "Universal" then page.hidden = true end
    end
  end
  if spec.script then runScript(spec) end
end

function Registry.status()
  local spec = Registry.active
  return { engineered = spec ~= nil, name = spec and spec.name or nil, tagline = spec and spec.tagline or nil, gameName = Registry.gameName, count = #Registry.games,
    mode = spec and (spec.tabs and "tabs" or "script") or "universal", universal = Registry.universal(),
    kept = spec and type(spec.universal) == "table" and spec.universal or nil }
end

function Registry.announce()
  if Config.get("app.toasts") == false then return end
  local spec = Registry.active
  if spec then
    Window.toast({ title = "Engineered for " .. spec.name, text = spec.tabs and (Registry.universal() and "Its tabs are in the sidebar." or (type(spec.universal) == "table" and "Its own tabs, and what it keeps of Universal." or "Its own tabs only: Universal is not loaded here.")) or "Its script is running.",
      icon = "badge-check", tone = "ok", time = 5 })
  else
    Window.toast({ title = "No script engineered for this game yet", text = "Universal is loaded and ready.", icon = "info", tone = "accent", time = 6 })
  end
end
end
do -- 11_hud.lua
-- ============================================================================
--  11 hud      the island: what is left on screen when the hub is hidden
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window
local Hud = {}
B.Hud = Hud

function Hud.ping()
  local ok, value = pcall(function() return B.LP:GetNetworkPing() * 1000 end)
  if ok and value and value > 0 then return value end
  local ok2, item = pcall(function() return S.Stats.Network.ServerStatsItem["Data Ping"]:GetValue() end)
  return ok2 and item or 0
end
function Hud.fps() return 1 / math.max(Motion.smoothDt, 1 / 1000) end

function Hud.start()
  if Hud.island then return end
  local holder = UI.frame(Window.hud, { Name = "Island", AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 12), Size = UDim2.fromOffset(0, 34),
    AutomaticSize = Enum.AutomaticSize.X, Visible = false })
  local sizer = Instance.new("UIScale"); sizer.Scale = Window.scale; sizer.Parent = holder
  local glass = UI.glass(holder, { level = "popover", radius = 17, shadow = 22, shadowY = 8, grain = false,
    props = { Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X } })
  local body = UI.pressable(glass, { Name = "Body", Size = UDim2.fromScale(0, 1), AutomaticSize = Enum.AutomaticSize.X })
  UI.pad(body, 0, 14, 0, 14)
  UI.list(body, "x", 9, { v = "Center" })
  UI.text(body, "BASED", "brand", "ink", { TextSize = 11, LayoutOrder = 1 })
  local dot = UI.frame(body, { Size = UDim2.fromOffset(4, 4), LayoutOrder = 2, Theme = { BackgroundColor3 = "accent" }, BackgroundTransparency = 0 })
  UI.corner(dot, true)
  local stats = UI.text(body, "", "mono", "sub", { TextSize = 11, LayoutOrder = 3 })
  local key = UI.text(body, "", "mono", "faint", { TextSize = 11, LayoutOrder = 4 })
  Hud.island = holder
  local shown = false
  local function show(on)
    on = on and Config.get("app.island") ~= false and not (B.Unnamed and (B.Unnamed.active() or B.Unnamed.open))
      and not (B.Novoline and (B.Novoline.active() or B.Novoline.open))
    if on == shown then return end
    shown = on
    if on then
      holder.Visible = true
      holder.Position = UDim2.new(0.5, 0, 0, -44)
      Motion.to(holder, "Position", UDim2.new(0.5, 0, 0, 12), "bouncy")
    else
      Motion.to(holder, "Position", UDim2.new(0.5, 0, 0, -48), "quick", function() if not shown then holder.Visible = false end end)
    end
  end
  UI.wire(body, {
    hover = function(on) Motion.to(sizer, "Scale", Window.scale * (on and 1.05 or 1), "snappy") end,
    click = function() Window.show(true) end,
  })
  Window.onShow:connect(function(open) show(not open) end)
  Config.on("app.island", function() show(not Window.open) end)
  Config.on("app.gui", function() show(not Window.open) end)
  -- in flight the island reads the speed instead: it is the number worth watching then
  local tick = 0
  Motion.every(function()
    if not shown then return end
    tick += 1
    local flight = B.Flight
    if flight and flight.state == "flying" then
      local _, speed, mach = flight.status()
      stats.Text = util.comma(speed) .. " st/s" .. ((mach or 0) >= 1 and string.format("  ·  Mach %.1f", mach) or "")
    elseif tick % 4 == 0 or stats.Text == "" or string.find(stats.Text, "st/s", 1, true) then
      stats.Text = string.format("%d fps  ·  %d ms", math.floor(Hud.fps() + 0.5), math.floor(Hud.ping() + 0.5))
    end
    key.Text = Config.keyLabel(Config.get("app.key.menu"))
  end, 8, "hud.island")
  show(not Window.open)
end
end
do -- 12_board.lua
-- ============================================================================
--  12 board    the film on the Home tab: an ad board that opens when hovered
--
--  Docked, it is part of the Home card: the film runs silently and fades into
--  the card on its left. Rest the mouse on it and it comes forward over the hub,
--  opens to the whole picture and the sound comes in; move off it and it goes
--  back. Click it while it is open and it stays open until it is clicked again.
--
--  Two players share one clock, so they are always on the same frame. Measured
--  on the test machine with the Home tab up (126 fps with no board): the small
--  set played in the card costs nothing that can be measured (128, 129), the
--  1820x1024 set costs up to a tenth (114 to 126). So the card plays the small
--  set, which it shows at less than its own size anyway, and the big one runs
--  only once the mouse is on it. The hand-over happens with both on the same
--  picture in the same place, and the sound joins where the picture already is.
--
--  The film keeps its own rate (24000/1001 frames a second: every frame the
--  file has). Nothing is decoded while it cannot be seen: hub hidden, another
--  tab, the card scrolled away, or switched off in Settings.
-- ============================================================================
local S, util, Motion, T, UI, Config, Window, Assets, Film = B.S, B.util, B.Motion, B.T, B.UI, B.Config, B.Window, B.Assets, B.Film
local UIS = S.UserInputService
local Board = { spec = B.BOARD, p = 0, popped = false, opens = 0 }
B.Board = Board

local DWELL = 0.28        -- seconds the mouse rests on it before it opens: passing over it does nothing
local LINGER = 0.14       -- and how long it may be off it before it goes back
local RADIUS = 18         -- corner radius opened out, in screen pixels
local MARGIN = 28         -- kept clear of the screen edge
local FOCUS = 0.3         -- docked, the card shows a strip of the picture: this far down it
-- docked: clear on the left where the card's words are, the picture itself on the right
local RAMP = { { 0, 1 }, { 0.5, 0.42 }, { 1, 0.04 } }
local DOCK_ALPHA = 0.9
local UNSEEN = 0.001      -- drawn, so it is decoded, and not to be seen

local O
local holder, panel, screen, scrim, rim, shade, bar, fill, chip, still
local dock, big           -- the player in the card, and the one that comes forward
local spring
local origin = os.clock()
local function clock() return os.clock() - origin end
local wantPop, pinned, armed, overSince, offSince = false, false, false, nil, nil
local bigOnShow = false   -- which of the two players is the one being looked at
local handing = false     -- opening, and the big player has no picture yet: the card's keeps its own until it has
local dockShown = 0       -- how visible the card's player is right now

local function enabled() return Board.spec ~= nil and not Assets.lite and O ~= nil and O.on end
-- The BASED window's own Home tab, open: the board is a card on that page alone. (Asked of any look,
-- Novoline's Home deck counted: the BASED window sat hidden with its layout in place, and hovering
-- where the card would have been opened the film over the deck. Seen by the user 2026-10-22.)
local function onHome()
  return Window.open == true and Window.current ~= nil and Window.current.id == "home" and Window.look() == "based"
end
-- docked, the board is on screen only where the page shows through its scroll area
local function inView()
  if not holder or not holder.Parent or not Window.pageHost then return false end
  local top, bottom = holder.AbsolutePosition.Y, holder.AbsolutePosition.Y + holder.AbsoluteSize.Y
  local hostTop = Window.pageHost.AbsolutePosition.Y
  return bottom > hostTop + 12 and top < hostTop + Window.pageHost.AbsoluteSize.Y - 12
end

local function dockRect()
  local at, size = holder.AbsolutePosition - UI.overlay.AbsolutePosition, holder.AbsoluteSize
  return at.X, at.Y, size.X, size.Y
end
local function popRect()
  local view = B.viewport()
  local width = math.min(view.X * O.size / 100, (view.Y - MARGIN * 2) * 16 / 9, view.X - MARGIN * 2)
  local height = width * 9 / 16
  -- over the middle of the hub, and never off the screen
  local centre = Window.holder.AbsolutePosition + Window.holder.AbsoluteSize / 2 - UI.overlay.AbsolutePosition
  local x = math.clamp(centre.X - width / 2, MARGIN, math.max(MARGIN, view.X - width - MARGIN))
  local y = math.clamp(centre.Y - height / 2, MARGIN, math.max(MARGIN, view.Y - height - MARGIN))
  return x, y, width, height
end
local function dockLook()
  return { tl = 0, bl = 0, tr = T.rCard, br = T.rCard, fade = RAMP, focusX = 0.5, focusY = FOCUS }
end

-- Everything that depends on how far open it is: 0 docked, 1 open (a spring, so it may pass 1).
-- It only ever moves the big player: the one in the card stays where it is.
local function apply(p)
  Board.p = p
  if not big or big.dead or not holder.Parent then return end
  local q = util.clamp01(p)
  Board.popped = q > 0.5
  local dx, dy, dw, dh = dockRect()
  local px, py, pw, ph = popRect()
  panel.Position = UDim2.fromOffset(util.lerp(dx, px, p), util.lerp(dy, py, p))
  panel.Size = UDim2.fromOffset(math.max(8, util.lerp(dw, pw, p)), math.max(8, util.lerp(dh, ph, p)))
  -- out here nothing is scaled with the hub: the card's radius is carried over in screen pixels
  local card = T.rCard * UI.unit()
  local left, right = util.lerp(0, RADIUS, q), util.lerp(card, RADIUS, q)
  local fade = false
  if q < 0.995 then
    local keep = (1 - q) ^ 1.6
    fade = { { RAMP[1][1], RAMP[1][2] * keep }, { RAMP[2][1], RAMP[2][2] * keep }, { RAMP[3][1], RAMP[3][2] * keep } }
  end
  big:setLook({ tl = left, bl = left, tr = right, br = right, fade = fade, focusY = util.lerp(FOCUS, 0.5, q) })
  if wantPop or p > 0.002 then big:setAlpha(util.lerp(DOCK_ALPHA, 1, q)) end
  big:setVolume(O.volume / 100 * q * q)
  scrim.BackgroundTransparency = 1 - 0.46 * q
  scrim.Visible = q > 0.01
  rim.Corner.CornerRadius = UDim.new(0, math.floor(right + 0.5))
  rim.Stroke.Transparency = 1 - (pinned and 0.5 or 0.2) * q
  if shade then shade.Transparency = 1 - 0.6 * q end
  bar.Visible = q > 0.6
end

-- the big player, made the first time the mouse comes near
local function makeBig()
  if big and not big.dead then return true end
  local set = Film.pick(O.quality, Board.spec)
  if not set then return false end
  big = Film.new(screen, { spec = Board.spec, set = set, loop = true, audio = true, muted = true, volume = 0, window = true, backdrop = false,
    slots = 6, budget = 2, soundHost = UI.soundHost, clock = clock })
  Board.big = big
  return big ~= nil
end
-- The mouse is on the board: start the big player where the small one is, out of sight, so
-- that by the time the board opens it has a picture to open with.
local function arm()
  if armed or not makeBig() then return end
  armed = true
  panel.Visible = true
  apply(0)
  big:setAlpha(UNSEEN)
  big:play()
end
local function disarm()
  if not armed then return end
  armed = false
  if big and not big.dead then
    big:setMuted(true)
    big:pause()
  end
  panel.Visible, scrim.Visible = false, false
end
local function open(on)
  if not on then pinned = false end
  if wantPop == on then return end
  if on then
    arm()
    if not armed then return end
    wantPop = true
    Board.opens += 1
    big:setMuted(false)
    if chip then chip.Visible = false end
    -- the hand-over, in one go: the big player shows the picture from this frame on, exactly
    -- where the card's player was showing it, and that one stops
    bigOnShow = true
    apply(Board.p)
    handing = true
    spring:to({ 1 }, { 0.5, 0.16 })
  else
    wantPop, handing = false, false
    -- the card's player starts again now, unseen, to be on the right frame when this lands
    if dock and not dock.dead and not dock.playing then dock:play() end
    spring:to({ 0 }, "smooth")
  end
end
-- shut at once, with nothing left over the hub: for when the tab or the hub goes away under it
local function shut()
  wantPop, pinned, overSince, offSince = false, false, nil, nil
  if spring then spring:snap({ 0 }) end
  bigOnShow, handing = false, false
  disarm()
end
Board.open, Board.shut = open, shut
-- held open whatever the mouse does (a click on the open board does this)
function Board.pin(on)
  pinned = on == true
  if pinned then open(true) end
  if big and not big.dead and armed then apply(Board.p) end
end

local function makeDock()
  if dock and not dock.dead then return end
  if not holder or not holder.Parent then return end
  -- the small set is all the card can show; where only the big one is installed, that plays
  local set = Film.has("hd", Board.spec) and "hd" or Film.pick("ultra", Board.spec)
  if not set then return end
  dock = Film.new(holder, { spec = Board.spec, set = set, loop = true, window = true, backdrop = false, slots = 6, budget = 2, look = dockLook(), clock = clock })
  Board.film = dock
  if dock then
    dock:setAlpha(UNSEEN)
    dockShown = 0
  end
end
local function drop()
  shut()
  if big then big:destroy() end
  if dock then dock:destroy() end
  big, dock, Board.big, Board.film = nil, nil, nil, nil
  if still and still.Parent then still.Visible = true end
end

-- Whether the board's film is on this machine at all (it is not part of a public install).
function Board.installed() return Board.spec ~= nil and not Assets.lite and Film.pick("ultra", Board.spec) ~= nil end

-- Called by the Home tab with its card. Returns false when there is no board to show (not
-- installed, lite mode): the card then keeps its still.
function Board.mount(card, stillImage)
  if not Board.installed() then return false end
  Board.define()
  still = stillImage
  holder = UI.frame(card, { Name = "Board", Size = UDim2.new(0.62, 0, 1, 0), Position = UDim2.fromScale(1, 0), AnchorPoint = Vector2.new(1, 0), Visible = O.on })

  scrim = UI.new("TextButton", { Name = "BoardScrim", Text = "", AutoButtonColor = false, BorderSizePixel = 0, BackgroundColor3 = Color3.new(0, 0, 0),
    BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 78, Visible = false, Parent = UI.overlay })
  scrim.Activated:Connect(B.safe("board.scrim", function() open(false) end))
  panel = UI.frame(UI.overlay, { Name = "BoardPanel", ZIndex = 80, Visible = false })
  if UI.fx.shadow then
    local host = UI.frame(panel, { Name = "Shadow", Size = UDim2.fromScale(1, 1) })
    UI.corner(host, RADIUS)
    shade = Instance.new("UIShadow")
    shade.BlurRadius = UDim.new(0, 64)
    shade.Offset = UDim2.fromOffset(0, 24)
    shade.Color = Color3.new(0, 0, 0)
    shade.Transparency = 1
    pcall(function() shade.ShowBehindParent = false end)
    shade.Parent = host
  end
  screen = UI.frame(panel, { Name = "Screen", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local hit = UI.new("TextButton", { Name = "Hit", Text = "", AutoButtonColor = false, BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = panel })
  hit.Activated:Connect(B.safe("board.pin", function()
    if not wantPop then return end
    if pinned then open(false) else Board.pin(true) end
  end))
  -- a hairline round the picture, and how far through it is
  rim = UI.frame(panel, { Name = "Rim", Size = UDim2.fromScale(1, 1), ZIndex = 3 })
  local corner = Instance.new("UICorner")
  corner.Name = "Corner"
  corner.Parent = rim
  local stroke = Instance.new("UIStroke")
  stroke.Name = "Stroke"
  stroke.Color = Color3.new(1, 1, 1)
  stroke.Thickness = 1
  stroke.Transparency = 1
  stroke.Parent = rim
  bar = UI.frame(panel, { Name = "Progress", Size = UDim2.new(1, -RADIUS * 2, 0, 2), Position = UDim2.new(0, RADIUS, 1, -10), BackgroundColor3 = Color3.new(1, 1, 1),
    BackgroundTransparency = 0.78, ZIndex = 4, Visible = false })
  UI.corner(bar, true)
  fill = UI.frame(bar, { Name = "Fill", Size = UDim2.fromScale(0, 1), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.1 })
  UI.corner(fill, true)

  -- what the board is for, until it has been opened once
  chip = UI.frame(holder, { Name = "Hint", AnchorPoint = Vector2.new(1, 1), Position = UDim2.new(1, -12, 1, -12), Size = UDim2.fromOffset(0, 24),
    AutomaticSize = Enum.AutomaticSize.X, BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.45, ZIndex = 6, Visible = O.hover })
  UI.corner(chip, true)
  UI.pad(chip, 0, 10, 0, 9)
  UI.list(chip, "x", 6, { v = "Center" })
  local glyph = UI.icon(chip, "volume-x", 13, "ink", { LayoutOrder = 1 })
  glyph.ImageColor3 = Color3.new(1, 1, 1)
  local words = UI.text(chip, "Hover for sound", "caption", "ink", { LayoutOrder = 2, TextSize = 11 })
  words.TextColor3 = Color3.new(1, 1, 1)

  spring = Motion.spring(1, "smooth", function(x) apply(x[1]) end, 0.0008)

  -- Every frame the Home tab is up: the mouse, and which of the two players is the one on show.
  Motion.every(function(dt)
    if not holder.Parent then return end
    local live = dock ~= nil and not dock.dead and enabled() and onHome()
    if not live or UI.popoverOpen() or (not O.hover and not pinned) then
      if wantPop then open(false) elseif armed and Board.p <= 0.002 then disarm() end
      overSince = nil
    else
      local now = os.clock()
      local mouse = UI.mouse()
      local over
      if Board.p > 0.02 then
        over = UI.inside(panel, mouse)
      else
        over = UI.inside(holder, mouse) and UI.inside(Window.pageHost, mouse) and inView() and not UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1)
      end
      if over then
        offSince = nil
        overSince = overSince or now
        arm()
        -- open once it has rested there AND the big player has a picture to open with
        if not wantPop and now - overSince >= DWELL and big and big.fresh > 0 then open(true) end
      else
        overSince = nil
        if wantPop and not pinned then
          offSince = offSince or now
          if now - offSince >= LINGER then open(false) end
        elseif armed and not wantPop and Board.p <= 0.002 then
          disarm()
        end
      end
    end
    -- The hand-over back. The big player keeps the picture all the way home, and then sits
    -- exactly where the card's player is until that one has a picture of its own again.
    if dock and not dock.dead then
      if handing and big and big.fresh > 0 then
        handing = false
        if dock.playing then dock:pause() end
        dockShown = 0
        dock:setAlpha(UNSEEN)
      end
      if bigOnShow then
        if not wantPop and Board.p <= 0.002 and dock.fresh > 0 and not handing then
          bigOnShow = false
          dockShown = 1
          dock:setAlpha(DOCK_ALPHA)
          disarm()
          if chip then chip.Visible = O.hover and Board.opens == 0 end
        end
      elseif dock.playing then
        -- on its own in the card: let it in gently when it has just (re)started
        local goal = dock.fresh > 0 and 1 or 0
        if dockShown ~= goal then
          dockShown = goal == 1 and math.min(1, dockShown + dt * 6) or 0
          dock:setAlpha(util.lerp(UNSEEN, DOCK_ALPHA, dockShown))
          if still and still.Parent then still.Visible = dockShown < 1 end
        end
      end
    end
    if big and bar.Visible then fill.Size = UDim2.fromScale(util.clamp01(big.time / big.length), 1) end
  end, nil, "board.mouse")

  -- play only while it can be seen
  Motion.every(function()
    if not holder.Parent then return end
    if not enabled() then
      if dock or big then drop() end
      return
    end
    local seen = onHome() and (Board.p > 0.02 or inView())
    if seen then
      makeDock()
      if dock and not dock.playing and not wantPop and Board.p <= 0.002 then dock:play() end
    else
      if Board.p > 0 or wantPop or armed then shut() end
      if dock and dock.playing then
        dock:pause()
        dockShown = 0
        dock:setAlpha(UNSEEN)
        if still and still.Parent then still.Visible = true end
      end
    end
  end, 8, "board.watch")

  Config.on("home.board", function(on)
    if holder.Parent then holder.Visible = on end
    if not on then drop() end
  end)
  Config.on("home.boardQuality", function()
    shut()
    if big then big:destroy() end
    big, Board.big = nil, nil
  end)
  Config.on("home.boardHover", function(on)
    if chip and chip.Parent then chip.Visible = on and Board.p <= 0.02 and Board.opens == 0 end
    if not on and wantPop then open(false) end
  end)
  Config.on("app.radius", function() if dock and not dock.dead then dock:setLook(dockLook()) end end)
  -- open and at rest, nothing is moving to pick a new volume or size up
  for _, id in ipairs({ "home.boardVolume", "home.boardSize" }) do
    Config.on(id, function() if armed and big and not big.dead then apply(Board.p) end end)
  end
  Window.onShow:connect(function(on) if not on then shut() end end)
  Window.onPage:connect(function() shut() end)
  B.own(function()
    if big then big:destroy() end
    if dock then dock:destroy() end
  end)
  return true
end

function Board.define()
  if O then return end
  Config.define("home.board", true)
  Config.define("home.boardHover", true)
  Config.define("home.boardVolume", 60)
  Config.define("home.boardSize", 56)
  Config.define("home.boardQuality", "ultra")
  O = Config.mirror({ on = "home.board", hover = "home.boardHover", volume = "home.boardVolume", size = "home.boardSize", quality = "home.boardQuality" })
  Board.options = O
end
end
do -- 13_picker.lua
-- ============================================================================
--  13 picker   the first launch: which look to open in
--
--  The first time the hub runs on a machine (nothing saved yet), once the intro
--  is done, three cards fade in: BASED, Novoline and Unnamed, each with a small
--  drawing of what it looks like. A click (or 1, 2, 3) opens that one; it can be
--  changed any time after in Settings > Menu style.
-- ============================================================================
local S, util, Motion, Config = B.S, B.util, B.Motion, B.Config
local UIS = S.UserInputService
local Picker = { active = false }
B.Picker = Picker

local rgb = Color3.fromRGB
local INK, SOFT, FAINT = rgb(245, 244, 239), rgb(170, 170, 180), rgb(110, 110, 120)
local LOOKS = {
  { id = "based", name = "BASED", line = "Glass, a sidebar, and motion everywhere.", accent = rgb(159, 140, 255) },
  { id = "novoline", name = "Novoline", line = "A dock at the bottom. A panel rises from it.", accent = rgb(230, 30, 30) },
  { id = "unnamed", name = "Unnamed", line = "Compact and classic, with pixel letters.", accent = rgb(32, 98, 255) },
}

local function frame(parent, props)
  local item = Instance.new("Frame")
  item.BorderSizePixel = 0
  item.BackgroundTransparency = 1
  for key, value in pairs(props or {}) do item[key] = value end
  item.Parent = parent
  return item
end
local function round(item, radius)
  local corner = Instance.new("UICorner")
  corner.CornerRadius = UDim.new(0, radius)
  corner.Parent = item
  return corner
end
local function label(parent, text, font, size, color, props)
  local item = Instance.new("TextLabel")
  item.BackgroundTransparency = 1
  item.BorderSizePixel = 0
  item.FontFace = B.F[font] or B.F.text400
  item.TextSize = size
  item.TextColor3 = color
  item.Text = text
  item.TextXAlignment = Enum.TextXAlignment.Left
  for key, value in pairs(props or {}) do item[key] = value end
  item.Parent = parent
  return item
end
local function block(parent, x, y, w, h, color, alpha, radius)
  local item = frame(parent, { Position = UDim2.fromOffset(x, y), Size = UDim2.fromOffset(w, h), BackgroundColor3 = color, BackgroundTransparency = alpha or 0 })
  if radius then round(item, radius) end
  return item
end

-- ---------------------------------------------------------------- the three drawings (196 x 150)
local DRAW = {}
function DRAW.based(box, accent)
  local glass = block(box, 0, 0, 196, 150, rgb(30, 30, 38), 0, 12)
  local shade = Instance.new("UIGradient")
  shade.Color = ColorSequence.new(rgb(52, 50, 66), rgb(18, 18, 24))
  shade.Rotation = 120
  shade.Parent = glass
  local side = block(glass, 6, 6, 50, 138, rgb(255, 255, 255), 0.93, 9)
  block(side, 8, 9, 24, 5, INK, 0.1, 2)
  for index = 1, 6 do
    local on = index == 2
    local row = block(side, 5, 22 + index * 16, 40, 11, on and accent or INK, on and 0.55 or 0.9, 4)
    if on then block(row, 4, 3, 5, 5, accent, 0, 3) end
  end
  block(glass, 64, 12, 70, 8, INK, 0.15, 3)
  block(glass, 64, 28, 124, 46, rgb(255, 255, 255), 0.92, 8)
  block(glass, 64, 80, 59, 58, rgb(255, 255, 255), 0.92, 8)
  block(glass, 129, 80, 59, 58, rgb(255, 255, 255), 0.92, 8)
  block(glass, 72, 38, 50, 5, INK, 0.4, 2)
  block(glass, 72, 50, 90, 4, INK, 0.7, 2)
  block(glass, 160, 37, 20, 10, accent, 0.1, 5)
end
function DRAW.novoline(box, accent)
  local back = block(box, 0, 0, 196, 150, rgb(10, 10, 11), 0, 12)
  local panel = block(back, 38, 18, 120, 88, rgb(22, 22, 25), 0.02, 10)
  local rim = Instance.new("UIStroke")
  rim.Color, rim.Transparency, rim.Thickness = rgb(255, 255, 255), 0.86, 1
  rim.Parent = panel
  block(panel, 10, 10, 46, 6, INK, 0.1, 3)
  for index = 1, 4 do
    block(panel, 10, 22 + index * 14, 70, 5, INK, 0.72, 2)
    local switch = block(panel, 92, 20 + index * 14, 18, 9, index % 2 == 1 and rgb(242, 242, 244) or rgb(60, 60, 66), 0, 5)
    block(switch, index % 2 == 1 and 10 or 2, 2, 5, 5, rgb(18, 18, 20), 0, 3)
  end
  local dock = block(back, 48, 118, 100, 22, rgb(40, 40, 44), 0, 11)
  for index = 1, 5 do
    local on = index == 3
    block(dock, 8 + (index - 1) * 18, 6, on and 14 or 10, 10, on and rgb(242, 242, 244) or rgb(150, 150, 156), on and 0 or 0.35, 5)
  end
  block(back, 93, 112, 10, 2, accent, 0, 1)
end
function DRAW.unnamed(box, accent)
  local back = block(box, 0, 0, 196, 150, rgb(14, 14, 16), 0, 4)
  local edge = Instance.new("UIStroke")
  edge.Color, edge.Transparency, edge.Thickness = rgb(60, 60, 66), 0, 1
  edge.Parent = back
  block(back, 0, 0, 196, 2, accent, 0)
  for index = 1, 4 do
    local on = index == 1
    block(back, 8 + (index - 1) * 46, 8, 40, 12, on and accent or rgb(34, 34, 38), on and 0.2 or 0, 2)
  end
  for column = 0, 1 do
    local x = 8 + column * 94
    block(back, x, 28, 86, 114, rgb(22, 22, 25), 0, 2)
    for row = 1, 6 do
      local ticked = (row + column) % 3 ~= 0
      block(back, x + 6, 22 + row * 17, 8, 8, ticked and accent or rgb(48, 48, 54), 0, 1)
      block(back, x + 20, 24 + row * 17, 40 + (row * 7 + column * 11) % 22, 4, INK, 0.65, 1)
    end
  end
end

-- ---------------------------------------------------------------- the picker
-- done(look): look is "based", "novoline" or "unnamed"
function Picker.show(done)
  if Picker.active then return end
  Picker.active = true
  local gui = B.screen(9650)
  gui:SetAttribute("OwnLetters", true)
  local view = B.viewport()
  local k = math.clamp(math.min(view.Y / 1080, view.X / 1280), 0.55, 1.6)
  local shade = frame(gui, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = rgb(4, 4, 6), BackgroundTransparency = 1 })
  local veil = Instance.new("TextButton")          -- (frees the cursor and keeps clicks from the game)
  veil.Text, veil.AutoButtonColor, veil.BackgroundTransparency, veil.Size, veil.Modal, veil.ZIndex = "", false, 1, UDim2.fromScale(1, 1), true, 1
  veil.Parent = gui
  local stage = frame(gui, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(780, 430), ZIndex = 2 })
  local scale = Instance.new("UIScale")
  scale.Scale = k
  scale.Parent = stage
  local title = label(stage, "Pick your interface", "wideBold", 26, INK, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 0), Size = UDim2.fromOffset(780, 34),
    TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1 })
  local sub = label(stage, "You can change it any time in Settings, under Menu style.", "text400", 14, SOFT, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, 0, 0, 40),
    Size = UDim2.fromOffset(780, 20), TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1 })
  local cards, chosen = {}, false
  -- (picked from outside: the same as a click on that card)
  function Picker.pick(look) if Picker.active then Picker.finish(look) end end

  local function finish(look)
    if chosen then return end
    chosen = true
    for _, card in ipairs(cards) do
      local mine = card.look.id == look
      Motion.tween(mine and 0.5 or 0.3, Motion.ease.outCubic, function(p)
        card.fade(mine and 0 or p)
        if mine then card.scale.Scale = 1.04 + 0.03 * math.sin(p * math.pi) end
      end)
    end
    task.delay(0.42, function()
      Motion.tween(0.38, Motion.ease.inCubic, function(p)
        shade.BackgroundTransparency = 0.25 + 0.75 * p
        title.TextTransparency, sub.TextTransparency = p, math.max(p, 0.2)
        for _, card in ipairs(cards) do card.fade(math.max(p, card.look.id == look and 0 or 1)) end
      end, function()
        gui:Destroy()
        Picker.active = false
        done(look)
      end)
    end)
  end

  Picker.finish = finish
  for index, look in ipairs(LOOKS) do
    local x = (index - 2) * 252
    local card = frame(stage, { AnchorPoint = Vector2.new(0.5, 0), Position = UDim2.new(0.5, x, 0, 104), Size = UDim2.fromOffset(228, 300), BackgroundColor3 = rgb(18, 18, 22),
      BackgroundTransparency = 1, ZIndex = 2 })
    round(card, 16)
    local cardScale = Instance.new("UIScale")
    cardScale.Parent = card
    local rim = Instance.new("UIStroke")
    rim.Color, rim.Thickness, rim.Transparency = rgb(255, 255, 255), 1.2, 1
    rim.Parent = card
    local art = frame(card, { Position = UDim2.fromOffset(16, 16), Size = UDim2.fromOffset(196, 150), ZIndex = 3 })
    local group = Instance.new("CanvasGroup")
    group.BackgroundTransparency, group.BorderSizePixel, group.Size, group.GroupTransparency = 1, 0, UDim2.fromScale(1, 1), 1
    group.Parent = art
    DRAW[look.id](group, look.accent)
    local name = label(card, look.name, "wideBold", 17, INK, { Position = UDim2.fromOffset(18, 184), Size = UDim2.fromOffset(192, 22), TextTransparency = 1, ZIndex = 3 })
    local line = label(card, look.line, "text400", 13, SOFT, { Position = UDim2.fromOffset(18, 212), Size = UDim2.fromOffset(192, 40), TextWrapped = true,
      TextYAlignment = Enum.TextYAlignment.Top, TextTransparency = 1, ZIndex = 3 })
    local key = label(card, tostring(index), "mono500", 11, FAINT, { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -14, 0, 266), Size = UDim2.fromOffset(18, 18),
      TextXAlignment = Enum.TextXAlignment.Center, TextTransparency = 1, BackgroundColor3 = rgb(255, 255, 255), BackgroundTransparency = 1, ZIndex = 3 })
    round(key, 5)
    local tag = label(card, "Open", "text500", 12, look.accent, { Position = UDim2.fromOffset(18, 266), Size = UDim2.fromOffset(120, 18), TextTransparency = 1, ZIndex = 3 })
    local entry = { look = look, frame = card, scale = cardScale, hovered = false }
    -- 0 shown, 1 gone (and the rim, which lights on hover)
    function entry.fade(alpha)
      card.BackgroundTransparency = 0.08 + 0.92 * alpha
      group.GroupTransparency = alpha
      name.TextTransparency, line.TextTransparency = alpha, alpha
      key.TextTransparency, key.BackgroundTransparency = alpha, 0.92 + 0.08 * alpha
      tag.TextTransparency = entry.hovered and alpha or 1
      rim.Transparency = entry.hovered and (0.15 + 0.85 * alpha) or (0.88 + 0.12 * alpha)
      rim.Color = entry.hovered and look.accent or rgb(255, 255, 255)
    end
    entry.fade(1)
    local hit = Instance.new("TextButton")
    hit.Text, hit.AutoButtonColor, hit.BackgroundTransparency, hit.Size, hit.ZIndex = "", false, 1, UDim2.fromScale(1, 1), 5
    hit.Parent = card
    hit.MouseEnter:Connect(function()
      if chosen then return end
      entry.hovered = true
      Motion.to(cardScale, "Scale", 1.035, "snappy")
      entry.fade(0)
    end)
    hit.MouseLeave:Connect(function()
      if chosen then return end
      entry.hovered = false
      Motion.to(cardScale, "Scale", 1, "snappy")
      entry.fade(0)
    end)
    hit.Activated:Connect(function() finish(look.id) end)
    cards[index] = entry
  end

  -- in: the room darkens, the words come up, the cards rise one after another
  Motion.tween(0.6, Motion.ease.outCubic, function(p)
    shade.BackgroundTransparency = 1 - 0.75 * p
    title.TextTransparency, sub.TextTransparency = 1 - p, 1 - p * 0.9
    title.Position = UDim2.new(0.5, 0, 0, 10 * (1 - p))
  end)
  for index, entry in ipairs(cards) do
    task.delay(0.18 + index * 0.09, function()
      local x = (index - 2) * 252
      Motion.tween(0.55, Motion.ease.outCubic, function(p)
        if chosen then return end
        entry.frame.Position = UDim2.new(0.5, x, 0, 104 + 26 * (1 - p))
        entry.fade(1 - p)
      end)
    end)
  end
  -- 1, 2, 3 on the keyboard
  local keys = { One = 1, Two = 2, Three = 3, KeypadOne = 1, KeypadTwo = 2, KeypadThree = 3 }
  local link
  link = B.connect(UIS.InputBegan, function(input)
    if chosen then return end
    local pick = keys[input.KeyCode.Name]
    if pick and LOOKS[pick] then finish(LOOKS[pick].id) end
  end, "picker.keys")
  gui.Destroying:Connect(function() pcall(function() link:Disconnect() end) end)
end
end
do -- 20_home.lua
-- ============================================================================
--  20 home     what game this is, whether it has a script, session numbers
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Assets, Registry, Hud = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Assets, B.Registry, B.Hud
B.pages = B.pages or {}

local function visible() return Window.showing("home") end

local function hero(frame)
  local status = Registry.status()
  local card = UI.surface(frame, { Name = "Hero", Size = UDim2.new(1, 0, 0, 214), ClipsDescendants = true }, "rCard")
  UI.stroke(card, "ink", "strokeA")
  -- The board: a film that plays silently in the card and opens with its sound when the mouse
  -- rests on it. Where it is not installed (or switched off), a still from the intro stands in.
  local film = B.Film and B.Film.spec
  local picture
  if film and not Assets.lite then
    local still = Assets.frame(film.sets.hd.tiles[1].path, 378, film.sets.hd.digits)
    if still then
      picture = UI.new("ImageLabel", { Name = "Still", BackgroundTransparency = 1, Image = still, ScaleType = Enum.ScaleType.Crop, Size = UDim2.new(0.62, 0, 1, 0),
        Position = UDim2.fromScale(1, 0), AnchorPoint = Vector2.new(1, 0), ImageTransparency = 0.25, Parent = card })
      UI.corner(picture, "rCard")
      UI.gradient(picture, { Transparency = UI.alphaSeq(0, 1, 0.55, 0.35, 1, 0.1) })
    end
  end
  if B.Board then B.try("home.board", B.Board.mount, card, picture) end
  local text = UI.frame(card, { Name = "Text", Size = UDim2.new(0.66, 0, 1, 0) })
  UI.pad(text, 22, 0, 20, 24)
  UI.list(text, "y", 6, { v = "Bottom" })
  local eyebrow = UI.frame(text, { Size = UDim2.new(1, 0, 0, 20), LayoutOrder = 1 })
  UI.list(eyebrow, "x", 8, { v = "Center" })
  local pip = UI.frame(eyebrow, { Size = UDim2.fromOffset(7, 7), LayoutOrder = 1, Theme = { BackgroundColor3 = status.engineered and "ok" or "accent" }, BackgroundTransparency = 0 })
  UI.corner(pip, true)
  UI.text(eyebrow, status.engineered and "ENGINEERED FOR THIS GAME" or "NO SCRIPT ENGINEERED FOR THIS GAME YET", "eyebrow", status.engineered and "ok" or "sub", { LayoutOrder = 2 })
  local title = UI.text(text, status.engineered and status.name or "Universal", "display", "ink", { TextSize = 46, LayoutOrder = 2, TextTruncate = Enum.TextTruncate.AtEnd,
    AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0) })
  local function line()
    local name = Registry.gameName and ("“" .. Registry.gameName .. "”") or "this game"
    if status.engineered then
      if status.kept then return "Its own tabs are in the sidebar. Of Universal, only " .. table.concat(status.kept, ", ") .. " is loaded in this game." end
      if not status.universal then return "Its own tabs are in the sidebar. Universal is not loaded in this game." end
      return status.mode == "tabs" and "Its tabs are in the sidebar, above Universal." or "Its script is running. Universal is here too."
    end
    return "Nothing has been built for " .. name .. " yet, so BASED loaded Universal: aim, ESP, movement and the rest work in any game."
  end
  local sub = UI.text(text, line(), "body", "sub", { TextWrapped = true, AutomaticSize = Enum.AutomaticSize.Y, Size = UDim2.new(1, 0, 0, 0), LayoutOrder = 3, LineHeight = 1.25 })
  Registry.onName = function() if sub.Parent then sub.Text = line() end end
  local _ = title
  -- pulse on the status pip
  local ring = UI.frame(pip, { Size = UDim2.fromScale(1, 1), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
    Theme = { BackgroundColor3 = status.engineered and "ok" or "accent" }, BackgroundTransparency = 0.5 })
  UI.corner(ring, true)
  local phase = 0
  Motion.every(function(dt)
    if not ring.Parent or not visible() then return end
    phase = (phase + dt / 1.8) % 1
    local p = Motion.ease.outCubic(phase)
    ring.Size = UDim2.fromScale(1 + p * 2.4, 1 + p * 2.4)
    ring.BackgroundTransparency = 0.5 + 0.5 * p
  end, 30, "home.pulse")
end

local function stats(frame)
  local row = UI.frame(frame, { Name = "Stats", Size = UDim2.new(1, 0, 0, 74) })
  local tiles = {}
  local specs = {
    { "gauge", "FPS", function() return tostring(math.floor(Hud.fps() + 0.5)) end },
    { "wifi", "PING", function() return math.floor(Hud.ping() + 0.5) .. " ms" end },
    { "users", "PLAYERS", function() return #S.Players:GetPlayers() .. " / " .. S.Players.MaxPlayers end },
    { "timer", "SESSION", function()
      local s = math.floor(os.clock() - B.bootClock)
      return string.format("%d:%02d", s // 60, s % 60)
    end },
  }
  for index, spec in ipairs(specs) do
    local tile = UI.surface(row, { Size = UDim2.new(0.25, -9, 1, 0), Position = UDim2.new((index - 1) * 0.25, (index - 1) * 3, 0, 0) }, "rCard")
    UI.stroke(tile, "ink", "strokeA")
    UI.icon(tile, spec[1], 15, "faint", { Position = UDim2.fromOffset(14, 14) })
    UI.text(tile, spec[2], "eyebrow", "faint", { Position = UDim2.fromOffset(36, 15), TextSize = 9 })
    tiles[index] = { label = UI.text(tile, spec[3](), "monoBold", "ink", { Position = UDim2.fromOffset(14, 40), TextSize = 19 }), read = spec[3] }
  end
  Motion.every(function()
    if not row.Parent or not visible() then return end
    for _, tile in ipairs(tiles) do tile.label.Text = tile.read() end
  end, 2, "home.stats")
end

local function library(page)
  local games = Registry.games
  local section = page:section({ title = "Library", icon = "layers", full = true,
    desc = #games == 0 and "Game scripts show up here as they are engineered." or (#games .. (#games == 1 and " game script installed." or " game scripts installed.")) })
  if #games == 0 then
    section:custom({ height = 148, build = function(frame)
      local box = UI.frame(frame, { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.48), Size = UDim2.fromOffset(470, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(box, "y", 8, { h = "Center" })
      local orb = UI.frame(box, { Size = UDim2.fromOffset(46, 46), LayoutOrder = 1, Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "fill2A" } })
      UI.corner(orb, true)
      UI.icon(orb, "sprout", 21, "accent", { AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5) })
      UI.text(box, "The tree is planted. No apples yet.", "heading", "ink", { LayoutOrder = 2 })
      UI.text(box, "When a script is engineered for a game, joining that game switches BASED to its tabs on its own. Everywhere else you get Universal.",
        "caption", "sub", { LayoutOrder = 3, TextWrapped = true, TextXAlignment = Enum.TextXAlignment.Center, Size = UDim2.new(1, 0, 0, 0),
          AutomaticSize = Enum.AutomaticSize.Y, LineHeight = 1.25 })
    end })
    return
  end
  for _, spec in ipairs(games) do
    local active = Registry.active == spec
    section:custom({ height = 46, build = function(frame)
      UI.icon(frame, spec.icon or "gamepad-2", 17, active and "accent" or "sub", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      UI.text(frame, spec.name, "label", "ink", { Position = UDim2.new(0, 42, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      if active then
        UI.badge(frame, "ACTIVE", "ok", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
      else
        UI.text(frame, spec.tabs and "tabs" or "script", "mono", "faint", { Position = UDim2.new(1, -14, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5) })
      end
    end })
  end
end

B.pages[#B.pages + 1] = function()
  Window.page({ id = "home", title = "Home", icon = "house", group = "", order = 10, eyebrow = "Welcome back, " .. B.LP.DisplayName, build = function(page)
    page:custom(214, hero)
    page:custom(74, stats)
    library(page)
    local quick = page:section({ title = "Quick actions", icon = "zap" })
    quick:button({ id = "home.rejoin", label = "Rejoin this server", text = "Rejoin", run = function() if B.Server then B.Server.rejoin() end end })
    quick:button({ id = "home.hop", label = "Find another server", text = "Hop", run = function() if B.Server then B.Server.hop() end end })
    local tips = page:section({ title = "Good to know", icon = "lightbulb" })
    tips:note({ icon = "keyboard", text = "Right-click a toggle or a button to bind it to a key. Right-click anything to reset it." })
    tips:note({ icon = "search", text = "Ctrl K searches every setting in every tab." })
    tips:note({ icon = "eye-off", text = Config.keyLabel(Config.get("app.key.menu")) .. " hides the hub. The island at the top brings it back." })
  end })
  Window.startPage = Window.startPage or "home"
end
end
do -- 21_roster.lua
-- ============================================================================
--  21 roster   every other player, kept current by events
--
--  ESP, aim and the player list all read this one table. A character's parts are
--  looked up when it spawns and cached, so nothing walks the workspace per frame.
-- ============================================================================
local S, Config = B.S, B.Config
local Players = S.Players
local Roster = { list = {}, byPlayer = {}, changed = B.Signal.new(), friends = {}, targets = {}, hidden = {} }
B.Roster = Roster

local R15_JOINTS = { "Head", "UpperTorso", "LowerTorso", "LeftUpperArm", "LeftLowerArm", "LeftHand", "RightUpperArm", "RightLowerArm", "RightHand",
  "LeftUpperLeg", "LeftLowerLeg", "LeftFoot", "RightUpperLeg", "RightLowerLeg", "RightFoot" }
local R6_JOINTS = { "Head", "Torso", "Left Arm", "Right Arm", "Left Leg", "Right Leg" }
Roster.BONES_R15 = { { "Head", "UpperTorso" }, { "UpperTorso", "LowerTorso" }, { "UpperTorso", "LeftUpperArm" }, { "LeftUpperArm", "LeftLowerArm" },
  { "LeftLowerArm", "LeftHand" }, { "UpperTorso", "RightUpperArm" }, { "RightUpperArm", "RightLowerArm" }, { "RightLowerArm", "RightHand" },
  { "LowerTorso", "LeftUpperLeg" }, { "LeftUpperLeg", "LeftLowerLeg" }, { "LeftLowerLeg", "LeftFoot" }, { "LowerTorso", "RightUpperLeg" },
  { "RightUpperLeg", "RightLowerLeg" }, { "RightLowerLeg", "RightFoot" } }
Roster.BONES_R6 = { { "Head", "Torso" }, { "Torso", "Left Arm" }, { "Torso", "Right Arm" }, { "Torso", "Left Leg" }, { "Torso", "Right Leg" } }

local function scan(entry)
  local character = entry.character
  if not character then return end
  local humanoid = character:FindFirstChildOfClass("Humanoid")
  entry.humanoid = humanoid
  entry.root = character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart
  entry.head = character:FindFirstChild("Head")
  local r6 = (humanoid and humanoid.RigType == Enum.HumanoidRigType.R6) or character:FindFirstChild("Torso") ~= nil
  entry.r6 = r6
  local joints = {}
  local complete = true
  for _, name in ipairs(r6 and R6_JOINTS or R15_JOINTS) do
    local part = character:FindFirstChild(name)
    if part and part:IsA("BasePart") then joints[name] = part else complete = false end
  end
  entry.joints, entry.complete = joints, complete and entry.root ~= nil and humanoid ~= nil
  entry.bones = r6 and Roster.BONES_R6 or Roster.BONES_R15
  if humanoid then
    entry.health, entry.maxHealth = humanoid.Health, math.max(humanoid.MaxHealth, 1)
    entry.alive = humanoid.Health > 0
    -- how far below the root the feet are: the box needs it
    entry.legs = r6 and 3 or (humanoid.HipHeight + (entry.root and entry.root.Size.Y * 0.5 or 1))
  else
    entry.alive = false
  end
  local tool = character:FindFirstChildOfClass("Tool")
  entry.tool = tool and tool.Name or nil
  -- spawn protection: the game's own shield, while it lasts
  entry.shielded = character:FindFirstChildOfClass("ForceField") ~= nil
end

local function watch(entry, character)
  for _, connection in ipairs(entry.links) do connection:Disconnect() end
  table.clear(entry.links)
  entry.character = character
  entry.humanoid, entry.root, entry.head, entry.joints, entry.complete, entry.alive = nil, nil, nil, {}, false, false
  entry.spawned = os.clock()
  if not character then Roster.changed:fire(entry); return end
  scan(entry)
  local links = entry.links
  local function rescan() scan(entry) end
  links[#links + 1] = character.ChildAdded:Connect(function(child)
    if child:IsA("Tool") then entry.tool = child.Name
    elseif child:IsA("ForceField") then entry.shielded = true
    elseif child:IsA("Humanoid") or child:IsA("BasePart") then task.defer(rescan) end
  end)
  links[#links + 1] = character.ChildRemoved:Connect(function(child)
    if child:IsA("Tool") then
      local other = character:FindFirstChildOfClass("Tool")
      entry.tool = other and other.Name or nil
    elseif child:IsA("ForceField") then
      entry.shielded = character:FindFirstChildOfClass("ForceField") ~= nil
    elseif child:IsA("BasePart") then task.defer(rescan) end
  end)
  local function hookHumanoid(humanoid)
    links[#links + 1] = humanoid.HealthChanged:Connect(function(health)
      entry.health, entry.maxHealth = health, math.max(humanoid.MaxHealth, 1)
      entry.alive = health > 0
    end)
    links[#links + 1] = humanoid.Died:Connect(function() entry.alive = false end)
  end
  if entry.humanoid then hookHumanoid(entry.humanoid) else
    task.spawn(function()
      local humanoid = character:WaitForChild("Humanoid", 8)
      if humanoid and entry.character == character and B.alive then scan(entry); hookHumanoid(humanoid) end
    end)
  end
  Roster.changed:fire(entry)
end

local function add(player)
  if player == B.LP or Roster.byPlayer[player] then return end
  local entry = { player = player, name = player.Name, display = player.DisplayName, userId = player.UserId, links = {}, playerLinks = {}, joints = {},
    alive = false, complete = false }
  Roster.byPlayer[player] = entry
  Roster.list[#Roster.list + 1] = entry
  entry.playerLinks[1] = player.CharacterAdded:Connect(function(character) watch(entry, character) end)
  entry.playerLinks[2] = player.CharacterRemoving:Connect(function() watch(entry, nil) end)
  watch(entry, player.Character)
end
local function remove(player)
  local entry = Roster.byPlayer[player]
  if not entry then return end
  Roster.byPlayer[player] = nil
  local at = table.find(Roster.list, entry)
  if at then table.remove(Roster.list, at) end
  for _, connection in ipairs(entry.links) do connection:Disconnect() end
  for _, connection in ipairs(entry.playerLinks) do connection:Disconnect() end
  entry.gone = true
  Roster.changed:fire(entry)
end

function Roster.start()
  if Roster.started then return end
  Roster.started = true
  for _, userId in ipairs(Config.define("players.friends", {})) do Roster.friends[userId] = true end
  for _, userId in ipairs(Config.define("players.targets", {})) do Roster.targets[userId] = true end
  for _, userId in ipairs(Config.define("players.hidden", {})) do Roster.hidden[userId] = true end
  for _, player in ipairs(Players:GetPlayers()) do add(player) end
  B.connect(Players.PlayerAdded, add, "roster.add")
  B.connect(Players.PlayerRemoving, remove, "roster.remove")
  -- characters assemble over several frames: fill in whatever was missing
  B.Motion.every(function()
    for _, entry in ipairs(Roster.list) do
      if entry.character and not entry.complete then scan(entry) end
    end
  end, 2, "roster.scan")
  B.own(function()
    for _, entry in ipairs(Roster.list) do
      for _, connection in ipairs(entry.links) do connection:Disconnect() end
      for _, connection in ipairs(entry.playerLinks) do connection:Disconnect() end
    end
  end)
end

-- the same part lookup for any model: the ESP preview runs it on a clone of your character
function Roster.describe(character)
  local entry = { character = character, joints = {} }
  scan(entry)
  return entry
end
-- Three marks a player can carry, each kept by user id so it outlasts the server:
--   friend   skipped by aim, own colour in ESP
--   target   aim goes for them first (or only for them, if set so)
--   hidden   left out of ESP and aim altogether
local function mark(set, id)
  return function(entry, on)
    set[entry.userId] = on and true or nil
    local list = {}
    for userId in pairs(set) do list[#list + 1] = userId end
    table.sort(list)
    Config.set(id, list)
    Roster.changed:fire(entry)
  end
end
function Roster.isFriend(entry) return Roster.friends[entry.userId] == true end
function Roster.isTarget(entry) return Roster.targets[entry.userId] == true end
function Roster.isHidden(entry) return Roster.hidden[entry.userId] == true end
Roster.setFriend = mark(Roster.friends, "players.friends")
Roster.setTarget = mark(Roster.targets, "players.targets")
Roster.setHidden = mark(Roster.hidden, "players.hidden")
function Roster.anyTargets() return next(Roster.targets) ~= nil end
-- empty one of the three sets
function Roster.clear(which)
  local set = Roster[which]
  if not set then return end
  table.clear(set)
  Config.set("players." .. which, {})
  for _, entry in ipairs(Roster.list) do Roster.changed:fire(entry) end
end
function Roster.teamName(entry)
  local team = entry.player and entry.player.Team
  return team and team.Name or nil
end
-- on the other side: a different team, or no teams in this game at all
function Roster.isEnemy(entry)
  local mine, theirs = B.LP.Team, entry.player.Team
  if mine == nil or theirs == nil then return true end
  return mine ~= theirs
end
function Roster.teamColor(entry)
  local team = entry.player.Team
  return team and team.TeamColor.Color or nil
end
end
do -- 22_esp.lua
-- ============================================================================
--  22 esp      player overlays, drawn with GUI objects
--
--  GUI rather than the Drawing API, on purpose: these sit in a ScreenGui below
--  the hub, so the hub draws over them instead of under them; they take custom
--  fonts and antialiased sprites; and the same renderer draws the live preview
--  in the Visuals tab. A box is ONE 9-slice image with its dark keyline baked
--  in, a line is one stretched sprite. Elements that are switched off are never
--  created, and a property is only written when its value changed.
--
--  Far away is where an overlay earns its keep, and where the first version
--  gave up: a body under 3 px tall was simply not drawn. Now a body is never
--  drawn smaller than a set size (a mark rather than a figure, with no bones or
--  head ring, which would be a smudge), the range runs to no limit at all, a
--  ray that asks whether someone is in view is cast in lengths the engine can
--  see along, and when there are more players than chams or a set cap allow,
--  the nearest get them.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Roster, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Roster, B.Assets
local Esp = { objects = {} }
B.Esp = Esp

local ELEMENTS = { "box", "name", "health", "hp", "distance", "tool", "team", "skeleton", "head", "tracer", "look", "arrows", "chams",
  "armor", "ammo", "money", "flags" }
Esp.ELEMENTS = ELEMENTS
-- What only a game knows about a player. Its module fills in what it has; an element with no
-- reader is not offered in the tab and is never drawn:
--   armor(entry) -> share (0..1), figure     a second bar beside health, and its number
--   ammo(entry)  -> "3/5"                    after the name of what they hold
--   money(entry) -> "$12,400 · wanted 585"   a line of its own under the box
--   flags(entry) -> "KNOCKED\nRELOADING"     beside the box, one to a line
-- `sample` is the same four for the picture in the tab: sample.armor(clock) and so on.
Esp.extras = {}
Esp.EXTRA = { { "armor", "Armor bar", icon = "shield" }, { "ammo", "Ammo of the held gun", icon = "zap" }, { "money", "Cash and wanted", icon = "gem" },
  { "flags", "State flags", icon = "flag" } }
Esp.sections = {}         -- functions (page) a game's module adds: its own sections on the Visuals tab
local ARMOR_COLOR = Color3.fromRGB(88, 166, 255)
local FLAG_COLOR = Color3.fromRGB(255, 209, 102)
local FAR = 100000        -- the last stop of the Range slider: no limit
local EVERYONE = 100      -- and of the player cap
local FIGURE = 14         -- a body shorter than this on screen is a mark: no bones, head ring or look line
Esp.FAR, Esp.EVERYONE = FAR, EVERYONE
local O            -- live settings
local want = {}    -- element name -> bool

-- ---------------------------------------------------------------- one target
local Object = {}
Object.__index = Object
Esp.Object = Object

local function sprite(parent, name, z)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency = 1
  image.BorderSizePixel = 0
  image.Image = Assets.image(name) or ""
  image.ZIndex = z or 1
  image.Visible = false
  image.Parent = parent
  return image
end
local function text(parent, size)
  local label = Instance.new("TextLabel")
  label.BackgroundTransparency = 1
  label.BorderSizePixel = 0
  label.FontFace = B.F.text600
  label.TextSize = size
  label.Text = ""
  label.TextStrokeColor3 = Color3.new(0, 0, 0)
  label.TextStrokeTransparency = 0.45
  label.Size = UDim2.fromOffset(220, size + 4)
  label.ZIndex = 4
  label.Visible = false
  label.Parent = parent
  return label
end
-- write a position/size only when it moved by a pixel
local function rect(gui, cache, x, y, w, h)
  x, y, w, h = math.floor(x + 0.5), math.floor(y + 0.5), math.floor(w + 0.5), math.floor(h + 0.5)
  if cache[1] ~= x or cache[2] ~= y then gui.Position = UDim2.fromOffset(x, y); cache[1], cache[2] = x, y end
  if cache[3] ~= w or cache[4] ~= h then gui.Size = UDim2.fromOffset(w, h); cache[3], cache[4] = w, h end
end
local function show(gui, on)
  if gui.Visible ~= on then gui.Visible = on end
end
local function line(image, x1, y1, x2, y2, thickness)
  local dx, dy = x2 - x1, y2 - y1
  local length = math.sqrt(dx * dx + dy * dy)
  image.Position = UDim2.fromOffset((x1 + x2) * 0.5, (y1 + y2) * 0.5)
  image.Size = UDim2.fromOffset(length, thickness + 2.6)
  image.Rotation = math.deg(math.atan2(dy, dx))
end

function Object.new(parent)
  local self = setmetatable({ parent = parent, cache = {}, bones = {}, shown = false }, Object)
  self.root = Instance.new("Frame")
  self.root.BackgroundTransparency = 1
  self.root.Size = UDim2.fromScale(1, 1)
  self.root.Visible = false
  self.root.Parent = parent
  return self
end
function Object:get(key, make)
  local item = self[key]
  if not item then
    item = make(self.root)
    self[key] = item
    self.cache[key] = {}
  end
  return item
end
function Object:hide()
  if self.shown then
    self.shown = false
    self.root.Visible = false
  end
  if self.highlight and self.highlight.Enabled then self.highlight.Enabled = false end
  if self.arrow and self.arrow.Visible then self.arrow.Visible = false end
  if self.arrowText and self.arrowText.Visible then self.arrowText.Visible = false end
end
function Object:destroy()
  self.root:Destroy()
  if self.highlight then self.highlight:Destroy() end
  if self.arrow then self.arrow:Destroy() end
  if self.arrowText then self.arrowText:Destroy() end
end

-- info: x, y, w, h (the box), name, distance, health (0..1), hp (a number), tool, team, color,
--       alpha (0..1), joints = { [name] = {x, y, front} }, bones, headX, headY, headR, lookX,
--       lookY, originX, originY
function Object:draw(info, o, on)
  if not self.shown then self.shown = true; self.root.Visible = true end
  local cache = self.cache
  local color, fade = info.color, 1 - info.alpha
  local x, y, w, h = info.x, info.y, info.w, info.h
  local cx = x + w * 0.5

  -- box: one 9-slice sprite, or four corner brackets
  local full, corners = on.box and o.box == "full", on.box and o.box ~= "full"
  if full then
    local box = self:get("box", function(p)
      local image = sprite(p, "esp_box", 2)
      image.ScaleType = Enum.ScaleType.Slice
      image.SliceCenter = Rect.new(8, 8, 16, 16)
      return image
    end)
    box.SliceScale = o.thickness * 0.5
    box.ImageColor3, box.ImageTransparency = color, fade
    rect(box, cache.box, x - 1, y - 1, w + 2, h + 2)
    show(box, true)
  elseif self.box then show(self.box, false) end
  if corners then
    local size = math.clamp(math.min(w, h) * 0.28, 5, 26)
    for index = 1, 4 do
      local key = "corner" .. index
      local corner = self:get(key, function(p)
        local image = sprite(p, "esp_corner", 2)
        image.ScaleType = Enum.ScaleType.Slice
        image.SliceCenter = Rect.new(5, 5, 15, 15)
        image.Rotation = (index - 1) * 90
        return image
      end)
      corner.SliceScale = o.thickness * 0.5
      corner.ImageColor3, corner.ImageTransparency = color, fade
      local px = (index == 1 or index == 4) and x - 1 or x + w + 1 - size
      local py = (index == 1 or index == 2) and y - 1 or y + h + 1 - size
      rect(corner, cache[key], px, py, size, size)
      show(corner, true)
    end
  elseif self.corner1 then
    for index = 1, 4 do show(self["corner" .. index], false) end
  end
  if on.box and o.fill then
    local fill = self:get("fill", function(p)
      local frame = Instance.new("Frame")
      frame.BorderSizePixel = 0
      frame.ZIndex = 1
      frame.Visible = false
      UI.gradient(frame, { Rotation = 90, Transparency = UI.alphaSeq(0, 0.97, 1, 0.72) })
      frame.Parent = p
      return frame
    end)
    -- (two colours: the gradient carries them, over a white box)
    -- (what the gradient was last given is kept on the box's cache: set again only when it changes)
    local shade = fill:FindFirstChildOfClass("UIGradient")
    local two = o.fillColor2
    local want = o.fillTwo and shade and string.format("%.3f %.3f %.3f %.3f %.3f %.3f", two.R, two.G, two.B, color.R, color.G, color.B) or "one"
    fill.BackgroundColor3 = want == "one" and color or Color3.new(1, 1, 1)
    if shade and cache.fillShade ~= want then
      cache.fillShade = want
      shade.Color = want == "one" and ColorSequence.new(Color3.new(1, 1, 1)) or ColorSequence.new(o.fillColor2, color)
    end
    fill.BackgroundTransparency = fade
    rect(fill, cache.fill, x, y, w, h)
    show(fill, true)
  elseif self.fill then show(self.fill, false) end

  -- health: a thin bar on the left that eases toward the real value
  if on.health and info.health then
    local back = self:get("healthBack", function(p)
      local frame = Instance.new("Frame")
      frame.BorderSizePixel = 0
      frame.BackgroundColor3 = Color3.new(0, 0, 0)
      frame.ZIndex = 2
      frame.Visible = false
      frame.Parent = p
      local bar = Instance.new("Frame")
      bar.Name = "Bar"
      bar.BorderSizePixel = 0
      bar.AnchorPoint = Vector2.new(0, 1)
      bar.Position = UDim2.new(0, 1, 1, -1)
      bar.Parent = frame
      return frame
    end)
    local shownHealth = self.healthShown or info.health
    shownHealth += (info.health - shownHealth) * math.min(1, Motion.dt * 10)
    self.healthShown = shownHealth
    local bar = back.Bar
    back.BackgroundTransparency = 0.45 + fade * 0.55
    bar.BackgroundColor3 = Color3.fromHSV(0.33 * util.clamp01(shownHealth), 0.78, 0.96)
    bar.BackgroundTransparency = fade
    rect(back, cache.healthBack, x - 7, y - 1, 4, h + 2)
    local inner = math.max(1, math.floor((h) * util.clamp01(shownHealth) + 0.5))
    if cache.healthBack[5] ~= inner then bar.Size = UDim2.new(1, -2, 0, inner); cache.healthBack[5] = inner end
    show(back, true)
  elseif self.healthBack then show(self.healthBack, false) end
  -- armor: the same bar in blue, outside the health bar when there is one
  if on.armor and info.armor then
    local back = self:get("armorBack", function(p)
      local frame = Instance.new("Frame")
      frame.BorderSizePixel = 0
      frame.BackgroundColor3 = Color3.new(0, 0, 0)
      frame.ZIndex = 2
      frame.Visible = false
      frame.Parent = p
      local bar = Instance.new("Frame")
      bar.Name = "Bar"
      bar.BorderSizePixel = 0
      bar.AnchorPoint = Vector2.new(0, 1)
      bar.Position = UDim2.new(0, 1, 1, -1)
      bar.BackgroundColor3 = ARMOR_COLOR
      bar.Parent = frame
      return frame
    end)
    local shownArmor = self.armorShown or info.armor
    shownArmor += (info.armor - shownArmor) * math.min(1, Motion.dt * 10)
    self.armorShown = shownArmor
    local bar = back.Bar
    back.BackgroundTransparency = 0.45 + fade * 0.55
    bar.BackgroundTransparency = fade
    rect(back, cache.armorBack, x - ((on.health and info.health) and 12 or 7), y - 1, 4, h + 2)
    local inner = math.floor(h * util.clamp01(shownArmor) + 0.5)
    if cache.armorBack[5] ~= inner then bar.Size = UDim2.new(1, -2, 0, inner); cache.armorBack[5] = inner end
    show(back, true)
  elseif self.armorBack then show(self.armorBack, false) end

  -- labels
  if on.name and info.name then
    local label = self:get("name", function(p)
      local item = text(p, o.textSize)
      item.AnchorPoint = Vector2.new(0.5, 1)
      return item
    end)
    if cache.name.text ~= info.name then label.Text = info.name; cache.name.text = info.name end
    if cache.name.size ~= o.textSize then label.TextSize = o.textSize; cache.name.size = o.textSize end
    label.TextColor3, label.TextTransparency = color, fade
    label.TextStrokeTransparency = 0.45 + fade * 0.55
    rect(label, cache.name, cx, y - 4, 220, o.textSize + 4)
    show(label, true)
  elseif self.name then show(self.name, false) end
  -- under the box: how far and how much health in figures, then what they hold and whose side they are on
  local small = math.max(9, o.textSize - 2)
  local below = y + h + 3
  local figures
  if on.distance and info.distance then figures = util.studs(info.distance) .. " st" end
  if on.hp and info.hp then
    figures = (figures and (figures .. "  ·  ") or "") .. math.floor(info.hp + 0.5) .. " hp"
    if on.armor and info.armorValue and info.armorValue > 0 then figures = figures .. " +" .. math.floor(info.armorValue + 0.5) end
  end
  if figures then
    local label = self:get("dist", function(p)
      local item = text(p, small)
      item.FontFace = B.F.mono500
      item.AnchorPoint = Vector2.new(0.5, 0)
      return item
    end)
    if cache.dist.value ~= figures then label.Text = figures; cache.dist.value = figures end
    if cache.dist.size ~= small then label.TextSize = small; cache.dist.size = small end
    label.TextColor3 = Color3.new(1, 1, 1)
    label.TextTransparency = 0.12 + fade * 0.88
    label.TextStrokeTransparency = 0.5 + fade * 0.5
    rect(label, cache.dist, cx, below, 220, small + 3)
    show(label, true)
    below += small + 2
  elseif self.dist then show(self.dist, false) end
  local words
  if on.tool and info.tool then words = info.tool end
  if on.ammo and info.ammo then words = (words and (words .. "  ") or "") .. info.ammo end
  if on.team and info.team then words = (words and (words .. "  ·  ") or "") .. info.team end
  if words then
    local label = self:get("tool", function(p)
      local item = text(p, small)
      item.FontFace = B.F.text500
      item.AnchorPoint = Vector2.new(0.5, 0)
      return item
    end)
    if cache.tool.text ~= words then label.Text = words; cache.tool.text = words end
    if cache.tool.size ~= small then label.TextSize = small; cache.tool.size = small end
    label.TextColor3 = Color3.new(1, 1, 1)
    label.TextTransparency = 0.3 + fade * 0.7
    rect(label, cache.tool, cx, below, 220, small + 3)
    show(label, true)
    below += small + 2
  elseif self.tool then show(self.tool, false) end
  -- what they have on them, on a line of its own
  if on.money and info.money then
    local label = self:get("money", function(p)
      local item = text(p, small)
      item.FontFace = B.F.mono500
      item.AnchorPoint = Vector2.new(0.5, 0)
      item.TextColor3 = Color3.fromRGB(126, 231, 135)
      return item
    end)
    if cache.money.text ~= info.money then label.Text = info.money; cache.money.text = info.money end
    if cache.money.size ~= small then label.TextSize = small; cache.money.size = small end
    label.TextTransparency = 0.15 + fade * 0.85
    label.TextStrokeTransparency = 0.5 + fade * 0.5
    rect(label, cache.money, cx, below, 220, small + 3)
    show(label, true)
  elseif self.money then show(self.money, false) end
  -- what they are doing, beside the box: one word to a line
  if on.flags and info.flags then
    local label = self:get("flags", function(p)
      local item = text(p, small)
      item.FontFace = B.F.text700
      item.TextXAlignment = Enum.TextXAlignment.Left
      item.TextYAlignment = Enum.TextYAlignment.Top
      item.TextColor3 = FLAG_COLOR
      return item
    end)
    if cache.flags.text ~= info.flags then label.Text = info.flags; cache.flags.text = info.flags end
    local tiny = math.max(8, small - 1)
    if cache.flags.size ~= tiny then label.TextSize = tiny; cache.flags.size = tiny end
    label.TextTransparency = fade
    label.TextStrokeTransparency = 0.45 + fade * 0.55
    rect(label, cache.flags, x + w + 5, y - 1, 160, (tiny + 2) * 5)
    show(label, true)
  elseif self.flags then show(self.flags, false) end

  -- skeleton
  local bones = self.bones
  if on.skeleton and info.joints and info.bones then
    local joints = info.joints
    for index, pair in ipairs(info.bones) do
      local a, b = joints[pair[1]], joints[pair[2]]
      local bone = bones[index]
      if a and b and a[3] and b[3] then
        if not bone then
          bone = sprite(self.root, "line", 3)
          bone.AnchorPoint = Vector2.new(0.5, 0.5)
          bones[index] = bone
        end
        line(bone, a[1], a[2], b[1], b[2], o.thickness * 0.8)
        bone.ImageColor3, bone.ImageTransparency = color, fade
        show(bone, true)
      elseif bone then show(bone, false) end
    end
    for index = #info.bones + 1, #bones do show(bones[index], false) end
  else
    for _, bone in ipairs(bones) do show(bone, false) end
  end
  -- head ring
  if on.head and info.headR then
    local ring = self:get("head", function(p)
      local image = sprite(p, "ring", 3)
      image.AnchorPoint = Vector2.new(0.5, 0.5)
      return image
    end)
    local d = math.max(6, info.headR * 2)
    ring.ImageColor3, ring.ImageTransparency = color, fade
    rect(ring, cache.head, info.headX, info.headY, d, d)
    show(ring, true)
  elseif self.head then show(self.head, false) end
  -- look direction
  if on.look and info.lookX then
    local ray = self:get("look", function(p)
      local image = sprite(p, "line", 3)
      image.AnchorPoint = Vector2.new(0.5, 0.5)
      return image
    end)
    line(ray, info.headX, info.headY, info.lookX, info.lookY, o.thickness * 0.8)
    ray.ImageColor3, ray.ImageTransparency = color, 0.25 + fade * 0.75
    show(ray, true)
  elseif self.look then show(self.look, false) end
  -- tracer
  if on.tracer and info.originX then
    local tracer = self:get("tracer", function(p)
      local image = sprite(p, "line", 1)
      image.AnchorPoint = Vector2.new(0.5, 0.5)
      return image
    end)
    line(tracer, info.originX, info.originY, cx, o.tracerFrom == "top" and y or y + h, o.thickness * 0.8)
    tracer.ImageColor3, tracer.ImageTransparency = color, 0.35 + fade * 0.65
    show(tracer, true)
  elseif self.tracer then show(self.tracer, false) end
end

-- ---------------------------------------------------------------- the live overlay
local gui, layer, arrowLayer, highlights
local info = { joints = {} }
local jointPool = {}
local rayParams
local chamsBudget = 0
local order = {}          -- the roster, nearest first, when that matters

local function colorFor(entry, o)
  if o.markTarget and B.Aim and B.Aim.target == entry then return o.targetColor end
  if Roster.isFriend(entry) then return o.friendColor end
  if o.seenTint and entry.seen then return o.seenColor end
  if o.colorMode == "team" then return Roster.teamColor(entry) or o.color end
  if o.colorMode == "health" then return Color3.fromHSV(0.33 * util.clamp01((entry.health or 100) / (entry.maxHealth or 100)), 0.75, 1) end
  return o.color
end
local function nearer(a, b) return a.far < b.far end
-- Where a body is, to draw it. A body is where its torso is: knocked (Da Hood), the server holds the
-- root where it fell while the rest lies elsewhere, and a box between root and head stretched and
-- jumped. And a body in the void (a hider a million studs out, or flung off the map) is shown at the
-- last place it was on the map, faded and flagged, for a while: drawn where it really was, the box
-- flew about the screen or blinked between there and the map every frame.
local VOID_OUT, VOID_LOW, VOID_KEEP = 60000, -3000, 20
local function placeOf(entry, now)
  local root = entry.root
  local pos = root.Position
  local joints = entry.joints
  local torso = joints and (joints.UpperTorso or joints.Torso)
  local lying = false
  if torso and torso.Parent and (torso.Position - pos).Magnitude > 2.6 then
    pos, lying = torso.Position, true
  end
  entry.lying = lying
  if pos.Y > VOID_LOW and math.abs(pos.X) < VOID_OUT and math.abs(pos.Z) < VOID_OUT and pos.Y < VOID_OUT and pos.X == pos.X then
    entry.mapPos, entry.mapAt, entry.inVoid = pos, now, false
    return pos
  end
  entry.inVoid = true
  if entry.mapPos and now - (entry.mapAt or 0) < VOID_KEEP then return entry.mapPos end
  return nil
end
-- what the game's module can say about a player, read ten times a second at the most
local function extrasOf(entry, now)
  local kept = entry.extra
  if kept and now - kept.at < 0.1 then return kept end
  kept = kept or {}
  entry.extra = kept
  kept.at = now + (entry.userId % 5) * 0.004
  local extras = Esp.extras
  kept.armor, kept.armorValue, kept.ammo, kept.money, kept.flags = nil, nil, nil, nil, nil
  if want.armor and extras.armor then kept.armor, kept.armorValue = B.try("esp.armor", extras.armor, entry) end
  if want.ammo and extras.ammo then kept.ammo = B.try("esp.ammo", extras.ammo, entry) end
  if want.money and extras.money then kept.money = B.try("esp.money", extras.money, entry) end
  if want.flags and extras.flags then kept.flags = B.try("esp.flags", extras.flags, entry) end
  return kept
end

local function step()
  local camera = workspace.CurrentCamera
  if not camera then return end
  local o = O
  local camCF = camera.CFrame
  local camPos = camCF.Position
  local view = camera.ViewportSize
  local range = o.range >= FAR and math.huge or o.range
  local nameRange = o.nameRange >= FAR and math.huge or o.nameRange
  -- where the fade begins and ends: on the range, or over 20,000 studs when there is none
  local span = range == math.huge and 20000 or range
  local fadeFrom = span * o.fadeFrom / 100
  local now = os.clock()
  local mouse = S.UserInputService:GetMouseLocation()
  local tanHalf = math.tan(math.rad(camera.FieldOfView) * 0.5)
  local sight = o.dimHidden or o.hideHidden or o.seenTint
  chamsBudget = 28      -- the engine draws 31 highlights at most

  -- who is in play this frame, and how far off
  local list = Roster.list
  local count = 0
  for _, entry in ipairs(list) do
    local root = entry.root
    local live = entry.alive and root ~= nil and root.Parent ~= nil and (not o.teamCheck or Roster.isEnemy(entry)) and not Roster.isHidden(entry)
    if live then
      local at = placeOf(entry, now)
      if not at then live = false
      else
        entry.at = at
        entry.far = (at - camPos).Magnitude
        if entry.far > range then live = false end
      end
    end
    if live then
      count += 1
      order[count] = entry
    else
      local object = Esp.objects[entry]
      if object then object:hide() end
    end
  end
  for index = count + 1, #order do order[index] = nil end
  -- Nearest first, but only when it changes anything: a cap on how many are drawn, or more
  -- players than there are highlights to go round.
  local cap = o.maxPlayers >= EVERYONE and math.huge or o.maxPlayers
  if cap < count or (want.chams and count > chamsBudget) then table.sort(order, nearer) end

  for index = 1, count do
    local entry = order[index]
    local object = Esp.objects[entry]
    local root = entry.root
    local distance = entry.far
    local visible = index <= cap
    if visible and sight then
      -- one ray per player, ten times a second, spread across frames
      if not entry.seenAt or now - entry.seenAt > 0.1 then
        entry.seenAt = now + (entry.userId % 7) * 0.004
        rayParams.FilterDescendantsInstances = { B.LP.Character, entry.character }
        entry.seen = util.ray(camPos, (entry.head or root).Position, rayParams) == nil
      end
      if o.hideHidden and not entry.seen then visible = false end
    end
    if not visible then
      if object then object:hide() end
    else
      if not object then
        object = Object.new(layer)
        Esp.objects[entry] = object
      end
      local color = colorFor(entry, o)
      local alpha = 1
      if o.fade then alpha = 1 - util.clamp01((distance - fadeFrom) / math.max(span - fadeFrom, 1)) * 0.75 end
      if o.dimHidden and sight and not entry.seen then alpha *= 0.42 end
      if entry.inVoid then alpha *= 0.45 end
      local rootPos = entry.at or root.Position
      local head = entry.head
      local top, bottom
      if entry.inVoid then
        -- (held where it was last on the map: a standing body's box there)
        top = camera:WorldToViewportPoint(rootPos + Vector3.new(0, 2.45, 0))
        bottom = camera:WorldToViewportPoint(rootPos - Vector3.new(0, entry.legs or 3, 0))
      elseif entry.lying then
        -- lying down: the box round what is drawn of the body, from its parts on screen
        local minY, maxY, sumX, n, behind = math.huge, -math.huge, 0, 0, false
        for _, part in pairs(entry.joints) do
          if part.Parent then
            local p = camera:WorldToViewportPoint(part.Position)
            if p.Z <= 0 then behind = true; break end
            minY, maxY, sumX, n = math.min(minY, p.Y), math.max(maxY, p.Y), sumX + p.X, n + 1
          end
        end
        if n > 0 and not behind then
          local pad = math.max(4, (maxY - minY) * 0.18)
          top = Vector3.new(sumX / n, minY - pad, 1)
          bottom = Vector3.new(sumX / n, maxY + pad, 1)
        else
          top = camera:WorldToViewportPoint(rootPos + Vector3.new(0, 1.2, 0))
          bottom = camera:WorldToViewportPoint(rootPos - Vector3.new(0, 1.2, 0))
        end
      else
        top = camera:WorldToViewportPoint((head and head.Position or rootPos + Vector3.new(0, 1.6, 0)) + Vector3.new(0, 0.85, 0))
        bottom = camera:WorldToViewportPoint(rootPos - Vector3.new(0, entry.legs or 3, 0))
      end
      local onScreen = false
      if top.Z > 0 and bottom.Z > 0 then
        -- never smaller than the size that is set: far off, a body is a mark where they are
        local real = math.abs(bottom.Y - top.Y)
        local height = math.max(real, o.minSize)
        local width = height * o.boxWidth / 100
        local cx = (top.X + bottom.X) * 0.5
        local y = (top.Y + bottom.Y) * 0.5 - height * 0.5
        if height >= 2 and cx + width > 0 and cx - width < view.X and y + height > 0 and y < view.Y then
          onScreen = true
          local figure = real >= FIGURE and not entry.inVoid
          local named = distance <= nameRange
          info.x, info.y, info.w, info.h = cx - width * 0.5, y, width, height
          info.color, info.alpha = color, alpha
          info.name = named and (o.displayNames and entry.display or entry.name) or nil
          info.distance = distance
          info.health = entry.health and (entry.health / (entry.maxHealth or 100)) or nil
          info.hp = entry.health
          info.tool = named and entry.tool or nil
          info.team = named and Roster.teamName(entry) or nil
          if want.armor or want.ammo or want.money or want.flags then
            local extra = extrasOf(entry, now)
            info.armor, info.armorValue, info.flags = extra.armor, extra.armorValue, extra.flags
            info.ammo, info.money = named and extra.ammo or nil, named and extra.money or nil
          else
            info.armor, info.armorValue, info.flags, info.ammo, info.money = nil, nil, nil, nil, nil
          end
          if entry.inVoid and want.flags then info.flags = info.flags and ("IN VOID\n" .. info.flags) or "IN VOID" end
          info.joints, info.bones, info.headR, info.lookX, info.originX = nil, nil, nil, nil, nil
          if figure and (want.head or want.look) and head then
            local hp = camera:WorldToViewportPoint(head.Position)
            info.headX, info.headY = hp.X, hp.Y
            info.headR = math.max(3, (head.Size.Y * 0.62) / hp.Z * view.Y / (2 * tanHalf))
            if want.look then
              local lp = camera:WorldToViewportPoint(head.Position + head.CFrame.LookVector * 5)
              if lp.Z > 0 then info.lookX, info.lookY = lp.X, lp.Y end
            end
          end
          if figure and want.skeleton and distance < o.skeletonRange then
            local joints = jointPool
            for name, part in pairs(entry.joints) do
              local p = camera:WorldToViewportPoint(part.Position)
              local slot = joints[name]
              if not slot then slot = {}; joints[name] = slot end
              slot[1], slot[2], slot[3] = p.X, p.Y, p.Z > 0
            end
            info.joints, info.bones = joints, entry.bones
          end
          if want.tracer then
            if o.tracerFrom == "mouse" then info.originX, info.originY = mouse.X, mouse.Y
            elseif o.tracerFrom == "center" then info.originX, info.originY = view.X * 0.5, view.Y * 0.5
            elseif o.tracerFrom == "top" then info.originX, info.originY = view.X * 0.5, 0
            else info.originX, info.originY = view.X * 0.5, view.Y end
          end
          object:draw(info, o, want)
          if object.arrow then show(object.arrow, false) end
          if object.arrowText then show(object.arrowText, false) end
        end
      end
      if not onScreen then
        if object.shown then object.shown = false; object.root.Visible = false end
        -- off screen: an arrow on a ring round the centre, pointing at them
        if want.arrows then
          local arrow = object.arrow
          if not arrow then
            arrow = sprite(arrowLayer, "arrow", 2)
            arrow.AnchorPoint = Vector2.new(0.5, 0.5)
            object.arrow = arrow
          end
          local size = o.arrowSize
          if object.arrowSize ~= size then arrow.Size = UDim2.fromOffset(size, size); object.arrowSize = size end
          local rel = camCF:PointToObjectSpace(rootPos)
          local angle = math.atan2(rel.X, -rel.Z)
          local radius = math.min(view.X, view.Y) * o.arrowRadius / 100
          local ax, ay = view.X * 0.5 + math.sin(angle) * radius, view.Y * 0.5 - math.cos(angle) * radius
          arrow.Position = UDim2.fromOffset(ax, ay)
          arrow.Rotation = math.deg(angle)
          arrow.ImageColor3 = color
          arrow.ImageTransparency = 0.15 + (1 - alpha) * 0.85
          show(arrow, true)
          if o.arrowDistance then
            -- how far, just inside the arrow
            local label = object.arrowText
            if not label then
              label = text(arrowLayer, 10)
              label.FontFace = B.F.mono500
              label.AnchorPoint = Vector2.new(0.5, 0.5)
              label.Size = UDim2.fromOffset(80, 14)
              label.TextColor3 = Color3.new(1, 1, 1)
              object.arrowText = label
            end
            local figures = util.studs(distance)
            if object.arrowFigures ~= figures then label.Text = figures; object.arrowFigures = figures end
            local inward = radius - size * 0.5 - 12
            label.Position = UDim2.fromOffset(view.X * 0.5 + math.sin(angle) * inward, view.Y * 0.5 - math.cos(angle) * inward)
            label.TextTransparency = 0.2 + (1 - alpha) * 0.8
            show(label, true)
          elseif object.arrowText then show(object.arrowText, false) end
        else
          if object.arrow then show(object.arrow, false) end
          if object.arrowText then show(object.arrowText, false) end
        end
      end
      -- chams: the engine's own outline through walls
      if want.chams and chamsBudget > 0 and entry.character then
        chamsBudget -= 1
        local highlight = object.highlight
        if not highlight then
          highlight = Instance.new("Highlight")
          highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
          highlight.Parent = highlights
          object.highlight = highlight
        end
        if highlight.Adornee ~= entry.character then highlight.Adornee = entry.character end
        highlight.FillColor, highlight.OutlineColor = color, color
        highlight.FillTransparency = 1 - (1 - o.chamsFill / 100) * alpha
        highlight.OutlineTransparency = o.chamsOutline and (1 - alpha) or 1
        if not highlight.Enabled then highlight.Enabled = true end
      elseif object.highlight and object.highlight.Enabled then
        object.highlight.Enabled = false
      end
    end
  end
end

local bound = false
local function setRunning(on)
  if on == bound then return end
  bound = on
  if on then
    S.RunService:BindToRenderStep("BasedEsp", Enum.RenderPriority.Camera.Value + 3, function()
      local ok, err = pcall(step)
      if not ok then B.fault("esp", err); Config.set("esp.enabled", false) end
    end)
  else
    pcall(function() S.RunService:UnbindFromRenderStep("BasedEsp") end)
    for _, object in pairs(Esp.objects) do object:hide() end
  end
end

function Esp.define()
  Config.define("esp.enabled", false)
  Config.define("esp.elements", { "box", "name", "health", "distance" })
  Config.define("esp.box", "corners")
  Config.define("esp.fill", false)
  Config.define("esp.fillTwo", false)
  Config.define("esp.fillColor2", util.hex("FF6BD5"))
  Config.define("esp.boxWidth", 56)
  Config.define("esp.minSize", 12)
  Config.define("esp.colorMode", "custom")
  Config.define("esp.color", util.hex("C9C2FF"))
  Config.define("esp.friendColor", util.hex("45DDA8"))
  Config.define("esp.seenTint", false)
  Config.define("esp.seenColor", util.hex("FFD166"))
  Config.define("esp.markTarget", true)
  Config.define("esp.targetColor", util.hex("FF6B6B"))
  Config.define("esp.range", 3000)
  Config.define("esp.nameRange", FAR)
  Config.define("esp.skeletonRange", 500)
  Config.define("esp.maxPlayers", EVERYONE)
  Config.define("esp.teamCheck", false)
  Config.define("esp.displayNames", true)
  Config.define("esp.textSize", 13)
  Config.define("esp.thickness", 2)
  Config.define("esp.tracerFrom", "bottom")
  Config.define("esp.arrowSize", 18)
  Config.define("esp.arrowRadius", 36)
  Config.define("esp.arrowDistance", true)
  Config.define("esp.fade", true)
  Config.define("esp.fadeFrom", 55)
  Config.define("esp.dimHidden", false)
  Config.define("esp.hideHidden", false)
  Config.define("esp.chamsFill", 75)
  Config.define("esp.chamsOutline", true)
end

function Esp.start()
  if Esp.started then return end
  Esp.started = true
  Esp.define()
  Roster.start()
  gui = B.screen(8000)
  layer = UI.frame(gui, { Name = "Esp", Size = UDim2.fromScale(1, 1) })
  arrowLayer = UI.frame(gui, { Name = "Arrows", Size = UDim2.fromScale(1, 1) })
  highlights = Instance.new("Folder")
  highlights.Name = util.randomName()
  highlights.Parent = gui
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  O = Config.mirror({ enabled = "esp.enabled", box = "esp.box", fill = "esp.fill", fillTwo = "esp.fillTwo", fillColor2 = "esp.fillColor2", boxWidth = "esp.boxWidth", minSize = "esp.minSize", colorMode = "esp.colorMode",
    color = "esp.color", friendColor = "esp.friendColor", seenTint = "esp.seenTint", seenColor = "esp.seenColor", markTarget = "esp.markTarget",
    targetColor = "esp.targetColor", range = "esp.range", nameRange = "esp.nameRange", skeletonRange = "esp.skeletonRange", maxPlayers = "esp.maxPlayers",
    teamCheck = "esp.teamCheck", displayNames = "esp.displayNames", textSize = "esp.textSize", thickness = "esp.thickness", tracerFrom = "esp.tracerFrom",
    arrowSize = "esp.arrowSize", arrowRadius = "esp.arrowRadius", arrowDistance = "esp.arrowDistance", fade = "esp.fade", fadeFrom = "esp.fadeFrom",
    dimHidden = "esp.dimHidden", hideHidden = "esp.hideHidden", chamsFill = "esp.chamsFill", chamsOutline = "esp.chamsOutline" })
  Esp.options = O
  local function elements(list)
    table.clear(want)
    for _, name in ipairs(list) do want[name] = true end
  end
  elements(Config.get("esp.elements"))
  Config.on("esp.elements", elements)
  Esp.want = want
  Config.on("esp.enabled", setRunning, true)
  -- a player who left takes their overlay with them
  Roster.changed:connect(function(entry)
    if entry.gone then
      local object = Esp.objects[entry]
      if object then object:destroy(); Esp.objects[entry] = nil end
    end
  end)
  B.own(function() setRunning(false) end)
end
end
do -- 23_aim.lua
-- ============================================================================
--  23 aim      aim assist, FOV ring, triggerbot
--
--  Two ways to turn toward a target. "Mouse" feeds relative mouse movement to
--  the game, so the game's own camera does the turning (works with any camera
--  script, first or third person). "Camera" writes the camera's CFrame, for
--  games that leave the default camera alone. Both close the gap by a fraction
--  per frame derived from frame time, so the feel is the same at 60 and 240 fps,
--  and each axis can have its own.
--
--  Far targets need three things the first version did not have: a range with
--  no ceiling, a line of sight that is cast in lengths a ray can see along (one
--  ray finds nothing past 15,000 studs, which read as "in view"), and a lead
--  that knows a shot takes time to arrive and falls on the way.
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Roster, Hud, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Roster, B.Hud, B.Assets
local UIS = S.UserInputService
local Aim = { target = nil, active = false }
B.Aim = Aim
local FAR = 100000        -- the last stop of the Range slider: no limit
local WHOLE = 2500        -- the last stop of the circle: the whole screen
Aim.FAR, Aim.WHOLE = FAR, WHOLE
local O
local wantParts = {}
local rayParams
local ring, ringStroke, mark, markStroke, crossA, crossB, snap, note, gui
local toggled = false
local lostAt = -math.huge     -- when the last target was lost: a new one waits out the switch delay
local onSince, onWho = nil, nil
local canMouse = type(mousemoverel) == "function"
Aim.canMouse = canMouse
Aim.canClick = type(mouse1click) == "function" or (type(mouse1press) == "function" and type(mouse1release) == "function")

local function aimPoint(entry, camera, origin)
  -- returns the part to aim at, where it is on screen, and how far that is from the crosshair
  local best, bestScreen, bestDistance
  local function consider(part)
    if not part then return end
    local p = camera:WorldToViewportPoint(part.Position + Vector3.new(0, O.offset, 0))
    if p.Z <= 0 then return end
    local d = (Vector2.new(p.X, p.Y) - origin).Magnitude
    if not bestDistance or d < bestDistance then best, bestScreen, bestDistance = part, p, d end
  end
  local joints = entry.joints
  if wantParts.nearest then
    consider(entry.head); consider(joints.UpperTorso or joints.Torso); consider(entry.root); consider(joints.LowerTorso)
  else
    local part = (wantParts.head and entry.head) or (wantParts.torso and (joints.UpperTorso or joints.Torso)) or (wantParts.root and entry.root) or entry.head or entry.root
    consider(part)
  end
  return best, bestScreen, bestDistance
end

-- Is there a clear line from the camera to that point? With "see through glass" on, something
-- that can be seen through or walked through does not count as a wall.
local function visible(camera, entry, point)
  local from = camera.CFrame.Position
  local ignore = { B.LP.Character, entry.character }
  for _ = 1, O.wallClear and 6 or 1 do
    rayParams.FilterDescendantsInstances = ignore
    local hit = util.ray(from, point, rayParams)
    if not hit then return true end
    local part = hit.Instance
    if not (O.wallClear and part:IsA("BasePart") and (part.Transparency >= 0.8 or not part.CanCollide)) then return false end
    ignore[#ignore + 1] = part
  end
  return false
end

local function valid(entry, camPos)
  if not entry.alive or not entry.root or not entry.root.Parent then return false end
  if Roster.isHidden(entry) then return false end
  if O.teamCheck and not Roster.isEnemy(entry) then return false end
  if O.ignoreFriends and Roster.isFriend(entry) then return false end
  if O.skipShielded and entry.shielded then return false end
  if O.onlyMarked and Roster.anyTargets() and not Roster.isTarget(entry) then return false end
  return O.range >= FAR or (entry.root.Position - camPos).Magnitude <= O.range
end

-- what a candidate is ranked by: lower is better
local function rank(entry, pixels, camPos)
  if O.priority == "distance" then return (entry.root.Position - camPos).Magnitude end
  if O.priority == "health" then return (entry.health or 100) / (entry.maxHealth or 100) end
  return pixels
end
local function better(a, b)
  -- a marked target comes before anyone who is not
  if a[5] ~= b[5] then return a[5] end
  return a[4] < b[4]
end

local function pick(camera, origin, now)
  local camPos = camera.CFrame.Position
  local radius = O.fov >= WHOLE and math.huge or O.fov
  -- keep the current target while it stays valid and close to the crosshair
  local current = Aim.target
  if current then
    if valid(current, camPos) then
      if O.sticky then
        local part, screen, distance = aimPoint(current, camera, origin)
        if part and distance <= radius * 1.6 and (not O.wallCheck or visible(camera, current, part.Position)) then
          return current, part, screen
        end
      end
    else
      -- dead, gone or no longer allowed: the next one is not taken at once
      lostAt = now
    end
  end
  if now - lostAt < O.switchDelay / 1000 then return nil end
  local candidates = {}
  for _, entry in ipairs(Roster.list) do
    if valid(entry, camPos) then
      local part, screen, distance = aimPoint(entry, camera, origin)
      if part and distance <= radius then candidates[#candidates + 1] = { entry, part, screen, rank(entry, distance, camPos), Roster.isTarget(entry) } end
    end
  end
  table.sort(candidates, better)
  -- best first; at most three wall checks a frame
  for index = 1, math.min(#candidates, 3) do
    local c = candidates[index]
    if not O.wallCheck or visible(camera, c[1], c[2].Position) then return c[1], c[2], c[3] end
  end
  return nil
end

local function isActive()
  if not O.enabled then return false end
  if O.mode == "always" then return true end
  if O.mode == "toggle" then return toggled end
  return Config.keyDown(O.key)
end

local lastClick = 0
local function click()
  if type(mouse1click) == "function" then mouse1click()
  elseif type(mouse1press) == "function" then mouse1press(); task.delay(0.02, mouse1release) end
end

-- the ring, the mark on the target and the line to it all take one colour: the accent, or your own
local function paint()
  if not ring then return end
  local color = O.ownColor and O.color or T.accent
  local alpha = 1 - O.fovOpacity / 100
  ringStroke.Color, ringStroke.Thickness, ringStroke.Transparency = color, O.fovThickness, alpha
  ring.BackgroundColor3 = color
  ring.BackgroundTransparency = O.fovFill and 1 - 0.07 * O.fovOpacity / 100 or 1
  markStroke.Color, crossA.BackgroundColor3, crossB.BackgroundColor3, snap.ImageColor3 = color, color, color, color
  local style = O.markStyle
  local size = style == "ring" and 24 or 9
  mark.Size = UDim2.fromOffset(size, size)
  markStroke.Enabled = style ~= "cross"
  crossA.Visible, crossB.Visible = style == "cross", style == "cross"
end
local function hideMarks()
  if mark and mark.Visible then mark.Visible = false end
  if snap and snap.Visible then snap.Visible = false end
  if note and note.Visible then note.Visible = false end
end

local function step(dt)
  local camera = workspace.CurrentCamera
  if not camera then return end
  local now = os.clock()
  local mouse = UIS:GetMouseLocation()
  local locked = UIS.MouseBehavior == Enum.MouseBehavior.LockCenter
  local origin = locked and camera.ViewportSize * 0.5 or mouse
  if ring then
    local showRing = O.enabled and O.showFov and O.fov < WHOLE and not (B.Window.anyOpen() and UI.popoverOpen())
    if ring.Visible ~= showRing then ring.Visible = showRing end
    if showRing then
      ring.Position = UDim2.fromOffset(origin.X, origin.Y)
      local d = O.fov * 2
      if ring.Size.X.Offset ~= d then ring.Size = UDim2.fromOffset(d, d) end
    end
  end
  local active = isActive() and not (B.Window.anyOpen() and UIS:GetFocusedTextBox() ~= nil)
  Aim.active = active
  if active then
    local entry, part, screen = pick(camera, origin, now)
    Aim.target = entry
    if entry and part then
      local camPos = camera.CFrame.Position
      local goal = part.Position + Vector3.new(0, O.offset, 0)
      if O.predict then
        -- where they will be when it arrives: your ping, the extra asked for, and the shot's own
        -- flight if it has one, which also falls on the way
        local lead = O.lead / 1000 + (Hud and Hud.ping() or 0) / 1000
        if O.bulletSpeed > 0 then
          local flight = (goal - camPos).Magnitude / O.bulletSpeed
          lead += flight
          goal += Vector3.new(0, 0.5 * O.drop * flight * flight, 0)
        end
        goal += entry.root.AssemblyLinearVelocity * lead
        local p = camera:WorldToViewportPoint(goal)
        if p.Z > 0 then screen = p end
      end
      local offX, offY = screen.X - origin.X, screen.Y - origin.Y
      -- inside the dead zone it is close enough: no hunting about a point it is already on
      if offX * offX + offY * offY > O.deadzone * O.deadzone then
        -- fraction of the remaining gap to close this frame, each way
        local gainX = 1 - math.exp(-dt * util.lerp(46, 3.2, util.clamp01(O.smooth / 100)))
        local gainY = O.split and 1 - math.exp(-dt * util.lerp(46, 3.2, util.clamp01(O.smoothY / 100))) or gainX
        if O.method == "mouse" and canMouse then
          local dx, dy = offX * gainX * (O.sens / 100), offY * gainY * (O.sens / 100)
          if math.abs(dx) + math.abs(dy) > 0.05 then mousemoverel(dx, dy) end
        else
          -- turn and tilt separately, about the world's up: the camera never rolls
          local cf = camera.CFrame
          local look, to = cf.LookVector, (goal - cf.Position).Unit
          local yaw, pitch = math.atan2(-look.X, -look.Z), math.asin(math.clamp(look.Y, -1, 1))
          local turn = (math.atan2(-to.X, -to.Z) - yaw + math.pi) % (2 * math.pi) - math.pi
          local tilt = math.asin(math.clamp(to.Y, -1, 1)) - pitch
          camera.CFrame = CFrame.new(cf.Position) * CFrame.Angles(0, yaw + turn * gainX, 0) * CFrame.Angles(pitch + tilt * gainY, 0, 0)
        end
      end
      if mark then
        mark.Visible = O.showTarget
        mark.Position = UDim2.fromOffset(screen.X, screen.Y)
        local lineOn = O.snapline
        if snap.Visible ~= lineOn then snap.Visible = lineOn end
        if lineOn then
          local length = math.sqrt(offX * offX + offY * offY)
          snap.Position = UDim2.fromOffset((origin.X + screen.X) * 0.5, (origin.Y + screen.Y) * 0.5)
          snap.Size = UDim2.fromOffset(length, 3.6)
          snap.Rotation = math.deg(math.atan2(offY, offX))
        end
        local noteOn = O.targetInfo
        if note.Visible ~= noteOn then note.Visible = noteOn end
        if noteOn then
          note.Position = UDim2.fromOffset(screen.X, screen.Y + 16)
          local words = entry.display .. "  ·  " .. util.studs((entry.root.Position - camPos).Magnitude) .. " st"
          if entry.health then words ..= "  ·  " .. math.floor(entry.health + 0.5) .. " hp" end
          if note.Text ~= words then note.Text = words end
        end
      end
    else
      hideMarks()
    end
  else
    Aim.target = nil
    hideMarks()
  end

  -- triggerbot: fire when the crosshair rests on an enemy
  if O.trigger and Aim.canClick and not B.Window.anyOpen() and (O.triggerMode ~= "key" or Config.keyDown(O.key)) then
    local ray = camera:ViewportPointToRay(origin.X, origin.Y)
    rayParams.FilterDescendantsInstances = { B.LP.Character }
    local reach = O.range >= FAR and FAR or O.range
    local hit = util.ray(ray.Origin, ray.Origin + ray.Direction * reach, rayParams)
    local model = hit and hit.Instance and hit.Instance:FindFirstAncestorOfClass("Model")
    local player = model and S.Players:GetPlayerFromCharacter(model)
    local entry = player and Roster.byPlayer[player]
    if entry and valid(entry, camera.CFrame.Position) and (not O.triggerHead or hit.Instance.Name == "Head") then
      -- on someone: how long for, and is it time for another shot
      if onWho ~= entry then onWho, onSince = entry, now end
      if now - onSince >= O.triggerReact / 1000 and now - lastClick > math.max(0.03, O.triggerDelay / 1000) then
        lastClick = now
        click()
      end
    else
      onWho, onSince = nil, nil
    end
  else
    onWho, onSince = nil, nil
  end
end

function Aim.define()
  Config.define("aim.enabled", false)
  Config.define("aim.mode", "hold")
  Config.define("aim.key", "MouseButton2")
  Config.define("aim.method", canMouse and "mouse" or "camera")
  Config.define("aim.fov", 140)
  Config.define("aim.showFov", true)
  Config.define("aim.fovThickness", 1.5)
  Config.define("aim.fovOpacity", 65)
  Config.define("aim.fovFill", false)
  Config.define("aim.ownColor", false)
  Config.define("aim.color", util.hex("C9C2FF"))
  Config.define("aim.showTarget", true)
  Config.define("aim.markStyle", "dot")
  Config.define("aim.snapline", false)
  Config.define("aim.targetInfo", false)
  Config.define("aim.smooth", 45)
  Config.define("aim.split", false)
  Config.define("aim.smoothY", 45)
  Config.define("aim.sens", 100)
  Config.define("aim.deadzone", 0)
  Config.define("aim.offset", 0)
  Config.define("aim.parts", { "head" })
  Config.define("aim.priority", "crosshair")
  Config.define("aim.onlyMarked", false)
  Config.define("aim.switchDelay", 0)
  Config.define("aim.teamCheck", true)
  Config.define("aim.wallCheck", true)
  Config.define("aim.wallClear", false)
  Config.define("aim.ignoreFriends", true)
  Config.define("aim.skipShielded", true)
  Config.define("aim.range", 2000)
  Config.define("aim.sticky", true)
  Config.define("aim.predict", false)
  Config.define("aim.lead", 0)
  Config.define("aim.bulletSpeed", 0)
  Config.define("aim.drop", 0)
  Config.define("aim.trigger", false)
  Config.define("aim.triggerMode", "always")
  Config.define("aim.triggerDelay", 80)
  Config.define("aim.triggerReact", 0)
  Config.define("aim.triggerHead", false)
end

function Aim.start()
  if Aim.started then return end
  Aim.started = true
  Aim.define()
  Roster.start()
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  O = Config.mirror({ enabled = "aim.enabled", mode = "aim.mode", key = "aim.key", method = "aim.method", fov = "aim.fov", showFov = "aim.showFov",
    fovThickness = "aim.fovThickness", fovOpacity = "aim.fovOpacity", fovFill = "aim.fovFill", ownColor = "aim.ownColor", color = "aim.color",
    showTarget = "aim.showTarget", markStyle = "aim.markStyle", snapline = "aim.snapline", targetInfo = "aim.targetInfo", smooth = "aim.smooth",
    split = "aim.split", smoothY = "aim.smoothY", sens = "aim.sens", deadzone = "aim.deadzone", offset = "aim.offset", priority = "aim.priority",
    onlyMarked = "aim.onlyMarked", switchDelay = "aim.switchDelay", teamCheck = "aim.teamCheck", wallCheck = "aim.wallCheck", wallClear = "aim.wallClear",
    ignoreFriends = "aim.ignoreFriends", skipShielded = "aim.skipShielded", range = "aim.range", sticky = "aim.sticky", predict = "aim.predict",
    lead = "aim.lead", bulletSpeed = "aim.bulletSpeed", drop = "aim.drop", trigger = "aim.trigger", triggerMode = "aim.triggerMode",
    triggerDelay = "aim.triggerDelay", triggerReact = "aim.triggerReact", triggerHead = "aim.triggerHead" })
  Aim.options = O
  local function parts(list)
    table.clear(wantParts)
    for _, name in ipairs(list) do wantParts[name] = true end
  end
  parts(Config.get("aim.parts"))
  Config.on("aim.parts", parts)

  gui = B.screen(8500)
  ring = UI.frame(gui, { Name = "Fov", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(280, 280), Visible = false })
  UI.corner(ring, true)
  ringStroke = Instance.new("UIStroke")
  ringStroke.Parent = ring
  -- the line from the crosshair to the target, under the mark
  snap = UI.new("ImageLabel", { Name = "Snap", BackgroundTransparency = 1, Image = Assets.image("line") or "", AnchorPoint = Vector2.new(0.5, 0.5), ImageTransparency = 0.35,
    Visible = false, Parent = gui })
  mark = UI.frame(gui, { Name = "Target", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(9, 9), Visible = false, BackgroundTransparency = 1 })
  UI.corner(mark, true)
  markStroke = Instance.new("UIStroke")
  markStroke.Thickness = 1.5
  markStroke.Parent = mark
  crossA = UI.frame(mark, { Name = "CrossA", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 2), Rotation = 45,
    BackgroundTransparency = 0, Visible = false })
  crossB = UI.frame(mark, { Name = "CrossB", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(15, 2), Rotation = -45,
    BackgroundTransparency = 0, Visible = false })
  note = UI.new("TextLabel", { Name = "Note", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0), Size = UDim2.fromOffset(320, 14), FontFace = B.F.mono500,
    TextSize = 11, Text = "", TextColor3 = Color3.new(1, 1, 1), TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.5, Visible = false, Parent = gui })
  paint()
  for _, id in ipairs({ "aim.fovThickness", "aim.fovOpacity", "aim.fovFill", "aim.ownColor", "aim.color", "aim.markStyle", "app.accent", "app.scheme" }) do
    Config.on(id, function() task.defer(paint) end)
  end

  B.connect(UIS.InputBegan, function(input, processed)
    if O.mode ~= "toggle" or not O.enabled or Config.capturing then return end
    if input.UserInputType == Enum.UserInputType.Keyboard and UIS:GetFocusedTextBox() then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard and processed then return end
    if Config.keyName(input) == O.key then toggled = not toggled end
  end, "aim.toggle")

  local running = false
  local function refresh()
    local need = O.enabled or O.trigger
    if need == running then return end
    running = need
    if need then
      S.RunService:BindToRenderStep("BasedAim", Enum.RenderPriority.Camera.Value + 1, function(dt)
        local ok, err = pcall(step, dt)
        if not ok then B.fault("aim", err); Config.set("aim.enabled", false); Config.set("aim.trigger", false) end
      end)
    else
      pcall(function() S.RunService:UnbindFromRenderStep("BasedAim") end)
      ring.Visible = false
      hideMarks()
      Aim.target, Aim.active = nil, false
    end
  end
  Config.on("aim.enabled", refresh)
  Config.on("aim.trigger", refresh)
  refresh()
  B.own(function() pcall(function() S.RunService:UnbindFromRenderStep("BasedAim") end) end)
end
end
do -- 24_move.lua
-- ============================================================================
--  24 move     speed, jump, noclip, click teleport, gravity
--
--  Everything here restores what it changed when it is switched off, and
--  re-applies itself after a respawn. Flight lives in 26_flight.
-- ============================================================================
local S, Config = B.S, B.Config
local UIS = S.UserInputService
local Move = {}
B.Move = Move
local O
local saved = {}          -- original humanoid values, per character

local function parts()
  local character = B.character()
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  local root = character and (character:FindFirstChild("HumanoidRootPart") or character.PrimaryPart)
  return character, humanoid, root
end
local function remember(humanoid)
  if saved.humanoid ~= humanoid then
    saved = { humanoid = humanoid, WalkSpeed = humanoid.WalkSpeed, JumpPower = humanoid.JumpPower, JumpHeight = humanoid.JumpHeight, UseJumpPower = humanoid.UseJumpPower }
  end
end

-- ---------------------------------------------------------------- noclip
local noclip = { character = nil, list = {}, changed = {}, added = nil }
local function noclipStep()
  local character = B.character()
  if not character then return end
  if noclip.character ~= character then
    if noclip.added then noclip.added:Disconnect() end
    noclip.character, noclip.list, noclip.changed = character, {}, {}
    for _, part in ipairs(character:GetDescendants()) do
      if part:IsA("BasePart") then table.insert(noclip.list, part) end
    end
    noclip.added = character.DescendantAdded:Connect(function(part)
      if part:IsA("BasePart") then table.insert(noclip.list, part) end
    end)
  end
  for _, part in ipairs(noclip.list) do
    if part.CanCollide then
      part.CanCollide = false
      noclip.changed[part] = true
    end
  end
end
local function stopNoclip()
  if noclip.added then noclip.added:Disconnect() end
  for part in pairs(noclip.changed) do
    -- only the parts that normally collide get it back
    local name = part.Name
    if part.Parent and (name == "HumanoidRootPart" or name == "Torso" or name == "UpperTorso" or name == "LowerTorso" or name == "Head") then part.CanCollide = true end
  end
  noclip = { character = nil, list = {}, changed = {}, added = nil }
end

-- ---------------------------------------------------------------- per-step work
local function physics(dt)
  local _, humanoid, root = parts()
  if not humanoid or not root then return end
  if O.speed or O.jump then remember(humanoid) end
  if O.speed then
    if O.speedMode == "cframe" then
      local direction = humanoid.MoveDirection
      local flight = B.Flight and B.Flight.state
      if direction.Magnitude > 0.05 and flight ~= "flying" and flight ~= "landing" then
        root.CFrame += direction * math.max(0, O.speedValue - humanoid.WalkSpeed) * dt
      end
    elseif humanoid.WalkSpeed ~= O.speedValue then
      humanoid.WalkSpeed = O.speedValue
    end
  end
  if O.jump then
    if not humanoid.UseJumpPower then humanoid.UseJumpPower = true end
    if humanoid.JumpPower ~= O.jumpValue then humanoid.JumpPower = O.jumpValue end
  end
end
local function restore(what)
  local humanoid = saved.humanoid
  if not humanoid or not humanoid.Parent then return end
  if what == "speed" then humanoid.WalkSpeed = saved.WalkSpeed end
  if what == "jump" then
    humanoid.UseJumpPower = saved.UseJumpPower
    humanoid.JumpPower, humanoid.JumpHeight = saved.JumpPower, saved.JumpHeight
  end
end

function Move.teleport(position)
  local _, _, root = parts()
  if not root then return false end
  root.CFrame = CFrame.new(position) * root.CFrame.Rotation
  root.AssemblyLinearVelocity = Vector3.zero
  return true
end

function Move.define()
  Config.define("move.speed", false)
  Config.define("move.speedValue", 32)
  Config.define("move.speedMode", "humanoid")
  Config.define("move.jump", false)
  Config.define("move.jumpValue", 80)
  Config.define("move.infJump", false)
  Config.define("move.noclip", false)
  Config.define("move.clickTp", false)
  Config.define("move.gravity", false)
  Config.define("move.gravityValue", 80)
end

function Move.start()
  if Move.started then return end
  Move.started = true
  Move.define()
  O = Config.mirror({ speed = "move.speed", speedValue = "move.speedValue", speedMode = "move.speedMode",
    jump = "move.jump", jumpValue = "move.jumpValue", infJump = "move.infJump", noclip = "move.noclip", clickTp = "move.clickTp",
    gravity = "move.gravity", gravityValue = "move.gravityValue" })
  Move.options = O
  B.connect(S.RunService.Heartbeat, physics, "move.physics")
  B.connect(S.RunService.Stepped, function() if O.noclip then noclipStep() end end, "move.noclip")
  Config.on("move.noclip", function(on) if not on then stopNoclip() end end)
  Config.on("move.speed", function(on) if not on then restore("speed") end end)
  Config.on("move.speedMode", function() restore("speed") end)
  Config.on("move.jump", function(on) if not on then restore("jump") end end)
  local baseGravity = workspace.Gravity
  local function gravity()
    workspace.Gravity = O.gravity and O.gravityValue or baseGravity
  end
  Config.on("move.gravity", gravity)
  Config.on("move.gravityValue", gravity)
  if O.gravity then gravity() end
  B.connect(UIS.JumpRequest, function()
    if not O.infJump then return end
    local _, humanoid = parts()
    if humanoid and humanoid.Health > 0 then humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end
  end, "move.infjump")
  B.connect(UIS.InputBegan, function(input, processed)
    if not O.clickTp or processed or input.UserInputType ~= Enum.UserInputType.MouseButton1 then return end
    if not UIS:IsKeyDown(Enum.KeyCode.LeftControl) then return end
    local camera = workspace.CurrentCamera
    local mouse = UIS:GetMouseLocation()
    local ray = camera:ViewportPointToRay(mouse.X, mouse.Y)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    params.FilterDescendantsInstances = { B.LP.Character }
    -- as far as there is anything to click on: cast in lengths a ray can see along
    local hit = B.util.ray(ray.Origin, ray.Origin + ray.Direction * 100000, params)
    if hit then Move.teleport(hit.Position + Vector3.new(0, 3.2, 0)) end
  end, "move.clicktp")
  B.own(function()
    stopNoclip(); restore("speed"); restore("jump")
    workspace.Gravity = baseGravity
  end)
end
end
do -- 25_world.lua
-- ============================================================================
--  25 world    lighting, camera, crosshair, server tools
-- ============================================================================
local S, util, Motion, Theme, UI, Config, Window = B.S, B.util, B.Motion, B.Theme, B.UI, B.Config, B.Window
local Lighting = S.Lighting
local World = {}
B.World = World
local Server = {}
B.Server = Server
local O

-- ---------------------------------------------------------------- lighting
local LIGHT = { "Brightness", "ClockTime", "FogEnd", "FogStart", "GlobalShadows", "Ambient", "OutdoorAmbient", "ExposureCompensation" }
local original = nil
local atmospheres = {}
local function capture()
  if original then return end
  original = {}
  for _, key in ipairs(LIGHT) do original[key] = Lighting[key] end
end
-- A game that keeps its own day takes the hour from somewhere. Da Hood's Framework writes
-- ClockTime every second (updateDAY) unless Lighting has a "DayTimeValue" attribute, which it
-- then uses for the clock, the street lights and the lit windows alike: so the hour locked here
-- goes there, and the game shows that hour itself, lights and all, instead of fighting it.
local dayWas, dayHeld = nil, false
local function gameDay(clock)
  local renv = type(getrenv) == "function" and getrenv() or nil
  local shared = renv and rawget(renv, "_G")
  local update = type(shared) == "table" and rawget(shared, "UpdateDay") or nil
  if type(update) ~= "function" then return end
  if clock ~= nil then
    if not dayHeld then dayWas, dayHeld = Lighting:GetAttribute("DayTimeValue"), true end
    if Lighting:GetAttribute("DayTimeValue") ~= clock then
      Lighting:SetAttribute("DayTimeValue", clock)
      -- (a call into the game's own code: Potassium then drops this thread's Plugin capability)
      pcall(update)
      B.identity()
    end
  elseif dayHeld then
    dayHeld = false
    Lighting:SetAttribute("DayTimeValue", dayWas)
    pcall(update)
    B.identity()
  end
end
local function applyLighting()
  local bright, noFog, time = O.fullbright, O.noFog, O.time
  if not (bright or noFog or time) then return end
  capture()
  if bright then
    if Lighting.Brightness ~= O.brightValue then Lighting.Brightness = O.brightValue end
    if Lighting.GlobalShadows then Lighting.GlobalShadows = false end
    local white = Color3.fromRGB(178, 178, 178)
    if Lighting.Ambient ~= white then Lighting.Ambient = white end
    if Lighting.OutdoorAmbient ~= white then Lighting.OutdoorAmbient = white end
    if Lighting.ExposureCompensation ~= 0 then Lighting.ExposureCompensation = 0 end
  end
  if time or bright then
    local clock = time and O.timeValue or 14
    gameDay(clock)
    if math.abs(Lighting.ClockTime - clock) > 0.02 then Lighting.ClockTime = clock end
  end
  if noFog or bright then
    if Lighting.FogEnd < 9e5 then Lighting.FogEnd = 1e6 end
    for _, child in ipairs(Lighting:GetChildren()) do
      if child:IsA("Atmosphere") then
        if atmospheres[child] == nil then atmospheres[child] = child.Density end
        if child.Density ~= 0 then child.Density = 0 end
      end
    end
  end
end
local function restoreLighting()
  if not original then return end
  if not O.fullbright then
    for _, key in ipairs({ "Brightness", "GlobalShadows", "Ambient", "OutdoorAmbient", "ExposureCompensation" }) do Lighting[key] = original[key] end
  end
  if not O.time and not O.fullbright then
    gameDay(nil)
    Lighting.ClockTime = original.ClockTime
  end
  if not O.noFog and not O.fullbright then
    Lighting.FogEnd, Lighting.FogStart = original.FogEnd, original.FogStart
    for atmosphere, density in pairs(atmospheres) do
      if atmosphere.Parent then atmosphere.Density = density end
    end
    table.clear(atmospheres)
  end
  if not (O.fullbright or O.noFog or O.time) then original = nil end
end

-- ---------------------------------------------------------------- crosshair
local cross
-- four arms and a dot, each with a dark keyline; returns the pieces for World.styleCrosshair
function World.makeCrosshair(parent, props)
  local root = UI.frame(parent, { Name = "Crosshair", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(2, 2) })
  if props then
    for key, value in pairs(props) do root[key] = value end
  end
  local function keyline(target)
    local stroke = Instance.new("UIStroke")
    stroke.Color = Color3.new(0, 0, 0)
    stroke.Transparency = 0.4
    stroke.Thickness = 1
    stroke.Parent = target
    return stroke
  end
  local arms = {}
  for index = 1, 4 do
    local arm = Instance.new("Frame")
    arm.BorderSizePixel = 0
    arm.AnchorPoint = Vector2.new(0.5, 0.5)
    arm.Parent = root
    arms[index] = { frame = arm, stroke = keyline(arm) }
  end
  local dot = Instance.new("Frame")
  dot.BorderSizePixel = 0
  dot.AnchorPoint = Vector2.new(0.5, 0.5)
  dot.Position = UDim2.fromScale(0.5, 0.5)
  UI.corner(dot, true)
  dot.Parent = root
  return { root = root, arms = arms, dot = dot, dotStroke = keyline(dot) }
end
local function buildCrosshair()
  if cross then return end
  cross = World.makeCrosshair(B.screen(8600), { Visible = false })
end
-- draws the crosshair into `cross` from the current settings; also used by the tab's preview
function World.styleCrosshair(target, o)
  local length, gap, thick = o.crossLength, o.crossGap, o.crossThickness
  local clear = 1 - o.crossOpacity / 100
  local offsets = { { 0, -(gap + length * 0.5) }, { 0, gap + length * 0.5 }, { -(gap + length * 0.5), 0 }, { gap + length * 0.5, 0 } }
  target.root.Rotation = o.crossRotation
  for index, arm in ipairs(target.arms) do
    local vertical = index <= 2
    arm.frame.Size = UDim2.fromOffset(vertical and thick or length, vertical and length or thick)
    arm.frame.Position = UDim2.new(0.5, offsets[index][1], 0.5, offsets[index][2])
    arm.frame.BackgroundColor3 = o.crossColor
    arm.frame.BackgroundTransparency = clear
    -- the first arm is the one above the centre: a T has none
    arm.frame.Visible = length > 0 and not (index == 1 and o.crossT)
    arm.stroke.Enabled = o.crossOutline
    arm.stroke.Transparency = 0.4 + 0.6 * clear
  end
  target.dot.Visible = o.crossDot
  target.dot.Size = UDim2.fromOffset(thick + 2, thick + 2)
  target.dot.BackgroundColor3 = o.crossColor
  target.dot.BackgroundTransparency = clear
  target.dotStroke.Enabled = o.crossOutline
  target.dotStroke.Transparency = 0.4 + 0.6 * clear
end
local function refreshCrosshair()
  if O.crosshair then
    buildCrosshair()
    World.styleCrosshair(cross, O)
    cross.root.Visible = true
  elseif cross then
    cross.root.Visible = false
  end
end

-- ---------------------------------------------------------------- server
function Server.rejoin()
  Window.toast({ title = "Rejoining", text = "Back in a moment.", icon = "refresh-cw" })
  task.delay(0.4, function()
    local ok, err = pcall(function()
      if #S.Players:GetPlayers() <= 1 then S.TeleportService:Teleport(game.PlaceId, B.LP)
      else S.TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, B.LP) end
    end)
    if not ok then Window.toast({ title = "Could not rejoin", text = tostring(err), icon = "triangle-alert", tone = "bad" }) end
  end)
end
function Server.hop()
  Window.toast({ title = "Looking for a server", icon = "shuffle" })
  task.spawn(B.safe("server.hop", function()
    local url = "https://games.roblox.com/v1/games/" .. game.PlaceId .. "/servers/Public?sortOrder=Desc&excludeFullGames=true&limit=100"
    local ok, body = pcall(function() return game:HttpGet(url) end)
    local data = ok and select(2, pcall(function() return S.HttpService:JSONDecode(body) end))
    local choices = {}
    if type(data) == "table" and type(data.data) == "table" then
      for _, server in ipairs(data.data) do
        if type(server) == "table" and server.id ~= game.JobId and (server.playing or 0) < (server.maxPlayers or 0) then choices[#choices + 1] = server end
      end
    end
    if #choices == 0 then
      Window.toast({ title = "No other server found", text = "This may be the only one open.", icon = "triangle-alert", tone = "warn" })
      return
    end
    -- any of them, or the one with the fewest people in it, or the most that still has room
    local mode = Config.get("world.hopMode")
    local pick = choices[math.random(1, #choices)]
    if mode == "empty" or mode == "full" then
      table.sort(choices, function(a, b)
        if mode == "empty" then return (a.playing or 0) < (b.playing or 0) end
        return (a.playing or 0) > (b.playing or 0)
      end)
      pick = choices[1]
    end
    Server.picked = pick
    S.TeleportService:TeleportToPlaceInstance(game.PlaceId, pick.id, B.LP)
  end))
end
function Server.copyJoin()
  local line = string.format('game:GetService("TeleportService"):TeleportToPlaceInstance(%d, "%s", game.Players.LocalPlayer)', game.PlaceId, game.JobId)
  local ok = B.clipboard(line)
  Window.toast(ok and { title = "Join script copied", text = "Run it to land in this exact server.", icon = "clipboard", tone = "ok" }
    or { title = "No clipboard access", icon = "triangle-alert", tone = "warn" })
end

World.CROSS = { "world.crossLength", "world.crossGap", "world.crossThickness", "world.crossColor", "world.crossDot", "world.crossOutline", "world.crossOpacity",
  "world.crossRotation", "world.crossT" }
function World.define()
  Config.define("world.fullbright", false)
  Config.define("world.brightValue", 2)
  Config.define("world.crossOpacity", 100)
  Config.define("world.crossRotation", 0)
  Config.define("world.crossT", false)
  Config.define("world.hopMode", "random")
  Config.define("world.noFog", false)
  Config.define("world.time", false)
  Config.define("world.timeValue", 14)
  Config.define("world.fov", false)
  Config.define("world.fovValue", 90)
  Config.define("world.zoom", false)
  Config.define("world.zoomValue", 400)
  Config.define("world.crosshair", false)
  Config.define("world.crossLength", 7)
  Config.define("world.crossGap", 4)
  Config.define("world.crossThickness", 2)
  Config.define("world.crossColor", Color3.new(1, 1, 1))
  Config.define("world.crossDot", true)
  Config.define("world.crossOutline", true)
  Config.define("world.antiAfk", true)
  Config.define("world.fpsCap", 0)
  Config.define("world.autoExec", false)
end

World.AFK_QUIET = 600       -- s with no input and no answer before one is given unasked: half of what the engine allows

function World.start()
  if World.started then return end
  World.started = true
  World.define()
  O = Config.mirror({ fullbright = "world.fullbright", noFog = "world.noFog", time = "world.time", timeValue = "world.timeValue", fov = "world.fov",
    fovValue = "world.fovValue", zoom = "world.zoom", zoomValue = "world.zoomValue", crosshair = "world.crosshair", crossLength = "world.crossLength",
    crossGap = "world.crossGap", crossThickness = "world.crossThickness", crossColor = "world.crossColor", crossDot = "world.crossDot",
    crossOutline = "world.crossOutline", crossOpacity = "world.crossOpacity", crossRotation = "world.crossRotation", crossT = "world.crossT",
    brightValue = "world.brightValue", antiAfk = "world.antiAfk", fpsCap = "world.fpsCap" })
  World.options = O
  -- Games rewrite lighting on their own clock (Da Hood: the hour every second). Held at 4 Hz
  -- alone, the game's hour showed for up to a quarter of a second each time (a flash the user
  -- saw at every change of hour): so a write by the game is answered the moment it is made,
  -- before that frame is drawn, and the 4 Hz pass stays for anything that has no signal.
  Motion.every(applyLighting, 4, "world.lighting")
  for _, key in ipairs(LIGHT) do
    B.connect(Lighting:GetPropertyChangedSignal(key), function()
      if O.fullbright or O.noFog or O.time then applyLighting() end
    end, "world.lighting." .. key)
  end
  for _, id in ipairs({ "world.fullbright", "world.noFog", "world.time" }) do
    Config.on(id, function(on) if on then applyLighting() else restoreLighting() end end)
  end
  Config.on("world.timeValue", applyLighting)
  Config.on("world.brightValue", applyLighting)

  local baseFov
  Motion.every(function()
    local camera = workspace.CurrentCamera
    if not camera then return end
    if O.fov then
      if not baseFov then baseFov = camera.FieldOfView end
      if math.abs(camera.FieldOfView - O.fovValue) > 0.05 then camera.FieldOfView = O.fovValue end
    elseif baseFov then
      camera.FieldOfView = baseFov
      baseFov = nil
    end
  end, nil, "world.fov")
  local baseZoom
  local function zoom()
    if O.zoom then
      baseZoom = baseZoom or B.LP.CameraMaxZoomDistance
      B.LP.CameraMaxZoomDistance = O.zoomValue
    elseif baseZoom then
      B.LP.CameraMaxZoomDistance = baseZoom
      baseZoom = nil
    end
  end
  Config.on("world.zoom", zoom)
  Config.on("world.zoomValue", zoom)
  zoom()

  Config.on("world.crosshair", refreshCrosshair)
  for _, id in ipairs(World.CROSS) do
    Config.on(id, refreshCrosshair)
  end
  refreshCrosshair()

  -- Anti-AFK. The idle kick is the engine's: twenty minutes with no input and the client is
  -- dropped. The engine says when it has begun counting (Idled: two minutes in, and again after),
  -- and each time is answered the way a player touching the mouse would. Should it never say so,
  -- the same answer is given on a clock of our own: once AFK_QUIET has gone with no input and no
  -- answer, and then that often. What it has done is kept, to be shown.
  local afk = { answered = 0, last = nil, input = os.clock(), failed = 0 }
  World.afk = afk
  local function answer()
    local ok = pcall(function()
      local virtual = S.VirtualUser
      virtual:CaptureController()
      virtual:ClickButton2(Vector2.new())
    end)
    if ok then
      afk.answered += 1
      afk.last = os.clock()
    else
      afk.failed += 1
    end
    return ok
  end
  B.connect(B.LP.Idled, function()
    if O.antiAfk then answer() end
  end, "world.afk")
  B.connect(S.UserInputService.InputBegan, function() afk.input = os.clock() end, "world.afk.input")
  Motion.every(function()
    if not O.antiAfk then return end
    local now = os.clock()
    if now - math.max(afk.input, afk.last or 0, afk.tried or 0) >= World.AFK_QUIET then
      afk.tried = now
      answer()
    end
  end, 0.2, "world.afk.clock")

  local function cap()
    if type(setfpscap) ~= "function" then return end
    pcall(setfpscap, O.fpsCap > 0 and O.fpsCap or 9999)
  end
  Config.on("world.fpsCap", cap)
  if O.fpsCap > 0 then cap() end

  -- carry the hub across a teleport, once per session
  local function queue()
    if World.queued or not Config.get("world.autoExec") or type(queue_on_teleport) ~= "function" then return end
    World.queued = true
    pcall(queue_on_teleport, 'pcall(function() loadstring(readfile("BasedHub.lua"))() end)')
  end
  Config.on("world.autoExec", queue)
  queue()

  B.own(function()
    O.fullbright, O.noFog, O.time = false, false, false
    restoreLighting()
    if baseFov and workspace.CurrentCamera then workspace.CurrentCamera.FieldOfView = baseFov end
    if baseZoom then B.LP.CameraMaxZoomDistance = baseZoom end
  end)
end
end
do -- 26_flight.lua
-- ============================================================================
--  26 flight   animated flight: charge, launch, cruise, sonic boom, timed landing
--
--  Physics is the Zod project's proven arrangement: a LinearVelocity and an
--  AlignOrientation on our own root (which we own, so it replicates) with the
--  humanoid parked in a state that applies no forces of its own. The effects
--  and sounds are Zod's too (zod/src/fx.lua and its captured particle pack).
--
--  The animations are the eleven supplied clips. They are marketplace pack
--  animations, so they load in any game and replicate to everyone; they are
--  R15 only. Each was sampled on a live rig on 2026-10-07 and the numbers
--  below come from that, not from watching them:
--
--    clip        length  torso pitch         what it is
--    idle         6.33 s   +11..+17 deg      float, bobbing half a stud
--    idle2        3.48 s    +4..+7, yaw -41  side-on float
--    slow         1.08 s   -31..-35          forward-leaning glide
--    aggressive   1.85 s     0..-9           upright, arms driving
--    up           2.75 s    -4..+6           upright climb
--    upFast       0.50 s    -5..-7           rigid rocket pose
--    aimDown      1.67 s   -24               leaning in, looking down
--    sonic        0.50 s   -83               flat, head first
--    down         0.60 s   -122              head-first dive
--    charge       4.83 s   see CHARGE        crouch with a hand on the ground
--    land         2.87 s   see LAND          descend, crouch, stand, float again
--
--  The pitch already inside a clip decides how much the ROOT is tilted on top
--  of it (POSE): the flat sonic pose follows the flight path fully, the upright
--  climb not at all. Every clip is published as a loop, including the landing,
--  so the landing is played once by hand and its feet are timed to the ground.
-- ============================================================================
local S, util, Config, Assets, fs = B.S, B.util, B.Config, B.Assets, B.fs
local ease = B.Motion.ease
local UIS = S.UserInputService
local STATE = Enum.HumanoidStateType
local UP = Vector3.yAxis
local Flight = { state = "off", speed = 0, ramp = 0, charge = 0, booms = 0, landings = 0, launches = 0, boomLog = {} }
B.Flight = Flight
-- How the body is carried. "constraints": a LinearVelocity and an AlignOrientation on the root,
-- the humanoid parked in a state of its own (the Zod arrangement, everywhere by default).
-- "frame": nothing is added to the body and its state is left to the humanoid; the flight puts
-- the root where it should be every frame, along a path that is looked along first (nothing that
-- is put somewhere collides on its way), with its velocity held at zero. The same way the Da Hood
-- ragebot carries the body, which is what that game's module asks for (games/dahood.lua).
Flight.body = "constraints"
local function byFrame() return Flight.body == "frame" end
-- The switch that flies. A game module can give flight a switch of its own (Da Hood: "dahood.fly",
-- off until it is put on there), so a universal flight left on elsewhere does not arm itself in it.
Flight.flag = "move.fly"
local faked = false          -- lv and ao are the frame mode's stand-ins, not instances
local O

local ANIMS = { idle = 108435473734278, idle2 = 91122978632763, idle3 = 94269438718677, idle4 = 76290458763814, slow = 76516494715741,
  aggressive = 114663559035455, up = 115265121798442, upFast = 116738664195186, aimDown = 83572938141768, sonic = 132624199623293,
  down = 120193221019191, hoverDown = 102323315718330, land = 107349693471273, charge = 89111716130280 }
Flight.ANIMS = ANIMS
-- Three clips came later and were sampled the same way (2026-10-08):
--   idle3      3.48 s  the side-on float of idle2 with the arms folded, hips 0.85 above standing
--   idle4      7.10 s  arms folded, the torso turning between 11 and 53 degrees to look about
--   hoverDown  1.00 s  upright, arms held out wide, barely moving: the easy way down
-- Hovering wears whichever of the four idles the player picks. The descend key alone, at an easy
-- pace, wears hoverDown; the head-first `down` is kept for a real dive.
local IDLES = { a = "idle", b = "idle2", c = "idle3", d = "idle4" }
local IDLE_ORDER = { "a", "b", "c", "d" }
-- follow: share of the flight path's elevation the root takes on.  lean: pitch added at speed
-- (radians, negative is forward).  rocket: stands the body's own axis along a climbing path.
-- dive: the same for a dive steeper than the clip's own.  bank: share of the turn lean rolled.
local POSE = {
  idle = { follow = 0, lean = 0, bank = 0.3 }, idle2 = { follow = 0, lean = 0, bank = 0.3 },
  idle3 = { follow = 0, lean = 0, bank = 0.3 }, idle4 = { follow = 0, lean = 0, bank = 0.3 },
  hoverDown = { follow = 0, lean = 0, bank = 0.2 },
  slow = { follow = 0.35, lean = 0, bank = 0.5 }, aggressive = { follow = 0.6, lean = -0.45, bank = 0.7 },
  aimDown = { follow = 0.5, lean = 0, bank = 0.5 }, sonic = { follow = 1, lean = 0, bank = 1 },
  up = { follow = 0, lean = 0, bank = 0.3, rocket = 0.5 }, upFast = { follow = 0, lean = 0, bank = 0.3, rocket = 1 },
  -- measured live in a straight dive at 900 st/s: at 0.5 the hips-to-head line sat 54 degrees off
  -- the path (the clip arches the head back up), so the dive takes the whole difference
  down = { follow = 0, lean = 0, bank = 0.4, dive = 1 },
}
-- The land clip, in seconds (root space, standing feet at -2.99):
--   0.00  leaning back with the feet 0.38 above the ground: the last of the descent
--   0.47  the feet reach the ground          0.68  a hand comes down beside them
--   0.78  the crouch is at its deepest       1.63  starts to stand
--   2.07  upright, feet still down           2.20  lifts off into a float again (it is a loop)
-- So it starts `lead` seconds before the ground and plays at contact/lead until the feet are
-- down, is held there until `hold`, and is faded out across the moment it stands upright.
local LAND = { lead = 0.6, contact = 0.46, hold = 1.0, out = 1.95, fade = 0.2 }
Flight.LAND = LAND
-- The charge clip stands at 0, is crouched by 0.33 s and then only breathes, with the torso at
-- its lowest at 2.25 s and 4.25 s. Turning playback around at those two still points holds the
-- crouch for as long as Space is held, and playback speed replicates where TimePosition does not.
local CHARGE = { low = 2.25, high = 4.25 }
local CLIMB_BOOST = 1.0      -- seconds of Space on a straight climb before it starts to accelerate
-- At the top of the speed range one frame is tens of studs (20,000 st/s at 240 fps is 83), and a
-- slow frame is hundreds. Two rules keep the ground solid anyway:
local HITCH = 0.05           -- speed into the ground is held to what a frame this long could cover
local PIN_SPEED = 1500       -- a landing faster than this is held on its path frame by frame
local DWELL = 0.25           -- a clip that has only just started is not swapped for its neighbour
local HOVER_DOWN_MAX = 500   -- the easy descent is only easy up to here: faster is a dive, whatever cruise is set to
local BOOM_GAP = 0.6         -- seconds between booms when a hard acceleration runs through several tiers
local SHADE = Color3.fromRGB(22, 36, 66)      -- the dark every pale image on the screen is backed with, so it shows on a bright sky
local VAPOUR = Color3.fromRGB(74, 96, 132)    -- the same idea for rings in the air: the blue-grey of vapour in shadow, not smoke
local PACK = { "SBoost", "KBoost", "STakeoff", "KTakeoff", "KSonic", "KHaze", "KCrater", "SSlam", "SImpact", "SWindTrail" }

local char, hum, root, animator
local tracks, current, currentSince = {}, nil, 0
local lv, ao, attachment
local vel, facing, lean = Vector3.zero, Vector3.new(0, 0, -1), 0
local savedAutoRotate, jumpWasEnabled
local chargeStart, chargeFx = 0, false
local spaceSince, launchUntil, launchVel = nil, 0, Vector3.zero
local stage, boomed, lastSonic, lastImpact, impact, floor = 0, 0, 0, 0, 0, nil
local airborneSince, landing, hinted, warmed = nil, nil, false, false
local idleChoice, idleIndex = { "idle" }, 1
local chargeHold
local rayParams, ignore, ignoreAt = nil, {}, -1
local tweens = {}

-- ---------------------------------------------------------------- helpers
local function alpha(rate, dt) return 1 - math.exp(-rate * dt) end
local function flat(v)
  local f = Vector3.new(v.X, 0, v.Z)
  return f.Magnitude > 1e-3 and f.Unit or nil
end
-- signed angle in degrees from one flat direction to another: a turn to the right is negative
local function signedYaw(from, to)
  local d = math.deg(math.atan2(to.X, to.Z) - math.atan2(from.X, from.Z))
  return (d + 180) % 360 - 180
end
local function alive() return hum ~= nil and root ~= nil and hum.Health > 0 and root.Parent ~= nil end
local function down(keyName) return UIS:GetFocusedTextBox() == nil and Config.keyDown(keyName) end
local function onGround()
  local state = hum:GetState()
  return hum.FloorMaterial ~= Enum.Material.Air and state ~= STATE.Freefall and state ~= STATE.Jumping and state ~= STATE.Physics
end
-- how far below the root's centre the soles are: R15 carries its leg length in HipHeight, R6 has
-- a HipHeight of 0 and two-stud legs
local function feetBelowRoot()
  local legs = 0
  if hum.RigType == Enum.HumanoidRigType.R6 then
    local leg = char:FindFirstChild("Left Leg")
    legs = leg and leg.Size.Y or 2
  end
  return hum.HipHeight + root.Size.Y * 0.5 + legs
end
local function volume() return (O.sound and O.volume or 0) / 100 end
-- effects run on the real clock: the hub's own motion speed setting must not slow a shockwave
local function animate(seconds, curve, apply)
  tweens[#tweens + 1] = { t = 0, length = math.max(seconds, 1e-3), curve = curve, apply = apply }
  apply(curve(0))
end
local function stepTweens(dt)
  for index = #tweens, 1, -1 do
    local tween = tweens[index]
    tween.t += dt
    local p = math.min(tween.t / tween.length, 1)
    local ok = pcall(tween.apply, tween.curve(p))
    if p >= 1 or not ok then table.remove(tweens, index) end
  end
end
local function later(seconds, instance)
  task.delay(seconds, function() if instance.Parent then instance:Destroy() end end)
end

-- ---------------------------------------------------------------- effects (ported from zod/src/fx.lua)
local Fx = { shake = 0, shakeTime = 0, fovKick = 0, roll = 0, offset = CFrame.identity, baseFov = nil, windAcc = 0, trails = false, rings = {}, speed = 0,
  dress = 0, mach = 0, pulseAcc = 0, lineAlpha = 0, tunnelAlpha = 0, lineClock = 0, punch = 0, ripples = 0, previewUntil = 0, previewTier = 0 }
Flight.Fx = Fx
local pack, templates, folder, soundHost = nil, {}, nil, nil
local function fxFolder()
  if folder and folder.Parent then return folder end
  folder = Instance.new("Folder")
  folder.Name = util.randomName()
  folder.Parent = workspace
  B.own(folder)
  return folder
end
local function loadPack()
  if pack ~= nil then return pack end
  pack = false
  local file = Assets.manifest.fx and Assets.manifest.fx.flight
  local source = file and fs.read(fs.path(file))
  local chunk = source and loadstring(source, "=flight-pack")
  if chunk then
    local ok, result = pcall(chunk)
    if ok and type(result) == "table" then pack = result end
  end
  return pack
end
-- Potassium may write MeshPart.MeshId directly (measured); an executor that may not gets the
-- mesh the supported way, in the background, and the template simply has it from then on.
local function ensureMesh(part, id)
  if part.MeshId ~= "" then return end
  task.spawn(function()
    local ok, made = pcall(function() return S.AssetService:CreateMeshPartAsync(Content.fromUri(id)) end)
    if not ok then ok, made = pcall(function() return S.AssetService:CreateMeshPartAsync(id) end) end
    if ok and made then
      pcall(function() part:ApplyMesh(made) end)
      made:Destroy()
    end
  end)
end
-- node = { class, parentIndex, properties, attributes, references }
local function buildTemplate(nodes)
  local made = table.create(#nodes)
  for index, node in ipairs(nodes) do
    local instance = Instance.new(node[1])
    for name, value in pairs(node[3]) do pcall(function() instance[name] = value end) end
    if node[4] then
      for name, value in pairs(node[4]) do instance:SetAttribute(name, value) end
    end
    if node[1] == "MeshPart" and node[3].MeshId then ensureMesh(instance, node[3].MeshId) end
    made[index] = instance
  end
  local top
  for index, node in ipairs(nodes) do
    if node[5] then
      for property, target in pairs(node[5]) do pcall(function() made[index][property] = made[target] end) end
    end
    if node[2] == 0 then top = top or made[index] else made[index].Parent = made[node[2]] end
  end
  -- The captured pressure-wave mesh carries a red, always-on-top Highlight: on screen that is a
  -- red flash across the whole body at every boom. Nothing here wants a Highlight.
  for _, instance in ipairs(made) do
    if instance:IsA("Highlight") then instance:Destroy() end
  end
  return top
end
local function template(name)
  local cached = templates[name]
  if cached == nil then
    local data = loadPack()
    cached = data and data[name] and buildTemplate(data[name]) or false
    templates[name] = cached
  end
  return cached or nil
end
local function clone(name)
  local source = template(name)
  return source and source:Clone() or nil
end
Flight.template = template
-- Mach 1 is the sonic speed, and a tier is one doubling of it: tier 1 from Mach 1, tier 2 from
-- Mach 2, tier 3 from Mach 4, and so on. Tier 1 is the boom as it has always been. From tier 2
-- up, every tier makes the boom, and what follows the body afterwards, bigger.
local function tierOf(speed)
  local mach = speed / math.max(O.sonic, 1)
  if mach < 1 then return 0, mach end
  return math.floor(math.log(mach, 2) + 1e-6) + 1, mach
end
Flight.tierOf = tierOf
-- a child of a pack template, by path
local function piece(key, ...)
  local node = template(key)
  for _, name in ipairs({ ... }) do
    node = node and node:FindFirstChild(name)
  end
  return node
end
-- An emitter grown by `scale` and made more solid by `gain` (1 leaves it be). Each is built once
-- and handed out as copies: the tiers only ever ask for a handful of sizes.
local variants = {}
local function variant(name, emitter, scale, gain)
  local made = variants[name]
  if not made then
    made = emitter:Clone()
    local sizes = {}
    for index, point in ipairs(emitter.Size.Keypoints) do
      sizes[index] = NumberSequenceKeypoint.new(point.Time, point.Value * scale, point.Envelope * scale)
    end
    made.Size = NumberSequence.new(sizes)
    if gain ~= 1 then
      local alphas = {}
      for index, point in ipairs(emitter.Transparency.Keypoints) do
        alphas[index] = NumberSequenceKeypoint.new(point.Time, math.clamp(1 - (1 - point.Value) * gain, 0, 1))
      end
      made.Transparency = NumberSequence.new(alphas)
    end
    variants[name] = made
  end
  return made:Clone()
end
-- The pack's shock rings are additive, and measured, their textures have no alpha at all (a pale
-- ring on a black square): they light up a dark sky and cannot be seen against a bright one. So
-- each gets two twins that can: the pack's vapour ring, which does have alpha, moving exactly as
-- the shock ring does, drawn once dark a little outside it and once pale a little inside.
local function twin(name, like, scale, dark)
  local key = (dark and "shade:" or "mist:") .. name
  local made = variants[key]
  if not made then
    local ring = piece("SBoost", "Attachment", "Ring")
    if not ring then return nil end
    made = like:Clone()
    local sizes = {}
    for index, point in ipairs(like.Size.Keypoints) do
      sizes[index] = NumberSequenceKeypoint.new(point.Time, point.Value * scale, point.Envelope * scale)
    end
    made.Size = NumberSequence.new(sizes)
    made.Texture = ring.Texture
    made.LightEmission, made.LightInfluence, made.Brightness = 0, 0, 1
    made.Color = ColorSequence.new(dark and VAPOUR or Color3.new(1, 1, 1))
    made.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.18, 0.62),
      NumberSequenceKeypoint.new(0.6, 0.78), NumberSequenceKeypoint.new(1, 1) })
    made.ZOffset = dark and -0.6 or -0.3
    variants[key] = made
  end
  return made:Clone()
end
-- fire every emitter the way the source games do: after EmitDelay, for EmitDuration or EmitCount
local function emit(top, scale)
  scale = scale or 1
  for _, item in ipairs(top:IsA("ParticleEmitter") and { top } or top:GetDescendants()) do
    if item:IsA("ParticleEmitter") then
      local delay, duration = item:GetAttribute("EmitDelay") or 0, item:GetAttribute("EmitDuration") or 0
      local count = item:GetAttribute("EmitCount") or item.Rate
      local function go()
        if not item.Parent then return end
        if duration > 0 then
          item.Enabled = true
          task.delay(duration, function() if item.Parent then item.Enabled = false end end)
        else
          item:Emit(math.max(1, math.floor(count * scale + 0.5)))
        end
      end
      if delay > 0.01 then task.delay(delay, go) else go() end
    end
  end
end
local function place(model, cf)
  if model:IsA("BasePart") then
    model.CFrame = cf
    model.Anchored, model.CanCollide, model.CanQuery, model.CanTouch = true, false, false, false
  end
  model.Parent = fxFolder()
end
local function tweenSize(part, to, seconds, curve)
  local from = part.Size
  animate(seconds, curve or ease.outCubic, function(p) part.Size = from:Lerp(to, p) end)
end

-- the first four are the Zod project's own files; the ids are the ones it measured loading anywhere
local SOUNDS = {
  boom = { file = "fly_boom", fallback = 558073810 }, takeoff = { file = "fly_takeoff", fallback = 138149044086182 },
  slam = { file = "fly_land", fallback = 107674019694824 }, wind = { file = "fly_wind", fallback = 5813077875 },
  crack = { id = 92631715509459 }, thump = { id = 558073810 }, step = { id = 18782450650 },
}
local function soundId(name)
  local spec = SOUNDS[name]
  if spec.id then return "rbxassetid://" .. spec.id end
  return Assets.sound(spec.file) or ("rbxassetid://" .. spec.fallback)
end
local function sounds()
  if soundHost and soundHost.Parent then return soundHost end
  soundHost = Instance.new("Folder")
  soundHost.Name = util.randomName()
  soundHost.Parent = S.SoundService
  B.own(soundHost)
  return soundHost
end
local function play(name, scale, pitch)
  local level = volume() * (scale or 1)
  if level <= 0 then return nil end
  local sound = Instance.new("Sound")
  sound.SoundId = soundId(name)
  sound.Volume = math.min(level, 10)
  sound.PlaybackSpeed = pitch or 1
  sound.Parent = sounds()
  sound:Play()
  later(10, sound)
  Fx.lastSound = name
  return sound
end

function Fx.kick(shake, fov)
  if O.fxShake then Fx.shake = math.max(Fx.shake, shake) end
  if O.fxFov then Fx.fovKick = math.max(Fx.fovKick, fov) end
end
function Fx.takeoff(groundAt, strength)
  strength = math.clamp(strength, 0.3, 1.6)
  if O.fxTakeoff then
    for _, name in ipairs({ "KTakeoff", "STakeoff" }) do
      local burst = clone(name)
      if burst then
        place(burst, CFrame.new(groundAt))
        emit(burst, strength)
        later(6, burst)
      end
    end
  end
  play("takeoff", 1.1, 0.95 + 0.1 * strength)
  Fx.kick(0.35 * strength, 6 * strength)
end

-- Rings and bursts ride ahead of the body, square to the direction of travel. Zod could weld them
-- above the head because it laid the whole root flat; here the clip supplies the pose and the root
-- stays nearer upright, so they are re-aimed along the real path every frame instead.
local function heading()
  if Fx.previewUntil > os.clock() and Fx.previewDir then return Fx.previewDir end
  if Flight.state == "flying" and vel.Magnitude > 8 then return vel.Unit end
  return UP
end
local function frameAlong(direction, distance)
  local at = root.Position + direction * distance
  return CFrame.lookAt(at, at + direction, math.abs(direction.Y) < 0.95 and UP or Vector3.xAxis)
end
local function ride(distance)
  local att = Instance.new("Attachment")
  att.Parent = root
  att.WorldCFrame = frameAlong(heading(), distance)
  Fx.rings[att] = distance
  return att
end
function Fx.aim()
  local direction = heading()
  for att, distance in pairs(Fx.rings) do
    if att.Parent then att.WorldCFrame = frameAlong(direction, distance) else Fx.rings[att] = nil end
  end
end
local function ringAttachment(names, enabled, distance)
  local source = template("SBoost")
  local holder = source and source:FindFirstChild("Attachment")
  if not holder or not root then return nil end
  local att = ride(distance)
  for _, name in ipairs(names) do
    local emitter = holder:FindFirstChild(name)
    if emitter then
      local copy = emitter:Clone()
      copy.Enabled = enabled
      copy.Parent = att
    end
  end
  return att
end
local function retire(att, seconds)
  for _, item in ipairs(att:GetChildren()) do
    if item:IsA("ParticleEmitter") then item.Enabled = false end
  end
  later(seconds, att)
end
function Fx.startCharge()
  if Fx.chargeAtt or not O.fxBoost then return end
  Fx.chargeAtt = ringAttachment({ "Ring", "Ring1" }, true, 3.2)
end
function Fx.stopCharge()
  local att = Fx.chargeAtt
  Fx.chargeAtt = nil
  if att then retire(att, 1) end
end
function Fx.boostRing(on)
  if on then
    if not Fx.boostAtt and O.fxBoost then Fx.boostAtt = ringAttachment({ "Ring2" }, true, 3.5) end
  elseif Fx.boostAtt then
    retire(Fx.boostAtt, 2)
    Fx.boostAtt = nil
  end
end
-- a glass shell welded to the root that swells and collapses: the pressure wave
function Fx.haze()
  local mesh = O.fxHaze and root and clone("KHaze")
  if not mesh then return end
  mesh.Anchored, mesh.CanCollide, mesh.CanQuery, mesh.CanTouch, mesh.Massless = false, false, false, false, true
  mesh.Material = Enum.Material.Glass
  mesh.Transparency = 6          -- the source game passes 6 on purpose: refraction with no fill
  mesh.Size = Vector3.new(0.2, 0.2, 0.2)
  mesh.CFrame = root.CFrame
  local weld = Instance.new("Weld")
  weld.Part0, weld.Part1 = root, mesh
  weld.Parent = mesh
  mesh.Parent = fxFolder()
  tweenSize(mesh, Vector3.new(20, 20, 20), 0.12, ease.outSine)
  task.delay(0.12, function() if mesh.Parent then tweenSize(mesh, Vector3.zero, 0.36, ease.inCubic) end end)
  later(0.6, mesh)
end
function Fx.boostStage(level)
  if not root then return end
  if O.fxBoost then
    local source = template("KBoost")
    local part = source and source:FindFirstChild("Boost" .. level)
    local holder = part and part:FindFirstChild("Attachment")
    if holder then
      local att = ride(3)
      -- an emitter's Acceleration is in world space: as captured, these gusts all blew toward
      -- +Z whichever way the flight was going. They are turned to blow back along the path.
      local back = -heading()
      for _, item in ipairs(holder:GetChildren()) do
        if item:IsA("ParticleEmitter") then
          local copy = item:Clone()
          local push = copy.Acceleration.Magnitude
          if push > 0 then copy.Acceleration = back * push end
          copy.Parent = att
        end
      end
      emit(att)
      later(3, att)
    end
    Fx.boostRing(true)
  end
  if level >= 3 then Fx.haze() end
  play("takeoff", 0.55, 1.1 + level * 0.12)
  Fx.kick(0.25 + level * 0.12, 3 + level * 2.5)
end
function Fx.sonicBoom(velocity, tier)
  if not root then return end
  local direction = velocity.Magnitude > 1 and velocity.Unit or root.CFrame.LookVector
  local over = math.clamp((tier or 1) - 1, 0, 6)      -- how far past the plain boom this one is
  if O.fxSonic then
    local att = ringAttachment({ "BigRing" }, false, 3.5)
    if att then
      local big = att:FindFirstChild("BigRing")
      if big then big:Emit(big:GetAttribute("EmitCount") or 3) end
      local source = template("SBoost")
      local vapor = source and source.Attachment:FindFirstChild("VaporCone")
      if vapor then
        local cone = Instance.new("Attachment")
        cone.CFrame = CFrame.new(0, 0, 2.5)
        cone.Parent = att
        local copy = vapor:Clone()
        copy.Enabled = true
        copy.Parent = cone
        task.delay(1, function() if copy.Parent then copy.Enabled = false end end)
      end
      later(4, att)
    end
    -- the ring left hanging in the air where the barrier broke
    local ring = clone("KSonic")
    if ring then
      place(ring, CFrame.lookAt(root.Position, root.Position + direction, math.abs(direction.Y) < 0.95 and UP or Vector3.xAxis) * CFrame.Angles(math.pi / 2, 0, 0))
      emit(ring)
      later(4, ring)
    end
    if over > 0 then
      -- Past Mach 2, anything left hanging in the air is behind the camera within a frame. So
      -- what grows with the speed is what travels WITH the body: shock rings that open around
      -- it one after another, each wider than the last, and a gust of wind thrown back off it.
      local rings = ride(2.5)
      local big = 1 + 0.55 * over
      for index = 1, math.min(1 + over, 5) do
        task.delay((index - 1) * 0.07, function()
          if not rings.Parent then return end
          local grown = big * (0.7 + 0.3 * index)
          for _, name in ipairs({ "Shockwave1", "Shockwave2" }) do
            local from = piece("KBoost", "Boost3", "Attachment", name)
            if from then
              local wave = variant(name .. ":" .. over .. ":" .. index, from, grown, 1)
              wave.Name = "MachRing"
              wave.Parent = rings
              wave:Emit(1)
            end
          end
          local like = piece("KBoost", "Boost3", "Attachment", "Shockwave2")
          for _, dark in ipairs({ true, false }) do
            local ring = like and twin("ring:" .. over .. ":" .. index, like, grown * (dark and 1.04 or 0.93), dark)
            if ring then
              ring.Name = dark and "MachRingShade" or "MachRingMist"
              ring.Parent = rings
              ring:Emit(1)
            end
          end
        end)
      end
      local wind = piece("KBoost", "Boost3", "Attachment", "Wind3")
      if wind then
        -- Seen live at Mach 16: seventy-odd of these at 1.6 times their opacity were a white
        -- cloud with a silhouette in it. A dozen or two, as drawn, read as wind.
        local gust = variant("gust:" .. over, wind, 1 + 0.15 * over, 1)
        gust.Name = "MachGust"
        gust.Acceleration = -direction * wind.Acceleration.Magnitude
        gust.Parent = rings
        gust:Emit(10 + 6 * over)
      end
      later(2.5, rings)
    end
  end
  Fx.haze()
  -- louder and lower the higher the tier; from Mach 2 the boom comes as the pair of bangs a real
  -- one is, and from Mach 8 there is a roll of thunder under it
  local pitch = math.max(1 - 0.06 * over, 0.64)
  play("boom", math.min(1.5 + 0.2 * over, 2.8), pitch)
  play("crack", 0.55, pitch)
  if over >= 1 then
    task.delay(0.11, function() play("boom", 1.1 + 0.15 * over, pitch * 0.82) end)
    Fx.punch = 1
  end
  if over >= 1 then Fx.ripple(tier) end
  if over >= 3 then
    play("thump", 0.9, 0.6)
    play("slam", 0.9, 0.7)
  end
  Fx.kick(math.min(1.1 + 0.3 * over, 2.6), math.min(16 + 4 * over, 36))
end
function Fx.crater(at, normal, power)
  power = math.clamp(power, 0.2, 2)
  if O.fxCrater then
    local up = normal or UP
    local cf = CFrame.lookAt(at, at + up, math.abs(up.Y) < 0.95 and UP or Vector3.xAxis) * CFrame.Angles(-math.pi / 2, 0, 0)
    if power >= 0.45 then
      local mesh = clone("KCrater")
      if mesh then
        local full = mesh.Size
        mesh.Size = Vector3.new(full.X * 0.2, full.Y, full.Z * 0.2) * power
        place(mesh, cf + up * 0.05)
        tweenSize(mesh, full * power, 0.18, ease.outCubic)
        emit(mesh, power)
        task.delay(5, function()
          if not mesh.Parent then return end
          local skin = mesh:FindFirstChildOfClass("SurfaceAppearance")
          if skin then skin:Destroy() end      -- a SurfaceAppearance ignores the fade otherwise
          animate(1.2, ease.linear, function(p) mesh.Transparency = p end)
        end)
        later(7, mesh)
      end
    end
    -- dust for every landing; the full slam ring only for the heavy ones
    local dust = clone(power >= 0.9 and "SSlam" or "STakeoff")
    if dust then
      place(dust, power >= 0.9 and cf or CFrame.new(at))
      emit(dust, math.clamp(power, 0.35, 1.4))
      later(5, dust)
    end
  end
  if power >= 0.9 then
    play("slam", 1.4)
    play("thump", 0.7)
  else
    play("step", 0.5 + power * 0.6)
  end
  Fx.kick(0.4 + 0.6 * power, 7 * power)
end
function Fx.wall(at, normal)
  if O.fxCrater then
    local mark = clone("SImpact")
    if mark then
      local size = mark.Size
      mark.Size = Vector3.new(0.1, 0.1, 0.1)
      place(mark, CFrame.lookAt(at, at + normal, math.abs(normal.Y) < 0.95 and UP or Vector3.xAxis))
      tweenSize(mark, size, 0.2)
      for _, item in ipairs(mark:GetDescendants()) do
        if item:IsA("ParticleEmitter") then item:Emit(item.Rate) end
      end
      later(5, mark)
    end
  end
  play("slam", 1.1)
  Fx.kick(0.9, 10)
end
local LIMBS = { "RightHand", "LeftHand", "RightFoot", "LeftFoot" }
-- limb trails last longer and show more the higher the tier
local function styleTrail(trail)
  local over = math.clamp(Fx.dress - 1, 0, 5)
  trail.Lifetime = 0.13 * (1 + 0.6 * over)
  trail.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.93 - 0.07 * over), NumberSequenceKeypoint.new(1, 1) })
end
function Fx.setTrails(on)
  on = on == true
  if on == Fx.trails or not char then return end
  Fx.trails = on
  local proto = on and template("SWindTrail")
  proto = proto and proto:FindFirstChildWhichIsA("Trail")
  for _, name in ipairs(LIMBS) do
    local limb = char:FindFirstChild(name)
    if limb then
      local a, b = limb:FindFirstChild("BasedTrailA"), limb:FindFirstChild("BasedTrailB")
      if on and not a and proto then
        a, b = Instance.new("Attachment"), Instance.new("Attachment")
        a.Name, b.Name = "BasedTrailA", "BasedTrailB"
        local half = limb.Size.X / 1.7 * 2
        a.CFrame, b.CFrame = CFrame.new(half, 0, 0), CFrame.new(-half, 0, 0)
        a.Parent, b.Parent = limb, limb
        local trail = proto:Clone()
        trail.Attachment0, trail.Attachment1 = a, b
        trail.Color = ColorSequence.new(O.trailColor)
        styleTrail(trail)
        trail.Enabled = true
        trail.Parent = a
      elseif not on and a then
        local trail = a:FindFirstChildWhichIsA("Trail")
        if trail then trail.Enabled = false end
        a.Name = "BasedTrailDone"
        if b then b.Name = "BasedTrailDone"; later(0.6, b) end
        later(0.6, a)
      end
    end
  end
end
-- Wind streaks: two points a hair apart with a trail between them, carried for a tenth of a
-- second and then let go, so each draws a line as long as that tenth of a second of flight. They
-- are pooled: the top tiers throw ninety a second, and making three instances for every one of
-- them is the kind of churn that shows up as a stutter.
local streaks, streakFree = {}, {}
Fx.streaks = streaks
local function windStreak()
  local terrain = workspace:FindFirstChildOfClass("Terrain")
  if not root or not terrain then return end
  local streak = table.remove(streakFree)
  if not streak then
    local proto = template("SWindTrail")
    proto = proto and proto:FindFirstChildWhichIsA("Trail")
    if not proto or #streaks >= 140 then return end
    local a, b = Instance.new("Attachment"), Instance.new("Attachment")
    local trail = proto:Clone()
    trail.Attachment0, trail.Attachment1 = a, b
    trail.Color = ColorSequence.new(Color3.new(1, 1, 1))
    trail.Parent = a
    streak = { a = a, b = b, trail = trail }
    streaks[#streaks + 1] = streak
  end
  local a, b, trail = streak.a, streak.b, streak.trail
  local over = math.clamp(Fx.dress - 1, 0, 4)
  local reach = 10 + 3 * over
  local offset = Vector3.new(math.random(-100, 100), math.random(-100, 100), math.random(-100, 100)) / 100 * reach
  trail.Enabled = false
  a.Parent, b.Parent = root, root
  a.Position, b.Position = offset, offset + Vector3.new(0.06 + 0.03 * over, 0, 0)
  trail.Lifetime = 0.13 * (1 + 0.5 * over)
  trail:Clear()
  trail.Enabled = true
  -- let go of it after a moment, so the streak stretches out behind us
  task.delay(0.1, function()
    if not a.Parent or not b.Parent then return end
    local at, bt = a.WorldPosition, b.WorldPosition
    a.Parent, b.Parent = terrain, terrain
    a.WorldPosition, b.WorldPosition = at, bt
  end)
  task.delay(0.25 + trail.Lifetime, function()
    if a.Parent and b.Parent then
      streakFree[#streakFree + 1] = streak
    else
      -- its points went with a body that was replaced: forget it
      local at = table.find(streaks, streak)
      if at then table.remove(streaks, at) end
    end
  end)
end
-- What follows the body while it stays fast, from Mach 2 up: a vapour cone at the nose sized to
-- the tier, a shock ring thrown off it at intervals from Mach 4, and a glow there from Mach 8.
-- All of it rides with the body, for the reason given at the boom.
local function dressTo(tier)
  if tier == Fx.dress then return end
  Fx.dress = tier
  if Fx.dressAtt then
    retire(Fx.dressAtt, 0.6)
    Fx.dressAtt, Fx.pulse, Fx.pulseTwins = nil, nil, nil
  end
  if tier >= 2 and O.fxSonic and root and root.Parent then
    local over = math.min(tier - 1, 6)
    -- Ahead of the body, and further ahead the bigger it is. Seen on screen at Mach 32 with the
    -- cone a stud and a half off the chest: its vapour drifts back, and from the chase camera
    -- there was a white cloud where the body should be. Out in front, the body is drawn over it.
    local att = ride(4 + 0.6 * over)
    local vapor = piece("SBoost", "Attachment", "VaporCone")
    if vapor then
      local cone = variant("cone:" .. over, vapor, 1 + 0.2 * over, 1)
      cone.Name = "MachCone"
      cone.Enabled = true
      cone.Parent = att
    end
    local shock = tier >= 3 and piece("KBoost", "Boost3", "Attachment", "Shockwave2")
    if shock then
      Fx.pulse = variant("pulse:" .. over, shock, 0.9 + 0.35 * over, 0.85)
      Fx.pulse.Name = "MachPulse"
      Fx.pulse.Parent = att
      Fx.pulseTwins = {}
      for _, dark in ipairs({ true, false }) do
        local ring = twin("pulse:" .. over, shock, (0.9 + 0.35 * over) * (dark and 1.04 or 0.93), dark)
        if ring then
          ring.Name = dark and "MachPulseShade" or "MachPulseMist"
          ring.Parent = att
          Fx.pulseTwins[#Fx.pulseTwins + 1] = ring
        end
      end
    end
    local glowId = tier >= 4 and Assets.image("glow")
    if glowId then
      -- Air piled up white-hot ahead of the body: a rim of light round the head and shoulders
      -- as seen from behind. Small and faint on purpose. The first version (eleven studs wide,
      -- four deep) was measured on screen as a fog that left only a silhouette.
      local glow = Instance.new("ParticleEmitter")
      glow.Name = "BowGlow"
      glow.Texture = glowId
      glow.Rate, glow.Lifetime, glow.Speed = 16, NumberRange.new(0.1, 0.14), NumberRange.new(0, 0)
      glow.Size = NumberSequence.new(2.6 + 0.35 * over)
      glow.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.3, 0.9), NumberSequenceKeypoint.new(1, 1) })
      glow.Color = ColorSequence.new(Color3.fromRGB(214, 230, 255))
      glow.LightEmission, glow.LightInfluence, glow.LockedToPart, glow.ZOffset = 1, 0, true, 1
      glow.Parent = att
    end
    Fx.dressAtt = att
  end
  if char then
    for _, name in ipairs(LIMBS) do
      local limb = char:FindFirstChild(name)
      local a = limb and limb:FindFirstChild("BasedTrailA")
      local trail = a and a:FindFirstChildWhichIsA("Trail")
      if trail then styleTrail(trail) end
    end
  end
end
-- What is drawn over the game past Mach 2. All of it is images, so it costs nothing in the world:
--   speed lines   streaks at the edge of the screen that point at its centre, redrawn at a new
--                 angle some twenty times a second, with a second set between them from Mach 8
--   the tunnel    the edges of the screen darken, deeper with every doubling
--   the ripple    at each boom, a shock ring opens across the screen from the body
-- Measured on a pale sky, white alone could hardly be seen. So everything pale has the same
-- image in dark blue under it, a hair larger or turned a fraction: one of the two always shows.
local overlays, lines, lineShade, lines2, tunnel
local function overlay(name, image, z, tint)
  if not overlays or not overlays.Parent then overlays = B.screen(7900) end
  local label = Instance.new("ImageLabel")
  label.Name = name
  label.BackgroundTransparency = 1
  label.Image = image
  label.ImageColor3 = tint or Color3.new(1, 1, 1)
  label.AnchorPoint, label.Position = Vector2.new(0.5, 0.5), UDim2.fromScale(0.5, 0.5)
  label.ImageTransparency = 1
  label.Visible = false
  label.ZIndex = z
  label.Parent = overlays
  return label
end
function Fx.ripple(tier)
  local id = O.fxLines and Assets.image("shock")
  local camera = workspace.CurrentCamera
  if not id or not camera or not root then return end
  Fx.ripples += 1
  local over = math.clamp(tier - 1, 1, 6)
  local at, seen = camera:WorldToViewportPoint(root.Position)
  local centre = seen and UDim2.fromOffset(at.X, at.Y) or UDim2.fromScale(0.5, 0.5)
  local reach = camera.ViewportSize.Magnitude * (1.5 + 0.12 * over)       -- how wide it ends, in pixels
  local strength = math.min(0.55 + 0.08 * over, 0.9)
  -- one ring at Mach 2, two from Mach 4, three from Mach 16
  for index = 1, over >= 4 and 3 or (over >= 2 and 2 or 1) do
    task.delay((index - 1) * 0.09, function()
      local dark, light = overlay("ScreenShockShade", id, 5, SHADE), overlay("ScreenShock", id, 6)
      dark.Position, light.Position = centre, centre
      dark.Visible, light.Visible = true, true
      animate(0.36 + 0.05 * over, ease.outCubic, function(p)
        local side = (0.05 + 0.95 * p) * reach
        light.Size = UDim2.fromOffset(side, side)
        dark.Size = UDim2.fromOffset(side * 1.03, side * 1.03)
        local left = (1 - p) ^ 1.4 * strength
        light.ImageTransparency = 1 - left
        dark.ImageTransparency = 1 - left * 0.85
      end)
      later(1.5, dark)
      later(1.5, light)
    end)
  end
end
local function speedLines(dt, mach, active)
  local want, dark = 0, 0
  if O.fxLines then
    if active then want = math.clamp((mach - 1.6) / 5, 0, 1) * 0.5 end
    if active then dark = math.clamp(math.log(math.max(mach, 1), 2) - 1, 0, 3) / 3 * 0.42 end
    Fx.punch = math.max(0, Fx.punch - dt * 2.5)
    want = math.min(want + Fx.punch * 0.35, 0.8)
    dark = math.min(dark + Fx.punch * 0.2, 0.6)
  else
    Fx.punch = 0
  end
  Fx.lineAlpha += (want - Fx.lineAlpha) * alpha(7, dt)
  Fx.tunnelAlpha += (dark - Fx.tunnelAlpha) * alpha(5, dt)
  if Fx.tunnelAlpha < 0.004 then
    if tunnel and tunnel.Visible then tunnel.Visible = false end
  else
    local id = not tunnel and Assets.image("vignette")
    if id then
      tunnel = overlay("MachTunnel", id, 1)
      tunnel.Size = UDim2.fromScale(1, 1)
    end
    if tunnel then
      tunnel.Visible = true
      tunnel.ImageTransparency = 1 - Fx.tunnelAlpha
    end
  end
  if Fx.lineAlpha < 0.004 then
    if lines and lines.Visible then lines.Visible, lineShade.Visible, lines2.Visible = false, false, false end
    return
  end
  if not lines then
    local id = Assets.image("speedlines")
    if not id then return end
    lineShade, lines2, lines = overlay("SpeedShade", id, 2, SHADE), overlay("SpeedLines2", id, 3), overlay("SpeedLines", id, 4)
    Fx.lines = lines
  end
  if not lines.Visible then
    -- a square that still covers the screen whichever way it is turned
    local side = math.ceil(workspace.CurrentCamera.ViewportSize.Magnitude * 1.08)
    lines.Size = UDim2.fromOffset(side, side)
    lineShade.Size, lines2.Size = lines.Size, lines.Size
    lines.Visible, lineShade.Visible, lines2.Visible = true, true, true
  end
  lines.ImageTransparency = 1 - Fx.lineAlpha
  lineShade.ImageTransparency = 1 - Fx.lineAlpha * 0.9
  lines2.ImageTransparency = 1 - Fx.lineAlpha * math.clamp((mach - 8) / 24, 0, 1) * 0.9
  Fx.lineClock += dt
  if Fx.lineClock >= 0.045 then
    Fx.lineClock = 0
    lines.Rotation = math.random(0, 359)
    lineShade.Rotation = lines.Rotation + 0.35      -- beside each line, not under it
    lines2.Rotation = math.random(0, 359)
  end
end
-- every frame: the dressing, trails, streaks and the wind loop all follow real speed
function Fx.update(dt, speed, flying, boosting)
  Fx.speed, Fx.flying, Fx.boosting = speed, flying, boosting
  local previewing = Fx.previewUntil > os.clock()
  local tier, mach = 0, 0
  if previewing then
    tier, mach = Fx.previewTier, 2 ^ (Fx.previewTier - 1) * 1.2
  elseif flying then
    tier, mach = tierOf(speed)
  end
  Fx.mach = mach
  -- up a tier the moment it is reached, down only once the speed is well under it
  if tier > Fx.dress then
    dressTo(tier)
  elseif Fx.dress > 0 and (previewing or not flying or speed < O.sonic * 2 ^ (Fx.dress - 1) * 0.85) then
    dressTo(tier)
  end
  if Fx.pulse and Fx.pulse.Parent then
    Fx.pulseAcc += dt
    if Fx.pulseAcc >= math.clamp(0.95 - 0.12 * Fx.dress, 0.3, 0.7) then
      Fx.pulseAcc = 0
      Fx.pulse:Emit(1)
      for _, ring in ipairs(Fx.pulseTwins or {}) do ring:Emit(1) end
    end
  end
  speedLines(dt, mach, flying or previewing)
  if not flying and not Fx.trails and not Fx.wind then return end
  local cruise = O.speed
  Fx.setTrails(flying and O.fxTrails and speed > math.max(60, cruise * 0.45))
  if flying and O.fxStreaks and speed > math.max(cruise * 1.1, 100) then
    Fx.windAcc += dt
    local every = math.clamp(0.05 - (speed - cruise) / 20000, Fx.dress >= 3 and 0.011 or 0.02, 0.05)
    while Fx.windAcc >= every do
      Fx.windAcc -= every
      windStreak()
    end
  else
    Fx.windAcc = 0
  end
  local wind = Fx.wind
  if wind and wind.Parent then
    local charging = Flight.state == "charging"
    local target = (flying and math.clamp(speed / 300, 0, 3) * 0.5 or (charging and 0.25 + 0.3 * Flight.charge or 0)) * volume()
    wind.Volume += (target - wind.Volume) * alpha(8, dt)
    local pitch = charging and (0.6 + 0.9 * Flight.charge) or math.clamp(speed / 165, 0.75, 2)
    wind.PlaybackSpeed += (pitch - wind.PlaybackSpeed) * alpha(8, dt)
    if target > 0.01 and not wind.IsPlaying then wind:Play()
    elseif target <= 0.01 and wind.Volume < 0.01 and wind.IsPlaying then wind:Stop() end
  end
end
local function cameraUndo()
  local camera = workspace.CurrentCamera
  if camera and Fx.offset ~= CFrame.identity then camera.CFrame = camera.CFrame * Fx.offset:Inverse() end
  Fx.offset = CFrame.identity
end
local function cameraApply(dt)
  local camera = workspace.CurrentCamera
  if not camera or not O then return end
  dt = math.min(dt, 0.1)
  Fx.shakeTime += dt
  Fx.shake = math.max(0, Fx.shake - dt * 1.6)
  Fx.fovKick = math.max(0, Fx.fovKick - dt * 22)
  -- the camera rolls a few degrees the way the body banks
  Fx.roll += ((Fx.flying and O.fxShake and math.clamp(lean * 0.12, -8, 8) or 0) - Fx.roll) * alpha(4, dt)
  local amp = 0
  if Fx.flying and O.fxShake and Fx.speed > 5 then
    amp = math.clamp(Fx.speed / 900, 0, 0.55) * (Fx.boosting and 1.2 or 1) + 0.07 * math.clamp(Fx.dress - 1, 0, 5)
  end
  amp += Fx.shake * 2
  if amp > 1e-4 or math.abs(Fx.roll) > 0.01 then
    local t = Fx.shakeTime * 4.4 * math.pi
    local offset = CFrame.Angles(math.sin(t) * amp * 0.004 + math.sin(t * 3.1) * Fx.shake * 0.01,
      math.sin(t * 0.7 + 1.3) * amp * 0.003 + math.cos(t * 2.7) * Fx.shake * 0.01, math.sin(t * 0.5 + 2.7) * amp * 0.002 + math.rad(Fx.roll))
    camera.CFrame = camera.CFrame * offset
    Fx.offset = offset
  end
  -- the field of view widens with speed, unless the player has locked it in Visuals
  if O.fxFov and not Config.get("world.fov") and (Fx.flying or Fx.fovKick > 0 or Fx.baseFov) then
    Fx.baseFov = Fx.baseFov or camera.FieldOfView
    local want = Fx.baseFov + (Fx.flying and math.clamp(Fx.speed * 15 / 450, 0, 32) or 0)
    want = math.min(want + Fx.fovKick, 115)
    camera.FieldOfView += (want - camera.FieldOfView) * alpha(4, dt)
    if not Fx.flying and Fx.fovKick <= 0 and math.abs(camera.FieldOfView - Fx.baseFov) < 0.05 then
      camera.FieldOfView = Fx.baseFov
      Fx.baseFov = nil
    end
  elseif Fx.baseFov then
    camera.FieldOfView = Fx.baseFov
    Fx.baseFov = nil
  end
end
-- build the templates a frame apart and fetch their textures and the sounds, so the first
-- boom is not a silent, untextured one
local function warm()
  if warmed then return end
  warmed = true
  task.spawn(function()
    local list = {}
    for _, name in ipairs(PACK) do
      local made = template(name)
      if made then list[#list + 1] = made end
      task.wait()
    end
    local wind = Instance.new("Sound")
    wind.SoundId = soundId("wind")
    wind.Looped = true
    wind.Volume = 0
    wind.Parent = sounds()
    Fx.wind = wind
    for name in pairs(SOUNDS) do
      if name ~= "wind" then
        local sound = Instance.new("Sound")
        sound.SoundId = soundId(name)
        sound.Parent = sounds()
        list[#list + 1] = sound
        later(20, sound)
      end
    end
    pcall(function() S.ContentProvider:PreloadAsync(list) end)
  end)
end
-- Fire the boom of a tier where the body stands, and wear that tier for a moment: what a setting
-- looks like, without having to fly it. The rings open along the way the body faces.
function Fx.preview(tier)
  if not root or not root.Parent then return false end
  warm()
  local look = root.CFrame.LookVector
  Fx.previewTier, Fx.previewUntil, Fx.previewDir = tier, os.clock() + 2.6, look
  Fx.sonicBoom(look * O.sonic * 2 ^ (tier - 1), tier)
  return true
end

-- ---------------------------------------------------------------- animation layer
local function loadTracks()
  table.clear(tracks)
  current, Flight.clip = nil, nil
  Flight.animated = false
  if not animator or not O.animations or hum.RigType ~= Enum.HumanoidRigType.R15 then return end
  local preload = {}
  for name, id in pairs(ANIMS) do
    local animation = Instance.new("Animation")
    animation.AnimationId = "rbxassetid://" .. id
    local ok, track = pcall(function() return animator:LoadAnimation(animation) end)
    if ok and track then
      -- three of the clips are published at Core priority and would lose to the game's own idle
      track.Priority = Enum.AnimationPriority.Action4
      tracks[name] = track
      preload[#preload + 1] = animation
      Flight.animated = true
    end
  end
  -- fetched before first use: a track played before its data arrives shows nothing to anyone
  task.spawn(function() pcall(function() S.ContentProvider:PreloadAsync(preload) end) end)
end
local function setAnim(name, fade, rate)
  Flight.clip = name
  local track = tracks[name]
  if not track then
    -- no clip for this (R6, or animations off): make sure nothing stale keeps playing
    if current and tracks[current] then tracks[current]:Stop(fade or 0.25) end
    current = nil
    return
  end
  if current == name then
    if rate and math.abs(track.Speed - rate) > 0.04 then track:AdjustSpeed(rate) end
    return
  end
  local previous = current and tracks[current]
  track:Play(fade or 0.3, 1, rate or 1)
  if previous then previous:Stop(fade or 0.3) end
  current, currentSince = name, os.clock()
end
local function stopAnims(fade)
  for _, track in pairs(tracks) do
    if track.IsPlaying then track:Stop(fade or 0.25) end
  end
  current, Flight.clip = nil, nil
end
-- the hover poses the player picked, in a fixed order, and the one whose turn it is
local function chooseIdles(list)
  table.clear(idleChoice)
  for _, key in ipairs(IDLE_ORDER) do
    if table.find(list, key) then idleChoice[#idleChoice + 1] = IDLES[key] end
  end
  if #idleChoice == 0 then idleChoice[1] = "idle" end
end
local function idleName() return idleChoice[(idleIndex - 1) % #idleChoice + 1] end
local function isIdle(name) return name == "idle" or name == "idle2" or name == "idle3" or name == "idle4" end
-- playback speed follows airspeed; stepped, because every change is sent to the other clients
local function paced(base, gain, fraction, low, high)
  return math.floor(math.clamp(base + gain * fraction, low, high) * 20 + 0.5) / 20
end

-- ---------------------------------------------------------------- physics
local function buildPhysics()
  if byFrame() then
    -- (stand-ins with the same fields: the flight below sets them, and the frame step carries them out)
    if not (faked and lv) then
      lv = { fake = true, Parent = true, VectorVelocity = vel }
      ao = { fake = true, Parent = true, CFrame = root.CFrame.Rotation, Responsiveness = 14 }
      attachment = nil
      faked = true
    end
    return
  end
  faked = false
  if lv and lv.Parent and ao and ao.Parent then return end
  for _, item in ipairs({ lv, ao, attachment }) do
    if item then pcall(function() item:Destroy() end) end
  end
  attachment = Instance.new("Attachment")
  attachment.Name = util.randomName()
  attachment.Parent = root
  lv = Instance.new("LinearVelocity")
  lv.Attachment0 = attachment
  lv.MaxForce = math.huge
  lv.RelativeTo = Enum.ActuatorRelativeTo.World
  lv.VelocityConstraintMode = Enum.VelocityConstraintMode.Vector
  lv.VectorVelocity = vel
  lv.Parent = root
  ao = Instance.new("AlignOrientation")
  ao.Mode = Enum.OrientationAlignmentMode.OneAttachment
  ao.Attachment0 = attachment
  ao.MaxTorque = math.huge
  ao.MaxAngularVelocity = math.huge
  ao.Responsiveness = 14
  ao.CFrame = root.CFrame.Rotation
  ao.Parent = root
end
local function teardownPhysics()
  for _, item in ipairs({ lv, ao, attachment }) do
    if item and typeof(item) == "Instance" then pcall(function() item:Destroy() end) end
  end
  lv, ao, attachment = nil, nil, nil
  faked = false
end
-- the speed the body really has: in frame mode its velocity is held at zero, so it is the flight's own
local function bodySpeed()
  if faked and lv then return lv.VectorVelocity.Magnitude end
  return root and root.Parent and root.AssemblyLinearVelocity.Magnitude or 0
end
-- Space charges a launch while flight is armed, so it must not also jump
local function blockJump(block)
  if not hum then return end
  if block then
    if jumpWasEnabled == nil then
      jumpWasEnabled = hum:GetStateEnabled(STATE.Jumping)
      hum:SetStateEnabled(STATE.Jumping, false)
    end
  elseif jumpWasEnabled ~= nil then
    pcall(function() hum:SetStateEnabled(STATE.Jumping, jumpWasEnabled) end)
    jumpWasEnabled = nil
  end
end
-- Physics: the humanoid applies no forces of its own. Freefall: Roblox's own character sounds,
-- which run on every client for every character, play a rushing-wind loop from the replicated
-- state, which makes the wind the one sound other players hear.
local function flightState() return O.windForOthers and STATE.Freefall or STATE.Physics end
local function setState(state)
  if byFrame() or not hum then return end
  if hum:GetState() ~= state then hum:ChangeState(state) end
end

local function startFlying(initial)
  if not alive() or Flight.state == "flying" then return end
  Flight.state = "flying"
  vel = initial or (byFrame() and Vector3.zero or root.AssemblyLinearVelocity)
  Flight.ramp, stage, lean, spaceSince, boomed, impact, floor = 0, 0, 0, nil, 0, 0, nil
  facing = flat(root.CFrame.LookVector) or facing
  buildPhysics()
  if savedAutoRotate == nil then savedAutoRotate = hum.AutoRotate end
  hum.AutoRotate = false
  setState(flightState())
  blockJump(true)
end
-- Where the body last stood on something, and a safe way down when the flight lets go of it in
-- the air (frame mode only: there the body has no momentum to carry it anywhere). Measured live
-- in Da Hood: let go at rest over the edge of the world, it fell past the height where the game
-- takes a body out and the player died. So: a short drop is fallen; a long one is put straight
-- onto the ground under it; with no ground under it at all, back where it last stood.
local stood                  -- CFrame where the body last had a floor under its feet
local LET_FALL = 60          -- studs of drop that are simply fallen
local function putDown()
  if not alive() then return end
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.FilterDescendantsInstances = { char }
  params.IgnoreWater = false
  params.RespectCanCollide = true
  local from = root.Position
  local hit = util.ray(from, from - UP * 20000, params, 3)
  local feet = feetBelowRoot()
  root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
  if hit and hit.Normal.Y > 0.3 then
    if from.Y - hit.Position.Y - feet > LET_FALL then
      root.CFrame = root.CFrame.Rotation + (hit.Position + UP * (feet + 0.2))
    end
  elseif stood then
    root.CFrame = stood + UP * 0.5
    if B.Window and B.Window.toast then
      B.Window.toast({ title = "No ground under you", text = "Put back where you last stood.", icon = "shield-check", time = 3 })
    end
  end
end
Flight.putDown = putDown
-- hand the body back to the humanoid; `toGround` when we are standing on something
local function leaveFlight(toGround)
  Fx.stopCharge()
  Fx.boostRing(false)
  Fx.setTrails(false)
  stage, Flight.ramp = 0, 0
  -- (carried by frames, the body is let go at rest: a body thrown at flight speed lands at it)
  local momentum = (not byFrame() and root and root.Parent) and root.AssemblyLinearVelocity or Vector3.zero
  teardownPhysics()
  if hum and savedAutoRotate ~= nil then
    pcall(function() hum.AutoRotate = savedAutoRotate end)
    savedAutoRotate = nil
  end
  if alive() then
    if toGround then
      setState(STATE.GettingUp)
    else
      -- keep the momentum and let the humanoid fall normally
      setState(STATE.Freefall)
      root.AssemblyLinearVelocity = momentum
      if byFrame() and not (Flight.blocked and Flight.blocked()) then putDown() end
    end
  end
end
local function stopEverything()
  local state = Flight.state
  if state == "flying" or (state == "landing" and lv ~= nil) then leaveFlight(false) end
  Fx.stopCharge()
  if chargeHold then
    pcall(function() chargeHold.plane:Destroy() end)
    pcall(function() chargeHold.att:Destroy() end)
    chargeHold = nil
  end
  stopAnims(0.25)
  blockJump(false)
  landing, airborneSince = nil, nil
  Flight.state, Flight.speed, Flight.ramp, Flight.charge = "off", 0, 0, 0
end

-- ---------------------------------------------------------------- the ground
local function exclusions()
  local now = os.clock()
  if now - ignoreAt > 0.5 then
    ignoreAt = now
    table.clear(ignore)
    if folder then ignore[#ignore + 1] = folder end
    -- never land on, or crash into, another player
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player.Character then ignore[#ignore + 1] = player.Character end
    end
    rayParams.FilterDescendantsInstances = ignore
  end
  return rayParams
end
local function groundBelow(from, reach)
  local hit = workspace:Raycast(from, Vector3.new(0, -reach, 0), exclusions())
  if hit and hit.Normal.Y > 0.55 then return hit end
  return nil
end

-- ---------------------------------------------------------------- charge and launch
-- While charging the body is held where it stands: the crouch has a hand on the ground, and
-- walking slides it along (in the first minutes of real use the player held W through four
-- charges out of five). Sideways only; up and down are left to the ground.
local function holdStill(on)
  if chargeHold then
    pcall(function() chargeHold.plane:Destroy() end)
    pcall(function() chargeHold.att:Destroy() end)
    chargeHold = nil
  end
  if not on or not root or not root.Parent then return end
  if byFrame() then
    chargeHold = { fake = true, at = root.Position }
    return
  end
  local att = Instance.new("Attachment")
  att.Name = util.randomName()
  att.Parent = root
  local plane = Instance.new("LinearVelocity")
  plane.Attachment0 = att
  plane.MaxForce = math.huge
  plane.RelativeTo = Enum.ActuatorRelativeTo.World
  plane.VelocityConstraintMode = Enum.VelocityConstraintMode.Plane
  plane.PrimaryTangentAxis, plane.SecondaryTangentAxis = Vector3.xAxis, Vector3.zAxis
  plane.PlaneVelocity = Vector2.zero
  plane.Parent = root
  chargeHold = { att = att, plane = plane }
end
local function beginCharge()
  Flight.state, Flight.charge = "charging", 0
  chargeStart, chargeFx = os.clock(), false
  holdStill(true)
  setAnim("charge", 0.15, 1)
end
local function release()
  local held = os.clock() - chargeStart
  Fx.stopCharge()
  holdStill(false)
  local charge = math.clamp((held - 0.2) / math.max(O.chargeTime, 0.1), 0, 1)
  local quick = held < 0.2
  local strength = quick and 0.4 or (0.6 + charge)
  local up = quick and 46 or O.launch * (0.5 + 0.9 * charge)
  local forward = (flat(workspace.CurrentCamera.CFrame.LookVector) or Vector3.zero) * up * 0.12
  local hit = groundBelow(root.Position, 12)
  Fx.takeoff(hit and hit.Position + Vector3.new(0, 0.1, 0) or root.Position - Vector3.new(0, feetBelowRoot(), 0), strength)
  Flight.state, Flight.charge = "ground", 0
  Flight.launches += 1
  launchVel = UP * up + forward
  -- the launch carries for a moment whatever the keys say: it boosts up to the sky
  launchUntil = os.clock() + (quick and 0.25 or 0.45 + 0.75 * charge)
  startFlying(launchVel)
  setAnim(quick and "up" or "upFast", 0.12, 1)
end
local function stepCharge()
  local held = os.clock() - chargeStart
  if chargeHold and chargeHold.fake and root and root.Parent then
    -- sideways only, as the plane constraint does: up and down are the ground's
    local at, here = chargeHold.at, root.Position
    root.CFrame = root.CFrame.Rotation + Vector3.new(at.X, here.Y, at.Z)
    local v = root.AssemblyLinearVelocity
    root.AssemblyLinearVelocity = Vector3.new(0, math.min(v.Y, 0), 0)
  end
  Flight.charge = math.clamp((held - 0.2) / math.max(O.chargeTime, 0.1), 0, 1)
  if held > 0.2 then
    if not chargeFx then
      chargeFx = true
      Fx.startCharge()
    end
    Fx.kick(0.05 + 0.1 * Flight.charge, 0)
  end
  local track = tracks.charge
  if track and track.IsPlaying then
    local at = track.TimePosition
    if at >= CHARGE.high and track.Speed > 0 then track:AdjustSpeed(-1)
    elseif at <= CHARGE.low and track.Speed < 0 then track:AdjustSpeed(1) end
  end
  if not down("Space") then
    release()
  elseif not onGround() then
    -- knocked off the ground while charging: let go of the crouch, the armed state catches the fall
    Fx.stopCharge()
    holdStill(false)
    stopAnims(0.15)
    Flight.state, Flight.charge = "ground", 0
  end
end

-- ---------------------------------------------------------------- landing
local function beginLanding(hit, approach)
  local feet = feetBelowRoot()
  landing = { started = os.clock(), from = root.Position, to = hit.Position + UP * feet, ground = hit.Position, normal = hit.Normal,
    power = math.clamp(approach / 320, 0.25, 1.8), approach = approach, touched = false, released = false,
    look = flat(vel) or flat(root.CFrame.LookVector) or facing }
  Flight.state = "landing"
  Fx.boostRing(false)
  Fx.setTrails(false)
  stage, Flight.ramp, spaceSince = 0, 0, nil
  -- measured live: in Freefall the humanoid flickers into Landed over the last studs, at full
  -- descent speed, which is exactly what a game's fall damage listens for. Physics has no Landed.
  setState(STATE.Physics)
  -- slowed so that the clip's feet reach the ground on the frame the body does
  setAnim("land", 0.18, LAND.contact / LAND.lead)
end
-- The way down: sideways motion is shed along the way, the drop itself is not eased (the crouch
-- is what absorbs it). Returns where the root should be at `t` and how fast it is moving there.
local function landingPath(L, t)
  local p = math.clamp(t / LAND.lead, 0, 1)
  local span = L.to - L.from
  local across, rate = 1 - (1 - p) ^ 2, 2 * (1 - p) / LAND.lead
  return Vector3.new(L.from.X + span.X * across, L.from.Y + span.Y * p, L.from.Z + span.Z * across),
    Vector3.new(span.X * rate, span.Y / LAND.lead, span.Z * rate)
end
local function finishLanding(fade)
  local track = tracks.land
  if track and track.IsPlaying then track:Stop(fade) end
  if lv then leaveFlight(true) end
  current, Flight.clip = nil, nil
  landing = nil
  Flight.state = "ground"
end
local function touchDown(L)
  L.touched, L.touchedAt = true, os.clock()
  local feet = feetBelowRoot()
  -- Measured live: a landing from 5,665 st/s was abandoned because the body was more than six
  -- studs from its mark, which at that speed is a quarter of one frame. Only a body that stopped
  -- SHORT of the mark, by more than a tenth of a second of travel, met something on the way; one
  -- that is level with it or past it (a slow frame carries it on) simply belongs on the mark.
  local span = L.to - L.from
  local past = span.Magnitude > 1e-3 and (root.Position - L.to):Dot(span.Unit) or 0
  if past < 0 and (root.Position - L.to).Magnitude > math.max(6, L.approach * 0.12) then
    -- something stood in the way: put down here if there is ground here, otherwise carry on flying
    local below = groundBelow(root.Position, feet + 4)
    if not below then
      landing = nil
      Flight.state = "flying"
      vel = Vector3.zero
      return
    end
    L.to, L.ground, L.normal = below.Position + UP * feet, below.Position, below.Normal
  end
  vel = Vector3.zero
  if lv then lv.VectorVelocity = vel end
  root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = vel, vel
  root.CFrame = CFrame.lookAt(L.to, L.to + L.look)
  if ao then
    ao.CFrame = CFrame.lookAt(Vector3.zero, L.look)
    ao.Responsiveness = 60
  end
  local track = tracks.land
  if track then track:AdjustSpeed(1) end
  Flight.landings += 1
  Fx.crater(L.ground, L.normal, L.power)
end
local function stepLanding(dt)
  local L = landing
  local now = os.clock()
  if not L.touched then
    local t = now - L.started
    -- the last frame of travel is taken by the touchdown itself: one more frame at this
    -- velocity would carry the body past the ground before anything could stop it
    if t + dt < LAND.lead and lv and lv.Parent then
      setState(STATE.Physics)
      -- The path's own velocity with a gentle pull back onto it. Chasing the position frame by
      -- frame was measured live to swing between 4 and 250 st/s on a 120 st/s descent (frames
      -- and physics steps do not line up); this is the same path, flown smoothly.
      local point, speed = landingPath(L, t)
      local off = point - root.Position
      if L.approach > PIN_SPEED and off.Magnitude > 1 then
        -- at thousands of studs a second that same mismatch is tens of studs: put the body on
        -- the path. A correction of less than one frame's travel cannot be told from the travel.
        root.CFrame = root.CFrame.Rotation + point
        off = Vector3.zero
      end
      vel = speed + off * 6
      lv.VectorVelocity = vel
      ao.CFrame = CFrame.lookAt(Vector3.zero, L.look)
      ao.Responsiveness = 30
      return
    end
    touchDown(L)
    if landing ~= L then return end
  end
  local clipTime = LAND.contact + (now - L.touchedAt)
  if not tracks.land then
    if now - L.touchedAt > 0.25 then finishLanding(0) end
    return
  end
  if not L.released and clipTime >= LAND.hold then
    -- the body was held still through the impact; from here the humanoid has it again
    L.released = true
    leaveFlight(true)
  end
  if clipTime >= LAND.out then
    finishLanding(LAND.fade)
  elseif L.released and (hum.MoveDirection.Magnitude > 0.1 or down("Space")) then
    finishLanding(0.3)
  end
end

-- ---------------------------------------------------------------- flying
local function direction(camera)
  local move = UIS:GetFocusedTextBox() and Vector3.zero or hum.MoveDirection
  local dir = Vector3.zero
  if move.Magnitude > 0.01 then
    -- the flat move direction becomes camera-relative in 3D: look up while pressing forward, fly up
    local basis = CFrame.lookAt(Vector3.zero, flat(camera.CFrame.LookVector) or Vector3.new(0, 0, -1))
    dir = camera.CFrame:VectorToWorldSpace(basis:VectorToObjectSpace(move))
  end
  local vertical = (down("Space") and 1 or 0) - (down(O.keyDown) and 1 or 0)
  local horizontal = dir.Magnitude > 0.01
  if vertical ~= 0 then dir += UP * vertical * (horizontal and 0.7 or 1) end
  return dir.Magnitude > 0.01 and dir.Unit or Vector3.zero, vertical, horizontal
end
-- which clip, and how fast it plays. Every threshold is wider on the way out than on the way
-- in, so a speed sitting on one does not flicker between two poses.
local function pickClip(speed, elevation, moving, vertical, horizontal, heldUp, launching)
  local cruise, was = O.speed, current
  if launching then return "upFast", 1 end
  if not moving then
    -- a long hover moves on to the next of the chosen poses
    if O.idleEvery > 0 and #idleChoice > 1 and isIdle(was) and os.clock() - currentSince > O.idleEvery then idleIndex += 1 end
    return idleName(), 1
  end
  local fraction = speed / math.max(cruise, 1)
  local climbing = was == "up" or was == "upFast"
  if (vertical > 0 and not horizontal) or elevation > (climbing and 0.8 or 0.95) then
    if heldUp > CLIMB_BOOST + 0.1 or speed > cruise * (was == "upFast" and 1.4 or 1.7) then return "upFast", 1 end
    return "up", paced(0.8, 0.5, fraction, 0.8, 1.5)
  end
  if (vertical < 0 and not horizontal) or elevation < ((was == "down" or was == "hoverDown") and -0.75 or -0.9) then
    -- hovering down is the descend key on its own at an easy pace; boosted, steered into or simply fast, it is the dive
    local easy = math.min(math.max(cruise * 1.35, 60), HOVER_DOWN_MAX) * (was == "hoverDown" and 1.2 or 1)
    if vertical < 0 and not horizontal and Flight.ramp < 0.05 and speed <= easy then return "hoverDown", 1 end
    return "down", 1
  end
  if speed >= O.sonic * (was == "sonic" and 0.6 or 0.72) then return "sonic", 1 end
  if Flight.ramp > 0.1 or speed > cruise * (was == "aggressive" and 1.25 or 1.5) then
    return "aggressive", paced(0.9, 0.5, speed / math.max(O.top, 1), 0.9, 1.5)
  end
  if elevation < (was == "aimDown" and -0.28 or -0.38) then return "aimDown", 1 end
  return "slow", paced(0.7, 0.6, fraction, 0.7, 1.4)
end
local function stepFly(dt)
  local camera = workspace.CurrentCamera
  setState(flightState())
  buildPhysics()
  local now = os.clock()
  local dir, vertical, horizontal = direction(camera)
  local moving = dir.Magnitude > 0
  local launching = launchUntil > now
  -- how long Space has been held: a long hold on a straight climb becomes the run at the boom
  if vertical > 0 then spaceSince = spaceSince or now else spaceSince = nil end
  local heldUp = spaceSince and now - spaceSince or 0

  local boosting = moving and (down(O.keyBoost) or (vertical > 0 and not horizontal and heldUp > CLIMB_BOOST))
  local ramp = Flight.ramp
  if boosting then ramp = math.min(1, ramp + dt / math.max(O.rampTime, 0.3)) else ramp = math.max(0, ramp - dt / 0.8) end
  Flight.ramp = ramp
  local wantStage = ramp >= 0.999 and 3 or (ramp >= 0.6 and 2 or (ramp >= 0.2 and 1 or 0))
  if wantStage > stage then
    stage = wantStage
    Fx.boostStage(stage)
  elseif wantStage < stage then
    stage = wantStage
    if stage == 0 then Fx.boostRing(false) end
  end

  local cruise = O.speed
  local top = math.max(O.top, cruise)
  local target = launching and launchVel or (moving and dir * (cruise + (top - cruise) * ramp ^ 1.5) or Vector3.zero)
  vel = vel:Lerp(target, alpha(launching and 10 or (moving and 4 + 2 * ramp or 5), dt))
  lv.VectorVelocity = vel
  local speed = vel.Magnitude
  Flight.speed = speed

  -- The boom, on the speed the body really has. Each tier booms once on the way up and is armed
  -- again when the speed is back under 80% of where it starts. A hard acceleration that runs
  -- through several tiers inside BOOM_GAP booms once more, for the highest one it has reached.
  local real = bodySpeed()
  local tier = tierOf(real)
  if tier > boomed and now - lastSonic > (boomed == 0 and 1.35 or BOOM_GAP) then
    boomed, lastSonic = tier, now
    Flight.booms += 1
    Flight.boomLog[#Flight.boomLog + 1] = tier
    if #Flight.boomLog > 40 then table.remove(Flight.boomLog, 1) end
    Fx.sonicBoom(vel, tier)
  else
    while boomed > 0 and real < O.sonic * 2 ^ (boomed - 1) * 0.8 do boomed -= 1 end
  end

  local elevation = speed > 4 and math.asin(math.clamp(vel.Y / speed, -1, 1)) or 0
  local name, rate = pickClip(speed, elevation, moving, vertical, horizontal, heldUp, launching)
  if current and POSE[current] and name ~= current and now - currentSince < DWELL then name, rate = current, nil end
  if isIdle(current) and not isIdle(name) then idleIndex += 1 end
  setAnim(name, (name == "sonic" or name == "upFast") and 0.2 or (isIdle(name) and (isIdle(current) and 0.6 or 0.4) or 0.3), rate)

  -- orientation: face along the path, tilt by what the clip does not already supply, bank into turns
  local planar = Vector3.new(vel.X, 0, vel.Z)
  local planarSpeed = planar.Magnitude
  if (moving or launching) and planarSpeed > math.max(6, speed * 0.2) then facing = planar.Unit end
  local wantLean = 0
  local dirFlat = flat(dir)
  if moving and dirFlat and planarSpeed > 20 then wantLean = math.clamp(signedYaw(planar.Unit, dirFlat) * 1.3, -70, 70) end
  lean += (wantLean - lean) * alpha(5, dt)
  local base = CFrame.lookAt(Vector3.zero, facing)
  local pitch, roll
  if not moving and not launching then
    -- hovering or braking: upright, tipped a little the way it is still drifting
    local drift = base:VectorToObjectSpace(vel)
    pitch, roll = math.clamp(drift.Z / 200, -0.25, 0.25), math.clamp(-drift.X / 200, -0.25, 0.25)
    ao.Responsiveness = 18
  else
    local blend = math.clamp(speed / math.max(cruise * 0.7, 30), 0, 1)
    local pose = tracks[name] and POSE[name]
    if pose then
      pitch = elevation * pose.follow + pose.lean
      if pose.rocket then pitch += (math.max(elevation, 0.6) - math.pi / 2) * pose.rocket end
      if pose.dive and elevation < -0.56 then pitch += (elevation + 0.56) * pose.dive end
    else
      -- no clip to wear (R6, animations off, or it failed to load): the body itself leads, head first
      pitch = elevation - math.pi / 2
    end
    pitch *= blend
    roll = math.rad(lean) * (pose and pose.bank or 1) * blend
    ao.Responsiveness = 14
  end
  -- rolled about the direction of travel first, then pitched: a bank stays a bank at any pitch
  ao.CFrame = base * CFrame.Angles(0, 0, roll) * CFrame.Angles(pitch, 0, 0)

  -- the ground: a landing is timed from the moment the path is sure to meet it. Measured: a ray
  -- finds nothing further than 15,000 studs however long it is asked to be, so this look-ahead
  -- (0.6 s of descent) sees the whole approach up to about 25,000 st/s straight down. Faster
  -- than that the landing starts when the ground comes into view and takes its 0.6 s from there.
  if O.autoLand and not launching then
    local descent = math.max(-vel.Y, 0)
    local slope = speed > 1 and vel.Y / speed or 0
    if vertical < 0 or (descent > 4 and (slope < -0.5 or (speed >= 320 and slope < -0.2))) then
      local feet = feetBelowRoot()
      local hit = groundBelow(root.Position, feet + descent * LAND.lead + 6)
      local clearance = hit and root.Position.Y - hit.Position.Y - feet
      -- Coming down at the ground is only a landing while it is still being flown there, or when
      -- it is too late to stop. With the keys let go the body brakes inside descent / 5 studs, and
      -- letting go high above the ground used to be taken for a landing anyway.
      local meant = vertical < 0 or (moving and dir.Y < -0.2) or (hit ~= nil and descent / 5 > clearance)
      if hit and meant and clearance <= descent * LAND.lead + (vertical < 0 and 4.5 or 0.5) then
        -- where the path meets the ground, not the spot straight below
        local carry = planar * LAND.lead * 0.5
        local there = carry.Magnitude > 1 and groundBelow(root.Position + carry + UP * 2, clearance + feet + 16) or hit
        if there and carry.Magnitude > 1 then
          local blocked = workspace:Raycast(root.Position, there.Position + UP * feet - root.Position, exclusions())
          if blocked and (blocked.Position - there.Position).Magnitude > 1.5 then there = hit end
        end
        if there then
          beginLanding(there, speed)
          return
        end
      end
    end
  end
  -- Something solid in the next frame's path. A wall at speed cracks and throws us back. Ground
  -- we are not landing on lets the feet come down onto it and no further: at these speeds a body
  -- covers several studs between physics steps and would otherwise pass clean through a floor,
  -- and at any speed it would sink to its waist. So a low pass skims the ground on its feet.
  local solid = not Config.get("move.noclip")
  if speed > 20 and solid then
    local heading = vel.Unit
    local feet = feetBelowRoot()
    local travel = math.max(speed * dt * 1.6, 4)
    local hit = workspace:Raycast(root.Position, heading * (math.max(speed * HITCH, travel) + feet * math.max(-heading.Y, 0)), exclusions())
    if hit and hit.Normal.Y > 0.55 then
      -- the speed into the ground is held to what one slow frame could cover, so the body
      -- flares onto its feet instead of arriving in a single step that might go through
      local gap = math.max((root.Position - hit.Position):Dot(hit.Normal) - feet, 0)
      local into = -vel:Dot(hit.Normal)
      if into > gap / HITCH then
        impact = math.max(impact, into)
        vel += hit.Normal * (into - gap / HITCH)
        lv.VectorVelocity = vel
        if gap < 2 and impact > 250 and now - lastImpact > 1 then
          lastImpact = now
          Fx.crater(hit.Position, hit.Normal, math.clamp(impact / 320, 0.6, 1.8))
          impact = 0
        end
      else
        impact = 0
      end
      floor = floor or {}
      floor.at, floor.normal, floor.seen = hit.Position, hit.Normal, now
    elseif hit and speed > 320 and hit.Distance <= travel + 2 then
      Fx.wall(hit.Position, hit.Normal)
      vel = hit.Normal * 25
      lv.VectorVelocity = vel
      Flight.ramp, stage = 0, 0
      Fx.boostRing(false)
    end
  end
  -- A frame longer than HITCH can still leave the body under the ground it was coming down on,
  -- where no ray ahead will ever find that ground again. If the surface last seen is now above
  -- the body, put the body back on it.
  if floor and solid and now - floor.seen < 0.5 then
    local feet = feetBelowRoot()
    local height = (root.Position - floor.at):Dot(floor.normal)
    if height < feet - 0.75 then
      local over = workspace:Raycast(root.Position + floor.normal * (feet - height + 2), -floor.normal * (feet - height + 2), exclusions())
      if over and over.Normal.Y > 0.55 then
        root.CFrame += over.Normal * (feet - (root.Position - over.Position):Dot(over.Normal))
        local into = -vel:Dot(over.Normal)
        if into > 0 then
          vel += over.Normal * into
          lv.VectorVelocity = vel
        end
        floor.at, floor.normal, floor.seen = over.Position, over.Normal, now
      end
    end
  end
end

-- ---------------------------------------------------------------- carried by frames
-- What the two constraints do, done by hand (Flight.body = "frame"): the root goes along the
-- velocity the flight asked for and turns toward the way it asked to face, at the rate it asked
-- for, and is never put through anything solid: the path is looked along first and the body is
-- stopped short of what is in it, sliding along it. Its velocity is held at zero, so the engine
-- adds nothing; what gravity does between two frames (hundredths of a stud) is not carried on.
local carried, written       -- where it is being carried, and the CFrame last put on it
local SKIN = 2.4             -- studs kept from anything solid in the way
local DEEPEST = 60           -- studs over the height at which the game takes a body to have fallen out of the world
local function carry(dt)
  if not (faked and lv and alive()) then carried, written = nil, nil; return end
  local at = root.Position
  -- (anything that put the body somewhere since the last frame, this flight's own landing for
  -- one, is where it now is: carried on from there)
  local from = carried
  if not from or not written or (at - written.Position).Magnitude > 0.75 then from = at end
  local v = lv.VectorVelocity
  local step = v * dt
  local to = from + step
  if step.Magnitude > 1e-3 and not Config.get("move.noclip") then
    local hit = workspace:Raycast(from, step.Unit * (step.Magnitude + SKIN), exclusions())
    if hit then
      to = from + step.Unit * math.max(hit.Distance - SKIN, 0)
      local into = v:Dot(hit.Normal)
      if into < 0 then
        v -= hit.Normal * into
        lv.VectorVelocity, vel = v, v
      end
    end
  end
  local lowest = workspace.FallenPartsDestroyHeight + DEEPEST
  if to.Y < lowest then
    to = Vector3.new(to.X, lowest, to.Z)
    if os.clock() - (Flight.floorSaid or -math.huge) > 12 and B.Window and B.Window.toast then
      Flight.floorSaid = os.clock()
      B.Window.toast({ title = "Held over the void", text = "No ground out here. Fly back toward the map.", icon = "shield-check", time = 3.5 })
    end
    if v.Y < 0 then
      v = Vector3.new(v.X, 0, v.Z)
      lv.VectorVelocity, vel = v, v
    end
  end
  local turn = root.CFrame.Rotation:Lerp(ao.CFrame.Rotation, alpha(ao.Responsiveness or 14, dt))
  local cframe = turn + to
  root.CFrame = cframe
  root.AssemblyLinearVelocity = Vector3.zero
  root.AssemblyAngularVelocity = Vector3.zero
  carried, written = to, cframe
end

local function step(dt)
  stepTweens(dt)
  if root and root.Parent and hum and hum.FloorMaterial ~= Enum.Material.Air and Flight.state ~= "flying" and Flight.state ~= "landing" then
    stood = root.CFrame
  end
  -- (Flight.blocked: something else has the body, a game's own mover for one)
  if not O.fly or not alive() or hum.SeatPart or (Flight.blocked and Flight.blocked()) then
    if Flight.state ~= "off" then stopEverything() end
    if Fx.previewUntil > os.clock() and alive() then Fx.aim() end
    Fx.update(dt, 0, false, false)
    return
  end
  dt = math.min(dt, 0.1)
  warm()
  local state = Flight.state
  if state == "off" then
    if onGround() then
      Flight.state = "ground"
      blockJump(true)
      if not hinted and B.Window and B.Window.toast then
        hinted = true
        B.Window.toast({ title = "Flight is armed", text = "Hold Space to charge, let go to launch.", icon = "plane", time = 4.5 })
      end
    else
      startFlying()
    end
  elseif state == "ground" then
    blockJump(true)
    if onGround() then
      airborneSince = nil
      if down("Space") then beginCharge() end
    else
      -- walked off an edge, or knocked into the air: catch it
      airborneSince = airborneSince or os.clock()
      if os.clock() - airborneSince > 0.25 then
        airborneSince = nil
        startFlying()
      end
    end
  elseif state == "charging" then
    stepCharge()
  elseif state == "flying" then
    stepFly(dt)
  elseif state == "landing" then
    stepLanding(dt)
  end
  carry(dt)
  Fx.aim()
  Fx.update(dt, bodySpeed(), Flight.state == "flying", stage > 0)
end

local function attach(character)
  pcall(stopEverything)
  teardownPhysics()
  table.clear(Fx.rings)
  table.clear(streaks)
  table.clear(streakFree)
  Fx.trails, Fx.chargeAtt, Fx.boostAtt, Fx.dressAtt, Fx.pulse, Fx.pulseTwins, Fx.dress, Fx.previewUntil = false, nil, nil, nil, nil, nil, 0, 0
  savedAutoRotate, jumpWasEnabled = nil, nil
  char, hum, root, animator = nil, nil, nil, nil
  table.clear(tracks)
  if not character then return end
  local humanoid = character:WaitForChild("Humanoid", 8)
  local rootPart = character:WaitForChild("HumanoidRootPart", 8)
  if not humanoid or not rootPart or B.LP.Character ~= character then return end
  char, hum, root = character, humanoid, rootPart
  animator = humanoid:FindFirstChildOfClass("Animator") or humanoid:WaitForChild("Animator", 4)
  loadTracks()
end

-- what the Movement tab shows while this is running
function Flight.status()
  local state = Flight.state
  if state == "flying" then
    local speed = (root and root.Parent) and bodySpeed() or Flight.speed
    local tier, mach = tierOf(speed)
    return (tier > 0 and string.format("Mach %.1f", mach) or (stage > 0 and "Boosting" or (speed < 8 and "Hovering" or "Flying"))), speed, mach
  elseif state == "charging" then
    return "Charging " .. math.floor(Flight.charge * 100 + 0.5) .. "%", 0
  elseif state == "landing" then
    return "Landing", 0
  elseif state == "ground" then
    return "Armed: hold Space", 0
  end
  return O.fly and "Waiting for your character" or "Off", 0
end

function Flight.define()
  Config.define("move.fly", false)
  if Flight.flag ~= "move.fly" then Config.define(Flight.flag, false) end
  Config.define("move.flySpeed", 120)
  Config.define("fly.top", 900)
  Config.define("fly.sonic", 650)
  Config.define("fly.rampTime", 3)
  Config.define("fly.launch", 320)
  Config.define("fly.chargeTime", 1.2)
  Config.define("fly.idles", { "a" })
  Config.define("fly.idleEvery", 0)
  -- one hover pose used to be a single choice ("a", "b" or "alternate"): carry it over, once
  local legacy = Config.define("fly.idle", "a")
  if legacy ~= "a" and Config.isDefault("fly.idles") then
    Config.set("fly.idles", legacy == "alternate" and { "a", "b" } or { legacy })
    Config.set("fly.idle", "a")
  end
  Config.define("fly.animations", true)
  Config.define("fly.autoLand", true)
  Config.define("fly.windForOthers", true)
  Config.define("fly.effects", { "sonic", "takeoff", "boost", "trails", "streaks", "haze", "crater", "shake", "fov", "lines" })
  Config.define("fly.trailColor", Color3.fromRGB(225, 230, 240))
  Config.define("fly.sound", true)
  Config.define("fly.volume", 85)
  Config.define("fly.key.boost", "LeftShift")
  Config.define("fly.key.down", "LeftControl")
end

function Flight.start()
  if Flight.started then return end
  Flight.started = true
  Flight.define()
  O = Config.mirror({ fly = Flight.flag, speed = "move.flySpeed", top = "fly.top", sonic = "fly.sonic", rampTime = "fly.rampTime", launch = "fly.launch",
    chargeTime = "fly.chargeTime", idleEvery = "fly.idleEvery", animations = "fly.animations", autoLand = "fly.autoLand", windForOthers = "fly.windForOthers",
    trailColor = "fly.trailColor", sound = "fly.sound", volume = "fly.volume", keyBoost = "fly.key.boost", keyDown = "fly.key.down" })
  Flight.options = O
  local function effects(list)
    for _, name in ipairs({ "Sonic", "Takeoff", "Boost", "Trails", "Streaks", "Haze", "Crater", "Shake", "Fov", "Lines" }) do
      O["fx" .. name] = table.find(list, string.lower(name)) ~= nil
    end
  end
  effects(Config.get("fly.effects"))
  Config.on("fly.effects", effects)
  chooseIdles(Config.get("fly.idles"))
  Config.on("fly.idles", chooseIdles)
  rayParams = RaycastParams.new()
  rayParams.FilterType = Enum.RaycastFilterType.Exclude
  rayParams.IgnoreWater = true
  rayParams.RespectCanCollide = true      -- invisible trigger volumes are not ground

  B.connect(B.LP.CharacterAdded, attach, "flight.character")
  if B.LP.Character then task.spawn(B.safe("flight.attach", attach), B.LP.Character) end
  Config.on("fly.animations", function()
    if not hum then return end
    stopAnims(0.2)
    loadTracks()
  end)
  Config.on("fly.trailColor", function(color)
    if not char then return end
    for _, item in ipairs(char:GetDescendants()) do
      if item:IsA("Trail") and item.Parent and item.Parent.Name == "BasedTrailA" then item.Color = ColorSequence.new(color) end
    end
  end)
  B.connect(S.RunService.Heartbeat, function(dt)
    local ok, err = pcall(step, dt)
    if not ok then
      -- a fault here must never leave the body stuck in the air
      B.fault("flight", err)
      pcall(stopEverything)
      pcall(teardownPhysics)
      Config.set(Flight.flag, false)
    end
  end, "flight.step")
  S.RunService:BindToRenderStep("BasedFlightUndo", Enum.RenderPriority.Camera.Value - 1, cameraUndo)
  S.RunService:BindToRenderStep("BasedFlightApply", Enum.RenderPriority.Camera.Value + 1, function(dt) pcall(cameraApply, dt) end)
  B.own(function()
    pcall(function() S.RunService:UnbindFromRenderStep("BasedFlightUndo") end)
    pcall(function() S.RunService:UnbindFromRenderStep("BasedFlightApply") end)
    pcall(stopEverything)
    pcall(teardownPhysics)
    local camera = workspace.CurrentCamera
    if camera then
      if Fx.offset ~= CFrame.identity then camera.CFrame = camera.CFrame * Fx.offset:Inverse() end
      if Fx.baseFov then camera.FieldOfView = Fx.baseFov end
    end
    for _, track in pairs(tracks) do pcall(function() track:Stop(0) end) end
    for _, streak in ipairs(streaks) do
      pcall(function() streak.a:Destroy() end)
      pcall(function() streak.b:Destroy() end)
    end
    if char then
      for _, item in ipairs(char:GetDescendants()) do
        if item.Name == "BasedTrailA" or item.Name == "BasedTrailB" or item.Name == "BasedTrailDone" then pcall(function() item:Destroy() end) end
      end
    end
    for att in pairs(Fx.rings) do pcall(function() att:Destroy() end) end
  end)
end
end
do -- 27_void.lua
-- ============================================================================
--  27 void     the void cannot kill, and a fall into it is brought back
--
--  Measured on the client with throwaway parts (2026-10-07, a place whose height
--  was -500): an unanchored body under workspace.FallenPartsDestroyHeight is
--  removed by this client within half a second, an anchored one is not. Writing
--  -math.huge or -1e9 reads back -50,000: the engine clamps it, and the void is
--  simply 50,000 studs down, which is under three seconds away at flight speeds.
--  NaN is kept as written, and then nothing is removed at any depth, down to 1e12.
--  So the height is set to NaN, set again if the game changes it, and given back
--  on switch-off and on unload.
--
--  That removes the engine's void. A game whose own server script kills below
--  some height is out of reach from here. What can be done about those is not to
--  arrive: a fall with nothing under it is put back where the body last stood,
--  before it gets that far. Flight is never interfered with.
-- ============================================================================
local S, Config = B.S, B.Config
local Void = { rescues = 0, spots = {} }
B.Void = Void
local O
local NAN = 0 / 0
local AIR = Enum.Material.Air
local STATE = Enum.HumanoidStateType
local SETTLE = 0.4        -- seconds stood on a spot before it is somewhere to go back to
local APART = 10          -- studs between the spots that are remembered
local KEEP = 8
local SEE = 15000         -- a ray finds nothing further away than this (measured for the flight)
local EVERY = 0.06        -- seconds between looks: a fall is slow next to a frame

local spots = Void.spots
local gameHeight          -- the game's own height: the last value seen there that was not ours
local params
local clock, stoodSince, fallTop = 0, nil, nil
local lastRescue, lastOver, lastToast, nowhere = -math.huge, -math.huge, -math.huge, -math.huge
local wasAlive, lastY, warned, stopped = false, 0, false, false

local function unset(value) return value ~= value end      -- NaN is the one number that is not itself
local function apply()
  if stopped then return end
  local height = workspace.FallenPartsDestroyHeight
  if O.noVoid then
    if not unset(height) then
      gameHeight = height
      workspace.FallenPartsDestroyHeight = NAN
    end
  elseif gameHeight ~= nil and unset(height) then
    workspace.FallenPartsDestroyHeight = gameHeight
  end
  Void.height = gameHeight
end

local function toast(title, text)
  local now = os.clock()
  if now - lastToast < 6 or not (B.Window and B.Window.toast) then return end
  lastToast = now
  B.Window.toast({ title = title, text = text, icon = "shield", time = 3.5 })
end
local function flying()
  local state = B.Flight and B.Flight.state
  return state == "flying" or state == "landing" or state == "charging"
end
local function below(from, reach, character)
  params.FilterDescendantsInstances = { character }
  return workspace:Raycast(from, Vector3.new(0, -reach, 0), params)
end
local function soles(character, humanoid, root)
  local legs = 0
  if humanoid.RigType == Enum.HumanoidRigType.R6 then
    local leg = character:FindFirstChild("Left Leg")
    legs = leg and leg.Size.Y or 2
  end
  return humanoid.HipHeight + root.Size.Y * 0.5 + legs
end

-- Somewhere to go back to: ground the body has stood on for a moment, that is part of the map
-- (anchored, or terrain) rather than something loose or carried along.
local function remember(character, humanoid, root, now)
  stoodSince = stoodSince or now
  if now - stoodSince < SETTLE then return end
  local hit = below(root.Position, soles(character, humanoid, root) + 4, character)
  local ground = hit and hit.Instance
  if not ground or not ground:IsA("BasePart") or not (ground:IsA("Terrain") or ground.Anchored) then return end
  local newest = spots[#spots]
  if newest and (newest.Position - root.Position).Magnitude < APART then
    spots[#spots] = root.CFrame
  else
    spots[#spots + 1] = root.CFrame
    if #spots > KEEP then table.remove(spots, 1) end
  end
end
local function rescue(character, root, now)
  -- back in the void this soon after the last time: that spot was no good, use the one before
  if now - lastRescue < 4 and #spots > 1 then table.remove(spots) end
  while #spots > 0 do
    local spot = spots[#spots]
    if below(spot.Position + Vector3.new(0, 2, 0), 14, character) then
      root.CFrame = spot + Vector3.new(0, 0.5, 0)
      root.AssemblyLinearVelocity, root.AssemblyAngularVelocity = Vector3.zero, Vector3.zero
      lastRescue, fallTop = now, nil
      Void.rescues += 1
      toast("Back from the void", "Put back where you last stood.")
      return true
    end
    table.remove(spots)      -- the ground there has gone
  end
  return false
end

local function look(now)
  local character = B.character()
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  local root = character and character:FindFirstChild("HumanoidRootPart")
  local alive = humanoid ~= nil and root ~= nil and humanoid.Health > 0
  if not alive then
    -- It died with the void switched off, over nothing or under the game's height: the game has
    -- a rule of its own down there. Say so once, rather than leave it looking broken.
    if wasAlive and O.noVoid and not warned and (now - lastOver < 1.5 or (gameHeight ~= nil and lastY < gameHeight + 20)) then
      warned = true
      lastToast = -math.huge
      toast("This game has its own void", "Its scripts kill down there, which cannot be stopped from here. A shorter Catch me after gets you back before it.")
    end
    wasAlive, stoodSince, fallTop = false, nil, nil
    return
  end
  wasAlive, lastY = true, root.Position.Y
  if not O.noVoid then
    stoodSince, fallTop = nil, nil
    return
  end
  local state = humanoid:GetState()
  local airborne = humanoid.FloorMaterial == AIR
  -- (a game module moving the body on purpose, the Da Hood ragebot's void say: not a fall)
  local aside = Void.aside and Void.aside()
  if aside or flying() or humanoid.SeatPart or state == STATE.Swimming or state == STATE.Climbing then
    stoodSince, fallTop = nil, nil
    return
  end
  if not airborne and state ~= STATE.Freefall then
    fallTop = nil
    remember(character, humanoid, root, now)
    return
  end
  stoodSince = nil
  local y = root.Position.Y
  fallTop = math.max(fallTop or y, y)              -- the highest point of this fall
  local caught = gameHeight ~= nil and y < gameHeight          -- where the game itself would have ended it
  if not caught and root.AssemblyLinearVelocity.Y < -4 and fallTop - y > 30 then
    -- falling, and some way into it: is there anything down there at all?
    if not below(root.Position, SEE, character) then
      lastOver = now
      caught = fallTop - y > O.voidDrop
    end
  end
  if caught and O.voidRescue and now >= nowhere and not rescue(character, root, now) then
    nowhere = now + 8
    toast("Nowhere to put you back", "No ground you stood on is left. The void still cannot kill you: fly out of it.")
  end
end

function Void.define()
  Config.define("move.noVoid", true)
  Config.define("move.voidRescue", true)
  Config.define("move.voidDrop", 150)
end

function Void.start()
  if Void.started then return end
  Void.started = true
  Void.define()
  O = Config.mirror({ noVoid = "move.noVoid", voidRescue = "move.voidRescue", voidDrop = "move.voidDrop" })
  Void.options = O
  params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.RespectCanCollide = true        -- something that cannot be stood on is not ground
  params.IgnoreWater = false             -- water is somewhere to land
  Config.on("move.noVoid", apply)
  -- the game setting its height again must not bring the void back
  B.connect(workspace:GetPropertyChangedSignal("FallenPartsDestroyHeight"), apply, "void.height")
  apply()
  B.connect(S.RunService.Heartbeat, function(dt)
    clock += dt
    if clock < EVERY then return end
    clock = 0
    look(os.clock())
  end, "void.look")
  B.own(function()
    -- stopped first: giving the height back fires the signal above, which would take it away again
    stopped = true
    if gameHeight ~= nil and unset(workspace.FallenPartsDestroyHeight) then workspace.FallenPartsDestroyHeight = gameHeight end
  end)
end
end
do -- 28_self.lua
-- ============================================================================
--  28 self     how you look to yourself, and how the picture is graded
--
--  Your body: headless, a Korblox leg, a material over all of it, an aura, a
--  mark where each step lands. The picture: bloom, a colour grade, sun rays,
--  a blur. All of it is drawn on this screen only: nothing is sent to the game,
--  and everything is put back as it was when it is switched off or the hub goes.
-- ============================================================================
local S, util, Motion, Config = B.S, B.util, B.Motion, B.Config
local Lighting = S.Lighting
local Self = { kept = {}, bones = {}, aura = nil, orbs = {} }
B.Self = Self

local MATERIALS = { forcefield = Enum.Material.ForceField, neon = Enum.Material.Neon, glass = Enum.Material.Glass, foil = Enum.Material.Foil }
local RIGHT_LEG = { "RightUpperLeg", "RightLowerLeg", "RightFoot", "Right Leg" }
local BONE = Color3.fromRGB(22, 24, 38)

-- a property changed on one of our things, with what it was, kept to put back
local function set(item, key, value)
  local kept = Self.kept[item]
  if not kept then kept = {}; Self.kept[item] = kept end
  if kept[key] == nil then kept[key] = item[key] end
  if item[key] ~= value then item[key] = value end
end
local function putBack()
  for item, kept in pairs(Self.kept) do
    if item.Parent then
      for key, value in pairs(kept) do pcall(function() item[key] = value end) end
    end
  end
  table.clear(Self.kept)
  for _, piece in pairs(Self.bones) do pcall(function() piece:Destroy() end) end
  table.clear(Self.bones)
end
local function part(class, props, parent)
  local item = Instance.new(class)
  for key, value in pairs(props) do item[key] = value end
  item.Parent = parent
  return item
end
local function loose(props)
  props.Anchored, props.CanCollide, props.CanQuery, props.CanTouch, props.CastShadow = true, false, false, false, false
  return props
end

-- The body, made to look as asked. Safe to run again and again: what is already so is left alone
-- (run each second, for a part or a hat the game swaps in).
function Self.body()
  local character = B.LP.Character
  if not (character and character.Parent) then return end
  local o = Self.o
  if o.headless then
    local head = character:FindFirstChild("Head")
    if head then
      set(head, "Transparency", 1)
      for _, item in ipairs(head:GetChildren()) do
        if item:IsA("Decal") then set(item, "Transparency", 1) end
      end
    end
  end
  -- the right leg, swapped for a slim dark one: a bone welded inside each part of it, so it bends at the knee
  if o.korblox then
    for _, name in ipairs(RIGHT_LEG) do
      local leg = character:FindFirstChild(name)
      if leg and leg:IsA("BasePart") then
        set(leg, "Transparency", 1)
        local piece = Self.bones[leg]
        if name ~= "RightFoot" and not (piece and piece.Parent) then
          piece = part("Part", { Name = "BASED_Korblox", CanCollide = false, CanQuery = false, CanTouch = false, Massless = true, CastShadow = false,
            Size = Vector3.new(0.32, math.max(leg.Size.Y * 0.98, 0.4), 0.32), Material = Enum.Material.SmoothPlastic, Color = BONE }, character)
          part("Weld", { Part0 = leg, Part1 = piece }, piece)
          Self.bones[leg] = piece
        end
      end
    end
  end
  local material = MATERIALS[o.material]
  if material then
    for _, item in ipairs(character:GetDescendants()) do
      if item:IsA("BasePart") and item.Name ~= "HumanoidRootPart" and item.Name ~= "BASED_Korblox" and (Self.kept[item] or item.Transparency < 1) then
        set(item, "Material", material)
        set(item, "Color", o.materialColor)
        if item:IsA("MeshPart") then set(item, "TextureID", "") end
      end
    end
  end
end
-- everything put back, then made again as asked (a switch turned off)
function Self.redo()
  putBack()
  Self.body()
end

-- The aura: sparkles, fire or a glow on the root, or three lights going round it (moved each frame).
function Self.auraNow()
  if Self.aura then pcall(function() Self.aura:Destroy() end); Self.aura = nil end
  local o = Self.o
  local character = B.LP.Character
  local root = character and character:FindFirstChild("HumanoidRootPart")
  if not root then return end
  if o.aura == "sparkles" then
    Self.aura = part("Sparkles", { Name = "BASED_Aura", SparkleColor = o.auraColor }, root)
  elseif o.aura == "fire" then
    Self.aura = part("Fire", { Name = "BASED_Aura", Color = o.auraColor, SecondaryColor = o.auraColor:Lerp(Color3.new(1, 1, 1), 0.5), Size = 4, Heat = 6 }, root)
  elseif o.aura == "glow" then
    Self.aura = part("PointLight", { Name = "BASED_Aura", Color = o.auraColor, Brightness = 2.2, Range = 14, Shadows = false }, root)
  end
end
local function clearOrbs()
  for _, orb in ipairs(Self.orbs) do pcall(function() orb:Destroy() end) end
  table.clear(Self.orbs)
end

-- ---------------------------------------------------------------- each frame: the orbit and the steps
local stepAt, stepFrom = 0, nil
local function ripple(foot, color)
  local ring = part("Part", loose({ Name = "BASED_Step", Shape = Enum.PartType.Cylinder, Material = Enum.Material.Neon, Color = color, Transparency = 0.35,
    Size = Vector3.new(0.08, 0.8, 0.8), CFrame = CFrame.new(foot) * CFrame.Angles(0, 0, math.rad(90)) }), workspace)
  Motion.tween(0.6, Motion.ease.outCubic, function(p)
    if not ring.Parent then return end
    local size = 0.8 + p * 5.2
    ring.Size = Vector3.new(0.08, size, size)
    ring.Transparency = 0.35 + 0.65 * p
  end, function() ring:Destroy() end)
end
local function sparks(foot, color)
  for index = 1, 5 do
    local spark = part("Part", loose({ Name = "BASED_Step", Material = Enum.Material.Neon, Color = color, Size = Vector3.new(0.16, 0.16, 0.16), CFrame = CFrame.new(foot) }), workspace)
    local a = index * math.pi * 2 / 5 + math.random() * 0.8
    local way = Vector3.new(math.cos(a), 0.9 + math.random() * 0.6, math.sin(a)) * (1.6 + math.random() * 1.2)
    Motion.tween(0.45, Motion.ease.outCubic, function(p)
      if not spark.Parent then return end
      spark.CFrame = CFrame.new(foot + way * p - Vector3.new(0, 3 * p * p, 0))
      spark.Transparency = p
    end, function() spark:Destroy() end)
  end
end
local function frame()
  local o = Self.o
  local character = B.LP.Character
  local root = character and character:FindFirstChild("HumanoidRootPart")
  if o.aura == "orbit" and root then
    for index = 1, 3 do
      local orb = Self.orbs[index]
      if not (orb and orb.Parent) then
        orb = part("Part", loose({ Name = "BASED_Orb", Shape = Enum.PartType.Ball, Size = Vector3.new(0.5, 0.5, 0.5), Material = Enum.Material.Neon }), workspace)
        Self.orbs[index] = orb
      end
      local t = os.clock()
      local a = t * 2.4 + index * math.pi * 2 / 3
      orb.Color = o.auraColor
      orb.CFrame = CFrame.new(root.Position + Vector3.new(math.cos(a) * 3, math.sin(t * 1.7 + index) * 1.2, math.sin(a) * 3))
    end
  elseif #Self.orbs > 0 then
    clearOrbs()
  end
  -- a mark where each step lands: every 3.2 studs walked on the ground
  if o.steps == "off" or not root then stepFrom = nil; return end
  local humanoid = character:FindFirstChildOfClass("Humanoid")
  if not humanoid or humanoid.FloorMaterial == Enum.Material.Air then stepFrom = nil; return end
  local here = root.Position
  if not stepFrom then stepFrom = here; return end
  if Vector2.new(here.X - stepFrom.X, here.Z - stepFrom.Z).Magnitude < 3.2 or os.clock() - stepAt < 0.12 then return end
  stepFrom, stepAt = here, os.clock()
  local foot = here - Vector3.new(0, humanoid.HipHeight + root.Size.Y / 2 - 0.05, 0)
  if o.steps == "ripples" then ripple(foot, o.stepColor) else sparks(foot, o.stepColor) end
end

-- ---------------------------------------------------------------- the picture
local effects = {}
local function effect(class, name, on, props)
  local item = effects[name]
  if not on then
    if item then item:Destroy(); effects[name] = nil end
    return
  end
  if not (item and item.Parent) then
    item = Instance.new(class)
    item.Name = "BASED_" .. name
    item.Parent = Lighting
    effects[name] = item
  end
  for key, value in pairs(props) do
    if item[key] ~= value then item[key] = value end
  end
end
function Self.picture()
  local o = Self.o
  effect("BloomEffect", "Bloom", o.bloom, { Intensity = o.bloomIntensity, Size = 24, Threshold = 0.9 })
  effect("ColorCorrectionEffect", "Grade", o.grade, { Saturation = o.saturation / 100, Contrast = o.contrast / 100, Brightness = 0, TintColor = o.tint })
  effect("SunRaysEffect", "Rays", o.rays, { Intensity = o.raysIntensity / 100, Spread = 0.8 })
  effect("BlurEffect", "Blur", o.blur, { Size = o.blurSize })
end

function Self.define()
  Config.define("self.headless", false)
  Config.define("self.korblox", false)
  Config.define("self.material", "off")
  Config.define("self.materialColor", util.hex("9F8CFF"))
  Config.define("self.aura", "off")
  Config.define("self.auraColor", util.hex("9F8CFF"))
  Config.define("self.steps", "off")
  Config.define("self.stepColor", util.hex("FFFFFF"))
  Config.define("fx.bloom", false)
  Config.define("fx.bloomIntensity", 0.6)
  Config.define("fx.grade", false)
  Config.define("fx.saturation", 15)
  Config.define("fx.contrast", 10)
  Config.define("fx.tint", Color3.new(1, 1, 1))
  Config.define("fx.rays", false)
  Config.define("fx.raysIntensity", 12)
  Config.define("fx.blur", false)
  Config.define("fx.blurSize", 3)
end

function Self.start()
  if Self.started then return end
  Self.started = true
  Self.define()
  Self.o = Config.mirror({ headless = "self.headless", korblox = "self.korblox", material = "self.material", materialColor = "self.materialColor",
    aura = "self.aura", auraColor = "self.auraColor", steps = "self.steps", stepColor = "self.stepColor", bloom = "fx.bloom", bloomIntensity = "fx.bloomIntensity",
    grade = "fx.grade", saturation = "fx.saturation", contrast = "fx.contrast", tint = "fx.tint", rays = "fx.rays", raysIntensity = "fx.raysIntensity",
    blur = "fx.blur", blurSize = "fx.blurSize" })
  for _, id in ipairs({ "self.headless", "self.korblox", "self.material", "self.materialColor" }) do
    Config.on(id, function() B.try("self.body", Self.redo) end)
  end
  for _, id in ipairs({ "self.aura", "self.auraColor" }) do
    Config.on(id, function() B.try("self.aura", Self.auraNow) end)
  end
  for _, id in ipairs({ "fx.bloom", "fx.bloomIntensity", "fx.grade", "fx.saturation", "fx.contrast", "fx.tint", "fx.rays", "fx.raysIntensity", "fx.blur", "fx.blurSize" }) do
    Config.on(id, function() B.try("self.picture", Self.picture) end)
  end
  -- a new body (a respawn): what was kept belonged to the old one
  B.connect(B.LP.CharacterAdded, function(character)
    character:WaitForChild("HumanoidRootPart", 10)
    task.wait(0.5)
    table.clear(Self.kept)
    table.clear(Self.bones)
    B.try("self.body", Self.body)
    B.try("self.aura", Self.auraNow)
  end, "self.respawn")
  Motion.every(function() B.try("self.frame", frame) end, nil, "self.frame")
  -- (the game can swap a part of the body, or what it wears)
  Motion.every(function()
    local o = Self.o
    if o.headless or o.korblox or o.material ~= "off" then B.try("self.body", Self.body) end
  end, 1, "self.refresh")
  B.try("self.body", Self.body)
  B.try("self.aura", Self.auraNow)
  B.try("self.picture", Self.picture)
  B.onUnload:connect(function()
    putBack()
    clearOrbs()
    if Self.aura then pcall(function() Self.aura:Destroy() end) end
    for name in pairs(effects) do effect("Frame", name, false, {}) end
  end)
end
end
do -- 40_universal.lua
-- ============================================================================
--  40 universal  the tabs every game gets: Combat, Visuals, Movement, Players, World
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Controls
local Roster, Esp, Aim, Move, World, Server, Hud = B.Roster, B.Esp, B.Aim, B.Move, B.World, B.Server, B.Hud
local UIS = S.UserInputService
B.pages = B.pages or {}
local GROUP = "Universal"
local firstPage = #B.pages + 1

-- on screen in either look: the BASED window on that tab, or the Unnamed menu on it (the preview
-- only ever asked the BASED window, so in the Unnamed look it stood still: "frozen")
local function onPage(id) return Window.showing(id) end

-- ---------------------------------------------------------------- the 3D preview
-- Your own character on a turntable, with the real ESP renderer drawing over it.
-- Every switch in the tab changes this picture as you flip it.
local function dummy()
  local model = Instance.new("Model")
  local function block(name, size, position, color)
    local part = Instance.new("Part")
    part.Name = name
    part.Size = size
    part.CFrame = CFrame.new(position)
    part.Anchored = true
    part.Color = color
    part.Material = Enum.Material.SmoothPlastic
    part.TopSurface, part.BottomSurface = Enum.SurfaceType.Smooth, Enum.SurfaceType.Smooth
    part.Parent = model
    return part
  end
  local skin, shirt, trousers = Color3.fromRGB(226, 198, 170), Color3.fromRGB(96, 88, 150), Color3.fromRGB(44, 44, 54)
  block("Head", Vector3.new(1.2, 1.2, 1.2), Vector3.new(0, 4.6, 0), skin)
  local torso = block("Torso", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), shirt)
  block("Left Arm", Vector3.new(1, 2, 1), Vector3.new(-1.5, 3, 0), skin)
  block("Right Arm", Vector3.new(1, 2, 1), Vector3.new(1.5, 3, 0), skin)
  block("Left Leg", Vector3.new(1, 2, 1), Vector3.new(-0.5, 1, 0), trousers)
  block("Right Leg", Vector3.new(1, 2, 1), Vector3.new(0.5, 1, 0), trousers)
  local root = block("HumanoidRootPart", Vector3.new(2, 2, 1), Vector3.new(0, 3, 0), shirt)
  root.Transparency = 1
  model.PrimaryPart = torso
  return model
end
local function cloneCharacter()
  local character = B.character()
  if not character or not character:FindFirstChild("HumanoidRootPart") then return nil end
  local ok, clone = pcall(function()
    local archivable = character.Archivable
    character.Archivable = true
    local copy = character:Clone()
    character.Archivable = archivable
    return copy
  end)
  if not ok or not clone then return nil end
  for _, item in ipairs(clone:GetDescendants()) do
    if item:IsA("LuaSourceContainer") or item:IsA("Sound") or item:IsA("BillboardGui") or item:IsA("ForceField") or item:IsA("ParticleEmitter") or item:IsA("Tool") then
      item:Destroy()
    elseif item:IsA("BasePart") then
      item.Anchored = true
    end
  end
  local humanoid = clone:FindFirstChildOfClass("Humanoid")
  if humanoid then
    humanoid.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
    humanoid.HealthDisplayType = Enum.HumanoidHealthDisplayType.AlwaysOff
  end
  clone:PivotTo(CFrame.new(0, 3, 0))
  return clone
end

local function preview(frame)
  local stage = UI.frame(frame, { Name = "Stage", Size = UDim2.new(1, -24, 1, -24), Position = UDim2.fromOffset(12, 0), ClipsDescendants = true,
    Theme = { BackgroundColor3 = "ink" }, BackgroundTransparency = 0.965 })
  UI.corner(stage, "rControl")
  UI.gradient(stage, { Rotation = 90, Transparency = UI.alphaSeq(0, 1, 1, 0.9) })
  local viewport = UI.new("ViewportFrame", { Name = "Model", Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1, LightColor = Color3.new(1, 1, 1),
    Ambient = Color3.fromRGB(150, 150, 160), LightDirection = Vector3.new(-0.6, -1, -0.8), Parent = stage })
  local world = Instance.new("WorldModel")
  world.Parent = viewport
  local model = cloneCharacter() or dummy()
  model.Parent = world
  local camera = Instance.new("Camera")
  camera.FieldOfView = 30
  camera.Parent = viewport
  viewport.CurrentCamera = camera
  local overlay = UI.frame(stage, { Name = "Overlay", Size = UDim2.fromScale(1, 1), ZIndex = 2 })
  local sample = Esp.Object.new(overlay)
  local arrow = UI.image(overlay, "arrow", { Size = UDim2.fromOffset(18, 18), AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.new(1, -26, 0, 30), Rotation = 55, Visible = false })
  local hint = UI.text(stage, "drag to turn", "mono", "faint", { TextSize = 10, AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -8), ZIndex = 3 })
  -- how big a design pixel is where the stage sits: the BASED window and the Unnamed menu are
  -- scaled apart, and the picture is drawn in design pixels inside whichever holds it
  local ruler = UI.frame(stage, { Name = "Ruler", Size = UDim2.fromOffset(100, 100), BackgroundTransparency = 1 })

  local entry = Roster.describe(model)
  local centre = (entry.root and entry.root.Position or Vector3.new(0, 3, 0)) + Vector3.new(0, 0.25, 0)
  local yaw, spin, idle = 0.5, 0, 0
  local dragging = false
  local grab = UI.new("TextButton", { Text = "", BackgroundTransparency = 1, AutoButtonColor = false, Size = UDim2.fromScale(1, 1), ZIndex = 5, Parent = stage })
  local lastX
  UI.drag(grab, function(point) dragging = true; lastX = point.X; hint.Visible = false end, function(point)
    local dx = point.X - lastX
    lastX = point.X
    yaw -= dx * 0.012
    spin = -dx * 0.012 / math.max(Motion.dt, 1 / 240)
  end, function() dragging = false; idle = 0 end)

  local info = { joints = {} }
  local joints = {}
  local clock = 0
  Motion.every(function(dt)
    if not stage.Parent or not onPage("visuals") then return end
    clock += dt
    if not dragging then
      -- a flick keeps turning and eases out; left alone, it drifts round slowly
      spin *= math.exp(-dt * 3.2)
      idle += dt
      yaw += spin * dt + (idle > 1.4 and 0.38 * dt or 0)
    end
    local unit = ruler.AbsoluteSize.X / 100
    if unit < 0.05 then unit = UI.unit() end
    local size = stage.AbsoluteSize / unit
    if size.X < 10 then return end
    -- (a game whose module adds lines under the box gets a smaller figure, higher up: room for them)
    local more = Esp.extras.money ~= nil or Esp.extras.ammo ~= nil
    local distance = more and 18 or 15.5
    local cf = CFrame.new(centre - Vector3.new(0, more and 0.7 or 0, 0)) * CFrame.Angles(0, yaw, 0) * CFrame.new(0, 0, distance)
    camera.CFrame = cf
    local tanHalf = math.tan(math.rad(camera.FieldOfView) * 0.5)
    local aspect = size.X / size.Y
    local function project(point)
      local p = cf:PointToObjectSpace(point)
      local depth = -p.Z
      return (0.5 + p.X / (depth * tanHalf * aspect) * 0.5) * size.X, (0.5 - p.Y / (depth * tanHalf) * 0.5) * size.Y, depth
    end
    local o, on = Esp.options, Esp.want
    local head, root = entry.head, entry.root
    if not root then return end
    local _, topY = project((head and head.Position or root.Position + Vector3.new(0, 1.6, 0)) + Vector3.new(0, 0.85, 0))
    local cx, bottomY = project(root.Position - Vector3.new(0, entry.legs or 3, 0))
    local height = bottomY - topY
    local width = height * 0.56
    info.x, info.y, info.w, info.h = cx - width * 0.5, topY, width, height
    info.color = o.colorMode == "health" and Color3.fromHSV(0.33 * (0.55 + 0.45 * math.sin(clock * 0.9)), 0.75, 1) or o.color
    info.alpha = 1
    info.name = o.displayNames and B.LP.DisplayName or B.LP.Name
    info.distance = 128
    info.health = 0.55 + 0.45 * math.sin(clock * 0.9)
    info.hp = info.health * 100
    info.team = "Red team"
    info.tool = "Classic Sword"
    -- what the game's module adds, with figures of its own for the picture
    local extras = Esp.extras
    local demo = extras.sample or {}
    info.armor, info.armorValue, info.ammo, info.money, info.flags = nil, nil, nil, nil, nil
    if extras.armor then
      info.armor = 0.5 + 0.5 * math.sin(clock * 0.6 + 1.3)
      info.armorValue = info.armor * (demo.armorMax or 100)
    end
    if extras.ammo then info.ammo = demo.ammo or "12/30" end
    if extras.money then info.money = demo.money or "$12,500" end
    if extras.flags then info.flags = demo.flags or "RELOADING" end
    if demo.tool then info.tool = demo.tool end
    if demo.team ~= nil then info.team = demo.team or nil end
    info.joints, info.bones, info.headR, info.lookX, info.originX = nil, nil, nil, nil, nil
    if head then
      local hx, hy, depth = project(head.Position)
      info.headX, info.headY = hx, hy
      info.headR = (head.Size.Y * 0.62) / depth * size.Y / (2 * tanHalf)
      local lx, ly = project(head.Position + head.CFrame.LookVector * 2.2)
      info.lookX, info.lookY = lx, ly
    end
    for name, part in pairs(entry.joints) do
      local jx, jy, depth = project(part.Position)
      local slot = joints[name]
      if not slot then slot = {}; joints[name] = slot end
      slot[1], slot[2], slot[3] = jx, jy, depth > 0
    end
    info.joints, info.bones = joints, entry.bones
    info.originX, info.originY = size.X * 0.5, size.Y
    sample:draw(info, o, on)
    arrow.Visible = on.arrows == true
    arrow.ImageColor3 = info.color
    -- chams cannot draw inside a viewport: tint the model the way the fill would
    local fill = on.chams and (1 - o.chamsFill / 100) or 0
    viewport.ImageColor3 = Color3.new(1, 1, 1):Lerp(info.color, fill * 0.85)
  end, nil, "esp.preview")
end

-- ---------------------------------------------------------------- Visuals
-- the last stop of a distance slider reads as no limit rather than as a number
local function reach(limit)
  return function(v) return v >= limit and "No limit" or (util.comma(v) .. " st") end
end
B.pages[#B.pages + 1] = function()
  Esp.start(); World.start()
  if B.Self then B.Self.start() end
  Window.page({ id = "visuals", title = "Visuals", icon = "eye", group = GROUP, order = 220, build = function(page)
    local show = page:section({ title = "Preview", icon = "scan-eye", column = 1, weight = 8 })
    show:custom({ height = 348, build = preview })
    show:toggle({ id = "esp.enabled", label = "Player ESP", desc = "Draws the picture above on every player." })

    local what = page:section({ title = "What to draw", icon = "layers", column = 2, weight = 5 })
    local elements = {
      { "box", "Box", icon = "scan" }, { "name", "Name", icon = "tag" }, { "health", "Health bar", icon = "heart-pulse" }, { "hp", "Health number", icon = "hash" },
      { "distance", "Distance", icon = "ruler" }, { "tool", "Held tool", icon = "sword" }, { "team", "Team name", icon = "flag" }, { "skeleton", "Skeleton", icon = "bone" },
      { "head", "Head ring", icon = "circle" }, { "look", "Look direction", icon = "navigation" }, { "tracer", "Tracer", icon = "route" },
      { "arrows", "Off-screen arrows", icon = "arrow-up-right" }, { "chams", "Chams (through walls)", icon = "ghost" } }
    -- what only this game's module can read of a player: offered when it is there to be read
    for _, extra in ipairs(Esp.EXTRA) do
      if Esp.extras[extra[1]] then table.insert(elements, extra[1] == "armor" and 4 or #elements + 1, extra) end
    end
    what:multi({ id = "esp.elements", label = "Elements", empty = "Nothing", menuWidth = 226, options = elements })
    what:segmented({ id = "esp.box", label = "Box style", options = { { "corners", "Corners" }, { "full", "Full" } }, width = 160 })
    what:toggle({ id = "esp.fill", label = "Fill the box", bindable = false, children = function(sub)
      sub:toggle({ id = "esp.fillTwo", label = "Two colours", desc = "Fades from the box colour to this one.", bindable = false,
        children = function(more) more:color({ id = "esp.fillColor2", label = "Second colour" }) end })
    end })
    what:slider({ id = "esp.boxWidth", label = "Box width", desc = "As a share of its height.", min = 30, max = 90, step = 1, suffix = "%" })
    what:segmented({ id = "esp.tracerFrom", label = "Tracers start at", options = { { "bottom", "Bottom" }, { "center", "Centre" }, { "top", "Top" }, { "mouse", "Mouse" } }, width = 232 })
    -- and whatever the game's module has to add to this tab, where it is seen
    for _, add in ipairs(Esp.sections) do B.try("visuals.extra", add, page) end

    local style = page:section({ title = "Colour & weight", icon = "palette", column = 2, weight = 5 })
    style:dropdown({ id = "esp.colorMode", label = "Colour by", options = { { "custom", "One colour" }, { "team", "Team colour" }, { "health", "Health" } } })
    style:color({ id = "esp.color", label = "Colour" })
    style:color({ id = "esp.friendColor", label = "Friends" })
    style:toggle({ id = "esp.seenTint", label = "Own colour when in view", desc = "Anyone you have a clear line to. One ray per player, ten times a second.", bindable = false,
      children = function(sub) sub:color({ id = "esp.seenColor", label = "In view" }) end })
    style:toggle({ id = "esp.markTarget", label = "Colour the aim target", desc = "Whoever aim assist is on.", bindable = false,
      children = function(sub) sub:color({ id = "esp.targetColor", label = "Target" }) end })
    style:slider({ id = "esp.thickness", label = "Line weight", min = 0.5, max = 6, step = 0.5, suffix = " px" })
    style:slider({ id = "esp.textSize", label = "Text size", min = 8, max = 32, step = 1, suffix = " px" })
    style:slider({ id = "esp.chamsFill", label = "Chams fill", desc = "0 is solid, 100 is outline only.", min = 0, max = 100, step = 5, suffix = "%" })
    style:toggle({ id = "esp.chamsOutline", label = "Chams outline", bindable = false })

    local who = page:section({ title = "Who and how far", icon = "filter", column = 1, weight = 4 })
    who:toggle({ id = "esp.teamCheck", label = "Hide teammates", bindable = false })
    who:toggle({ id = "esp.displayNames", label = "Show display names", bindable = false })
    who:slider({ id = "esp.range", label = "Range", desc = "All the way right is no limit.", min = 50, max = Esp.FAR, step = 50, curve = 3.2, valueWidth = 84, format = reach(Esp.FAR) })
    who:slider({ id = "esp.nameRange", label = "Names within", desc = "Further off, only the box and the distance: less to read on a full map.", min = 50, max = Esp.FAR, step = 50,
      curve = 3.2, valueWidth = 84, format = reach(Esp.FAR) })
    who:slider({ id = "esp.skeletonRange", label = "Skeleton range", desc = "Skeletons are the costliest element: keep them near.", min = 25, max = 10000, step = 25, curve = 3,
      valueWidth = 84, format = function(v) return util.comma(v) .. " st" end })
    who:slider({ id = "esp.minSize", label = "Smallest box", desc = "Far players are never drawn smaller than this, so they stay findable.", min = 0, max = 40, step = 1,
      format = function(v) return v <= 0 and "Off" or (util.format(v, 0) .. " px") end })
    who:slider({ id = "esp.maxPlayers", label = "Draw at most", desc = "The nearest first.", min = 1, max = Esp.EVERYONE, step = 1,
      format = function(v) return v >= Esp.EVERYONE and "Everyone" or (util.format(v, 0) .. (v == 1 and " player" or " players")) end, valueWidth = 84 })
    who:toggle({ id = "esp.fade", label = "Fade with distance", bindable = false, children = function(sub)
      sub:slider({ id = "esp.fadeFrom", label = "Starting at", desc = "How far along the range it begins.", min = 0, max = 95, step = 5, suffix = "%" })
    end })
    who:toggle({ id = "esp.dimHidden", label = "Dim players behind walls", desc = "One ray per player, ten times a second.", bindable = false })
    who:toggle({ id = "esp.hideHidden", label = "Only players in view", desc = "Leaves out anyone behind a wall.", bindable = false })

    local arrows = page:section({ title = "Off-screen arrows", icon = "arrow-up-right", column = 1, weight = 3 })
    arrows:slider({ id = "esp.arrowSize", label = "Size", min = 10, max = 48, step = 1, suffix = " px" })
    arrows:slider({ id = "esp.arrowRadius", label = "Distance from centre", min = 10, max = 48, step = 1, suffix = "%" })
    arrows:toggle({ id = "esp.arrowDistance", label = "Say how far", bindable = false })

    local light = page:section({ title = "World", icon = "sun", column = 1, weight = 4 })
    light:toggle({ id = "world.fullbright", label = "Fullbright", desc = "No shadows, flat daylight.", children = function(sub)
      sub:slider({ id = "world.brightValue", label = "Brightness", min = 1, max = 6, step = 0.25 })
    end })
    light:toggle({ id = "world.noFog", label = "No fog" })
    light:toggle({ id = "world.time", label = "Lock the time of day", children = function(sub)
      sub:slider({ id = "world.timeValue", label = "Hour", min = 0, max = 24, step = 0.25 })
    end })

    local you = page:section({ title = "You", icon = "user", column = 2, weight = 5 })
    you:toggle({ id = "self.headless", label = "Headless", desc = "Only you see it." })
    you:toggle({ id = "self.korblox", label = "Korblox leg", desc = "Only you see it." })
    you:dropdown({ id = "self.material", label = "Body material", options = { { "off", "Off" }, { "forcefield", "Force field" }, { "neon", "Neon" }, { "glass", "Glass" }, { "foil", "Foil" } } })
    you:color({ id = "self.materialColor", label = "Material colour" })
    you:dropdown({ id = "self.aura", label = "Aura", options = { { "off", "Off" }, { "sparkles", "Sparkles" }, { "fire", "Fire" }, { "glow", "Glow" }, { "orbit", "Orbit" } } })
    you:color({ id = "self.auraColor", label = "Aura colour" })
