local AMBUSH_SPAN = 0.9      -- s after it comes out in which a shot can still be in time
local AMBUSH_LEAST = 6       -- places it has to have been seen at in showings before this one
local AMBUSH_GRID = 28       -- studs between the places a shot is claimed at through that room, at the least: a hit is taken 22 off
local AMBUSH_ROOM = 4        -- studs the room is taken to reach past the outermost place it was seen at
local AMBUSH_MARKS = 24      -- the most places in one claim (one call each; a shotgun's are five, and it keeps to HAUNT_SHELLS)
local AMBUSH_RANGE = 180     -- studs: guns that reach this far are used alone, from where the hider's own claims do not go
