    after:toggle({ id = "dahood.stomp", label = "Stomp", desc = "Stomps the moment you are over the body, in the air too. A carrier is shot down first.", default = true, children = function(sub)
      sub:segmented({ id = "dahood.finish", label = "Knock from", desc = "From above: fastest stomp. Same place: shoots from your Hover spot.",
        options = { { "above", "From above" }, { "same", "Same place" } }, default = "above", width = 190 })
      sub:slider({ id = "dahood.stompUp", label = "Stomp height", desc = "It counts from 1.5 to 9.5 studs up.", min = STOMP_LOW, max = STOMP_UP, step = 0.5, default = 3.5, suffix = " st" })
