      sub:toggle({ id = "dahood.repRoot", label = "Rep root", desc = "Asked for. Measured to change nothing.", default = true })
    end })
    after:toggle({ id = "dahood.cross", label = "Cross fire", desc = "A free gun knocks anyone else hunted in reach.", default = true })

    local timing = page:section({ title = "Timing", icon = "timer", desc = "When shots go after you arrive." })
    timing:slider({ id = "dahood.arrive", label = "Arrive delay", desc = "Wait after a long hop before the first shot.", min = ARRIVE, max = 1, step = 0.01, default = ARRIVE, suffix = " s" })
    timing:toggle({ id = "dahood.bait", label = "Bait", desc = "With Lure off: stops at home so a follower comes to you.", default = true })
    timing:toggle({ id = "dahood.flak", label = "Flak", desc = "A target that never holds still is shot at the places it has been.", default = true })
    timing:toggle({ id = "dahood.flakOpen", label = "Open flak", desc = "Off: flak only from inside a wall. Safer against many.", default = true })
    timing:toggle({ id = "dahood.lure", label = "Lure", desc = "Shows for a blink so a hider or follower comes, then shoots where it does.", default = true })
    timing:toggle({ id = "dahood.ambush", label = "Ambush", desc = "One that shows itself is shot where it goes next, from far off.", default = true })
    timing:toggle({ id = "dahood.pounce", label = "Pounce", desc = "With a gun that knocks in one shot, it goes in close instead.", default = true })
    timing:toggle({ id = "dahood.padTrap", label = "Armor pad trap", desc = "One that loses armor is shot on the pad it buys it back at.", default = true })
    timing:slider({ id = "dahood.seen", label = "Seen time", desc = "How long a target must hold still first.", min = 0, max = 0.5, step = 0.01, default = 0.05, suffix = " s" })
    timing:slider({ id = "dahood.shieldLead", label = "Shield lead", desc = "How early you are in place before a shield ends.", min = 0, max = 1, step = 0.05, default = 0.1, suffix = " s" })
    timing:slider({ id = "dahood.margin", label = "Rate margin", min = RATE_MARGIN, max = 0.2, step = 0.005, default = RATE_MARGIN, suffix = " s" })
