    page:custom(nil, function(frame)
      local DH = B.DaHood
      local card = UI.surface(frame, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.stroke(card, "ink", "strokeA")
      local stack = UI.frame(card, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(stack, "y", 0)
      local top = UI.frame(stack, { Name = "Top", Size = UDim2.new(1, 0, 0, 52), LayoutOrder = 0 })
      local count = UI.text(top, "Targets", "heading", "ink", { Position = UDim2.new(0, 16, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      local clear = Controls.pillButton(top, "Clear", nil, function() DH.clearMarks() end)
      clear.AnchorPoint, clear.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
      -- a search: a few letters of a name or a display name, and the list is whoever has them
      local shownNow = {}
      local every = Controls.pillButton(top, "All", nil, function()
        for _, player in ipairs(shownNow) do DH.mark(player, true) end
      end)
      every.Name = "MarkAll"
      every.AnchorPoint, every.Position = Vector2.new(1, 0.5), UDim2.new(1, -76, 0.5, 0)
      local search, box = Controls.field(top, { Width = 150, PlaceholderText = "Search a name" })
      search.Name = "Search"
      search.AnchorPoint, search.Position = Vector2.new(1, 0.5), UDim2.new(1, -128, 0.5, 0)
      local list = UI.frame(stack, { Name = "List", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1 })
      UI.list(list, "y", 0)
      UI.pad(list, 0, 0, 6, 0)
      local rows = {}
      local WORDS = { up = "up", down = "knocked", shield = "shielded", dead = "dead", loading = "loading", none = "no body", gone = "left" }
      local function rebuild()
        for _, row in ipairs(rows) do row.frame:Destroy() end
        table.clear(rows)
        local players = S.Players:GetPlayers()
        -- the marked first, then by name
        table.sort(players, function(a, b)
          local am, bm = DH.isMarked(a), DH.isMarked(b)
          if am ~= bm then return am end
          return string.lower(a.Name) < string.lower(b.Name)
        end)
        local wanted = string.lower(box.Text)
        table.clear(shownNow)
        local marked, others = 0, 0
        for index, player in ipairs(players) do
          if player ~= B.LP then others += 1 end
          if player ~= B.LP and (wanted == "" or string.find(string.lower(player.Name), wanted, 1, true) or string.find(string.lower(player.DisplayName), wanted, 1, true)) then
            shownNow[#shownNow + 1] = player
            local row = UI.frame(list, { Name = player.Name, Size = UDim2.new(1, 0, 0, 46), LayoutOrder = index })
            UI.frame(row, { Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
            local face = UI.new("ImageLabel", { Size = UDim2.fromOffset(30, 30), Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 0.9,
              Theme = { BackgroundColor3 = "ink" }, Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150", Parent = row })
            UI.corner(face, true)
            UI.text(row, player.DisplayName, "label", "ink", { Position = UDim2.fromOffset(56, 6), Size = UDim2.new(1, -250, 0, 18), AutomaticSize = Enum.AutomaticSize.None,
              TextTruncate = Enum.TextTruncate.AtEnd })
            UI.text(row, "@" .. player.Name, "caption", "faint", { Position = UDim2.fromOffset(56, 24), Size = UDim2.new(1, -250, 0, 16), AutomaticSize = Enum.AutomaticSize.None,
              TextTruncate = Enum.TextTruncate.AtEnd, TextSize = 11.5 })
            local state = UI.text(row, "", "mono", "sub", { Name = "State", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -184, 0.5, 0) })
            local on = DH.isMarked(player)
            if on then marked += 1 end
            local entry = B.Roster.byPlayer[player]
            local friend = entry ~= nil and B.Roster.isFriend(entry)
            -- a mark and a friend are one or the other
            local button = Controls.pillButton(row, on and "Marked" or "Mark", on and "primary" or nil, function()
              local marking = not DH.isMarked(player)
              if marking and entry and B.Roster.isFriend(entry) then B.Roster.setFriend(entry, false) end
              DH.mark(player, marking)
            end)
            button.Name = "Mark"
            button.AnchorPoint, button.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
            -- Spare: never hunted by Everyone, Anyone near you or Whoever hurts you (a mark still is)
            local spare = Controls.pillButton(row, friend and "Spared" or "Spare", nil, function()
              if not entry then return end
              local sparing = not B.Roster.isFriend(entry)
              B.Roster.setFriend(entry, sparing)
              if sparing then DH.mark(player, false) else DH.onTargets:fire() end
            end)
            spare.Name = "Spare"
            spare.AnchorPoint, spare.Position = Vector2.new(1, 0.5), UDim2.new(1, -96, 0.5, 0)
            rows[#rows + 1] = { frame = row, player = player, state = state }
          end
        end
        count.Text = others == 0 and "No one else is here" or (#rows == 0 and "No such name") or (marked .. " of " .. #rows .. " marked")
      end
      local waiting = false
      local function soon()
        if waiting then return end
        waiting = true
        task.delay(0.1, function()
          waiting = false
          if list.Parent then rebuild() end
        end)
      end
      DH.onTargets:connect(soon)
      box:GetPropertyChangedSignal("Text"):Connect(soon)
      rebuild()
      Motion.every(function()
        if not (list.Parent and Window.anyOpen()) then return end
        for _, row in ipairs(rows) do
          local character = row.player.Character
          local humanoid = character and character:FindFirstChildOfClass("Humanoid")
          local word = WORDS[DH.stateOf(row.player)] or ""
          if humanoid and word == "up" then
            local effects = character:FindFirstChild("BodyEffects")
            local armor = effects and effects:FindFirstChild("Armor")
            local extra = armor and tonumber(armor.Value) or 0
            word = extra > 0 and string.format("%d hp +%d", math.floor(humanoid.Health + 0.5), extra) or string.format("%d hp", math.floor(humanoid.Health + 0.5))
          end
          row.state.Text = word
        end
      end, 4, "dahood.targets")
    end, unnamedTargets)
  end })
end

local function movementPage(hub)
  local function studs(v) return util.comma(v) .. " st" end
  hub:page({ id = "movement", title = "Maneuvers", icon = "ghost", build = function(page)
    local at = page:section({ title = "Position", icon = "orbit", desc = "Where you shoot from." })
    at:dropdown({ id = "dahood.hover", label = "Hover", desc = "Where you shoot from. Orbit to Wave are paths round them.",
      options = { { "above", "Above" }, { "around", "Around" }, { "circle", "Circle" }, { "behind", "Behind" }, { "random", "Random" }, { "swarm", "Swarm" },
        { "adaptive", "Adaptive" }, { "orbit", "Orbit" }, { "spiral", "Spiral" }, { "helix", "Helix" }, { "figure8", "Figure 8" }, { "wave", "Wave" } }, default = "above" })
    at:toggle({ id = "dahood.frenzy", label = "Frenzy", desc = "Hops between places of that shape and shakes in each. Uses at least 60 studs.", default = true })
    at:toggle({ id = "dahood.noclip", label = "Noclip", desc = "Your body passes through walls while it works.", default = true })
    at:toggle({ id = "dahood.bunker", label = "Bunker", desc = "Stands inside a wall or floor: their shots hit the wall.", default = true })
    at:slider({ id = "dahood.exposeMax", label = "Expose max", desc = "Then on to a new place. 0 is no limit.", min = 0, max = 1, step = 0.01, default = 0, suffix = " s" })
    at:note({ icon = "info", text = "Frenzy off: the knocking shot comes from straight above." })
    at:slider({ id = "dahood.radius", label = "Radius", desc = "For every place but Above. Kept inside your guns' reach.", min = 3, max = HOVER_MAX, step = 0.5, default = 6, suffix = " st" })
    at:toggle({ id = "dahood.jitter", label = "Jitter", desc = "Keeps moving while it is there.", default = true, children = function(sub)
      sub:dropdown({ id = "dahood.motion", label = "Motion", desc = "How it moves about its place.",
        options = { { "jitter", "Jitter" }, { "orbit", "Orbit" }, { "spiral", "Spiral" }, { "flicker", "Flicker" }, { "ball", "Ball" } }, default = "jitter" })
      sub:slider({ id = "dahood.motionSpeed", label = "Speed", desc = "Turns a second.", min = 0.5, max = 240, step = 0.5, default = 6, curve = 2.5, suffix = " /s" })
      sub:slider({ id = "dahood.motionSize", label = "Size", desc = "Up to 7 studs. More and shots stop counting.", min = 0.5, max = WOBBLE, step = 0.5, default = 4, suffix = " st" })
    end })
    at:toggle({ id = "dahood.spin", label = "Spin", desc = "Off: faces the target.", default = true, children = function(sub)
      sub:dropdown({ id = "dahood.facing", label = "Facing", options = { { "random", "Random" }, { "spin", "Spin" }, { "target", "Face target" } }, default = "random" })
      sub:slider({ id = "dahood.yawSpeed", label = "Yaw speed", min = 0, max = 60, step = 0.5, default = 3, curve = 2, suffix = " /s" })
      sub:slider({ id = "dahood.yawOffset", label = "Yaw offset", min = -180, max = 180, step = 5, default = 0, suffix = " deg" })
    end })

    local strafe = page:section({ title = "Strafe", icon = "orbit", desc = "For Orbit, Spiral, Helix, Figure 8 and Wave." })
    strafe:slider({ id = "dahood.strafeHeight", label = "Height", desc = "Over the target.", min = 0, max = 250, step = 1, default = 14, suffix = " st" })
    strafe:slider({ id = "dahood.strafeSpeed", label = "Speed", desc = "Turns a second. Held under 560 st/s so shots count.", min = 0.1, max = 30, step = 0.1, default = 1.2, curve = 2, suffix = " /s" })
    strafe:slider({ id = "dahood.strafeRandom", label = "Random", desc = "Turns back and swings out now and then: harder to predict.", min = 0, max = 1, step = 0.05, default = 0.35 })
    strafe:slider({ id = "dahood.strafeWave", label = "Wave", desc = "Wave only.", min = 0, max = 80, step = 1, default = 8, suffix = " st" })
    strafe:toggle({ id = "dahood.cycle", label = "Cycle", desc = "Changes Hover every few seconds.", default = false, children = function(sub)
      sub:slider({ id = "dahood.cycleEvery", label = "Every", min = 0.2, max = 30, step = 0.1, default = 3, suffix = " s" })
      sub:multi({ id = "dahood.cycleKinds", label = "Kinds", options = { { "above", "Above" }, { "around", "Around" }, { "circle", "Circle" }, { "behind", "Behind" },
        { "swarm", "Swarm" }, { "adaptive", "Adaptive" }, { "orbit", "Orbit" }, { "spiral", "Spiral" }, { "helix", "Helix" }, { "figure8", "Figure 8" }, { "wave", "Wave" } },
        default = { "swarm", "orbit", "above" }, empty = "None" })
    end })

    local between = page:section({ title = "Wait", icon = "wind", desc = "Where you wait between shots." })
    between:dropdown({ id = "dahood.wait", label = "Wait in", desc = "Where you are between strikes.",
      options = { { "void", "The void" }, { "cloud", "A cloud round the target" }, { "cyclone", "A cyclone round the target" } }, default = "void" })
    between:slider({ id = "dahood.cloud", label = "Cloud size", min = 40, max = 5000, step = 10, default = 150, curve = 3, suffix = " st" })

    local void = page:section({ title = "Void", icon = "cloud-fog", desc = "Far out and high up, where nobody can hit you." })
    void:toggle({ id = "dahood.hide", label = "Void", desc = "Sends you to the void. Off: back where you stood.", default = false })
    void:toggle({ id = "dahood.voidRoam", label = "Void roam", desc = "A new side of the map every frame, not one corner.", default = true })
    void:slider({ id = "dahood.voidFar", label = "Void far", desc = "Held at a billion studs.", min = 5000, max = VOID_MAX, step = 1000, default = 40000, curve = 6, valueWidth = 110, format = studs })
    void:slider({ id = "dahood.voidJitter", label = "Void jitter", desc = "It never stays on one spot there.", min = 500, max = 10000000, step = 500, default = 6000, curve = 4, valueWidth = 110, format = studs })
    void:slider({ id = "dahood.voidHigh", label = "Void high", min = VOID_FLOOR, max = 1000000, step = 500, default = VOID_FLOOR, curve = 3, valueWidth = 110, format = studs })
    void:note({ icon = "info", text = "Nobody can hit you there. Knocked, you cannot go anywhere." })

    local spy = page:section({ title = "Ghost", icon = "ghost", desc = "A copy of you that only you see, while your body is away." })
    spy:toggle({ id = "dahood.ghost", label = "Ghost", desc = "It walks, runs and jumps as you do.", default = true })
    spy:toggle({ id = "dahood.ghostMatch", label = "Walk like you", desc = "Your own speed, sprint and jumps. Off: the speed below.", default = true })
    spy:slider({ id = "dahood.ghostSpeed", label = "Speed", desc = "The game walks at 16 and sprints at 22.", min = 16, max = 400, step = 1, default = 24, curve = 2.5, suffix = " st/s" })
    spy:toggle({ id = "dahood.ghostFly", label = "Ghost fly", desc = "Space up, Left Ctrl down, through walls.", default = false })
    spy:slider({ id = "dahood.ghostAlpha", label = "See-through", desc = "0: it looks like you.", min = 0, max = 95, step = 5, default = 0, suffix = "%" })
    spy:segmented({ id = "dahood.ghostReturn", label = "Return to", options = { { "ghost", "Where you walked" }, { "home", "Where it stood" } }, default = "ghost",
      width = 230 })

    local spam = page:section({ title = "Void spam", icon = "zap", desc = "Flick between the void and where you stood." })
    spam:toggle({ id = "dahood.spam", label = "Void spam", desc = "Flicks between the void and where you stood.", default = false })
    spam:slider({ id = "dahood.spamAt", label = "Spam at", min = 0.02, max = 3, step = 0.01, default = 0.45, suffix = " s" })
    spam:slider({ id = "dahood.spamVoid", label = "Spam void", min = 0.02, max = 3, step = 0.01, default = 0.15, suffix = " s" })
    spam:note({ icon = "info", text = "A stay under 0.12 s is never seen by the server." })
    extend("movement", page)
  end })
end

local function loadoutPage(hub)
  hub:page({ id = "loadout", title = "Arsenal", icon = "package", build = function(page)
    local buying = page:section({ title = "Restock", icon = "gem", desc = "Buys what you run out of." })
    buying:toggle({ id = "dahood.autoGuns", label = "Auto guns", desc = "Whenever one is missing.", default = true })
    buying:toggle({ id = "dahood.autoAmmo", label = "Auto ammo", desc = "When a gun is under one magazine in reserve.", default = true })
    buying:slider({ id = "dahood.mags", label = "Mags", min = 1, max = 50, step = 1, default = 3 })
    buying:slider({ id = "dahood.reloadBelow", label = "Reload below", desc = "Reloads in the void below this. Never over a held shot.", min = 0, max = 100, step = 5, default = 100, suffix = "%" })
    buying:toggle({ id = "dahood.autoArmor", label = "Auto armor", desc = "High-Medium Armor (130).", default = true, children = function(sub)
      sub:slider({ id = "dahood.armorBelow", label = "Armor below", min = 10, max = 130, step = 5, default = 100 })
    end })

    local owned = page:section({ title = "In hand", icon = "box" })
    local line = owned:note({ icon = "info", text = "" })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      local DH = B.DaHood
      local parts = {}
      for _, gun in ipairs(GUNS) do
        if table.find(DH.options.guns, gun.name) then
          local tool = DH.tool(gun.name)
          local ammo, max = tool and tool:FindFirstChild("Ammo"), tool and tool:FindFirstChild("MaxAmmo")
          parts[#parts + 1] = gun.label .. ": " .. (tool and string.format("%s / %s, %d in reserve", ammo and tostring(ammo.Value) or "?", max and tostring(max.Value) or "?", DH.reserve(gun.name)) or "not owned")
        end
      end
      line.set((#parts > 0 and table.concat(parts, "\n") or "No gun chosen.") .. "\nCash: $" .. util.comma(DH.cash()))
    end, 2, "dahood.owned")
    extend("loadout", page)
  end })
end

local function playerPage(hub)
  hub:page({ id = "player", title = "Player", icon = "footprints", build = function(page)
    local DH = B.DaHood
    local about = page:section({ title = "Movement", icon = "zap", desc = "For your own body, while the ragebot is off." })
    about:toggle({ id = "dahood.speed", label = "Speed", desc = "Added to where you stand. Walk speed is left alone: the game hangs if it is raised.", default = false, children = function(sub)
      sub:slider({ id = "dahood.speedValue", label = "Speed value", desc = "The game gives 16 walking, 22 sprinting.", min = 20, max = 400, step = 1, default = 60, curve = 2, suffix = " st/s" })
      sub:toggle({ id = "dahood.speedWalls", label = "Speed walls", desc = "Off: goes through them.", default = true })
    end })
    about:toggle({ id = "dahood.jump", label = "Jump", desc = "The game gives 50. Not while the game says no jumping.", default = false, children = function(sub)
      sub:slider({ id = "dahood.jumpValue", label = "Jump power", desc = "The game caps upward speed at 80 with its Anti-fling on.", min = 50, max = 250, step = 1, default = 75 })
    end })
    about:toggle({ id = "dahood.airJump", label = "Air jump", desc = "Space jumps again in the air.", default = false })
    about:toggle({ id = "dahood.back", label = "Respawn back", desc = "Your next body is put where the last one went down.", default = false })

    page:custom(nil, function(frame)
      local card = UI.surface(frame, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.stroke(card, "ink", "strokeA")
      local stack = UI.frame(card, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(stack, "y", 0)
      local top = UI.frame(stack, { Name = "Top", Size = UDim2.new(1, 0, 0, 52), LayoutOrder = 0 })
      local count = UI.text(top, "Players", "heading", "ink", { Position = UDim2.new(0, 16, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5) })
      local own = Controls.pillButton(top, "Back to yourself", nil, function() DH.watch(nil) end)
      own.Name = "Own"
      own.AnchorPoint, own.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
      local list = UI.frame(stack, { Name = "List", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, LayoutOrder = 1 })
      UI.list(list, "y", 0)
      UI.pad(list, 0, 0, 6, 0)
      local rows = {}
      local function rebuild()
        for _, row in ipairs(rows) do row.frame:Destroy() end
        table.clear(rows)
        local players = S.Players:GetPlayers()
        table.sort(players, function(a, b) return string.lower(a.Name) < string.lower(b.Name) end)
        local watched = DH.watching()
        for index, player in ipairs(players) do
          if player ~= B.LP then
            local row = UI.frame(list, { Name = player.Name, Size = UDim2.new(1, 0, 0, 46), LayoutOrder = index })
            UI.frame(row, { Size = UDim2.new(1, -28, 0, 1), Position = UDim2.fromOffset(14, 0), Theme = { BackgroundColor3 = "ink", BackgroundTransparency = "strokeA" } })
            local face = UI.new("ImageLabel", { Size = UDim2.fromOffset(30, 30), Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 0.9,
              Theme = { BackgroundColor3 = "ink" }, Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150", Parent = row })
            UI.corner(face, true)
            UI.text(row, player.DisplayName, "label", "ink", { Position = UDim2.fromOffset(56, 6), Size = UDim2.new(1, -396, 0, 18), AutomaticSize = Enum.AutomaticSize.None,
              TextTruncate = Enum.TextTruncate.AtEnd })
            UI.text(row, "@" .. player.Name, "caption", "faint", { Position = UDim2.fromOffset(56, 24), Size = UDim2.new(1, -396, 0, 16), AutomaticSize = Enum.AutomaticSize.None,
              TextTruncate = Enum.TextTruncate.AtEnd, TextSize = 11.5 })
            local away = UI.text(row, "", "mono", "sub", { Name = "Away", AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, -244, 0.5, 0) })
            local view = Controls.pillButton(row, watched == player and "Viewing" or "View", watched == player and "primary" or nil, function() DH.watch(player) end)
            view.Name = "Watch"
            view.AnchorPoint, view.Position = Vector2.new(1, 0.5), UDim2.new(1, -140, 0.5, 0)
            -- Bring: knocked, picked up and carried back to where you stand (already down: straight to the pick-up)
            local bring = Controls.pillButton(row, "Bring", nil, function()
              local ok, why = DH.runJob("bring", player)
              Window.toast(ok and { title = "Bringing " .. player.DisplayName, icon = "hand", time = 2 }
                or { title = "Not brought", text = why, icon = "triangle-alert", tone = "warn" })
            end)
            bring.Name = "Bring"
            bring.AnchorPoint, bring.Position = Vector2.new(1, 0.5), UDim2.new(1, -72, 0.5, 0)
            local go = Controls.pillButton(row, "Go", nil, function()
              local ok, why = DH.goTo(player)
              if not ok then Window.toast({ title = "Not moved", text = why, icon = "triangle-alert", tone = "warn" }) end
            end)
            go.Name = "GoTo"
            go.AnchorPoint, go.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
            rows[#rows + 1] = { frame = row, player = player, away = away }
          end
        end
        count.Text = #rows == 0 and "No one else is here" or (watched and ("Viewing " .. watched.DisplayName) or "Players")
        own.Visible = watched ~= nil
      end
      local waiting = false
      local function soon()
        if waiting then return end
        waiting = true
        task.delay(0.1, function()
          waiting = false
          if list.Parent then rebuild() end
        end)
      end
      DH.onTargets:connect(soon)
      DH.onWatch:connect(soon)
      rebuild()
      Motion.every(function()
        if not (list.Parent and Window.anyOpen()) then return end
        local mine = B.root()
        for _, row in ipairs(rows) do
          local character = row.player.Character
          local theirs = character and character:FindFirstChild("HumanoidRootPart")
          row.away.Text = (mine and theirs) and (util.comma(math.floor((theirs.Position - mine.Position).Magnitude + 0.5)) .. " st") or ""
        end
      end, 4, "dahood.players")
    end, unnamedPlayers)

    extend("player", page)

    local places = page:section({ title = "Teleports", icon = "map-pin", desc = "Shop pads, by what they sell." })
    local kinds = {}
    for _, item in ipairs(DH.places()) do kinds[#kinds + 1] = { item, item } end
    if #kinds == 0 then kinds[1] = { "", "The shop has not loaded" } end
    -- (a pad chosen before that this map does not have is not kept)
    local chosen = Config.get("dahood.place")
    local known = false
    for _, kind in ipairs(kinds) do known = known or kind[1] == chosen end
    if not known then Config.set("dahood.place", kinds[1][1], true) end
    places:dropdown({ id = "dahood.place", label = "Shop pad", options = kinds, default = "" })
    places:button({ id = "dahood.placeGo", label = "Teleport", text = "Go", run = function()
      local ok, why = DH.goToPlace(Config.get("dahood.place"))
      if not ok then Window.toast({ title = "Not moved", text = why, icon = "triangle-alert", tone = "warn" }) end
    end })

    local stay = page:section({ title = "Stay online", icon = "shield-check" })
    stay:toggle({ id = "world.antiAfk", label = "Anti-AFK", desc = "Stops the 20 minute idle kick. On by default.", bindable = false })
    local line = stay:note({ icon = "activity", text = "" })
    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      local afk = B.World and B.World.afk
      if not afk then return end
      if not Config.get("world.antiAfk") then
        line.set("Off: left alone for twenty minutes, you will be dropped.")
      elseif afk.answered == 0 then
        line.set("On. Nothing to answer yet: you have not been idle.")
      else
        local gone = os.clock() - afk.last
        line.set(string.format("On. Answered %d time%s, the last %s ago.", afk.answered, afk.answered == 1 and "" or "s", gone < 90 and (math.floor(gone) .. " s") or (math.floor(gone / 60) .. " min")))
      end
    end, 1, "dahood.afk")
  end })
end

