do -- dahood_bounty.lua
-- ============================================================================
--  Da Hood     the bounty hunter: someone has a price on their head, it goes
--              and collects it
--
--  Read from the game (version 3275): a bounty is set at one of the posters
--  (workspace.MAP.BountyPosters, a prompt on each) through
--  Remotes.SetBounty(name, amount), $100k to $8m ("Amount is out of range
--  bounds [100k - 8m]", answered live). Every poster shows it: Texts.PlayerName
--  and Texts.Bounty, each a SurfaceGui label. The server also tells everyone of
--  one of a million or more (MainEvent "HighBounty", player, amount).
--
--  A bounty found is a "kill" job for the ragebot engine: knocked and stomped
--  whatever Stomp is set to, then back where the body stood.
-- ============================================================================
local B = B or ...
local S, Config, Window = B.S, B.Config, B.Window
local DH = B.DaHood

local bounty = { seen = {}, hunted = 0, claimed = 0, last = nil }
DH.bounty = bounty

-- "$1,250,000", "1.25M", "250K" -> a number
local function amountOf(text)
  text = string.upper(tostring(text or ""))
  local digits = string.gsub(text, "[^%d%.KMB]", "")
  local number, unit = string.match(digits, "([%d%.]+)([KMB]?)")
  number = tonumber(number)
  if not number then return 0 end
  if unit == "K" then number *= 1e3 elseif unit == "M" then number *= 1e6 elseif unit == "B" then number *= 1e9
  elseif not string.find(text, "%.", 1, true) then number = tonumber((string.gsub(text, "[^%d]", ""))) or number end
  return number
end
-- the player a poster names: "@name", a display name, or the name itself
local function playerOf(text)
  text = string.lower((string.gsub(tostring(text or ""), "^%s*@", "")))
  text = string.gsub(text, "%s+$", "")
  if text == "" then return nil end
  for _, player in ipairs(S.Players:GetPlayers()) do
    if string.lower(player.Name) == text then return player end
  end
  for _, player in ipairs(S.Players:GetPlayers()) do
    if string.lower(player.DisplayName) == text then return player end
  end
  return nil
end
bounty.amountOf, bounty.playerOf = amountOf, playerOf

local function start()
  local LP = B.LP
  local O
  local map = {}
  for id, default in pairs({ bounty = false, bountyMin = 100000, bountyFriends = false, bountyBusy = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  bounty.options = O

  local announced = {}             -- player -> amount, from the server's own notice
  local function read()
    local found = {}
    local map = workspace:FindFirstChild("MAP")
    local posters = map and map:FindFirstChild("BountyPosters")
    for _, poster in ipairs(posters and posters:GetChildren() or {}) do
      local texts = poster:FindFirstChild("Texts")
      local nameLabel = texts and texts:FindFirstChild("PlayerName") and texts.PlayerName:FindFirstChildWhichIsA("SurfaceGui", true)
      local amountLabel = texts and texts:FindFirstChild("Bounty") and texts.Bounty:FindFirstChildWhichIsA("SurfaceGui", true)
      nameLabel = nameLabel and nameLabel:FindFirstChildWhichIsA("TextLabel")
      amountLabel = amountLabel and amountLabel:FindFirstChildWhichIsA("TextLabel")
      local player = nameLabel and playerOf(nameLabel.Text)
      if player then
        local amount = amountOf(amountLabel and amountLabel.Text)
        if not found[player] or amount > found[player] then found[player] = amount end
      end
    end
    for player, amount in pairs(announced) do
      if player.Parent and not found[player] then found[player] = amount end
    end
    return found
  end
  bounty.read = read
  local remote = DH.api.mainEvent()
  if remote then
    B.connect(remote.OnClientEvent, function(kind, who, amount)
      if kind == "HighBounty" and typeof(who) == "Instance" and who:IsA("Player") then announced[who] = tonumber(amount) or 0 end
    end, "dahood.bounty.notice")
  end
  local function friend(player)
    local roster = B.Roster
    local entry = roster and roster.byPlayer and roster.byPlayer[player]
    return entry ~= nil and roster.isFriend(entry)
  end
  local function step()
    local found = read()
    bounty.seen = found
    -- (a bounty that is gone from the posters was collected, by us or someone else)
    for player in pairs(announced) do
      if not player.Parent then announced[player] = nil end
    end
    if not O.bounty or DH.job then return end
    -- (with the ragebot running on its own targets, only if that is asked for)
    if DH.on and not O.bountyBusy then return end
    if DH.hiding or DH.farming or DH.errand then return end
    local best, most
    for player, amount in pairs(found) do
      if player ~= LP and amount >= O.bountyMin and (O.bountyFriends or not friend(player)) then
        local state = DH.stateOf(player)
        if (state == "up" or state == "down" or state == "shield") and (not most or amount > most) then best, most = player, amount end
      end
    end
    if best then
      local ok = DH.runJob("kill", best, { limit = 40 })
      if ok then
        bounty.hunted += 1
        bounty.last = string.format("%s ($%s)", best.Name, B.util.comma(math.floor(most)))
        Window.toast({ title = "Bounty: " .. best.DisplayName, text = "$" .. B.util.comma(math.floor(most)), icon = "crosshair", time = 3 })
      end
    end
  end
  DH.onJob:connect(function(job, over)
    if job == nil and over and over.kind == "kill" and over.why == "killed" then
      bounty.claimed += 1
      announced[over.player] = nil
    end
  end)
  B.Motion.every(step, 2, "dahood.bounty")
end

local function ragebot(page)
  local Motion = B.Motion
  local box = page:section({ title = "Bounty hunter", icon = "trophy", desc = "Someone gets a bounty: it goes, knocks, stomps and collects." })
  box:toggle({ id = "dahood.bounty", label = "Auto bounty", desc = "Hunts whoever is on the bounty posters.", default = false })
  box:slider({ id = "dahood.bountyMin", label = "At least", desc = "Only bounties this big.", min = 100000, max = 8000000, step = 50000, default = 100000, curve = 2, format = function(v) return "$" .. B.util.comma(v) end })
  box:toggle({ id = "dahood.bountyBusy", label = "Even while hunting", desc = "Leaves your marked targets for a bounty.", default = false })
  box:toggle({ id = "dahood.bountyFriends", label = "Friends too", desc = "Off: friends are never hunted for one.", default = false })
  local line = box:note({ icon = "info", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local b = DH.bounty
    local names = {}
    for player, amount in pairs(b.seen or {}) do names[#names + 1] = string.format("%s $%s", player.Name, B.util.comma(math.floor(amount))) end
    line.set((#names == 0 and "No bounties up." or ("Up now: " .. table.concat(names, ", ") .. "."))
      .. (b.hunted > 0 and string.format("  Hunted %d, collected %d.", b.hunted, b.claimed) or ""))
  end, 1, "dahood.bounty.line")
end

DH.parts[#DH.parts + 1] = { id = "bounty", start = start, ragebot = ragebot }
end
do -- dahood_cash.lua
-- ============================================================================
--  Da Hood     the cash round
--
--  Breaks the cashiers and picks up what falls out of them. Run by hand, or by
--  the ragebot itself in the time it has to spare: all of it when it cannot pay
--  for a gun, and otherwise the seconds before a dead target can be hurt again.
--
--  Measured on the live server (2026-10-12, version 3267, two accounts):
--    * workspace.Cashiers holds 29 "CA$HIER" with a Humanoid of 100 health. A
--      gun hurts one: a Rifle shot took 99, one Double-Barrel shell 115.5. The
--      shooter has to be in range (refused from 1,147 studs). The vaults are left
--      alone: eleven shells at one were all taken and did nothing.
--    * Fists do too: a light punch 6.3 to 8.1, a punch held 1.6 s 70 (held 1.2 s
--      it is a light one). About 5 s a cashier.
--    * A broken one drops four "MoneyDrop" parts in the same frame, 3.8 to 4.7
--      studs from it ($225 to $500 each). A click on one counts from 14 studs
--      (20 was refused), not for the first 0.05 s after arriving, and only one
--      pick-up is taken every 0.52 s: clicks every 0.1 s took the four at 0.07,
--      0.69, 1.21 and 1.73 s after the break.
--    * A cashier is whole again 240.0 s after it broke.
--  So a round of all of them is about 70 s for some $43,000, every four minutes.
--
--  Fists are what it uses unless guns are asked for. On 2026-10-13 the second
--  account was kicked by the game (its message: "Stop.", error 267) 17 s into a
--  round with a shotgun, about a cashier every two seconds. With its fists, a
--  cashier every eight or nine seconds, it had done eight minutes of rounds that
--  day and was not. Which of the two it was (the gun, or how fast) was not found
--  out: that would have taken more kicks.
-- ============================================================================
local B = B or ...
local S, util, Motion, Config, Window = B.S, B.util, B.Motion, B.Config, B.Window
local DH = B.DaHood

local REACH = 11             -- studs from a drop a click on it is made from: 14 was taken, 20 refused
local CLICK_EVERY = 0.06     -- s between clicks on a drop: one that is refused costs nothing
local PICK_GAP = 0.52        -- s between two pick-ups the server takes
local RESPAWN = 240          -- s until a broken cashier is whole again
local STAND = 6              -- studs from a cashier it is shot from: its drops fall 3.8 to 4.7 studs from it
local FIST = 3.4             -- and punched from (3.6 was taken)
local CHARGE = 1.65          -- s a punch is held to be the heavy one
local RETRY = 0.07           -- s between two tries of a shot, at the least
local SETTLE = 0.16          -- s after arriving until the server is taken to have the body there (less, if the ragebot has timed it as less)
local LEAST = 2.6            -- s one cashier takes with a gun at the most: with less to spare none is begun
local LEAST_FIST = 7         -- and with fists
local GIVE_UP = 60           -- s a cashier that could not be broken is left alone
local OTHER_SIDE = 3         -- s before another side of one is tried, after a stay that took nothing off it
local NO_USE = 2.6           -- s of punching that takes nothing off a cashier before the stay is given up
local SIDES = {}
for index = 0, 7 do
  local turn = index * math.pi / 4
  SIDES[#SIDES + 1] = Vector3.new(math.cos(turn), 0, math.sin(turn))
end

local farm = { LEAST = LEAST, earned = 0, broken = 0, picked = 0, status = nil, PICK_GAP = PICK_GAP, RESPAWN = RESPAWN }
DH.farm = farm

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  -- (kept for good: a table that forgets loses a cashier's time with nothing else holding it)
  local downAt = {}                                     -- per cashier: when it was seen broken
  local bad = {}                                        -- per cashier: until when it is left alone
  local skipped = {}                                    -- per drop: until when it is left alone
  local sides = {}                                      -- per cashier: the sides of it a stay took nothing from
  local worked = {}                                     -- per cashier: the side it was last broken from (it is the same one when it comes back)
  local noReload = {}                                   -- per gun: until when a reload that did nothing is not asked for again
  local shotAt = {}                                     -- per gun: when it last fired at a cashier
  local lastAt                                          -- where the last one worked on stands
  local began, beganCash                                -- when this run started, and with how much
  local params = RaycastParams.new()
  params.FilterType = Enum.RaycastFilterType.Exclude
  params.IgnoreWater = true

  local map = {}
  for id, default in pairs({ cash = false, cashAuto = true, cashGoal = 0, cashTool = "fists", cashLoose = true, cashAvoid = 40, cashWait = "void", cashGrab = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  -- never armed by a saved setting: it moves the character the moment it is on
  if Config.get("dahood.cash") then Config.set("dahood.cash", false) end
  O = Config.mirror(map)
  farm.options = O

  local function running() return B.alive and (DH.on or O.cash) end
  -- waits, and says whether the round is still meant to be going
  local function rest(seconds)
    local untilAt = os.clock() + seconds
    repeat task.wait() until os.clock() >= untilAt or not running()
    return running()
  end
  local function say(text)
    farm.status = text
    api.setStatus(text)
  end

  -- ---------------------------------------------------------------- what is on the map
  local function cashiers()
    local out = {}
    local folder = workspace:FindFirstChild("Cashiers")
    for _, model in ipairs(folder and folder:GetChildren() or {}) do
      if model.Name == "CA$HIER" then
        local humanoid, head = model:FindFirstChildOfClass("Humanoid"), model:FindFirstChild("Head")
        if humanoid and head and head:IsA("BasePart") then
          local whole = humanoid.Health > 0
          if whole then downAt[model] = nil elseif not downAt[model] then downAt[model] = os.clock() end
          out[#out + 1] = { model = model, humanoid = humanoid, head = head, whole = whole }
        end
      end
    end
    return out
  end
  -- a drop that is gone is forgotten (they come and go by the hundred)
  local function forget()
    for drop in pairs(skipped) do
      if not drop.Parent then skipped[drop] = nil end
    end
  end
  local function drops()
    forget()
    local ignored = workspace:FindFirstChild("Ignored")
    local folder = ignored and ignored:FindFirstChild("Drop")
    local out = {}
    for _, item in ipairs(folder and folder:GetChildren() or {}) do
      if item.Name == "MoneyDrop" and item:IsA("BasePart") and item:FindFirstChildOfClass("ClickDetector") then out[#out + 1] = item end
    end
    return out
  end
  -- is anyone else standing within `reach` of there? (someone knocked or dead is nobody)
  local function crowded(position, reach)
    if reach <= 0 then return false end
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player ~= LP then
        local state = DH.stateOf(player)
        local character = player.Character
        local root = character and character:FindFirstChild("HumanoidRootPart")
        if root and (state == "up" or state == "shield") and (root.Position - position).Magnitude <= reach then return true end
      end
    end
    return false
  end
  farm.cashiers, farm.drops, farm.crowded = cashiers, drops, crowded
  -- s until a broken one is whole again (at the most, for one that was broken before it was first seen)
  function farm.left(model, now)
    local at = downAt[model]
    return at and math.max(0, at + RESPAWN - (now or os.clock())) or nil
  end
  -- how many are whole, how many there are, and how long until the next one is
  function farm.count()
    local whole, soonest = 0, nil
    local list = cashiers()
    local now = os.clock()
    for _, cashier in ipairs(list) do
      if cashier.whole then whole += 1 else
        local left = math.max(0, (downAt[cashier.model] or now) + RESPAWN - now)
        if not soonest or left < soonest then soonest = left end
      end
    end
    return whole, #list, soonest
  end

  -- ---------------------------------------------------------------- what to break one with
  -- every gun that is on us with a round in it, the hardest shot first
  local function loaded(me)
    local out = {}
    if O.cashTool == "fists" then return out end
    for _, kind in ipairs(DH.GUNS) do
      local tool = api.myTool(kind.name)
      if tool and tool:FindFirstChild("Handle") and api.numberOf(tool, "Ammo", 0) > 0 then
        out[#out + 1] = { name = kind.name, tool = tool, hits = kind.hits or 1, cooldown = api.numberOf(tool, "ShootingCooldown", kind.cooldown),
          shot = api.numberOf(tool, "Damage", kind.damage) * (kind.hits or 1) }
      end
    end
    table.sort(out, function(a, b) return a.shot > b.shot end)
    local _ = me
    return out
  end
  local function fists() return (api.myTool("Combat")) end
  -- "gun", "fist" or nil
  local function weapon(me)
    if #loaded(me) > 0 then return "gun" end
    return fists() and "fist" or nil
  end
  farm.weapon = function() local me = B.character(); return me and weapon(me) or nil end

  -- Where to stand for a cashier: on a floor beside it with nothing between the body and its Head,
  -- the side nearest its own height first (its drops fall beside it, and have to be in reach).
  local function standFor(cashier, distance)
    local me = B.character()
    local centre = cashier.model:GetBoundingBox().Position
    local best
    local tried = sides[cashier.model]
    local known = worked[cashier.model]
    for index, side in ipairs(SIDES) do
      local at = centre + side * distance
      params.FilterDescendantsInstances = { me, cashier.model, api.folder }
      local floor = workspace:Raycast(at + Vector3.new(0, 3, 0), Vector3.new(0, -14, 0), params)
      if floor then
        local feet = Vector3.new(at.X, floor.Position.Y + 3, at.Z)
        local eye = feet + Vector3.new(0, 1.5, 0)
        params.FilterDescendantsInstances = { me, api.folder }
        local hit = workspace:Raycast(eye, cashier.head.Position - eye, params)
        if hit and hit.Instance:IsDescendantOf(cashier.model) and not (tried and tried[index]) then
          -- (the side it was broken from before, before any other)
          local score = math.abs(feet.Y - centre.Y) - (index == known and 1000 or 0)
          if not best or score < best.score then best = { at = feet, score = score, centre = centre, side = index } end
        end
      end
    end
    return best, centre
  end

  -- With a gun: the hardest loaded shot, sent again every RETRY until the round count answers,
  -- then the next gun (or the same one when its cooldown is over) until the cashier is broken.
  -- The first try goes out when the server is taken to have the body there, not before (sent on
  -- arriving and every 0.07 s after, the tries at 0, 0.07, 0.13 and 0.20 s were refused and the one
  -- at 0.24 taken). A try that is taken is answered a trip there and back later: the next waits
  -- for that, or a second shell goes into a cashier the first has already broken (a shotgun's
  -- second shot is held by the server and fired a cooldown later).
  local function shootDown(cashier, deadline)
    local me, pack = B.character(), LP:FindFirstChildOfClass("Backpack")
    local lastGun, lastFire, misses, useless = nil, -math.huge, 0, 0
    if not rest(math.min(DH.lag or SETTLE, SETTLE) + 0.02) then return false end
    while cashier.humanoid.Health > 0 and os.clock() < deadline and running() do
      local root = B.root()
      if not (root and me.Parent) then return false end
      local now = os.clock()
      local pick
      for _, gun in ipairs(loaded(me)) do
        local ready = (shotAt[gun.name] or -math.huge) + gun.cooldown + DH.rate.margin
        if lastGun and lastGun ~= gun.name then ready = math.max(ready, lastFire + DH.gap(lastGun, gun.name)) end
        if ready <= now then pick = gun; break end
      end
      if not pick then
        if #loaded(me) == 0 then return false end
        task.wait()
      else
        -- the first tool in the hand has to be a gun, or the server takes no shot at all
        if pack then
          for _, item in ipairs(me:GetChildren()) do
            if item:IsA("Tool") and not api.GUN[item.Name] then item.Parent = pack end
          end
        end
        if pick.tool.Parent ~= me then pick.tool.Parent = me end
        local before, was = api.numberOf(pick.tool, "Ammo", 0), cashier.humanoid.Health
        api.send(pick, root.Position + Vector3.new(0, 1.5, 0), cashier.head.Position, cashier.head)
        local sent = os.clock()
        local gap = math.max(RETRY, (DH.answer or (api.ping() * 2 + 0.05)) + 0.04)
        repeat task.wait() until api.numberOf(pick.tool, "Ammo", 0) < before or cashier.humanoid.Health <= 0 or os.clock() - sent >= gap
        if api.numberOf(pick.tool, "Ammo", 0) < before then
          local at = os.clock()
          shotAt[pick.name], lastGun, lastFire, misses = at, pick.name, at, 0
          -- (on the ragebot's own books too: it plans its next strike by when each gun last fired)
          api.fired[pick.name] = { at = at, shots = 1, step = pick.cooldown + DH.rate.margin }
          api.estimate[pick.name] = nil
          -- A shot the server took shows on the cashier with it. Two that took nothing off it:
          -- something is in the way, and every one more is a round thrown away.
          local seen = os.clock()
          while cashier.humanoid.Health >= was - 0.5 and os.clock() - seen < 0.25 and running() do task.wait() end
          if cashier.humanoid.Health >= was - 0.5 then
            useless += 1
            if useless >= 2 then return false end
          end
        else
          misses += 1
          if misses > 14 then return false end
        end
      end
    end
    return cashier.humanoid.Health <= 0
  end
  -- Nothing loaded, and a gun with rounds in reserve: it is reloaded. Only on its own: with the
  -- ragebot on the ragebot reloads, in the void and never over a shot the server is holding.
  local function reload(me)
    if O.cashTool == "fists" or #loaded(me) > 0 then return false end
    local remote, pack = api.mainEvent(), LP:FindFirstChildOfClass("Backpack")
    if not remote then return false end
    local now = os.clock()
    local pick, hardest
    for _, kind in ipairs(DH.GUNS) do
      local tool = api.myTool(kind.name)
      if tool and tool:FindFirstChild("Handle") and api.numberOf(tool, "MaxAmmo", 0) > 0 and api.reserve(kind.name) > 0 and not (noReload[kind.name] and noReload[kind.name] > now) then
        local shot = api.numberOf(tool, "Damage", kind.damage) * (kind.hits or 1)
        if not hardest or shot > hardest then pick, hardest = tool, shot end
      end
    end
    if not pick then return false end
    say("cash: reloading")
    -- (it is reloaded in the hand, and a gun has to be the first thing there)
    if pack then
      for _, item in ipairs(me:GetChildren()) do
        if item:IsA("Tool") and not api.GUN[item.Name] then item.Parent = pack end
      end
    end
    if pick.Parent ~= me then pick.Parent = me end
    local before, began, seen = api.numberOf(pick, "Ammo", 0), os.clock(), false
    remote:FireServer("Reload", pick)
    while os.clock() - began < 5 and running() do
      task.wait()
      local busy = api.flagOf(api.effectsOf(B.character()), "Reload")
      seen = seen or busy
      if not busy and (api.numberOf(pick, "Ammo", 0) > before or (not seen and os.clock() - began > 0.7)) then break end
    end
    if api.numberOf(pick, "Ammo", 0) <= before then noReload[pick.Name] = os.clock() + 20 end
    api.estimate[pick.Name] = nil
    farm.reloads = (farm.reloads or 0) + 1
    return true
  end
  -- With fists: one heavy punch, then light ones as fast as they go.
  local function punchDown(cashier, deadline)
    local me, humanoid = B.character(), B.humanoid()
    local combat = fists()
    if not (me and humanoid and combat) then return false end
    local effects = api.effectsOf(me)
    humanoid:EquipTool(combat)
    if not rest(0.35) then return false end
    if cashier.humanoid.Health > 30 then
      combat:Activate()
      local ok = rest(CHARGE)
      combat:Deactivate()
      if not (ok and rest(0.45)) then return false end
    end
    -- (a punch that lands shows on the cashier at once: NO_USE of punching with nothing to show is given up)
    local least, since = cashier.humanoid.Health, os.clock()
    while cashier.humanoid.Health > 0 and os.clock() < deadline and running() do
      if cashier.humanoid.Health < least - 0.5 then least, since = cashier.humanoid.Health, os.clock() end
      if os.clock() - since > NO_USE then break end
      if not api.flagOf(effects, "Attacking") then
        combat:Activate()
        task.wait(0.03)
        combat:Deactivate()
      end
      task.wait()
    end
    humanoid:UnequipTools()
    return cashier.humanoid.Health <= 0
  end

  -- Every drop within `radius` of `around`, the nearest to the body first: a click every
  -- CLICK_EVERY until it is gone (the server takes one pick-up in half a second).
  local function collect(around, radius, deadline)
    local took = 0
    while os.clock() < deadline and running() do
      local root = B.root()
      if not root then break end
      local now = os.clock()
      local best, bestAway
      for _, drop in ipairs(drops()) do
        if (drop.Position - around).Magnitude <= radius and not (skipped[drop] and skipped[drop] > now) then
          local away = (drop.Position - root.Position).Magnitude
          if not bestAway or away < bestAway then best, bestAway = drop, away end
        end
      end
      if not best then break end
      if bestAway > REACH then
        -- over it: a move of a few studs is the same place to the server
        api.pin("spot", best.Position + Vector3.new(0, 3.2, 0))
        if bestAway > REACH + 9 and not rest(math.max(api.lag(), 0.16)) then break end
      end
      local detector = best:FindFirstChildOfClass("ClickDetector")
      local tried = os.clock()
      while best.Parent and detector and os.clock() < deadline and os.clock() - tried < 2.2 and running() do
        fireclickdetector(detector)
        if not rest(CLICK_EVERY) then break end
      end
      if best.Parent then skipped[best] = os.clock() + 20 else
        took += 1
        farm.picked += 1
      end
    end
    return took
  end
  farm.collect = collect

  -- the nearest whole cashier nobody is standing at
  local function nextCashier(from)
    local now = os.clock()
    local best, bestAway
    for _, cashier in ipairs(cashiers()) do
      if cashier.whole and not (bad[cashier.model] and bad[cashier.model] > now) and not crowded(cashier.head.Position, O.cashAvoid) then
        local away = (cashier.head.Position - from).Magnitude
        if not bestAway or away < bestAway then best, bestAway = cashier, away end
      end
    end
    return best
  end
  -- loose cash that nobody is standing at, the nearest first
  local function strayDrop(from)
    local now = os.clock()
    local best, bestAway
    for _, drop in ipairs(drops()) do
      if not (skipped[drop] and skipped[drop] > now) and not crowded(drop.Position, O.cashAvoid) then
        local away = (drop.Position - from).Magnitude
        if not bestAway or away < bestAway then best, bestAway = drop, away end
      end
    end
    return best
  end

  function farm.wanted()
    if type(fireclickdetector) ~= "function" then return false end
    return O.cash or (O.cashAuto and DH.broke ~= nil)
  end
  -- One cashier, or one lot of loose cash, inside `spare` seconds. True when something was done.
  function farm.visit(spare)
    local me, root = B.character(), B.root()
    if not (me and root) then return false end
    local from = lastAt or (api.home() and api.home().Position) or root.Position
    local kind = weapon(me)
    local need = kind == "gun" and LEAST or LEAST_FIST
    local cashier = kind and spare >= need and nextCashier(from) or nil
    local before = api.cash()
    local started = os.clock()
    if cashier then
      local stand, centre = standFor(cashier, kind == "gun" and STAND or FIST)
      if not stand then
        bad[cashier.model] = started + GIVE_UP
        return true
      end
      local deadline = started + math.min(spare, kind == "gun" and 6 or 12) - 0.25
      local healthWas = cashier.humanoid.Health
      say("cash: breaking a cashier" .. (kind == "fist" and " (fists)" or ""))
      lastAt = centre
      api.focus.CFrame = CFrame.new(centre)
      api.pin("spot", stand.at, Vector3.new(centre.X, stand.at.Y, centre.Z))
      local broke
      if kind == "gun" then broke = shootDown(cashier, deadline) else
        broke = rest(math.max(api.lag(), 0.2)) and punchDown(cashier, deadline)
      end
      if broke then
        farm.broken += 1
        downAt[cashier.model] = os.clock()
        say("cash: picking up")
        -- (what falls out is on this client a frame or two after the cashier is seen to break:
        -- seen live, the first one of a round was left with all four lying there)
        local seen = os.clock()
        local function fallen()
          for _, drop in ipairs(drops()) do
            if (drop.Position - centre).Magnitude <= 16 then return true end
          end
          return false
        end
        while not fallen() and os.clock() - seen < 0.6 and running() do task.wait() end
        sides[cashier.model] = nil
        worked[cashier.model] = stand.side
        collect(centre, 16, math.max(deadline, os.clock() + math.min(2.4, math.max(spare - (os.clock() - started) - 0.2, 0))))
      elseif cashier.humanoid.Health > 0 and running() and cashier.humanoid.Health >= healthWas - 0.5 then
        -- Nothing taken off it in the whole stay: that side of it is no good (seen live: fists at
        -- one cashier for two minutes and more with not a point off it). Another side next time;
        -- and when no side is left, it is left alone for as long as a broken one takes to come back.
        local tried = sides[cashier.model]
        if not tried then tried = {}; sides[cashier.model] = tried end
        tried[stand.side] = true
        local left = 0
        for index = 1, #SIDES do
          if not tried[index] then left += 1 end
        end
        bad[cashier.model] = os.clock() + (left > 0 and OTHER_SIDE or RESPAWN)
        if left == 0 then sides[cashier.model] = nil end
        farm.gaveUp = (farm.gaveUp or 0) + 1
      elseif cashier.humanoid.Health > 0 and os.clock() >= deadline - 0.05 and kind == "gun" then
        bad[cashier.model] = os.clock() + GIVE_UP        -- shot at for the whole stay and still standing: something is in the way
      end
    elseif O.cashLoose and spare >= 1.2 then
      local drop = strayDrop(from)
      if not drop then return false end
      say("cash: picking up loose cash")
      lastAt = drop.Position
      api.focus.CFrame = CFrame.new(drop.Position)
      api.pin("spot", drop.Position + Vector3.new(0, 3.2, 0))
      if rest(math.max(api.lag(), 0.16)) then collect(drop.Position, 14, started + math.min(spare, 6) - 0.2) end
    else
      return false
    end
    farm.earned += math.max(0, api.cash() - before)
    if DH.on then api.pin("void") end
    return true
  end

  -- On its own (the ragebot off): cashier after cashier, and somewhere out of the way in between.
  function farm.step()
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    local effects = api.effectsOf(me)
    if not (me and root and humanoid and effects) or humanoid.Health <= 0 or api.flagOf(effects, "Dead") or not me:FindFirstChild("FULLY_LOADED_CHAR") then
      api.pin(nil)
      say("cash: respawning")
      return
    end
    if api.flagOf(effects, "K.O") then
      api.pin(nil)
      say("cash: knocked")
      return
    end
    if DH.steady then DH.steady(humanoid) elseif humanoid:GetStateEnabled(Enum.HumanoidStateType.Seated) then humanoid:SetStateEnabled(Enum.HumanoidStateType.Seated, false) end
    if O.cashGoal > 0 and api.cash() >= O.cashGoal then
      Window.toast({ title = "Cash round done", text = "$" .. util.comma(api.cash()) .. " in hand.", icon = "gem", tone = "ok" })
      Config.set("dahood.cash", false)
      return
    end
    local home = api.home()
    -- (a reload takes a second or two: out of the way for it)
    if #loaded(me) == 0 and O.cashTool ~= "fists" then
      local dry = false
      for _, kind in ipairs(DH.GUNS) do
        local tool = api.myTool(kind.name)
        if tool and api.reserve(kind.name) > 0 and not (noReload[kind.name] and noReload[kind.name] > os.clock()) then dry = true end
      end
      if dry then
        if O.cashWait == "void" or not home then api.pin("void") else api.pin("spot", home.Position) end
        if reload(me) then return end
      end
    end
    if farm.visit(30) then return end
    local whole, total, soonest = farm.count()
    if O.cashWait == "void" or not home then api.pin("void") else api.pin("spot", home.Position) end
    if not weapon(me) then say("cash: no loaded gun and no fists")
    elseif whole > 0 then say("cash: " .. whole .. " of " .. total .. " up, someone is at each")
    else say(string.format("cash: next cashier in %d s", math.ceil(soonest or RESPAWN))) end
  end

  local function switch(on)
    if on then
      if not (api.mainEvent() and api.arm()) then
        Window.toast({ title = "The cash round needs a spawned character", icon = "triangle-alert", tone = "warn" })
        task.defer(function() Config.set("dahood.cash", false) end)
        return
      end
      began, beganCash = os.clock(), api.cash()
      farm.began = began
      lastAt = nil
      DH.farming = true
      api.camera()
    elseif DH.farming then
      DH.farming = false
      farm.status = nil
      local humanoid = B.humanoid()
      if humanoid then pcall(function() humanoid:UnequipTools() end) end
      if not DH.on and not DH.hiding then
        api.pin(nil)
        api.release()
      end
    end
  end
  Config.on("dahood.cash", switch)
  B.onUnload:connect(function() DH.farming = false end)
  local _ = beganCash

  -- Cash near the player's own feet, while nothing here is moving the body: one drop in reach is
  -- clicked every CLICK_EVERY (the server takes one in half a second anyway).
  task.spawn(function()
    while B.alive do
      if O.cashGrab and not api.moving() and type(fireclickdetector) == "function" then
        local root = B.root()
        if root then
          local best, bestAway
          for _, drop in ipairs(drops()) do
            local away = (drop.Position - root.Position).Magnitude
            if away <= REACH and (not bestAway or away < bestAway) then best, bestAway = drop, away end
          end
          local detector = best and best:FindFirstChildOfClass("ClickDetector")
          if detector then
            local before = api.cash()
            B.try("dahood.grab", fireclickdetector, detector)
            task.wait(CLICK_EVERY)
            if api.cash() > before then
              farm.earned += api.cash() - before
              farm.picked += 1
            end
          end
        end
      end
      task.wait(O.cashGrab and CLICK_EVERY or 0.5)
    end
  end)
end

local function page(hub)
  hub:page({ id = "cash", title = "Cash", icon = "gem", build = function(page)
    local round = page:section({ title = "Cash farm", icon = "gem", desc = "Breaks cashiers and picks up what falls." })
    round:toggle({ id = "dahood.cash", label = "Cash farm", desc = "With the ragebot on, it goes between kills. Never on at launch." })
    round:toggle({ id = "dahood.cashAuto", label = "Auto farm", desc = "The ragebot does a round by itself when it cannot pay.", default = true })
    round:slider({ id = "dahood.cashGoal", label = "Goal", desc = "The farm stops at this much cash.", min = 0, max = 2000000, step = 5000, default = 0, curve = 2.4, valueWidth = 96,
      format = function(v) return v <= 0 and "Never" or ("$" .. util.comma(v)) end })
    local line = round:note({ icon = "activity", text = "" })

    local how = page:section({ title = "Farm", icon = "wrench" })
    how:segmented({ id = "dahood.cashTool", label = "Tool", desc = "Guns are faster. A test account was kicked 17 s into a round with one.", options = { { "fists", "Fists" }, { "auto", "Guns" } }, default = "fists", width = 150 })
    how:toggle({ id = "dahood.cashLoose", label = "Loose cash", desc = "Picks up cash lying about the map.", default = true })
    how:slider({ id = "dahood.cashAvoid", label = "Avoid range", desc = "Skips a cashier with someone this near. 0: never.", min = 0, max = 300, step = 5, default = 40, suffix = " st" })
    how:segmented({ id = "dahood.cashWait", label = "Wait in", desc = "While every cashier is broken.", options = { { "void", "The void" }, { "home", "Home" } }, default = "void", width = 150 })
    how:note({ icon = "info", text = "Fists: about 8 s a cashier. Each comes back after 4 minutes." })

    local own = page:section({ title = "On foot", icon = "footprints" })
    own:toggle({ id = "dahood.cashGrab", label = "Cash grab", desc = "Picks up any cash within reach as you walk.", default = false })

    Motion.every(function()
      if not (line.frame.Parent and Window.anyOpen()) then return end
      local farm = B.DaHood.farm
      local whole, total, soonest = farm.count()
      local text = string.format("Cash $%s    earned $%s    %d broken    %d picked up", util.comma(B.DaHood.cash()), util.comma(farm.earned), farm.broken, farm.picked)
      if farm.began and farm.earned > 0 and B.DaHood.farming then
        local hours = math.max(os.clock() - farm.began, 1) / 3600
        text = text .. string.format("    $%s an hour", util.comma(farm.earned / hours))
      end
      text = text .. string.format("\nCashiers up: %d of %d%s", whole, total, (soonest and whole < total) and string.format(", the next in %d s", math.ceil(soonest)) or "")
      if B.DaHood.broke then text = text .. "\nShort of $" .. util.comma(B.DaHood.broke) .. " for what the ragebot needs." end
      line.set(text)
    end, 2, "dahood.cash")
  end })
end

DH.parts[#DH.parts + 1] = { id = "cash", start = start, page = page }
end
do -- dahood_combat.lua
-- ============================================================================
--  Da Hood     Combat: your own shooting, made better
--
--  Aimbot, silent aim, a FOV ring, a shot from far (the bot hops in range for
--  it), rapid fire, kill aura, target strafe, a cursor of its own, anti slow,
--  no jump cooldown, rocket and grenade dodge, no recoil, a longer zoom.
--
--  How the shooting works here (read from the game, version 3275, and checked
--  live): every gun asks ReplicatedStorage.Modules.GunHandler where it is
--  aimed (getAim) at the moment it fires, and `require` from here gives the
--  very same table the game uses (one in memory). So silent aim is that one
--  function answering with a direction to the target: the gun's own script
--  then shoots, with its own spread, sound and effects, and sends what the
--  server expects. One Double-Barrel shell through it: getAim 10 times,
--  shoot 5 (a pellet each), 1 shell spent.
--  A rocket is a Model in workspace.Ignored holding a MeshPart "Launcher",
--  about 60 studs a second; a thrown grenade a Part "Handle" there, gone
--  2.2 s later; both leave an "explosion" part where they burst.
--  Recoil is the server's "ShootingRecoil", which turns the camera a little.
--  Not working any more (measured with two accounts): NetworkIsSleeping
--  "desync" (the other screen saw every stud walked) and velocity spoofing
--  (half a second of jitter, then the true path).
-- ============================================================================
local B = B or ...
local S, Config, Window, UI, Motion, util = B.S, B.Config, B.Window, B.UI, B.Motion, B.util
local DH = B.DaHood

local combat = { target = nil, point = nil, shots = 0, dodges = 0, auraShots = 0 }
DH.combat = combat

local PARTS = { torso = { "UpperTorso", "Torso" }, head = { "Head" }, root = { "HumanoidRootPart" } }

local function start()
  local api = DH.api
  local LP = B.LP
  local UIS, RS = S.UserInputService, S.RunService
  local O
  local map = {}
  for id, default in pairs({
    aimbot = false, aimSmooth = 35, aimPart = "torso", aimPredict = true, aimFov = 180, aimVisible = true, aimKnocked = true, aimFriends = true,
    silent = false, silentChance = 100, fovShow = true, fovFollow = "mouse", fovColor = Color3.fromRGB(255, 255, 255), fovFill = 96,
    bulletTp = false, bulletKill = false, rapid = false, aura = false, auraRange = 60, strafe = false, strafeRadius = 12, strafeHeight = 4,
    strafeSpeed = 6, cursor = false, cursorSize = 18, cursorSpin = 90, cursorPulse = true, cursorColor = Color3.fromRGB(255, 255, 255),
    cursorColor2 = Color3.fromRGB(120, 170, 255), targetMark = true, antiSlow = false, noJumpCd = false, dodge = false, dodgeRange = 28,
    noRecoil = false, camZoom = false, camZoomMax = 400,
  }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  combat.options = O

  local function friend(player)
    local roster = B.Roster
    local entry = roster and roster.byPlayer and roster.byPlayer[player]
    return entry ~= nil and roster.isFriend(entry)
  end
  local function partOf(character, kind)
    for _, name in ipairs(PARTS[kind] or PARTS.torso) do
      local part = character:FindFirstChild(name)
      if part and part:IsA("BasePart") then return part end
    end
    return character:FindFirstChild("HumanoidRootPart")
  end
  local sight = RaycastParams.new()
  sight.FilterType = Enum.RaycastFilterType.Exclude
  sight.IgnoreWater = true
  local function visible(from, part, character)
    local ignore = { B.character(), character }
    local ignored = workspace:FindFirstChild("Ignored")
    if ignored then ignore[#ignore + 1] = ignored end
    sight.FilterDescendantsInstances = ignore
    local hit = workspace:Raycast(from, part.Position - from, sight)
    return hit == nil
  end
  -- where to aim at a body: its part, led by how it is moving (what is drawn of another player is old)
  local function aimPoint(character, part)
    local point = part.Position
    if O.aimPredict then
      local root = character:FindFirstChild("HumanoidRootPart")
      local velocity = root and root.AssemblyLinearVelocity or Vector3.new()
      if velocity.Magnitude < 400 then point += velocity * (DH.lead and DH.lead() or 0.12) end
    end
    return point
  end
  combat.aimPoint = aimPoint
  -- the FOV ring's middle: the pointer, or the middle of the screen
  local function centre()
    local view = workspace.CurrentCamera
    if O.fovFollow == "centre" and view then return view.ViewportSize / 2 end
    return UIS:GetMouseLocation()
  end
  -- the one to aim at: inside the ring, nearest its middle
  local function pick(range)
    local view = workspace.CurrentCamera
    if not view then return nil end
    local middle = centre()
    local camPos = view.CFrame.Position
    local best, bestOff, bestPart
    for _, player in ipairs(S.Players:GetPlayers()) do
      local character = player ~= LP and player.Character
      if character and character.Parent and not (O.aimFriends and friend(player)) then
        local state = DH.stateOf(player)
        if state == "up" or (state == "down" and not O.aimKnocked) then
          local part = partOf(character, O.aimPart)
          if part then
            local screen, on = view:WorldToViewportPoint(part.Position)
            -- (GetMouseLocation and WorldToViewportPoint share one space)
            local off = Vector2.new(screen.X, screen.Y) - middle
            if on and screen.Z > 0 and off.Magnitude <= (range or O.aimFov) and (not O.aimVisible or visible(camPos, part, character)) then
              if not bestOff or off.Magnitude < bestOff then best, bestOff, bestPart = player, off.Magnitude, part end
            end
          end
        end
      end
    end
    return best, bestPart
  end
  combat.pick = pick
  -- the nearest in the world within `range` studs with a clear line from this body (kill aura)
  local function nearest(range)
    local root = B.root()
    if not root then return nil end
    local best, bestAway, bestPart
    for _, player in ipairs(S.Players:GetPlayers()) do
      local character = player ~= LP and player.Character
      if character and character.Parent and not friend(player) and DH.stateOf(player) == "up" then
        local part = partOf(character, O.aimPart)
        local away = part and (part.Position - root.Position).Magnitude
        if away and away <= range and (not bestAway or away < bestAway) and visible(root.Position, part, character) then best, bestAway, bestPart = player, away, part end
      end
    end
    return best, bestPart
  end
  local function gunInHand()
    local me = B.character()
    if not me then return nil end
    for _, tool in ipairs(me:GetChildren()) do
      if tool:IsA("Tool") and api.GUN[tool.Name] and tool:FindFirstChild("Ammo") then return tool end
    end
    return nil
  end
  local function automatic(tool) return tool:FindFirstChild("GunClientAutomatic") ~= nil end
  local function playing() return not Window.anyOpen() and UIS:GetFocusedTextBox() == nil end

  -- ---------------------------------------------------------------- silent aim: the game's own aim, answered
  -- (looked for on a thread of its own: a game without it would hold every tab back while it waited)
  task.spawn(function()
    local handler
    pcall(function() handler = require(S.ReplicatedStorage:WaitForChild("Modules", 5):WaitForChild("GunHandler", 5)) end)
    B.identity()
    local original = handler and handler.getAim
    if type(original) == "function" and B.alive then
      local function ours(origin, range, ...)
        local point = combat.point
        if point and typeof(origin) == "Vector3" and (O.silent or combat.forced) then
          local off = point - origin
          if off.Magnitude > 0.05 then return off.Unit, off.Magnitude end
        end
        return original(origin, range, ...)
      end
      handler.getAim = ours
      B.onUnload:connect(function() if handler.getAim == ours then handler.getAim = original end end)
      combat.hooked = true
    end
  end)

  -- ---------------------------------------------------------------- on screen: the ring, the mark, the cursor
  local gui = B.screen(8650)
  local ring = UI.frame(gui, { Name = "Fov", AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, Visible = false })
  UI.corner(ring, true)
  local ringLine = Instance.new("UIStroke"); ringLine.Thickness = 1.5; ringLine.Parent = ring
  local dot = UI.frame(gui, { Name = "TargetDot", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(7, 7), BackgroundColor3 = Color3.fromRGB(255, 70, 70),
    BackgroundTransparency = 0, Visible = false })
  UI.corner(dot, true)
  local mark = Instance.new("Highlight")
  mark.FillTransparency, mark.OutlineTransparency = 0.75, 0
  mark.FillColor, mark.OutlineColor = Color3.fromRGB(255, 60, 60), Color3.fromRGB(255, 60, 60)
  mark.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
  mark.Enabled = false
  mark.Parent = gui
  -- the cursor: four arms and a dot, turning and breathing, in two colours
  local cursor = UI.frame(gui, { Name = "Cursor", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(40, 40), Visible = false })
  local arms = {}
  for index = 1, 4 do
    local arm = UI.frame(cursor, { Name = "Arm" .. index, AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 0, BackgroundColor3 = Color3.new(1, 1, 1) })
    local edge = Instance.new("UIStroke"); edge.Color = Color3.new(0, 0, 0); edge.Transparency = 0.35; edge.Parent = arm
    local shade = Instance.new("UIGradient"); shade.Parent = arm
    arms[index] = { frame = arm, shade = shade }
  end
  local core = UI.frame(cursor, { Name = "Dot", AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5), Size = UDim2.fromOffset(3, 3), BackgroundTransparency = 0 })
  UI.corner(core, true)
  local spin, cursorOn = 0, false
  local function showCursor(on)
    if on == cursorOn then return end
    cursorOn = on
    cursor.Visible = on
    UIS.MouseIconEnabled = not on
  end
  B.onUnload:connect(function() UIS.MouseIconEnabled = true end)

  -- ---------------------------------------------------------------- each frame
  local swing = 0
  local strafeHome, strafing = nil, false
  local function stopStrafe()
    if not strafing then return end
    strafing = false
    DH.strafing = false
    api.release()
  end
  RS:BindToRenderStep("BasedCombat", Enum.RenderPriority.Camera.Value + 1, B.safe("dahood.combat", function(dt)
    local view = workspace.CurrentCamera
    if not view then return end
    local now = os.clock()
    local wantAim = O.aimbot or O.silent or O.strafe or O.bulletTp
    local target, part
    if wantAim and B.character() then target, part = pick() end
    -- the kill aura's own target takes the shot when there is one
    local auraTarget, auraPart
    -- (the aura is on its own: it works with the menu open too, only not while typing)
    if O.aura and UIS:GetFocusedTextBox() == nil then auraTarget, auraPart = nearest(O.auraRange) end
    combat.target = auraTarget or target
    local aimingAt = auraTarget or target
    local aimingPart = auraPart or part
    combat.point = aimingPart and aimPoint(aimingAt.Character, aimingPart) or nil
    if combat.point and O.silentChance < 100 and math.random(100) > O.silentChance then combat.point = nil end
    combat.forced = auraTarget ~= nil
    -- the aimbot: the camera turned onto the target (smoothly, unless set to 0)
    if O.aimbot and target and part and playing() then
      local point = aimPoint(target.Character, part)
      local goal = CFrame.lookAt(view.CFrame.Position, point)
      local alpha = O.aimSmooth <= 0 and 1 or math.clamp(dt * (60 / math.max(O.aimSmooth, 1)) * 2.2, 0.02, 1)
      view.CFrame = view.CFrame:Lerp(goal, alpha)
    end
    -- the ring
    local showRing = O.fovShow and (O.aimbot or O.silent or O.bulletTp) and playing()
    ring.Visible = showRing
    if showRing then
      local at = centre()
      local size = O.aimFov * 2
      ring.Position = UDim2.fromOffset(at.X, at.Y)
      ring.Size = UDim2.fromOffset(size, size)
      ringLine.Color = O.fovColor
      ring.BackgroundColor3 = O.fovColor
      ring.BackgroundTransparency = math.clamp(O.fovFill / 100, 0, 1)
    end
    -- the target: a dot on the point and the body lit
    local markOn = O.targetMark and combat.target ~= nil and combat.point ~= nil
    if markOn then
      local screen, on = view:WorldToViewportPoint(combat.point)
      dot.Visible = on and screen.Z > 0
      dot.Position = UDim2.fromOffset(screen.X, screen.Y)
      if mark.Adornee ~= combat.target.Character then mark.Adornee = combat.target.Character end
      mark.Enabled = true
    else
      dot.Visible = false
      mark.Enabled = false
    end
    -- the cursor
    local wantCursor = O.cursor and playing()
    showCursor(wantCursor)
    if wantCursor then
      local mouse = UIS:GetMouseLocation()
      cursor.Position = UDim2.fromOffset(mouse.X, mouse.Y)
      spin = (spin + dt * O.cursorSpin) % 360
      swing = swing + dt
      local size = O.cursorSize
      local gap = size * 0.28 + (O.cursorPulse and math.sin(swing * 5) * size * 0.08 or 0)
      local length = size * 0.42
      cursor.Rotation = spin
      for index, arm in ipairs(arms) do
        local angle = (index - 1) * math.pi / 2
        local offset = gap + length / 2
        arm.frame.Position = UDim2.new(0.5, math.cos(angle) * offset, 0.5, math.sin(angle) * offset)
        arm.frame.Size = (index % 2 == 1) and UDim2.fromOffset(length, 2) or UDim2.fromOffset(2, length)
        arm.frame.BackgroundColor3 = Color3.new(1, 1, 1)
        arm.shade.Color = ColorSequence.new(O.cursorColor, O.cursorColor2)
        arm.shade.Rotation = (index % 2 == 1) and 0 or 90
      end
      core.BackgroundColor3 = O.cursorColor
    end
    -- rapid fire: the gun's own trigger, pulled every frame while the button is held (each gun keeps
    -- its own rate; a semi-auto fires as fast as it is allowed)
    if O.rapid and playing() and UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) then
      local tool = gunInHand()
      if tool and not automatic(tool) then pcall(function() tool:Activate() end) end
    end
    local _ = now
  end))
  B.onUnload:connect(function() pcall(function() RS:UnbindFromRenderStep("BasedCombat") end) end)

  -- ---------------------------------------------------------------- the kill aura's trigger
  local auraHeld = nil
  Motion.every(function()
    if not O.aura then
      if auraHeld then pcall(function() auraHeld:Deactivate() end); auraHeld = nil end
      return
    end
    local tool = gunInHand()
    -- empty with rounds to spare: reloaded (one at a time, as the game allows)
    if tool and api.numberOf(tool, "Ammo", 0) == 0 and api.reserve(tool.Name) > 0 and os.clock() - (combat.reloadAt or 0) > 1.2
      and not api.flagOf(api.effectsOf(B.character()), "Reload") then
      combat.reloadAt = os.clock()
      local remote = api.mainEvent()
      if remote then remote:FireServer("Reload", tool) end
    end
    if combat.forced and tool and UIS:GetFocusedTextBox() == nil and not api.moving() then
      if automatic(tool) then
        if auraHeld ~= tool then pcall(function() tool:Activate() end); auraHeld = tool end
      else
        pcall(function() tool:Activate() end)
      end
      combat.auraShots += 1
    elseif auraHeld then
      pcall(function() auraHeld:Deactivate() end)
      auraHeld = nil
    end
  end, 20, "dahood.aura")

  -- ---------------------------------------------------------------- a shot from far: the bot goes in range for it
  B.connect(UIS.InputBegan, function(input, processed)
    if input.UserInputType ~= Enum.UserInputType.MouseButton1 or processed or not O.bulletTp or not playing() then return end
    local target = combat.target
    local character = target and target.Character
    local root, tool = B.root(), gunInHand()
    if not (character and root) then return end
    local part = partOf(character, O.aimPart)
    if not part then return end
    -- in reach of the gun in the hand, with a line to it: the gun's own shot does it
    local reach = tool and tool:FindFirstChild("Range") and tool.Range.Value or 0
    if tool and (part.Position - root.Position).Magnitude <= reach * 0.92 and visible(root.Position, part, character) then return end
    local ok, why = DH.runJob(O.bulletKill and "kill" or "knock", target, { limit = O.bulletKill and 12 or 4 })
    if ok then combat.shots += 1
    elseif why then Window.toast({ title = "No shot from far", text = why, icon = "triangle-alert", tone = "warn", time = 2 }) end
  end, "dahood.bullettp")

  -- ---------------------------------------------------------------- target strafe
  B.connect(RS.Heartbeat, function(dt)
    local target = O.strafe and combat.target
    local character = target and target.Character
    local torso = character and api.torsoOf(character)
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    local able = me and root and humanoid and humanoid.Health > 0 and not api.flagOf(api.effectsOf(me), "K.O")
    if not (torso and able and playing()) or (api.moving() and not strafing) or DH.job then
      stopStrafe()
      return
    end
    if not strafing then
      if not api.arm() then return end
      strafing, DH.strafing = true, true
      strafeHome = root.CFrame
    end
    DH.steady(humanoid)
    swing += dt * O.strafeSpeed
    local at = torso.Position + Vector3.new(math.cos(swing) * O.strafeRadius, O.strafeHeight, math.sin(swing) * O.strafeRadius)
    root.CFrame = CFrame.lookAt(at, torso.Position)
    root.AssemblyLinearVelocity = Vector3.new()
  end, "dahood.strafe")
  Config.on("dahood.strafe", function(on) if not on then stopStrafe() end end)
  local _ = strafeHome

  -- ---------------------------------------------------------------- anti slow, and no jump cooldown
  -- The game writes the walk and jump itself every frame (never touched here: its Animate script
  -- hangs the client when the walk is above what it last wrote). Slowed (blocking walks at 5,
  -- reloading and hurt take some off, tasers and spray stop it), the body is carried on along the
  -- way it walks to the normal 16. A jump the game says no to only for jumping too often (five in
  -- a row: 1.5 s of 0) is given back; knocked, held, cuffed or stunned stays no.
  B.connect(RS.Heartbeat, function(dt)
    if not O.antiSlow or api.moving() or DH.strafing then return end
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    if not (me and root and humanoid) or humanoid.Health <= 0 or root.Anchored then return end
    local walk, direction = humanoid.WalkSpeed, humanoid.MoveDirection
    local normal = (Config.get("dahood.speed") and math.max(Config.get("dahood.speedValue") or 16, 16)) or 16
    if walk <= 0 or walk >= normal or direction.Magnitude < 0.05 or Config.get("dahood.speed") then return end
    root.CFrame += direction.Unit * ((normal - walk) * math.min(dt, 0.1))
  end, "dahood.antislow")
  B.connect(RS.Stepped, function()
    if not O.noJumpCd then return end
    local me, humanoid = B.character(), B.humanoid()
    local effects = me and api.effectsOf(me)
    if not (humanoid and effects) or humanoid.Health <= 0 or humanoid.JumpPower > 0 then return end
    if api.flagOf(effects, "K.O") or api.flagOf(effects, "Cuff") or me:FindFirstChild("GRABBING_CONSTRAINT") then return end
    local movement = effects:FindFirstChild("Movement")
    if movement and (movement:FindFirstChild("NoJumping") or movement:FindFirstChild("NoWalkSpeed")) then return end
    local grabbed = effects:FindFirstChild("Grabbed")
    if grabbed and grabbed.Value then return end
    humanoid.JumpPower = Config.get("dahood.jump") and Config.get("dahood.jumpValue") or 50
  end, "dahood.nojumpcd")

  -- ---------------------------------------------------------------- rockets and grenades: out of the way
  local threats = {}          -- part -> true: a rocket (Launcher) or a thrown grenade (a Handle in Ignored)
  local function watchThreat(item)
    if not item:IsA("BasePart") then return end
    if item.Name == "Launcher" and item.Parent and item.Parent:IsA("Model") and item.Parent.Parent and item.Parent.Parent.Name == "Ignored" then threats[item] = os.clock()
    elseif item.Name == "Handle" and item.Parent and item.Parent.Name == "Ignored" then threats[item] = os.clock() end
  end
  local ignored = workspace:FindFirstChild("Ignored")
  if ignored then
    B.connect(ignored.DescendantAdded, function(item) task.defer(watchThreat, item) end, "dahood.threats")
  end
  local dodging, clearSince = false, nil
  B.connect(RS.Heartbeat, function()
    local root = B.root()
    local danger = false
    for part in pairs(threats) do
      if not part.Parent then threats[part] = nil
      elseif O.dodge and root then
        -- where it is, and where it will be in the next half second
        local velocity = part.AssemblyLinearVelocity
        local from = part.Position
        local mine = (dodging and api.home() and api.home().Position) or root.Position
        for step = 0, 5 do
          if ((from + velocity * (step * 0.1)) - mine).Magnitude <= O.dodgeRange then danger = true; break end
        end
      end
    end
    if danger and not dodging then
      if api.moving() or DH.job or not root then return end
      if not api.arm() then return end
      dodging, DH.dodging, clearSince = true, true, nil
      combat.dodges += 1
      DH.hiding = true
      api.pin("void")
      api.setStatus("dodging (void)")
    elseif dodging and not danger then
      clearSince = clearSince or os.clock()
      -- (a burst is over in a moment: back a quarter second after the last one has gone)
      if os.clock() - clearSince >= 0.25 then
        dodging, DH.dodging = false, false
        DH.hiding = false
        api.release()
      end
    end
  end, "dahood.dodge")

  -- ---------------------------------------------------------------- no recoil, a longer zoom
  local lastView
  RS:BindToRenderStep("BasedRecoil", Enum.RenderPriority.Last.Value, function()
    local view = workspace.CurrentCamera
    if view then lastView = view.CFrame end
  end)
  B.onUnload:connect(function() pcall(function() RS:UnbindFromRenderStep("BasedRecoil") end) end)
  local remote = api.mainEvent()
  if remote then
    B.connect(remote.OnClientEvent, function(kind)
      if kind ~= "ShootingRecoil" or not O.noRecoil then return end
      local before = lastView
      task.defer(function()
        local view = workspace.CurrentCamera
        if view and before then view.CFrame = CFrame.new(view.CFrame.Position) * before.Rotation end
      end)
    end, "dahood.norecoil")
  end
  local zoomWas
  local function zoom()
    if O.camZoom then
      zoomWas = zoomWas or LP.CameraMaxZoomDistance
      LP.CameraMaxZoomDistance = O.camZoomMax
    elseif zoomWas then
      LP.CameraMaxZoomDistance = zoomWas
      zoomWas = nil
    end
  end
  Config.on("dahood.camZoom", zoom, true)
  -- the void cannot kill here either: the universal one, standing aside while anything here moves the body
  local void = B.Void
  if void and void.start then
    void.aside = function() return api.moving() or DH.job ~= nil or DH.strafing == true end
    void.start()
  end
  Config.on("dahood.camZoomMax", zoom)
  B.onUnload:connect(function() if zoomWas then LP.CameraMaxZoomDistance = zoomWas end end)
end

local function page(hub)
  hub:page({ id = "combat", title = "Combat", icon = "swords", build = function(tab)
    local aim = tab:section({ title = "Aim", icon = "crosshair", desc = "Who it aims at: inside the ring, nearest the middle." })
    aim:toggle({ id = "dahood.aimbot", label = "Aimbot", desc = "Turns your camera onto them. Bind it as hold.", default = false })
    aim:slider({ id = "dahood.aimSmooth", label = "Smooth", desc = "0: snaps on.", min = 0, max = 100, step = 1, default = 35 })
    aim:toggle({ id = "dahood.silent", label = "Silent aim", desc = "Your shots go to them wherever you point.", default = false })
    aim:slider({ id = "dahood.silentChance", label = "Hit chance", min = 1, max = 100, step = 1, default = 100, suffix = "%" })
    aim:segmented({ id = "dahood.aimPart", label = "Aim at", options = { { "torso", "Torso" }, { "head", "Head" }, { "root", "Root" } }, default = "torso", width = 210 })
    aim:toggle({ id = "dahood.aimPredict", label = "Lead", desc = "Aims where they are going.", default = true })
    aim:toggle({ id = "dahood.aimVisible", label = "Visible only", default = true })
    aim:toggle({ id = "dahood.aimKnocked", label = "Skip knocked", default = true })
    aim:toggle({ id = "dahood.aimFriends", label = "Skip friends", default = true })
    aim:toggle({ id = "dahood.targetMark", label = "Show target", desc = "Lights them and dots the aim point.", default = true })

    local fov = tab:section({ title = "FOV", icon = "circle-dot" })
    fov:toggle({ id = "dahood.fovShow", label = "Show ring", default = true })
    fov:slider({ id = "dahood.aimFov", label = "Size", min = 20, max = 900, step = 5, default = 180, suffix = " px" })
    fov:segmented({ id = "dahood.fovFollow", label = "Centre", options = { { "mouse", "Mouse" }, { "centre", "Screen" } }, default = "mouse", width = 170 })
    fov:color({ id = "dahood.fovColor", label = "Colour", default = Color3.fromRGB(255, 255, 255) })
    fov:slider({ id = "dahood.fovFill", label = "See-through", min = 50, max = 100, step = 1, default = 96, suffix = "%" })

    local guns = tab:section({ title = "Guns", icon = "zap" })
    guns:toggle({ id = "dahood.bulletTp", label = "Bullet TP", desc = "Out of reach: you hop over, shoot, hop back.", default = false })
    guns:toggle({ id = "dahood.bulletKill", label = "Stomp after", desc = "Bullet TP stomps them too.", default = false })
    guns:toggle({ id = "dahood.rapid", label = "Rapid fire", desc = "Hold to fire as fast as the gun allows.", default = false })
    guns:toggle({ id = "dahood.aura", label = "Kill aura", desc = "Shoots anyone near with the gun in your hand.", default = false })
    guns:slider({ id = "dahood.auraRange", label = "Aura range", min = 5, max = 250, step = 5, default = 60, suffix = " st" })
    guns:toggle({ id = "dahood.noRecoil", label = "No recoil", default = false })

    local move = tab:section({ title = "Movement", icon = "move" })
    move:toggle({ id = "dahood.strafe", label = "Target strafe", desc = "Circles your target. Bind it as hold.", default = false })
    move:slider({ id = "dahood.strafeRadius", label = "Distance", min = 3, max = 60, step = 1, default = 12, suffix = " st" })
    move:slider({ id = "dahood.strafeHeight", label = "Height", min = -10, max = 40, step = 1, default = 4, suffix = " st" })
    move:slider({ id = "dahood.strafeSpeed", label = "Speed", min = 1, max = 40, step = 1, default = 6 })
    move:toggle({ id = "dahood.antiSlow", label = "Anti slow", desc = "Blocking, reloading or hurt: full speed anyway.", default = false })
    move:toggle({ id = "dahood.noJumpCd", label = "No jump cooldown", desc = "Jump as often as you like. Not flying.", default = false })
    move:toggle({ id = "dahood.dodge", label = "Dodge", desc = "A rocket or grenade near: into the void until it bursts.", default = false })
    move:slider({ id = "dahood.dodgeRange", label = "Dodge within", min = 8, max = 80, step = 1, default = 28, suffix = " st" })

    local look = tab:section({ title = "Cursor", icon = "mouse-pointer-2" })
    look:toggle({ id = "dahood.cursor", label = "Cursor", desc = "Replaces your mouse with a moving crosshair.", default = false })
    look:slider({ id = "dahood.cursorSize", label = "Size", min = 8, max = 60, step = 1, default = 18, suffix = " px" })
    look:slider({ id = "dahood.cursorSpin", label = "Spin", min = 0, max = 720, step = 10, default = 90, suffix = "°/s" })
    look:toggle({ id = "dahood.cursorPulse", label = "Breathe", default = true })
    look:color({ id = "dahood.cursorColor", label = "Colour", default = Color3.fromRGB(255, 255, 255) })
    look:color({ id = "dahood.cursorColor2", label = "Second colour", default = Color3.fromRGB(120, 170, 255) })
    look:toggle({ id = "dahood.camZoom", label = "Zoom out", default = false })
    look:slider({ id = "dahood.camZoomMax", label = "Max zoom", min = 30, max = 2000, step = 10, default = 400, suffix = " st" })
  end })
end

local function player(tab)
  local void = tab:section({ title = "Void", icon = "shield" })
  void:toggle({ id = "move.noVoid", label = "Anti void", desc = "Falling off the map never kills you.", default = true, bindable = false })
  void:toggle({ id = "move.voidRescue", label = "Catch falls", desc = "A long fall puts you back where you stood.", default = true, bindable = false })
end

DH.parts[#DH.parts + 1] = { id = "combat", start = start, page = page, player = player }
end
do -- dahood_esp.lua
-- ============================================================================
--  Da Hood     what ESP can read here, and marks on the map
--
--  Everything below is replicated to every client by the game itself (read on
--  2026-10-12, version 3267, one account looking at the other):
--    BodyEffects.Armor (130 with High-Medium Armor on) and FireArmor, the flags
--    K.O / Dead / Reload / Attacking / Grabbed / Cuff, a "Block" child while
--    blocking, a GRABBING_CONSTRAINT on a body that is being carried, the Ammo
--    and MaxAmmo of the tool in a hand, DataFolder.Currency and
--    leaderstats.Wanted.
--  And on the map: the cashiers (whole or broken, and since when) and cash
--  lying on the ground with what it is worth.
-- ============================================================================
local B = B or ...
local S, util, UI, Config = B.S, B.util, B.UI, B.Config
local DH = B.DaHood
local Esp = B.Esp

local ARMOR_FULL = 130       -- High-Medium Armor
local MARKS = 60             -- cashiers and drops marked at once, at the most (the nearest)
local AIM_NEAR = 6           -- studs from this body that someone's mouse point has to be, for them to be aiming at it

local function money(amount)
  if amount >= 999500 then return string.format("$%.1fM", amount / 1e6) end
  if amount >= 9950 then return string.format("$%.0fk", amount / 1000) end
  return "$" .. util.comma(amount)
end

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  local map = {}
  for id, default in pairs({ espCashiers = false, espDrops = false, espWorldRange = 600, espCashierColor = Color3.fromRGB(126, 231, 135), espDropColor = Color3.fromRGB(255, 209, 102) }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  -- Once: the armor bar, the ammo and the flags join whatever was already drawn here, so they are
  -- seen without being looked for. After that the list is the player's own again.
  Config.define("dahood.espAdded", false)
  if not Config.get("dahood.espAdded") and type(Config.get("esp.elements")) == "table" then
    local list = table.clone(Config.get("esp.elements"))
    for _, name in ipairs({ "armor", "ammo", "flags" }) do
      if not table.find(list, name) then list[#list + 1] = name end
    end
    Config.set("esp.elements", list)
    Config.set("dahood.espAdded", true)
  end

  -- ---------------------------------------------------------------- what ESP reads of a player
  local extras = Esp.extras
  function extras.armor(entry)
    local character = entry.character
    if not character then return nil end
    local effects = api.effectsOf(character)
    local fire = effects and effects:FindFirstChild("FireArmor")
    local value = api.armorOf(character) + (fire and tonumber(fire.Value) or 0)
    return math.clamp(value / ARMOR_FULL, 0, 1), value
  end
  function extras.ammo(entry)
    local character = entry.character
    local tool = character and character:FindFirstChildOfClass("Tool")
    local ammo = tool and tool:FindFirstChild("Ammo")
    if not ammo then return nil end
    local max = tool:FindFirstChild("MaxAmmo")
    return tostring(ammo.Value) .. "/" .. tostring(max and max.Value or "?")
  end
  function extras.money(entry)
    local player = entry.player
    if not player then return nil end
    local data = player:FindFirstChild("DataFolder")
    local cash = data and data:FindFirstChild("Currency")
    local stats = player:FindFirstChild("leaderstats")
    local wanted = stats and stats:FindFirstChild("Wanted")
    local text = cash and money(tonumber(cash.Value) or 0) or nil
    local level = wanted and tonumber(wanted.Value) or 0
    if level > 0 then text = (text and (text .. "  ·  ") or "") .. "wanted " .. util.comma(level) end
    return text
  end
  function extras.flags(entry)
    local character = entry.character
    if not character then return nil end
    local effects = api.effectsOf(character)
    local out = {}
    -- Their mouse is on this body, with a gun out. (BodyEffects.MousePos is where each player's
    -- mouse points, sent to every client: read on 2026-10-14.)
    local mouse = effects and effects:FindFirstChild("MousePos")
    local tool = character:FindFirstChildOfClass("Tool")
    local mine = not api.moving() and B.root()
    if mine and mouse and tool and tool:FindFirstChild("Ammo") and typeof(mouse.Value) == "Vector3" and (mouse.Value - mine.Position).Magnitude <= AIM_NEAR then out[#out + 1] = "AIMING AT YOU" end
    if api.flagOf(effects, "K.O") then out[#out + 1] = "KNOCKED" end
    if character:FindFirstChild("GRABBING_CONSTRAINT") then out[#out + 1] = "CARRIED" end
    if character:FindFirstChildOfClass("ForceField") then out[#out + 1] = "SHIELD" end
    if effects then
      local grabbed = effects:FindFirstChild("Grabbed")
      if grabbed and grabbed.Value ~= nil then out[#out + 1] = "CARRYING" end
      if effects:FindFirstChild("Block") then out[#out + 1] = "BLOCKING" end
      if api.flagOf(effects, "Reload") then out[#out + 1] = "RELOADING" end
      if api.flagOf(effects, "Attacking") then out[#out + 1] = "SWINGING" end
      if api.flagOf(effects, "Cuff") then out[#out + 1] = "CUFFED" end
    end
    if entry.player and DH.isMarked(entry.player) then out[#out + 1] = "MARKED" end
    if #out == 0 then return nil end
    return table.concat(out, "\n", 1, math.min(#out, 4))
  end
  extras.sample = { armorMax = ARMOR_FULL, ammo = "2/2", money = "$12.4k  ·  wanted 585", flags = "RELOADING\nMARKED", tool = "[Double-Barrel SG]", team = false }

  -- ---------------------------------------------------------------- marks on the map
  local gui = B.screen(7990)
  local layer = UI.frame(gui, { Name = "World", Size = UDim2.fromScale(1, 1) })
  local pool, used = {}, 0
  local function label()
    used += 1
    local item = pool[used]
    if not item then
      item = UI.new("TextLabel", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.fromOffset(180, 14), FontFace = B.F.mono500, TextSize = 11,
        TextStrokeColor3 = Color3.new(0, 0, 0), TextStrokeTransparency = 0.45, Text = "", Visible = false, Parent = layer })
      pool[used] = item
    end
    return item
  end
  local found = {}
  local function nearer(a, b) return a.away < b.away end
  local function step()
    used = 0
    local camera = workspace.CurrentCamera
    if camera and (O.espCashiers or O.espDrops) then
      local from = camera.CFrame.Position
      local now = os.clock()
      table.clear(found)
      if O.espCashiers and DH.farm and DH.farm.cashiers then
        for _, cashier in ipairs(DH.farm.cashiers()) do
          local away = (cashier.head.Position - from).Magnitude
          if away <= O.espWorldRange then found[#found + 1] = { at = cashier.head.Position, away = away, cashier = cashier } end
        end
      end
      if O.espDrops and DH.farm and DH.farm.drops then
        for _, drop in ipairs(DH.farm.drops()) do
          local away = (drop.Position - from).Magnitude
          if away <= O.espWorldRange then found[#found + 1] = { at = drop.Position, away = away, drop = drop } end
        end
      end
      if #found > MARKS then table.sort(found, nearer) end
      for index = 1, math.min(#found, MARKS) do
        local thing = found[index]
        local point = camera:WorldToViewportPoint(thing.at)
        if point.Z > 0 then
          local item = label()
          local text, color, alpha
          if thing.cashier then
            if thing.cashier.whole then
              text, color, alpha = string.format("ATM  %s st", util.studs(thing.away)), O.espCashierColor, 0.05
            else
              local left = DH.farm.left and DH.farm.left(thing.cashier.model, now)
              text, color, alpha = left and string.format("ATM  back in %d s", math.ceil(left)) or "ATM  broken", O.espCashierColor, 0.55
            end
          else
            local tag = thing.drop:FindFirstChildWhichIsA("TextLabel", true)
            text, color, alpha = string.format("%s  %s st", tag and tag.Text or "cash", util.studs(thing.away)), O.espDropColor, 0.05
          end
          if item.Text ~= text then item.Text = text end
          item.TextColor3 = color
          item.TextTransparency = alpha
          item.Position = UDim2.fromOffset(point.X, point.Y)
          if not item.Visible then item.Visible = true end
        end
      end
    end
    for index = used + 1, #pool do
      if pool[index].Visible then pool[index].Visible = false end
    end
  end
  B.connect(S.RunService.RenderStepped, step, "dahood.world")
  local _ = LP
end

-- its own section on the Visuals tab
Esp.sections[#Esp.sections + 1] = function(page)
  if not (B.Registry and B.Registry.active and B.Registry.active.id == "dahood") then return end
  local world = page:section({ title = "Da Hood ESP", icon = "map-pin", column = 2, weight = 4, desc = "Marks on the map. Armor, ammo, cash and flags are under Elements." })
  world:toggle({ id = "dahood.espCashiers", label = "Cashiers", desc = "Every ATM: whole, or how long until it is.", default = false, children = function(sub)
    sub:color({ id = "dahood.espCashierColor", label = "Colour", default = Color3.fromRGB(126, 231, 135) })
  end })
  world:toggle({ id = "dahood.espDrops", label = "Drops", desc = "Each drop and what it is worth.", default = false, children = function(sub)
    sub:color({ id = "dahood.espDropColor", label = "Colour", default = Color3.fromRGB(255, 209, 102) })
  end })
  world:slider({ id = "dahood.espWorldRange", label = "Within", min = 50, max = 3000, step = 50, default = 600, curve = 2, suffix = " st" })
end

DH.parts[#DH.parts + 1] = { id = "esp", start = start }
end
do -- dahood_fly.lua
-- ============================================================================
--  Da Hood     flight: the universal flight's clips, booms, trails and sounds,
--              carried the way this game takes it
--
--  The universal flight (src/26_flight.lua) carries the body with a LinearVelocity and
--  an AlignOrientation and parks the humanoid in a state of its own. Here it does none of
--  that (Flight.body = "frame"): the body is put where it should be every frame, the way
--  the ragebot has carried it in this game every day, with its velocity held at zero. Its
--  path is looked along first, so no speed carries it through a wall or the floor; it is
--  never lower than 60 studs over the height at which the game takes a body to have fallen
--  out of the world; walk speed and jump power are not touched. The same fourteen clips,
--  the same booms at every Mach tier, the launch, the trails, the wind and the timed
--  landing. It stands aside while the ragebot, the void or the cash round has the body.
-- ============================================================================
local B = B or ...
local Config, Motion, util = B.Config, B.Motion, B.util
local DH = B.DaHood

local function start()
  local Flight = B.Flight
  if not Flight then return end
  Flight.body = "frame"
  Flight.flag = "dahood.fly"
  Flight.blocked = function() return DH.on or DH.hiding or DH.farming == true or DH.errand == true or DH.strafing == true end
  Flight.start()
end

local function studs(v) return util.comma(math.floor(v + 0.5)) .. " st/s" end

local function player(page)
  local Flight = B.Flight
  if not (Flight and Flight.started) then return end
  local fly = page:section({ title = "Flight", icon = "plane", desc = "Fly with the universal flight's moves, built for Da Hood." })
  local live = fly:note({ icon = "gauge", text = "" })
  Motion.every(function()
    if not (live.frame and live.frame.Parent) then return end
    if not (B.Window.anyOpen and B.Window.anyOpen()) then return end
    local label, speed, mach = Flight.status()
    local text = label
    if Flight.state == "flying" then text = string.format("%s  ·  %s%s", label, studs(speed or 0), (mach or 0) >= 1 and string.format("  ·  Mach %.1f", mach) or "") end
    if (DH.on or DH.hiding or DH.farming == true) and Config.get("dahood.fly") then text = "Waiting: the ragebot has your body" end
    live.set(text)
  end, 6, "dahood.fly.live")
  fly:toggle({ id = "dahood.fly", label = "Fly", desc = "Hold Space on the ground to charge, let go to launch." })
  fly:slider({ id = "move.flySpeed", label = "Cruise speed", min = 10, max = 5000, step = 5, curve = 3.5, valueWidth = 88, format = studs })
  fly:slider({ id = "fly.top", label = "Top speed", desc = "What a held boost builds up to.", min = 100, max = 100000, step = 25, curve = 4, valueWidth = 96, format = studs })
  fly:multi({ id = "fly.idles", label = "Idles", desc = "Pick one, or several to take turns.", empty = "Float", menuWidth = 210, options = {
    { "a", "Float", icon = "feather" }, { "b", "Menace", icon = "swords" }, { "c", "Arms crossed", icon = "shield" }, { "d", "On watch", icon = "binoculars" } } })
  fly:toggle({ id = "fly.autoLand", label = "Auto land", desc = "Fly down at the ground to land, feet first.", bindable = false })
  fly:note({ icon = "info", text = "WASD steers, Space climbs, Left Ctrl comes down, Left Shift boosts. Nothing is added to your body: walls and the floor stop you at any speed." })

  local boom = page:section({ title = "Launch", icon = "rocket" })
  boom:slider({ id = "fly.chargeTime", label = "Charge time", desc = "How long Space is held for the strongest launch.", min = 0.2, max = 10, step = 0.1, curve = 2, suffix = " s" })
  boom:slider({ id = "fly.launch", label = "Launch", min = 100, max = 20000, step = 10, curve = 3.5, valueWidth = 88, format = studs })
  boom:slider({ id = "fly.rampTime", label = "Ramp time", min = 0.5, max = 60, step = 0.25, curve = 2, suffix = " s" })
  boom:slider({ id = "fly.sonic", label = "Sonic", desc = "Mach 1. Every doubling past it booms again, bigger.", min = 150, max = 100000, step = 25, curve = 4,
    valueWidth = 96, format = studs })

  local look = page:section({ title = "Effects", icon = "sparkles" })
  look:multi({ id = "fly.effects", label = "Effects", empty = "None", menuWidth = 244, options = {
    { "sonic", "Sonic booms", icon = "zap" }, { "lines", "Mach 2+ screen effects", icon = "scan-line" }, { "takeoff", "Launch burst", icon = "rocket" },
    { "boost", "Charge and boost rings", icon = "circle-dot" }, { "trails", "Limb trails", icon = "spline" }, { "streaks", "Wind streaks", icon = "wind" },
    { "haze", "Pressure wave", icon = "droplets" }, { "crater", "Landing crater", icon = "mountain" }, { "shake", "Camera shake and bank", icon = "vibrate" },
    { "fov", "Speed field of view", icon = "aperture" } } })
  look:color({ id = "fly.trailColor", label = "Trail colour" })
  look:toggle({ id = "fly.sound", label = "Flight sounds", bindable = false, children = function(sub)
    sub:slider({ id = "fly.volume", label = "Volume", min = 0, max = 150, step = 5, suffix = "%" })
  end })
  look:toggle({ id = "fly.animations", label = "Flight animations", desc = "R15 only. Off, or on R6, the body simply leads head first.", bindable = false })
  look:keybind({ id = "fly.key.boost", label = "Boost key", default = "LeftShift" })
  look:keybind({ id = "fly.key.down", label = "Descend key", default = "LeftControl" })
end

DH.parts[#DH.parts + 1] = { id = "fly", start = start, player = player }
end
do -- dahood_fx.lua
-- ============================================================================
--  Da Hood     what a hit looks and sounds like
--
--  The server tells this client of every hit it counted ("HitMarker", and
--  whether it was the head), whoever fired it: the ragebot or the player. On
--  each one: a sound from the pack, a mark where the body is (or mid screen),
--  and the damage as a figure, read off the health and armor the body lost.
--  A knock gets a sound and a mark of its own. All of it is this client's own:
--  nobody else hears or sees any of it.
--
--  The sounds are made by based/tools/hitsounds.py from sines, sweeps and
--  noise: nobody's recording.
-- ============================================================================
local B = B or ...
local S, util, Motion, UI, Config, Window, Assets = B.S, B.util, B.Motion, B.UI, B.Config, B.Window, B.Assets
local DH = B.DaHood

local HIT_SOUNDS = { { "off", "None" }, { "tick", "Tick" }, { "pop", "Pop" }, { "blip", "Blip" }, { "clack", "Clack" }, { "snap", "Snap" }, { "chirp", "Chirp" },
  { "thud", "Thud" }, { "punch", "Punch" }, { "bell", "Bell" }, { "ding", "Ding" }, { "glass", "Glass" }, { "coin", "Coin" }, { "zap", "Zap" } }
local KNOCK_SOUNDS = { { "off", "None" }, { "kill_chime", "Chime" }, { "kill_bass", "Bass drop" }, { "kill_coins", "Coins" }, { "kill_gong", "Gong" }, { "kill_sweep", "Sweep" },
  { "bell", "Bell" }, { "glass", "Glass" }, { "punch", "Punch" } }
local STYLES = { { "cross", "Cross" }, { "plus", "Plus" }, { "ring", "Ring" }, { "burst", "Burst" }, { "square", "Square" } }
local VOICES = 3             -- copies of a sound: quick hits overlap instead of cutting each other off
local STREAK = 1.2           -- s between hits that still count as one run: the pitch climbs along it
local SEEN = 0.4             -- s either side of the server's word in which a body's loss is taken to be that hit
local MARKS = 28             -- marks and figures on screen at once, at the most

local fx = { hits = 0, knocks = 0, HIT_SOUNDS = HIT_SOUNDS, KNOCK_SOUNDS = KNOCK_SOUNDS, STYLES = STYLES }
DH.fx = fx

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  -- The player's own sounds: any .mp3, .ogg or .wav put in BasedHub/hitsounds is offered beside
  -- the pack, under its file name. (They stay on this machine: nothing here sends them anywhere.)
  fx.own = 0
  local has = {}
  for _, file in ipairs(B.fs.list(B.fs.path("hitsounds"))) do
    local base, kind = string.match(file, "([^/]+)%.(%w+)$")
    kind = kind and string.lower(kind)
    if base and (kind == "mp3" or kind == "ogg" or kind == "wav") then
      local label = string.gsub(string.gsub(base, "^Nebula_", ""), "_", " ")
      local key = "file:" .. base .. "." .. kind
      HIT_SOUNDS[#HIT_SOUNDS + 1] = { key, label }
      KNOCK_SOUNDS[#KNOCK_SOUNDS + 1] = { key, label }
      has[key] = true
      fx.own += 1
    end
  end
  local map = {}
  for id, default in pairs({ hitSound = "tick", headSound = has["file:Nebula_RustHeadshot.mp3"] and "file:Nebula_RustHeadshot.mp3" or "glass", knockSound = "kill_chime",
    hitVolume = 60, hitPitch = true, marker = true, markerStyle = "cross",
    markerSize = 16, markerTime = 0.4, markerWorld = true, markerColor = Color3.fromRGB(255, 255, 255), markerHead = Color3.fromRGB(255, 209, 102),
    markerKnock = Color3.fromRGB(255, 84, 84), damage = true, card = true, shotSound = "off", shotVolume = 50, muteGuns = "auto", muteAll = false, muteHit = true }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  fx.options = O
  -- (a sound that was chosen and is not there any more: its file was taken away)
  for _, id in ipairs({ "hitSound", "headSound", "knockSound", "shotSound" }) do
    local chosen = O[id]
    if type(chosen) == "string" and string.sub(chosen, 1, 5) == "file:" and not has[chosen] then Config.set("dahood." .. id, id == "shotSound" and "off" or "tick", true) end
  end

  -- ---------------------------------------------------------------- sound
  local host
  local voices = {}
  local function play(name, volume, speed)
    if not name or name == "off" or volume <= 0 then return false end
    local id
    if string.sub(name, 1, 5) == "file:" then id = Assets.id("hitsounds/" .. string.sub(name, 6)) else id = Assets.sound("hit_" .. name) end
    if not id then return false end
    if not (host and host.Parent) then
      host = Instance.new("Folder")
      host.Name = util.randomName()
      host.Parent = S.SoundService
      B.own(host)
      table.clear(voices)
    end
    local set = voices[name]
    if not set then set = { at = 0 }; voices[name] = set end
    set.at = set.at % VOICES + 1
    local sound = set[set.at]
    if not sound then
      sound = Instance.new("Sound")
      sound.SoundId = id
      sound.Parent = host
      set[set.at] = sound
    end
    sound.Volume = volume
    sound.PlaybackSpeed = speed or 1
    sound:Play()
    return true
  end
  fx.play = function(name) return play(name, O.hitVolume / 100, 1) end

  -- ---------------------------------------------------------------- marks
  local layer = UI.frame(api.gui, { Name = "Hits", Size = UDim2.fromScale(1, 1) })
  local live = {}              -- marks and figures being drawn: { frame, world, dx, dy, rise }
  local function bar(parent, color, angle)
    local frame = Instance.new("Frame")
    frame.BorderSizePixel = 0
    frame.AnchorPoint = Vector2.new(0.5, 0.5)
    frame.BackgroundColor3 = color
    frame.Rotation = angle
    local edge = Instance.new("UIStroke")
    edge.Color = Color3.new(0, 0, 0)
    edge.Transparency = 0.55
    edge.Thickness = 1
    edge.Parent = frame
    frame.Parent = parent
    return frame, edge
  end
  -- One mark: its pieces spread and fade over `life`. `world` keeps it on a place in the game
  -- as the view moves; without one it sits where it was put on screen.
  local function mark(style, color, size, life, x, y, world)
    while #live >= MARKS do
      local old = table.remove(live, 1)
      old.dead = true
      old.frame:Destroy()
    end
    local holder = UI.frame(layer, { Name = "Mark", Size = UDim2.fromOffset(0, 0), Position = UDim2.fromOffset(x, y) })
    local entry = { frame = holder, world = world }
    live[#live + 1] = entry
    local pieces = {}
    local ring, ringEdge
    if style == "ring" then
      ring = Instance.new("Frame")
      ring.BackgroundTransparency = 1
      ring.AnchorPoint = Vector2.new(0.5, 0.5)
      ring.Position = UDim2.fromOffset(0, 0)
      UI.corner(ring, true)
      ringEdge = Instance.new("UIStroke")
      ringEdge.Color = color
      ringEdge.Thickness = math.max(1.5, size * 0.13)
      ringEdge.Parent = ring
      ring.Parent = holder
    else
      local count = style == "burst" and 8 or 4
      local turn = (style == "cross" or style == "square") and 45 or (style == "burst" and 22.5 or 0)
      for index = 1, count do
        local angle = turn + (index - 1) * (360 / count)
        local piece, edge = bar(holder, color, style == "square" and angle + 90 or angle)
        pieces[index] = { piece, edge, math.rad(angle) }
      end
    end
    local thick = math.max(2, math.floor(size * 0.16 + 0.5))
    Motion.tween(math.max(life, 0.08), Motion.ease.outCubic, function(p)
      if entry.dead then return end
      local fade = p * p
      if ring then
        local across = size * (0.7 + 1.5 * p)
        ring.Size = UDim2.fromOffset(across, across)
        ringEdge.Transparency = fade
      else
        local out = size * (style == "burst" and (0.5 + 1.1 * p) or (0.42 + 0.5 * p))
        local long = size * (style == "burst" and 0.42 or (style == "square" and 0.9 or 0.62)) * (1 - 0.35 * p)
        for _, item in ipairs(pieces) do
          local piece, edge, angle = item[1], item[2], item[3]
          piece.Size = UDim2.fromOffset(long, thick)
          piece.Position = UDim2.fromOffset(math.cos(angle) * out, math.sin(angle) * out)
          piece.BackgroundTransparency = fade
          edge.Transparency = 0.55 + 0.45 * fade
        end
      end
    end, function()
      entry.dead = true
      local at = table.find(live, entry)
      if at then table.remove(live, at) end
      holder:Destroy()
    end)
    return entry
  end
  -- a figure that rises from where it was put and fades
  local function figure(text, color, x, y, world, size)
    while #live >= MARKS do
      local old = table.remove(live, 1)
      old.dead = true
      old.frame:Destroy()
    end
    local label = UI.new("TextLabel", { Name = "Figure", BackgroundTransparency = 1, AnchorPoint = Vector2.new(0.5, 1), Size = UDim2.fromOffset(160, 22),
      Position = UDim2.fromOffset(x, y), FontFace = B.F.text700, TextSize = size or 15, Text = text, TextColor3 = color, TextStrokeColor3 = Color3.new(0, 0, 0),
      TextStrokeTransparency = 0.4, Parent = layer })
    local entry = { frame = label, world = world, rise = 0, side = (math.random() * 2 - 1) * 14 }
    live[#live + 1] = entry
    Motion.tween(0.85, Motion.ease.outCubic, function(p)
      if entry.dead then return end
      entry.rise = 34 * p
      label.TextTransparency = p * p
      label.TextStrokeTransparency = 0.4 + 0.6 * p * p
    end, function()
      entry.dead = true
      local at = table.find(live, entry)
      if at then table.remove(live, at) end
      label:Destroy()
    end)
    return entry
  end
  -- marks that belong to a place in the game follow it as the view moves
  B.connect(S.RunService.RenderStepped, function()
    if #live == 0 then return end
    local camera = workspace.CurrentCamera
    if not camera then return end
    for _, entry in ipairs(live) do
      if entry.world and not entry.dead then
        local point = camera:WorldToViewportPoint(entry.world)
        local shown = point.Z > 0
        if entry.frame.Visible ~= shown then entry.frame.Visible = shown end
        if shown then entry.frame.Position = UDim2.fromOffset(point.X + (entry.side or 0), point.Y - (entry.rise or 0)) end
      elseif entry.rise and not entry.dead then
        entry.frame.Position = UDim2.fromOffset(entry.x + (entry.side or 0), entry.y - entry.rise)
      end
    end
  end, "dahood.marks")

  -- ---------------------------------------------------------------- whom, and how much
  -- What every body near has just lost: health and armor together, by the frame. The server's
  -- word that a hit counted comes within a few frames of the loss being seen, before or after.
  local totals = {}                                    -- per character: { total, losses = { { at, amount } }, knocked } (a body that is gone is taken out below)
  local function vitalsOf(character)
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    if not humanoid then return nil end
    return humanoid.Health + api.armorOf(character)
  end
  -- The loss that goes with a hit told at `at`: the one nearest to it in time that no other hit has
  -- been given, inside SEEN before it and up to now. One hit, one loss: a gun that fires every
  -- 0.05 s has the next hit's loss on the body before this one's line is written.
  local function lossFor(record, at, upTo)
    local best, bestGap
    for _, loss in ipairs(record.losses) do
      if not loss[3] and loss[1] >= at - SEEN and loss[1] <= upTo then
        local gap = math.abs(loss[1] - at)
        if not bestGap or gap < bestGap then best, bestGap = loss, gap end
      end
    end
    return best, bestGap
  end
  local lastHit = { at = -math.huge, run = 0 }
  local recent = {}                                    -- per player: when a hit of ours was last put down to them
  local card = { player = nil, at = -math.huge }

  local function placeOf(player, head)
    local character = player and player.Parent and player.Character
    if not (character and character.Parent) then return nil end
    local part = head and character:FindFirstChild("Head") or api.torsoOf(character)
    return part and part.Position or nil
  end
  local function screenOf(world)
    local camera = workspace.CurrentCamera
    local view = B.viewport()
    if world and camera and O.markerWorld then
      local point = camera:WorldToViewportPoint(world)
      if point.Z > 0 and point.X > -40 and point.X < view.X + 40 and point.Y > -40 and point.Y < view.Y + 40 then return point.X, point.Y, world end
    end
    return view.X * 0.5, view.Y * 0.5, nil
  end

  -- a hit the server counted: `known` is who the ragebot was shooting at, when it was the one shooting
  local function onHit(head, known)
    local now = os.clock()
    fx.hits += 1
    -- (a shell is five pellets and the server says so five times in one frame: that is one hit to hear and to see)
    if now - lastHit.at < 0.04 then return end
    lastHit.run = (now - lastHit.at <= STREAK) and math.min(lastHit.run + 1, 12) or 0
    lastHit.at = now
    local pitch = 1
    if O.hitPitch then pitch = 1 + lastHit.run * 0.035 end
    local name = head and O.headSound ~= "off" and O.headSound or O.hitSound
    play(name, O.hitVolume / 100, pitch)
    -- who it was: the ragebot's target, or whoever is seen to lose health about now (a few frames
    -- are given for that to show)
    task.delay(0.09, function()
      if not B.alive then return end
      local stamp = os.clock()
      local victim, amount = known, 0
      local mine
      if known and known.Character and totals[known.Character] then
        mine = lossFor(totals[known.Character], now, stamp)
      else
        -- (nobody was being shot at by the ragebot: whoever lost health nearest to that moment)
        local nearest
        for _, player in ipairs(S.Players:GetPlayers()) do
          local record = player ~= LP and player.Character and totals[player.Character]
          local loss, gap = nil, nil
          if record then loss, gap = lossFor(record, now, stamp) end
          if loss and (not nearest or gap < nearest) then victim, mine, nearest = player, loss, gap end
        end
      end
      if mine then
        mine[3] = true
        amount = mine[2]
      end
      if victim then
        recent[victim] = stamp
        card.player, card.at = victim, stamp
      end
      local world = placeOf(victim, head)
      local x, y, anchor = screenOf(world)
      if api.O.hudHits then
        local who = victim and victim.Name or "someone"
        local where = head and "Head" or "Body"
        api.feed(amount >= 0.5 and string.format("Hit %s for %d in the %s", who, math.floor(amount + 0.5), where) or string.format("Hit %s in the %s", who, where), "Hit")
      end
      if O.marker then mark(O.markerStyle, head and O.markerHead or O.markerColor, O.markerSize, O.markerTime, x, y, anchor) end
      if O.damage and amount >= 0.5 then
        local entry = figure(string.format("-%d", math.floor(amount + 0.5)), head and O.markerHead or O.markerColor, x, y - O.markerSize, anchor and (anchor + Vector3.new(0, 1.6, 0)) or nil)
        entry.x, entry.y = x, y - O.markerSize
      end
    end)
  end
  DH.onHit:connect(onHit)
  fx.onHit = onHit

  -- a knock: one of ours if a hit was put down to that body a moment before
  local function onKnock(player, character)
    local now = os.clock()
    local ours = (recent[player] and now - recent[player] < 1.2) or (DH.on and DH.target == player)
    if not ours then return end
    fx.knocks += 1
    play(O.knockSound, O.hitVolume / 100, 1)
    local torso = api.torsoOf(character)
    local x, y, anchor = screenOf(torso and torso.Position or nil)
    if O.marker then mark(O.markerStyle == "ring" and "burst" or "ring", O.markerKnock, O.markerSize * 1.5, O.markerTime * 1.6, x, y, anchor) end
  end
  B.connect(S.Players.PlayerRemoving, function(player) recent[player] = nil end, "dahood.vitals.left")
  B.connect(S.RunService.Heartbeat, function()
    local now = os.clock()
    for character in pairs(totals) do
      if not character.Parent then totals[character] = nil end
    end
    for _, player in ipairs(S.Players:GetPlayers()) do
      local character = player ~= LP and player.Character
      if character and character.Parent then
        local total = vitalsOf(character)
        if total then
          local record = totals[character]
          if not record then
            record = { total = total, losses = {}, knocked = false }
            totals[character] = record
          end
          if total < record.total - 0.4 then
            local losses = record.losses
            losses[#losses + 1] = { now, record.total - total }
            while #losses > 0 and now - losses[1][1] > 2 do table.remove(losses, 1) end
          end
          record.total = total
          local down = api.flagOf(api.effectsOf(character), "K.O")
          if down and not record.knocked then
            -- (the flag follows the last hit by a few frames: the hit's own bookkeeping goes first)
            task.delay(0.12, function() if B.alive then B.try("dahood.knock", onKnock, player, character) end end)
          end
          record.knocked = down
        end
      end
    end
  end, "dahood.vitals")

  -- ---------------------------------------------------------------- shots
  -- A sound on every shot. The ragebot's are told by the engine as the server takes them: when the
  -- first of a turn fired, and how many it holds behind it, each a cooldown later. A shot the
  -- player fires by hand is told by the gun's own sound being played (the game plays it for those).
  local function shot()
    if O.shotSound ~= "off" then play(O.shotSound, O.shotVolume / 100, 0.97 + math.random() * 0.06) end
    fx.shots = (fx.shots or 0) + 1
  end
  fx.shot = shot
  DH.onShot:connect(function(gun, shots, first)
    local kind = api.GUN[gun]
    local step = (kind and kind.cooldown or 0.1) + DH.rate.margin
    local now = os.clock()
    for index = 0, math.max(shots, 1) - 1 do
      local due = (first or now) + index * step - now
      if due <= 0.02 then shot() else task.delay(due, function() if B.alive then shot() end end) end
    end
  end)
  -- The game's own gun sounds: each gun's Handle has a ShootSound (and the game plays copies of it
  -- called MG and DefaultShoot) and a NoAmmo. Hushed here, on this client only, by setting their
  -- volume to nothing and putting it back after.
  local GUN_SOUNDS = { ShootSound = true, MG = true, DefaultShoot = true, NoAmmo = true }
  -- (what the game sets them to: a sound found at nothing with no record of what it was is given this back)
  local GAME_VOLUME = { ShootSound = 0.5, MG = 0.5, DefaultShoot = 0.5, NoAmmo = 0.4 }
  -- Kept for good, not in a table that forgets: seen live, the record of a hushed sound was
  -- collected while the sound lived on, and it stayed silent after the ragebot stopped.
  local hushed = {}                                      -- sound -> the volume it had
  local wired = {}                                       -- a gun's ShootSound -> its Played link
  local function mineOf(sound)
    local me, pack = B.character(), LP:FindFirstChildOfClass("Backpack")
    return (me ~= nil and sound:IsDescendantOf(me)) or (pack ~= nil and sound:IsDescendantOf(pack))
  end
  local function quiet() return O.muteGuns == "always" or (O.muteGuns == "auto" and (DH.on or DH.farming == true)) end
  local function hush(sound)
    if hushed[sound] == nil then hushed[sound] = sound.Volume > 0 and sound.Volume or (GAME_VOLUME[sound.Name] or 0.5) end
    if sound.Volume ~= 0 then sound.Volume = 0 end
  end
  local function unhush()
    for sound, volume in pairs(hushed) do
      if sound.Parent then sound.Volume = volume end
    end
    table.clear(hushed)
  end
  local function tend(sound)
    if not (sound:IsA("Sound") and GUN_SOUNDS[sound.Name]) then return end
    local mine = mineOf(sound)
    if sound.Name == "ShootSound" and mine and not wired[sound] then
      wired[sound] = sound.Played:Connect(B.safe("dahood.shot", function() if not DH.on then shot() end end))
    end
    if quiet() and (mine or O.muteAll) then hush(sound) end
  end
  local function sweep()
    local on = quiet()
    if not on then unhush() end
    -- (a sound that is gone, with its gun or its body: forgotten, and its link let go)
    for sound in pairs(hushed) do
      if not sound.Parent then hushed[sound] = nil end
    end
    for sound, link in pairs(wired) do
      if not sound.Parent then link:Disconnect(); wired[sound] = nil end
    end
    local roots = { B.character(), LP:FindFirstChildOfClass("Backpack") }
    if on and O.muteAll then
      for _, player in ipairs(S.Players:GetPlayers()) do
        if player ~= LP and player.Character then roots[#roots + 1] = player.Character end
      end
    end
    for _, root in pairs(roots) do
      for _, item in ipairs(root:GetDescendants()) do tend(item) end
    end
    -- the game's own hit sound, when one from here is played in its place
    local gui = LP:FindFirstChildOfClass("PlayerGui")
    local theirs = gui and gui:FindFirstChild("HitSound", true)
    if theirs and theirs:IsA("Sound") then
      if O.muteHit and O.hitSound ~= "off" then
        if fx.theirHit == nil then fx.theirHit = theirs.Volume end
        if theirs.Volume ~= 0 then theirs.Volume = 0 end
      elseif fx.theirHit ~= nil then
        theirs.Volume = fx.theirHit
        fx.theirHit = nil
      end
    end
  end
  fx.sweep = sweep
  Motion.every(sweep, 3, "dahood.hush")
  -- (and the moment it is switched, not a third of a second later)
  for _, id in ipairs({ "dahood.on", "dahood.cash", "dahood.muteGuns", "dahood.muteAll", "dahood.muteHit", "dahood.hitSound" }) do
    Config.on(id, function() task.defer(function() if B.alive then B.try("dahood.hush", sweep) end end) end)
  end
  -- (a copy the game makes for one shot is hushed the frame it appears)
  B.connect(workspace.DescendantAdded, function(item)
    if item:IsA("Sound") and GUN_SOUNDS[item.Name] then tend(item) end
  end, "dahood.hush.added")
  B.onUnload:connect(function()
    unhush()
    for _, link in pairs(wired) do link:Disconnect() end
    local gui = LP:FindFirstChildOfClass("PlayerGui")
    local theirs = gui and gui:FindFirstChild("HitSound", true)
    if theirs and fx.theirHit ~= nil then theirs.Volume = fx.theirHit end
  end)

  -- ---------------------------------------------------------------- the target card
  -- Who is being shot at (or was last hit): face, name, health and armor as bars, what they hold.
  local cardFrame = UI.frame(api.gui, { Name = "Target", AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -118), Size = UDim2.fromOffset(250, 62),
    BackgroundColor3 = Color3.fromRGB(12, 12, 16), BackgroundTransparency = 0.28, Visible = false })
  UI.corner(cardFrame, 10)
  local rim = Instance.new("UIStroke")
  rim.Color = Color3.new(1, 1, 1)
  rim.Transparency = 0.86
  rim.Parent = cardFrame
  local face = UI.new("ImageLabel", { Name = "Face", Size = UDim2.fromOffset(42, 42), Position = UDim2.fromOffset(10, 10), BackgroundColor3 = Color3.new(1, 1, 1),
    BackgroundTransparency = 0.9, Parent = cardFrame })
  UI.corner(face, true)
  local nameLabel = UI.new("TextLabel", { Name = "Name", BackgroundTransparency = 1, Position = UDim2.fromOffset(62, 7), Size = UDim2.new(1, -150, 0, 16), FontFace = B.F.text600,
    TextSize = 13, TextColor3 = Color3.new(1, 1, 1), TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = "", Parent = cardFrame })
  local stateLabel = UI.new("TextLabel", { Name = "State", BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -10, 0, 8), Size = UDim2.fromOffset(84, 14),
    FontFace = B.F.mono500, TextSize = 10, TextColor3 = Color3.fromRGB(255, 209, 102), TextXAlignment = Enum.TextXAlignment.Right, Text = "", Parent = cardFrame })
  local function meter(y, color)
    local back = UI.frame(cardFrame, { Position = UDim2.fromOffset(62, y), Size = UDim2.new(1, -72, 0, 6), BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 0.88 })
    UI.corner(back, true)
    local fill = UI.frame(back, { Size = UDim2.fromScale(1, 1), BackgroundColor3 = color, BackgroundTransparency = 0 })
    UI.corner(fill, true)
    return fill
  end
  local healthFill = meter(27, Color3.fromRGB(110, 231, 135))
  local armorFill = meter(37, Color3.fromRGB(88, 166, 255))
  local holdLabel = UI.new("TextLabel", { Name = "Holds", BackgroundTransparency = 1, Position = UDim2.fromOffset(62, 45), Size = UDim2.new(1, -72, 0, 13), FontFace = B.F.mono500,
    TextSize = 10, TextColor3 = Color3.new(1, 1, 1), TextTransparency = 0.25, TextXAlignment = Enum.TextXAlignment.Left, TextTruncate = Enum.TextTruncate.AtEnd, Text = "", Parent = cardFrame })
  local shownFor, shownHealth, shownArmor
  -- (nothing is written for a knocked one: its empty health bar says it. The owner asked for the word gone.)
  local WORDS = { up = "", down = "", shield = "SHIELD", dead = "DEAD", loading = "LOADING", none = "NO BODY", gone = "LEFT" }
  Motion.every(function(dt)
    local now = os.clock()
    local player = DH.on and (DH.target) or nil
    if not player and now - card.at < 4 then player = card.player end
    if not (O.card and player and player.Parent) then
      if cardFrame.Visible then cardFrame.Visible = false end
      shownFor = nil
      return
    end
    if not cardFrame.Visible then cardFrame.Visible = true end
    if shownFor ~= player then
      shownFor, shownHealth, shownArmor = player, nil, nil
      face.Image = "rbxthumb://type=AvatarHeadShot&id=" .. player.UserId .. "&w=150&h=150"
      nameLabel.Text = player.DisplayName
    end
    local state = DH.stateOf(player)
    local character = player.Character
    local humanoid = character and character:FindFirstChildOfClass("Humanoid")
    local health = (humanoid and state ~= "dead") and math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1) or 0
    local armor = character and math.clamp(api.armorOf(character) / 130, 0, 1) or 0
    shownHealth = shownHealth and (shownHealth + (health - shownHealth) * math.min(1, dt * 12)) or health
    shownArmor = shownArmor and (shownArmor + (armor - shownArmor) * math.min(1, dt * 12)) or armor
    healthFill.Size = UDim2.fromScale(shownHealth, 1)
    armorFill.Size = UDim2.fromScale(shownArmor, 1)
    stateLabel.Text = WORDS[state] or ""
    local tool = character and character:FindFirstChildOfClass("Tool")
    local ammo, max = tool and tool:FindFirstChild("Ammo"), tool and tool:FindFirstChild("MaxAmmo")
    local words = tool and (tool.Name .. (ammo and (" " .. tostring(ammo.Value) .. "/" .. tostring(max and max.Value or "?")) or "")) or "nothing in hand"
    holdLabel.Text = string.format("%d hp +%d   %s", humanoid and math.floor(humanoid.Health + 0.5) or 0, character and math.floor(api.armorOf(character) + 0.5) or 0, words)
  end, 30, "dahood.card")
end

local function display(page)
  local DHfx = B.DaHood.fx
  local sound = page:section({ title = "Hit sounds", icon = "volume-2", desc = "Only you hear them. Your own files go in BasedHub/hitsounds." })
  sound:dropdown({ id = "dahood.hitSound", label = "Body hit", options = DHfx.HIT_SOUNDS, default = "tick" })
  sound:dropdown({ id = "dahood.headSound", label = "Head hit", desc = "None: the body sound.", options = DHfx.HIT_SOUNDS, default = "glass" })
  sound:dropdown({ id = "dahood.knockSound", label = "Knock", options = DHfx.KNOCK_SOUNDS, default = "kill_chime" })
  sound:slider({ id = "dahood.hitVolume", label = "Volume", min = 0, max = 100, step = 5, default = 60, suffix = "%" })
  sound:toggle({ id = "dahood.hitPitch", label = "Pitch up", desc = "Each hit in a run sounds a little higher.", default = true })
  sound:toggle({ id = "dahood.muteHit", label = "Mute hit", desc = "Hushes the game's own hit sound.", default = true })
  for _, id in ipairs({ "dahood.hitSound", "dahood.headSound", "dahood.knockSound", "dahood.shotSound" }) do
    -- picking one plays it
    Config.on(id, function(name) if Window.anyOpen() and DHfx.play then DHfx.play(name) end end)
  end

  local guns = page:section({ title = "Gun sounds", icon = "music", desc = "What a shot sounds like, to you." })
  guns:dropdown({ id = "dahood.shotSound", label = "Shot sound", desc = "Played as each shot is fired.", options = DHfx.HIT_SOUNDS, default = "off" })
  guns:slider({ id = "dahood.shotVolume", label = "Volume", min = 0, max = 100, step = 5, default = 50, suffix = "%" })
  guns:segmented({ id = "dahood.muteGuns", label = "Mute guns", desc = "Auto: while the ragebot or cash round runs.",
    options = { { "off", "Off" }, { "auto", "Auto" }, { "always", "Always" } }, default = "auto", width = 190 })
  guns:toggle({ id = "dahood.muteAll", label = "Mute all", default = false })

  local marks = page:section({ title = "Hitmarkers", icon = "target", desc = "Only you see them." })
  marks:toggle({ id = "dahood.marker", label = "Hitmarkers", default = true, children = function(sub)
    sub:dropdown({ id = "dahood.markerStyle", label = "Shape", options = DHfx.STYLES, default = "cross" })
    sub:toggle({ id = "dahood.markerWorld", label = "On the body", desc = "Off: in the middle of the screen.", default = true })
    sub:slider({ id = "dahood.markerSize", label = "Size", min = 8, max = 40, step = 1, default = 16, suffix = " px" })
    sub:slider({ id = "dahood.markerTime", label = "Stays for", min = 0.1, max = 1.5, step = 0.05, default = 0.4, suffix = " s" })
    sub:color({ id = "dahood.markerColor", label = "Body hit", default = Color3.fromRGB(255, 255, 255) })
    sub:color({ id = "dahood.markerHead", label = "Head hit", default = Color3.fromRGB(255, 209, 102) })
    sub:color({ id = "dahood.markerKnock", label = "Knock", default = Color3.fromRGB(255, 84, 84) })
  end })
  marks:toggle({ id = "dahood.damage", label = "Damage numbers", desc = "What each hit took, rising off the body.", default = true })
  marks:button({ id = "dahood.markerTry", label = "Test it", text = "Show", bindable = false, run = function()
    if DHfx.onHit then
      DHfx.onHit(false, nil)
      task.delay(0.35, function() if B.alive then DHfx.onHit(true, nil) end end)
    end
  end })
  marks:toggle({ id = "dahood.card", label = "Target card", desc = "Health, armor and gun of who you are hitting.", default = true })
end

DH.parts[#DH.parts + 1] = { id = "fx", start = start, display = display }
end
do -- dahood_guard.lua
-- ============================================================================
--  Da Hood     the guard: auto block, and two things for when you are down
--
--  Measured on the live server (2026-10-12, version 3267, two accounts three
--  studs apart, one punching and one watching its own health):
--    * Fists go straight through armor. A light punch took 12.6 to 16.2 health
--      with 130 armor on (the armor was not touched); a punch held 1.7 s took
--      77.2. One heavy punch and two light ones is a knock.
--    * "Block", true: BodyEffects.Block is there 0.08 to 0.12 s later. Blocked,
--      a light punch took 2.5 to 3.2 and a heavy one 28. BodyEffects.Defense
--      (100) falls 5 to 8 a light punch and 24 a heavy one, and comes back about
--      a quarter of a point a second. A block 0.26 s old and one 1.97 s old took
--      the same: there is no parry in this game, only the block.
--    * The puncher's BodyEffects.Attacking goes true 0.05 to 0.06 s before a
--      light punch lands, and about 1.9 s before a heavy one. So a block raised
--      on seeing it stops the heavy punch and is too late for the light one
--      (three of three landed in full). To stop those the block has to be up
--      before the swing: whenever someone is close with no gun out.
--    * While it blocks the game's own client will not fire a gun, and walks at 5.
-- ============================================================================
local B = B or ...
local S, Config, Window = B.S, B.Config, B.Window
local DH = B.DaHood

local CLOSE = 9              -- studs: someone this near with fists out can land a punch before a block is up (a punch reaches 3.6)
local LOWER = 0.35           -- s the block stays up after the last sign of a punch
local AGAIN = 0.6            -- s before a block the server does not show is asked for again
local STOMP_EVERY = 0.6      -- a stomp that misses costs about 0.55 s before another counts
local STOMP_SIDE = 2         -- studs to the side, and
local STOMP_LOW, STOMP_HIGH = 1.5, 9.5   -- studs above the torso, that a stomp counted from (measured over a body lying still)

local guard = { up = false, blocks = 0, why = nil, resets = 0, stomps = 0 }
DH.guard = guard

local function start()
  local api = DH.api
  local LP = B.LP
  local UIS = S.UserInputService
  local O
  local map = {}
  for id, default in pairs({ guard = "off", guardRange = 12, guardGun = true, unknock = true, autoStomp = false, guardHide = true }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  guard.options = O

  local lastThreat, askedAt, lastStomp, resetAt = -math.huge, -math.huge, -math.huge, -math.huge
  local function friend(player)
    local roster = B.Roster
    local entry = roster and roster.byPlayer and roster.byPlayer[player]
    return entry ~= nil and roster.isFriend(entry)
  end
  -- who is about to hit, and how it shows: a swing under way, or fists out within reach
  local function threat(root)
    local nearest, kind, nearestAway
    for _, player in ipairs(S.Players:GetPlayers()) do
      if player ~= LP and not friend(player) and DH.stateOf(player) == "up" then
        local character = player.Character
        local theirs = character:FindFirstChild("HumanoidRootPart")
        local away = theirs and (theirs.Position - root.Position).Magnitude or math.huge
        if away <= O.guardRange then
          local found
          if api.flagOf(api.effectsOf(character), "Attacking") then
            found = "swing"
          elseif (O.guard == "close" or O.guard == "god") and away <= (O.guard == "god" and O.guardRange or math.min(O.guardRange, CLOSE)) then
            -- God: anyone near with no gun out, whichever way they face (a punch can come round in a frame)
            local tool = character:FindFirstChildOfClass("Tool")
            local unarmed = not (tool and tool:FindFirstChild("Ammo"))
            local toward = (root.Position - theirs.Position)
            local facing = toward.Magnitude < 0.5 or toward.Unit:Dot(theirs.CFrame.LookVector) > 0.25
            if unarmed and (facing or O.guard == "god") then found = "close" end
          end
          if found and (not nearestAway or away < nearestAway or (found == "swing" and kind ~= "swing")) then
            nearest, kind, nearestAway = player, found, away
          end
        end
      end
    end
    return nearest, kind
  end
  guard.threat = threat
  local function set(on, why)
    local remote = api.mainEvent()
    if not remote then return end
    if on == guard.up then
      -- up already: asked for again only when the server does not show it (the game's own key let it go)
      if not on or os.clock() - askedAt < AGAIN then return end
      local effects = api.effectsOf(B.character())
      if effects and effects:FindFirstChild("Block") then return end
    end
    if on and not guard.up then
      guard.blocks += 1
      guard.why = why
    end
    guard.up = on
    askedAt = os.clock()
    remote:FireServer("Block", on)
  end
  -- a gun in the hand and the trigger held: the block comes down, the game will not fire through it
  local function firing(me)
    if not O.guardGun then return false end
    local tool = me:FindFirstChildOfClass("Tool")
    if not (tool and tool:FindFirstChild("Ammo")) then return false end
    return UIS:IsMouseButtonPressed(Enum.UserInputType.MouseButton1) and not Window.anyOpen()
  end

  local function step()
    local now = os.clock()
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    local effects = api.effectsOf(me)
    local able = me and root and humanoid and effects and humanoid.Health > 0 and not api.flagOf(effects, "Dead")
    local knocked = able and api.flagOf(effects, "K.O")
    -- the block: only for a body that is standing where others can reach it
    if O.guard ~= "off" and able and not knocked and not api.moving() then
      local who, kind = threat(root)
      if who and not firing(me) then
        lastThreat = now
        set(true, (kind == "swing" and "a swing from " or "fists out: ") .. who.Name)
      elseif guard.up and (now - lastThreat > LOWER or firing(me)) then
        set(false)
      end
    elseif guard.up then
      set(false)
    end
    -- Knocked: gone before the stomp, if that is asked for. The game's own reset is asked for once
    -- (measured: it does nothing to a knocked body inside 0.3 s). What works is the body's health
    -- put to nothing by its own client, and that is written every frame until it holds. Measured
    -- on 2026-10-13: written once, the instant the flag showed, the server put the health back
    -- and the body lay there for the 1.5 s until the next try (which held: dead 0.05 s after it);
    -- the day before, one written 0.3 s after the knock held at once.
    if O.unknock and knocked then
      if now - resetAt > 3 then
        resetAt = now
        guard.resets += 1
        local remote = api.mainEvent()
        if remote then remote:FireServer("ResetNew") end
      end
      humanoid.Health = 0
    end
    -- standing on a knocked body: stomp it
    if O.autoStomp and able and not knocked and not api.moving() and now - lastStomp >= STOMP_EVERY then
      for _, player in ipairs(S.Players:GetPlayers()) do
        if player ~= LP and not friend(player) and DH.stateOf(player) == "down" then
          local torso = api.torsoOf(player.Character)
          local off = torso and (root.Position - torso.Position)
          if off and off.Y >= STOMP_LOW and off.Y <= STOMP_HIGH and Vector3.new(off.X, 0, off.Z).Magnitude <= STOMP_SIDE then
            local remote = api.mainEvent()
            if remote then
              lastStomp = now
              guard.stomps += 1
              remote:FireServer("Stomp")
            end
            break
          end
        end
      end
    end
  end
  B.connect(S.RunService.Heartbeat, step, "dahood.guard")
  -- The game plays ReplicatedStorage.ClientAnimations.Block on this body when the block goes up
  -- (Framework, Blocking(true)). With Hide pose on, that one track is stopped as it starts: the
  -- server still has BodyEffects.Block, so blows are blocked, and nobody sees the stance.
  -- (looked for on a thread of its own: a game without it would hold every tab back while it waited)
  local blockId
  task.spawn(function()
    pcall(function() blockId = S.ReplicatedStorage:WaitForChild("ClientAnimations", 5):WaitForChild("Block", 5).AnimationId end)
    B.identity()
  end)
  local function watchAnimator(character)
    local humanoid = character and character:WaitForChild("Humanoid", 10)
    local animator = humanoid and humanoid:WaitForChild("Animator", 10)
    if not animator then return end
    B.connect(animator.AnimationPlayed, function(track)
      if O.guardHide and O.guard ~= "off" and track.Animation and track.Animation.AnimationId == blockId then track:Stop(0) end
    end, "dahood.guard.pose")
  end
  if LP.Character then task.spawn(watchAnimator, LP.Character) end
  B.connect(LP.CharacterAdded, function(character) task.spawn(watchAnimator, character) end, "dahood.guard.char")
  Config.on("dahood.guard", function(mode) if mode == "off" and guard.up then set(false) end end)
  B.onUnload:connect(function()
    if guard.up then
      local remote = api.mainEvent()
      if remote then pcall(function() remote:FireServer("Block", false) end) end
      guard.up = false
    end
  end)
end

local function player(page)
  local Motion = B.Motion
  local defence = page:section({ title = "Survival", icon = "shield", desc = "For your own body, while the ragebot is off." })
  defence:segmented({ id = "dahood.guard", label = "Auto block", desc = "God: blocks anyone near before a hit lands.",
    options = { { "off", "Off" }, { "swings", "Swings" }, { "close", "Close" }, { "god", "God" } }, default = "off", width = 250 })
  defence:toggle({ id = "dahood.guardHide", label = "Hide block pose", desc = "Still blocks; nobody sees the stance.", default = true })
  defence:slider({ id = "dahood.guardRange", label = "Within", desc = "How near someone has to be.", min = 5, max = 30, step = 1, default = 12, suffix = " st" })
  defence:toggle({ id = "dahood.guardGun", label = "Drop block to shoot", desc = "Drops the block while you fire a gun.", default = true })
  local HOW = "Swings: on a wind-up. Close: fists out and facing you. God: anyone near without a gun. A block takes four fifths off."
  local line = defence:note({ icon = "info", text = HOW })
  defence:toggle({ id = "dahood.unknock", label = "Anti stomp", desc = "Respawns before anyone can stomp you, and you keep your guns.", default = true })
  defence:toggle({ id = "dahood.autoStomp", label = "Auto stomp", desc = "Stomps any knocked player you stand on.", default = false })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local g = B.DaHood.guard
    if g.blocks == 0 then line.set(HOW)
    else line.set(string.format("%s    Blocked %d time%s%s.", g.up and "Blocking." or "Down.", g.blocks, g.blocks == 1 and "" or "s", g.why and (", the last for " .. g.why) or "")) end
  end, 2, "dahood.guard.line")
end

DH.parts[#DH.parts + 1] = { id = "guard", start = start, player = player }
end
do -- dahood_hunt.lua
-- ============================================================================
--  Da Hood     the hunt panel: hold the ragebot's key, pick who to hunt
--
--  A tap of the ragebot's key flips it, as always. Held (0.3 s, Config.holdPanels),
--  a small panel slides out beside the key list: everyone in the server, nearest
--  first, with their health; click one to mark or unmark them, right click to
--  spare them, type to find one. Let go of the key and it goes, unless the mouse
--  is on it or its search is in use (then it goes when the mouse leaves). Drawn
--  in the look in use (Window.activeKit).
-- ============================================================================
local B = B or ...
local S, Config, Window, UI, Motion = B.S, B.Config, B.Window, B.UI, B.Motion
local DH = B.DaHood
local Players = S.Players
local UIS = S.UserInputService
local TS = S.TweenService

local hunt = { open = false }
DH.hunt = hunt
local OPEN = TweenInfo.new(0.26, Enum.EasingStyle.Quint, Enum.EasingDirection.Out)
local SHUT = TweenInfo.new(0.16, Enum.EasingStyle.Quad, Enum.EasingDirection.In)
local W, ROW = 300, 46

local function frame(parent, props)
  local f = Instance.new("Frame")
  f.BorderSizePixel, f.BackgroundTransparency = 0, 1
  for key, value in pairs(props or {}) do f[key] = value end
  f.Parent = parent
  return f
end
local function hitbox(parent, props)
  local b = Instance.new("TextButton")
  b.Text, b.AutoButtonColor, b.BackgroundTransparency, b.BorderSizePixel, b.Size, b.ZIndex = "", false, 1, 0, UDim2.fromScale(1, 1), 8
  for key, value in pairs(props or {}) do b[key] = value end
  b.Parent = parent
  return b
end
local function round(f, r)
  local c = Instance.new("UICorner")
  c.CornerRadius = r == true and UDim.new(1, 0) or UDim.new(0, r)
  c.Parent = f
end
local function glyph(parent, name, size, kit, role, props)
  local image = Instance.new("ImageLabel")
  image.BackgroundTransparency, image.BorderSizePixel = 1, 0
  image.Size = UDim2.fromOffset(size, size)
  UI.setIcon(image, name)
  kit.paint(image, "ImageColor3", role or "text")
  for key, value in pairs(props or {}) do image[key] = value end
  image.Parent = parent
  return image
end

local function spared(player)
  local entry = B.Roster and B.Roster.byPlayer[player]
  return entry ~= nil and B.Roster.isFriend(entry)
end
local function others()
  local out = {}
  for _, player in ipairs(Players:GetPlayers()) do
    if player ~= B.LP then out[#out + 1] = player end
  end
  return out
end
local function bodyOf(player)
  local character = player.Character
  local root = character and (character:FindFirstChild("UpperTorso") or character:FindFirstChild("HumanoidRootPart"))
  local humanoid = character and character:FindFirstChildOfClass("Humanoid")
  return root, humanoid
end

-- the panel: built once a look, kept (shown and hidden), rows redrawn when the list changes
local panel
local function build()
  local kit = Window.activeKit()
  local square = kit.look == "unnamed"
  local holder = Instance.new("CanvasGroup")
  holder.Name = "Hunt"
  holder.BackgroundTransparency, holder.BorderSizePixel = 1, 0
  holder.Size = UDim2.fromOffset(W, 0)
  holder.AutomaticSize = Enum.AutomaticSize.Y
  holder.GroupTransparency = 1
  holder.Visible = false
  holder.ZIndex = 40
  holder.Parent = Window.hud
  local sizer = Instance.new("UIScale"); sizer.Parent = holder
  local card = frame(holder, { Name = "Card", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
  if kit.look == "novoline" and B.Novoline and B.Novoline.glass then
    B.Novoline.glass(card, 20, false)
  elseif kit.look == "based" then
    card.BackgroundColor3, card.BackgroundTransparency = Color3.fromRGB(14, 14, 18), 0.06
    round(card, 16)
    UI.stroke(card, "ink", "strokeA")
  else
    kit.fill(card, "back")
    kit.outline(card)
  end
  local stack = frame(card, { Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
  local padding = Instance.new("UIPadding")
  padding.PaddingTop, padding.PaddingBottom, padding.PaddingLeft, padding.PaddingRight = UDim.new(0, 12), UDim.new(0, 12), UDim.new(0, 12), UDim.new(0, 12)
  padding.Parent = stack
  local layout = Instance.new("UIListLayout"); layout.Padding = UDim.new(0, 8); layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Parent = stack
  -- the head: what it is, and how many are marked
  local head = frame(stack, { Size = UDim2.new(1, 0, 0, 34), LayoutOrder = 1 })
  glyph(head, "crosshair", 18, kit, "accent", { Position = UDim2.fromOffset(0, 2) })
  kit.text(head, "Hunt", { Position = UDim2.fromOffset(26, 0), Size = UDim2.new(1, -90, 0, 18) }, true, kit.size + 2)
  local hint = kit.text(head, "Click: mark  ·  right click: spare", { Position = UDim2.fromOffset(26, 18), Size = UDim2.new(1, -90, 0, 14) }, false, kit.size - 3)
  kit.paint(hint, "TextColor3", "dim")
  local count = kit.text(head, "", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 2), Size = UDim2.fromOffset(70, 16), TextXAlignment = Enum.TextXAlignment.Right },
    true, kit.size - 1)
  kit.paint(count, "TextColor3", "accent")
  -- the search
  local field = frame(stack, { Size = UDim2.new(1, 0, 0, 30), LayoutOrder = 2 })
  kit.fill(field, "field")
  if square then kit.outline(field) else round(field, 10) end
  glyph(field, "search", 14, kit, "faint", { AnchorPoint = Vector2.new(0, 0.5), Position = UDim2.new(0, 10, 0.5, 0) })
  local search = kit.entry(field, kit.size)
  search.Position, search.Size = UDim2.fromOffset(30, 0), UDim2.new(1, -40, 1, 0)
  search.PlaceholderText, search.Text = "Find someone", ""
  -- the players
  local area = frame(stack, { Size = UDim2.new(1, 0, 0, ROW * 6), LayoutOrder = 3, ClipsDescendants = true })
  local scroller = Instance.new("ScrollingFrame")
  scroller.BackgroundTransparency, scroller.BorderSizePixel = 1, 0
  scroller.Size, scroller.CanvasSize, scroller.AutomaticCanvasSize = UDim2.fromScale(1, 1), UDim2.new(), Enum.AutomaticSize.Y
  scroller.ScrollBarThickness, scroller.ScrollingDirection = 3, Enum.ScrollingDirection.Y
  kit.paint(scroller, "ScrollBarImageColor3", "accent")
  scroller.Parent = area
  local rowsLayout = Instance.new("UIListLayout"); rowsLayout.Padding = UDim.new(0, 3); rowsLayout.SortOrder = Enum.SortOrder.LayoutOrder; rowsLayout.Parent = scroller
  -- the foot: everyone, the nearest, clear
  local foot = frame(stack, { Size = UDim2.new(1, 0, 0, 28), LayoutOrder = 4 })
  local footLayout = Instance.new("UIListLayout")
  footLayout.FillDirection, footLayout.Padding, footLayout.SortOrder = Enum.FillDirection.Horizontal, UDim.new(0, 6), Enum.SortOrder.LayoutOrder
  footLayout.Parent = foot
  local buttons = {}
  local function footButton(label, order, run)
    local b = frame(foot, { Size = UDim2.new(1 / 3, -4, 1, 0), LayoutOrder = order })
    kit.fill(b, "field")
    if square then kit.outline(b) else round(b, true) end
    local text = kit.text(b, label, { Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center }, true, kit.size - 2)
    local hit = hitbox(b)
    hit.MouseEnter:Connect(function() kit.fill(b, "hover") end)
    hit.MouseLeave:Connect(function() if b:GetAttribute("On") then kit.fill(b, "accent") else kit.fill(b, "field") end end)
    hit.Activated:Connect(B.safe("dahood.hunt.foot", function() UI.sfx("click", 0.5); run() end))
    buttons[label] = { frame = b, text = text }
    return b
  end
  footButton("Everyone", 1, function() Config.set("dahood.everyone", not Config.get("dahood.everyone")) end)
  footButton("Nearest", 2, function() if DH.markNearest then DH.markNearest() end end)
  footButton("Clear", 3, function() if DH.clearMarks then DH.clearMarks() end end)
  local function paintFoot()
    local every = buttons.Everyone
    local on = Config.get("dahood.everyone") == true
    every.frame:SetAttribute("On", on)
    kit.fill(every.frame, on and "accent" or "field")
    kit.paint(every.text, "TextColor3", on and "onAccent" or "text")
  end
  paintFoot()
  Config.on("dahood.everyone", function() if holder.Parent then paintFoot() end end)
  -- (frees the mouse while it is open: first person, shift lock)
  local modal = Instance.new("TextButton")
  modal.Text, modal.BackgroundTransparency, modal.Size, modal.Modal, modal.Visible = "", 1, UDim2.fromOffset(0, 0), true, false
  modal.Parent = holder
  local rows = {}
  local function paintRow(row)
    local player = row.player
    local marked = DH.isMarked and DH.isMarked(player)
    local spare = spared(player)
    if marked then kit.fill(row.frame, "field") else kit.clear(row.frame) end
    row.ring.Enabled = marked
    kit.paint(row.name, "TextColor3", marked and "accent" or (spare and "dim" or "text"))
    row.tag.Text = marked and "HUNTED" or (spare and "SPARED" or "")
    kit.paint(row.tag, "TextColor3", marked and "accent" or "faint")
  end
  local function redraw()
    for _, child in ipairs(scroller:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
    table.clear(rows)
    local wanted = string.lower(search.Text or "")
    local me = B.root()
    local list = {}
    for _, player in ipairs(others()) do
      if wanted == "" or string.find(string.lower(player.Name), wanted, 1, true) or string.find(string.lower(player.DisplayName), wanted, 1, true) then
        local root = bodyOf(player)
        list[#list + 1] = { player = player, away = (root and me) and (root.Position - me.Position).Magnitude or math.huge }
      end
    end
    table.sort(list, function(a, b)
      local ma, mb = DH.isMarked and DH.isMarked(a.player), DH.isMarked and DH.isMarked(b.player)
      if ma ~= mb then return ma end
      return a.away < b.away
    end)
    -- (as tall as the people in it, up to six)
    area.Size = UDim2.new(1, 0, 0, math.clamp(#list, 1, 6) * (ROW + 3))
    if #list == 0 then
      local empty = kit.text(scroller, wanted == "" and "Nobody else is here." or "Nobody by that name.", { Size = UDim2.new(1, 0, 0, 30), TextXAlignment = Enum.TextXAlignment.Center },
        false, kit.size - 1)
      kit.paint(empty, "TextColor3", "dim")
    end
    for index, item in ipairs(list) do
      local player = item.player
      local line = frame(scroller, { Name = player.Name, Size = UDim2.new(1, -4, 0, ROW), LayoutOrder = index })
      if not square then round(line, 10) end
      local face = Instance.new("ImageLabel")
      face.BorderSizePixel, face.Size, face.Position = 0, UDim2.fromOffset(34, 34), UDim2.fromOffset(6, 6)
      face.Image = "rbxthumb://type=AvatarHeadShot&id=" .. tostring(player.UserId) .. "&w=48&h=48"
      kit.fill(face, "field")
      if square then kit.outline(face) else round(face, true) end
      face.Parent = line
      local ring = Instance.new("UIStroke")
      ring.Thickness, ring.ApplyStrokeMode = 2, Enum.ApplyStrokeMode.Border
      kit.paint(ring, "Color", "accent")
      ring.Parent = face
      local name = kit.text(line, player.DisplayName, { Position = UDim2.fromOffset(48, 6), Size = UDim2.new(1, -120, 0, 17), TextTruncate = Enum.TextTruncate.AtEnd }, true, kit.size)
      local sub = kit.text(line, "@" .. player.Name, { Position = UDim2.fromOffset(48, 23), Size = UDim2.new(1, -120, 0, 14), TextTruncate = Enum.TextTruncate.AtEnd }, false, kit.size - 3)
      kit.paint(sub, "TextColor3", "dim")
      local away = kit.text(line, "", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 6), Size = UDim2.fromOffset(60, 14), TextXAlignment = Enum.TextXAlignment.Right },
        false, kit.size - 2)
      kit.paint(away, "TextColor3", "dim")
      local tag = kit.text(line, "", { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 24), Size = UDim2.fromOffset(60, 12), TextXAlignment = Enum.TextXAlignment.Right },
        true, kit.size - 4)
      local bar = frame(line, { AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 48, 1, -4), Size = UDim2.new(1, -120, 0, 2) })
      kit.fill(bar, "field")
      local fill = frame(bar, { Size = UDim2.fromScale(1, 1) })
      kit.fill(fill, "good")
      local row = { player = player, frame = line, ring = ring, name = name, tag = tag, away = away, fill = fill }
      rows[#rows + 1] = row
      paintRow(row)
      local hit = hitbox(line)
      hit.MouseEnter:Connect(function() kit.fill(line, "hover") end)
      hit.MouseLeave:Connect(function() paintRow(row) end)
      hit.Activated:Connect(B.safe("dahood.hunt.mark", function()
        if not DH.mark then return end
        UI.sfx("click", 0.5)
        if spared(player) then B.Roster.setFriend(B.Roster.byPlayer[player], false) end
        DH.mark(player, not DH.isMarked(player))
        paintRow(row)
      end))
      hit.MouseButton2Click:Connect(B.safe("dahood.hunt.spare", function()
        local entry = B.Roster and B.Roster.byPlayer[player]
        if not entry then return end
        UI.sfx("click", 0.4)
        local on = not spared(player)
        B.Roster.setFriend(entry, on)
        if on and DH.isMarked(player) then DH.mark(player, false) end
        if DH.onTargets then DH.onTargets:fire() end
        paintRow(row)
      end))
    end
    local marked = 0
    for _, player in ipairs(others()) do if DH.isMarked and DH.isMarked(player) then marked += 1 end end
    count.Text = marked > 0 and (marked .. " hunted") or ""
  end
  search:GetPropertyChangedSignal("Text"):Connect(function() if holder.Visible then redraw() end end)
  -- distance and health, a few times a second while it shows
  Motion.every(function()
    if not holder.Visible then return end
    local me = B.root()
    for _, row in ipairs(rows) do
      local root, humanoid = bodyOf(row.player)
      if root and me then row.away.Text = math.floor((root.Position - me.Position).Magnitude) .. " st" else row.away.Text = "" end
      local health = humanoid and math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1) or 0
      row.fill.Size = UDim2.fromScale(health, 1)
    end
  end, 6, "dahood.hunt.live")
  panel = { holder = holder, sizer = sizer, search = search, redraw = redraw, look = kit.look, modal = modal }
  return panel
end

-- where it goes: beside the key list (to its left), or the bottom right corner without one
local function place()
  local holder = panel.holder
  local list = B.Keys and B.Keys.panel
  holder.AnchorPoint = Vector2.new(1, 1)
  if list and list.Visible and list.AbsoluteSize.X > 0 then
    local layer = Window.hud.AbsolutePosition
    local at = list.AbsolutePosition - layer
    holder.Position = UDim2.fromOffset(at.X - 12, at.Y + list.AbsoluteSize.Y)
  else
    holder.Position = UDim2.new(1, -16, 1, -16)
  end
end
function hunt.show(on)
  if on == hunt.open then return end
  hunt.open = on
  if on then
    if not panel or panel.look ~= Window.activeKit().look or not panel.holder.Parent then
      if panel then panel.holder:Destroy() end
      build()
    end
    local holder = panel.holder
    panel.sizer.Scale = math.clamp((Window.scale or 1), 0.8, 1.2)
    panel.redraw()
    place()
    holder.Visible = true
    panel.modal.Visible = true
    holder.GroupTransparency = 1
    local rest = holder.Position
    holder.Position = rest + UDim2.fromOffset(16, 0)
    panel.sizer.Scale = panel.sizer.Scale * 0.95
    TS:Create(holder, OPEN, { GroupTransparency = 0, Position = rest }):Play()
    TS:Create(panel.sizer, OPEN, { Scale = math.clamp((Window.scale or 1), 0.8, 1.2) }):Play()
    UI.sfx("open", 0.35)
  elseif panel then
    local holder = panel.holder
    panel.modal.Visible = false
    if panel.search:IsFocused() then panel.search:ReleaseFocus() end
    TS:Create(holder, SHUT, { GroupTransparency = 1, Position = holder.Position + UDim2.fromOffset(12, 0) }):Play()
    task.delay(0.17, function() if not hunt.open and holder.Parent then holder.Visible = false end end)
  end
end
-- let go of the key: shut, unless it is being used (then shut when the mouse leaves it)
local function release()
  if not panel or not hunt.open then return end
  local function inUse()
    if panel.search:IsFocused() then return true end
    local point = UI.mouse()
    local at, size = panel.holder.AbsolutePosition, panel.holder.AbsoluteSize
    return point.X >= at.X and point.X <= at.X + size.X and point.Y >= at.Y and point.Y <= at.Y + size.Y
  end
  if not inUse() then hunt.show(false); return end
  task.spawn(function()
    local away = 0
    while hunt.open do
      task.wait(0.1)
      if inUse() then away = 0 else away += 0.1 end
      if away >= 0.35 then hunt.show(false) end
    end
  end)
end

local function start()
  Config.holdPanels["dahood.on"] = { open = function() hunt.show(true) end, close = release }
  B.connect(UIS.InputBegan, function(input)
    if not hunt.open or not panel then return end
    if input.KeyCode == Enum.KeyCode.Escape then hunt.show(false); return end
    if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.MouseButton2 then
      local point = UI.point(input)
      local at, size = panel.holder.AbsolutePosition, panel.holder.AbsoluteSize
      local inside = point.X >= at.X and point.X <= at.X + size.X and point.Y >= at.Y and point.Y <= at.Y + size.Y
      local key = Config.bindOf("dahood.on")
      if not inside and not (key and Config.keyDown(key.key)) then hunt.show(false) end
    end
  end, "dahood.hunt.outside")
  if DH.onTargets then DH.onTargets:connect(function() if hunt.open and panel then panel.redraw() end end) end
  B.connect(Players.PlayerAdded, function() if hunt.open and panel then panel.redraw() end end, "dahood.hunt.added")
  B.connect(Players.PlayerRemoving, function() if hunt.open and panel then task.defer(panel.redraw) end end, "dahood.hunt.left")
  B.onUnload:connect(function() Config.holdPanels["dahood.on"] = nil end)
end

DH.parts[#DH.parts + 1] = { id = "hunt", start = start }
end
do -- dahood_skins.lua
-- ============================================================================
--  Da Hood     skins: any gun skin the game has, on your own guns, on your screen
--
--  Read from the game (version 3275): ReplicatedStorage.SkinModules returns
--  every skin by gun ("[AUG]" -> "Shadow" -> { TextureID, CFrame, Rarity }).
--  TextureID is a texture for the gun's own mesh, or a mesh of its own placed
--  at the gun's mesh times CFrame (the game's own skinModel does the same for
--  its shop). The handle's "SkinName" is what the game's shot effects read
--  (muzzle particles from ReplicatedStorage.SkinAssets). ~1,265 skins, five
--  rarities, the Halloween 26 set among them.
--
--  Only this client sees it: the gun is the server's, and nothing here is sent.
-- ============================================================================
local B = B or ...
local S, Config, Window, UI, Motion, T, Theme = B.S, B.Config, B.Window, B.UI, B.Motion, B.T, B.Theme
local DH = B.DaHood

local RARITY = { Exclusive = 1, Legendary = 2, Epic = 3, Rare = 4, Common = 5 }
local TINT = { Exclusive = Color3.fromRGB(255, 92, 120), Legendary = Color3.fromRGB(255, 196, 64), Epic = Color3.fromRGB(196, 110, 255),
  Rare = Color3.fromRGB(80, 160, 255), Common = Color3.fromRGB(170, 170, 180) }
local NOT_GUNS = { ["[Knife]"] = true, ["[House]"] = true, ["[Wallet]"] = true, ["[Bat]"] = true, ["[Stomps]"] = true, ["[Vehicle]"] = true, ["[Mask]"] = true }

local skins = { data = nil, guns = {}, applied = {}, changed = B.Signal.new() }
DH.skins = skins

-- (waits for the game's list only when asked to, on a thread of its own: from a page being drawn it
-- is looked for, never waited on)
local function load(wait)
  if skins.data then return skins.data end
  local ok, data = pcall(function()
    local module = wait and S.ReplicatedStorage:WaitForChild("SkinModules", 10) or S.ReplicatedStorage:FindFirstChild("SkinModules")
    return module and require(module)
  end)
  B.identity()
  if not ok or type(data) ~= "table" then return nil end
  skins.data = data
  table.clear(skins.guns)
  for gun, list in pairs(data) do
    if type(gun) == "string" and string.sub(gun, 1, 1) == "[" and not NOT_GUNS[gun] and type(list) == "table" and next(list) ~= nil then
      skins.guns[#skins.guns + 1] = gun
    end
  end
  table.sort(skins.guns)
  return data
end
-- a gun's skins, best first: { name, label, rarity }
function skins.list(gun)
  local data = load()
  local out = {}
  for name, entry in pairs(data and data[gun] or {}) do
    if type(entry) == "table" and entry.TextureID ~= nil then
      out[#out + 1] = { name = name, label = type(entry.DisplayName) == "string" and (entry.DisplayName .. "  ·  " .. name) or name, rarity = entry.Rarity or "Common" }
    end
  end
  table.sort(out, function(a, b)
    local ra, rb = RARITY[a.rarity] or 9, RARITY[b.rarity] or 9
    if ra ~= rb then return ra < rb end
    return a.name < b.name
  end)
  return out
end

-- dress a gun's mesh in a skin (the shop's own way); returns what to undo.
-- Measured 2026-10-22: the shop puts the AUG's Shadow 0.05 studs from the gun; held with a
-- WeldConstraint it sat 6.6 studs off the equipped gun (a constraint keeps the gap it first sees,
-- and a gun in the bag is not where the hand puts it). A Weld carries the offset itself: right
-- wherever and whenever the gun is.
local function dress(base, entry, parent)
  local undo = { base = base, texture = base:IsA("MeshPart") and base.TextureID or nil, alpha = base.Transparency }
  local offset = typeof(entry.CFrame) == "CFrame" and entry.CFrame or CFrame.new()
  if type(entry.TextureID) == "string" then
    if base:IsA("MeshPart") then
      base.TextureID = entry.TextureID
    else
      local mesh = base:FindFirstChildOfClass("SpecialMesh")
      if mesh then undo.mesh, undo.meshTexture = mesh, mesh.TextureId; mesh.TextureId = entry.TextureID end
    end
    undo.want = entry.TextureID
  elseif typeof(entry.TextureID) == "Instance" then
    local copy = entry.TextureID:Clone()
    local all = copy:GetDescendants()
    table.insert(all, copy)
    local root = copy:IsA("BasePart") and copy or (copy:IsA("Model") and (copy.PrimaryPart or copy:FindFirstChildWhichIsA("BasePart", true))) or nil
    if not root then copy:Destroy(); return undo end
    -- every other part keeps its place against the root; the skin's own joints go (they are rebuilt)
    local rel, visible = {}, false
    for _, part in ipairs(all) do
      if part:IsA("BasePart") then
        if part ~= root then rel[part] = root.CFrame:ToObjectSpace(part.CFrame) end
        part.Anchored, part.CanCollide, part.CanQuery, part.CanTouch, part.Massless = false, false, false, false, true
        if part.Transparency < 1 then visible = true end
      elseif part:IsA("LuaSourceContainer") or part:IsA("JointInstance") or part:IsA("WeldConstraint") then
        part:Destroy()
      end
    end
    -- (a skin the game ships all see-through, the RPG's Paper: it was picked to be seen)
    if not visible then root.Transparency = 0 end
    root.CFrame = base.CFrame * offset
    local weld = Instance.new("Weld")
    weld.Part0, weld.Part1, weld.C0 = base, root, offset
    weld.Parent = root
    for part, at in pairs(rel) do
      part.CFrame = root.CFrame * at
      local hold = Instance.new("Weld")
      hold.Part0, hold.Part1, hold.C0 = root, part, at
      hold.Parent = part
    end
    copy.Name = "BasedSkin"
    copy.Parent = parent
    base.Transparency = 1
    undo.clone = copy
  end
  return undo
end
local function undress(undo)
  if not undo then return end
  if undo.clone then undo.clone:Destroy() end
  if undo.mesh and undo.mesh.Parent then undo.mesh.TextureId = undo.meshTexture end
  if undo.base and undo.base.Parent then
    if undo.texture and undo.base:IsA("MeshPart") then undo.base.TextureID = undo.texture end
    undo.base.Transparency = undo.alpha
  end
end
skins.dress, skins.undress = dress, undress

local function start()
  local LP = B.LP
  Config.define("dahood.skinsOn", true)
  Config.define("dahood.skins", {})
  Config.define("dahood.skinGun", "[Double-Barrel SG]")
  local function chosen(gun) local map = Config.get("dahood.skins"); return type(map) == "table" and map[gun] or nil end
  skins.chosen = chosen
  local function revert(tool)
    local state = skins.applied[tool]
    if not state then return end
    skins.applied[tool] = nil
    for _, link in ipairs(state.links or {}) do link:Disconnect() end
    undress(state.undo)
    local handle = tool:FindFirstChild("Handle")
    if handle and state.attr ~= false then pcall(function() handle:SetAttribute("SkinName", state.attr) end) end
  end
  local function apply(tool)
    if not (tool and tool:IsA("Tool")) or NOT_GUNS[tool.Name] then return end
    local data = load()
    local want = Config.get("dahood.skinsOn") and chosen(tool.Name) or nil
    local state = skins.applied[tool]
    if (state and state.skin) == want then return end
    revert(tool)
    local entry = want and data and data[tool.Name] and data[tool.Name][want]
    local base = tool:FindFirstChild("Default")
    if not (entry and base and base:IsA("BasePart")) then return end
    local handle = tool:FindFirstChild("Handle")
    local was = handle and handle:GetAttribute("SkinName")
    local state = { skin = want, undo = dress(base, entry, tool), attr = handle and was or false, links = {} }
    skins.applied[tool] = state
    -- (the game's shot effects read this: the skin's muzzle flash, on this screen)
    if handle then handle:SetAttribute("SkinName", want) end
    -- whatever the game writes back over the skin (a gun handed out again, an equip) is put back
    local function hold()
      if skins.applied[tool] ~= state or not base.Parent then return end
      local undo = state.undo
      if undo.want and base:IsA("MeshPart") and base.TextureID ~= undo.want then base.TextureID = undo.want end
      if undo.clone and base.Transparency ~= 1 then base.Transparency = 1 end
      if undo.clone and not undo.clone.Parent then
        local fresh = dress(base, entry, tool)
        fresh.alpha, fresh.texture = undo.alpha, undo.texture
        state.undo = fresh
      end
      if handle and handle.Parent and handle:GetAttribute("SkinName") ~= want then handle:SetAttribute("SkinName", want) end
    end
    if base:IsA("MeshPart") then state.links[#state.links + 1] = base:GetPropertyChangedSignal("TextureID"):Connect(hold) end
    state.links[#state.links + 1] = base:GetPropertyChangedSignal("Transparency"):Connect(hold)
    state.links[#state.links + 1] = tool.Equipped:Connect(function() task.delay(0.15, hold) end)
  end
  skins.apply = apply
  local function sweep()
    for tool in pairs(skins.applied) do
      if not tool.Parent then skins.applied[tool] = nil end
    end
    local me = B.character()
    for _, holder in ipairs({ me, LP:FindFirstChildOfClass("Backpack") }) do
      for _, tool in ipairs(holder and holder:GetChildren() or {}) do
        if tool:IsA("Tool") then B.try("dahood.skin", apply, tool) end
      end
    end
  end
  skins.sweep = sweep
  -- every gun that turns up in the hand or the bag, now and in every life to come
  local function watch(holder)
    if not holder then return end
    B.connect(holder.ChildAdded, function(child) if child:IsA("Tool") then task.defer(function() B.try("dahood.skin", apply, child) end) end end, "dahood.skins.watch")
  end
  watch(LP:FindFirstChildOfClass("Backpack"))
  watch(LP.Character)
  B.connect(LP.CharacterAdded, function(character)
    watch(character)
    task.defer(function() watch(LP:FindFirstChildOfClass("Backpack")); sweep() end)
  end, "dahood.skins.char")
  Config.on("dahood.skins", function() sweep(); skins.changed:fire() end)
  Config.on("dahood.skinsOn", function() sweep(); skins.changed:fire() end)
  B.onUnload:connect(function()
    for tool in pairs(table.clone(skins.applied)) do pcall(revert, tool) end
  end)
  task.defer(sweep)
end

-- ---------------------------------------------------------------- the tab
local function choose(gun, name)
  local map = table.clone(Config.get("dahood.skins") or {})
  map[gun] = name
  Config.set("dahood.skins", map)
end
-- small pieces drawn in the look the tab is in (Window.kit): BASED, Unnamed or Novoline
local function frame(parent, props)
  local f = Instance.new("Frame")
  f.BorderSizePixel, f.BackgroundTransparency = 0, 1
  for key, value in pairs(props or {}) do f[key] = value end
  f.Parent = parent
  return f
end
local function hitbox(parent, props)
  local b = Instance.new("TextButton")
  b.Text, b.AutoButtonColor, b.BackgroundTransparency, b.BorderSizePixel, b.Size, b.ZIndex = "", false, 1, 0, UDim2.fromScale(1, 1), 8
  for key, value in pairs(props or {}) do b[key] = value end
  b.Parent = parent
  return b
end
-- the live picture: the gun turning on a stand, in the skin picked (or the one under the pointer)
local function preview(holder)
  local kit = Window.kit(holder)
  local square = kit.look == "unnamed"
  local stage = frame(holder, { Name = "Stage", Size = UDim2.new(1, 0, 1, -6), ClipsDescendants = true })
  kit.fill(stage, "field")
  if square then kit.outline(stage) else kit.corner(stage, kit.small) end
  local view = Instance.new("ViewportFrame")
  view.Name, view.Size, view.BackgroundTransparency = "Gun", UDim2.fromScale(1, 1), 1
  view.Ambient, view.LightColor, view.LightDirection = Color3.fromRGB(170, 170, 180), Color3.new(1, 1, 1), Vector3.new(-0.5, -1, -0.7)
  view.Parent = stage
  local camera = Instance.new("Camera")
  camera.FieldOfView = 26
  camera.Parent = view
  view.CurrentCamera = camera
  local title = kit.text(stage, "", { Position = UDim2.fromOffset(12, 10), Size = UDim2.new(1, -24, 0, 18), ZIndex = 3 }, true, kit.size + 2)
  local sub = kit.text(stage, "", { Position = UDim2.fromOffset(12, 30), Size = UDim2.new(1, -24, 0, 14), ZIndex = 3 }, false, kit.size - 1)
  kit.paint(sub, "TextColor3", "dim")
  local hint = kit.text(stage, "drag to turn", { AnchorPoint = Vector2.new(0.5, 1), Position = UDim2.new(0.5, 0, 1, -8), Size = UDim2.fromOffset(160, 14),
    TextXAlignment = Enum.TextXAlignment.Center, ZIndex = 3 }, false, kit.size - 3)
  kit.paint(hint, "TextColor3", "faint")
  local model, radius = nil, 2
  local shown = nil
  local function build()
    local skins = DH.skins
    local gun = Config.get("dahood.skinGun")
    local name = skins.hover or skins.chosen and skins.chosen(gun) or nil
    local key = tostring(gun) .. "/" .. tostring(name)
    if key == shown then return end
    shown = key
    if model then model:Destroy(); model = nil end
    local data = skins.data
    local folder = S.ReplicatedStorage:FindFirstChild("SkinModules")
    local source = folder and folder:FindFirstChild("GunModels") and folder.GunModels:FindFirstChild(gun)
    if not source then title.Text = tostring(gun); sub.Text = "No model for this gun."; return end
    local copy = source:Clone()
    local holderModel = Instance.new("Model")
    copy.Parent = holderModel
    local base = copy:IsA("Model") and (copy.PrimaryPart or copy:FindFirstChildWhichIsA("BasePart", true)) or copy
    for _, part in ipairs(holderModel:GetDescendants()) do
      if part:IsA("LuaSourceContainer") then part:Destroy() end
    end
    local entry = name and data and data[gun] and data[gun][name]
    if entry and base then skins.dress(base, entry, holderModel) end
    -- (in a ViewportFrame nothing moves by itself: every part is put where its weld says, then held)
    for _, part in ipairs(holderModel:GetDescendants()) do
      if part:IsA("Weld") and part.Part0 and part.Part1 then part.Part1.CFrame = part.Part0.CFrame * part.C0 * part.C1:Inverse() end
    end
    for _, part in ipairs(holderModel:GetDescendants()) do
      if part:IsA("BasePart") then part.Anchored = true end
    end
    holderModel.Parent = view
    local cf, size = holderModel:GetBoundingBox()
    radius = math.max(size.Magnitude * 0.5, 0.5)
    holderModel:PivotTo(holderModel:GetPivot() * (cf:Inverse() * holderModel:GetPivot()):Inverse())
    model = holderModel
    title.Text = name and (entry and type(entry.DisplayName) == "string" and entry.DisplayName or name) or "Default"
    sub.Text = gun .. (entry and ("  ·  " .. tostring(entry.Rarity or "")) or "")
    if entry and TINT[entry.Rarity] then
      if kit.look == "based" then Theme.unbind(title, "TextColor3") end
      title.TextColor3 = TINT[entry.Rarity]
    else
      kit.paint(title, "TextColor3", "text")
    end
  end
  local yaw, spin, idle, dragging, lastX = 0.6, 0, 0, false, nil
  local grab = hitbox(stage, { ZIndex = 5 })
  UI.drag(grab, function(point) dragging = true; lastX = point.X; hint.Visible = false end, function(point)
    local dx = point.X - lastX
    lastX = point.X
    yaw -= dx * 0.012
    spin = -dx * 0.012 / math.max(Motion.dt or 1 / 60, 1 / 240)
  end, function() dragging = false; idle = 0 end)
  local job
  job = Motion.every(function(dt)
    if not stage.Parent then job.cancel(); return end
    if not Window.showing("dahood.skins") then return end
    build()
    if not dragging then
      spin *= math.exp(-dt * 3)
      idle += dt
      yaw += spin * dt + (idle > 1.2 and 0.5 * dt or 0)
    end
    if model then
      local centre = model:GetPivot().Position
      camera.CFrame = CFrame.lookAt(centre + Vector3.new(math.sin(yaw), 0.32, math.cos(yaw)).Unit * (radius * 4.4 + 0.5), centre)
    end
  end, nil, "dahood.skins.preview")
end
-- the list of one gun's skins: search, rarity colours, a mark on the one worn, hover to preview
local function picker(holder)
  local kit = Window.kit(holder)
  local square = kit.look == "unnamed"
  local field = frame(holder, { Name = "Search", Size = UDim2.new(1, -96, 0, 30) })
  kit.fill(field, "field")
  if square then kit.outline(field) else kit.corner(field, kit.small) end
  local box = kit.entry(field, kit.size)
  box.Position, box.Size = UDim2.fromOffset(10, 0), UDim2.new(1, -20, 1, 0)
  box.PlaceholderText, box.Text = "Search skins", ""
  local clear = frame(holder, { Name = "Default", AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 0), Size = UDim2.fromOffset(88, 30) })
  kit.fill(clear, "field")
  if square then kit.outline(clear) else kit.corner(clear, 15) end
  kit.text(clear, "Default", { Size = UDim2.fromScale(1, 1), TextXAlignment = Enum.TextXAlignment.Center }, true, kit.size - 1)
  hitbox(clear).Activated:Connect(B.safe("dahood.skins.default", function() UI.sfx("click", 0.6); choose(Config.get("dahood.skinGun"), nil) end))
  local area = frame(holder, { Name = "List", Size = UDim2.new(1, 0, 1, -38), Position = UDim2.fromOffset(0, 38), ClipsDescendants = true })
  local scroller = Instance.new("ScrollingFrame")
  scroller.BackgroundTransparency, scroller.BorderSizePixel = 1, 0
  scroller.Size, scroller.CanvasSize, scroller.AutomaticCanvasSize = UDim2.fromScale(1, 1), UDim2.new(), Enum.AutomaticSize.Y
  scroller.ScrollBarThickness, scroller.ScrollingDirection = 3, Enum.ScrollingDirection.Y
  kit.paint(scroller, "ScrollBarImageColor3", "accent")
  scroller.Parent = area
  local layout = Instance.new("UIListLayout"); layout.Padding = UDim.new(0, 2); layout.SortOrder = Enum.SortOrder.LayoutOrder; layout.Parent = scroller
  local function rebuild()
    for _, child in ipairs(scroller:GetChildren()) do if child:IsA("GuiObject") then child:Destroy() end end
    local gun = Config.get("dahood.skinGun")
    local query = string.lower(box.Text or "")
    local worn = DH.skins.chosen and DH.skins.chosen(gun)
    for index, skin in ipairs(DH.skins.list(gun)) do
      if query == "" or string.find(string.lower(skin.label), query, 1, true) or string.find(string.lower(skin.rarity), query, 1, true) then
        local row = frame(scroller, { Name = skin.name, Size = UDim2.new(1, -6, 0, square and 22 or 30), LayoutOrder = index })
        if not square then kit.corner(row, 8) end
        if skin.name == worn then kit.fill(row, "field") end
        frame(row, { Size = UDim2.fromOffset(3, square and 14 or 18), Position = UDim2.new(0, 6, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), BackgroundTransparency = 0,
          BackgroundColor3 = TINT[skin.rarity] or TINT.Common })
        kit.text(row, skin.label, { Position = UDim2.fromOffset(16, 0), Size = UDim2.new(1, -100, 1, 0), TextTruncate = Enum.TextTruncate.AtEnd }, false, kit.size)
        local tag = kit.text(row, skin.name == worn and "WORN" or string.upper(skin.rarity), { AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -8, 0, 0),
          Size = UDim2.new(0, 80, 1, 0), TextXAlignment = Enum.TextXAlignment.Right }, true, kit.size - 3)
        kit.paint(tag, "TextColor3", skin.name == worn and "accent" or "faint")
        local button = hitbox(row)
        button.MouseEnter:Connect(function()
          DH.skins.hover = skin.name
          kit.fill(row, "hover")
        end)
        button.MouseLeave:Connect(function()
          if DH.skins.hover == skin.name then DH.skins.hover = nil end
          if skin.name == worn then kit.fill(row, "field") else kit.clear(row) end
        end)
        button.Activated:Connect(B.safe("dahood.skins.pick", function() UI.sfx("click", 0.6); choose(gun, skin.name ~= worn and skin.name or nil) end))
      end
    end
  end
  box:GetPropertyChangedSignal("Text"):Connect(function() if scroller.Parent then rebuild() end end)
  DH.skins.changed:connect(function() if scroller.Parent then rebuild() end end)
  Config.on("dahood.skinGun", function() if scroller.Parent then rebuild() end end)
  rebuild()
end

local function page(hub)
  hub:page({ id = "skins", title = "Skins", icon = "swatch-book", build = function(tab)
    local guns = {}
    for _, gun in ipairs(DH.skins.guns) do guns[#guns + 1] = { gun, gun } end
    if #guns == 0 then guns[1] = { "[Double-Barrel SG]", "[Double-Barrel SG]" } end
    local list = tab:section({ title = "Skin changer", icon = "swatch-book", column = 1, weight = 7, desc = "Every skin in the game. Only you see it." })
    list:toggle({ id = "dahood.skinsOn", label = "Skins on", desc = "Puts the skins you pick on your guns.", default = true })
    list:dropdown({ id = "dahood.skinGun", label = "Gun", options = guns, default = "[Double-Barrel SG]" })
    list:custom({ height = 420, name = "Skins", build = picker })
    local look = tab:section({ title = "Preview", icon = "rotate-3d", column = 2, weight = 5 })
    look:custom({ height = 340, name = "Preview", build = preview })
    look:button({ label = "Clear every gun", text = "Clear", style = "danger", bindable = false, run = function() Config.set("dahood.skins", {}) end })
  end })
end

-- (the game's list of skins is waited for on a thread of its own: a game without it would hold every tab back)
DH.parts[#DH.parts + 1] = { id = "skins", start = function() task.spawn(function() load(true); B.try("dahood.skins.start", start) end) end, page = page }
end
do -- dahood_social.lua
-- ============================================================================
--  Da Hood     chat that can be read, and emotes kept by their ids
--
--  Read on the live game (2026-10-12, version 3267): chat here is Roblox's
--  TextChatService with its window switched off (ChatWindowConfiguration.Enabled
--  is false; the bar to type in is left on). So nothing anyone says is listed
--  anywhere. Two ways to read it, both this client's own: the window switched
--  back on, and a log of every message this client is sent, on screen and in
--  the tab. A whisper between two other players is never sent to a third
--  client: no script can show those.
--
--  An emote is an animation played on the player's own character, which the
--  game sends on to everyone like any other. One bought in the catalogue is an
--  asset that holds the animation; its id is turned into the animation's.
-- ============================================================================
local B = B or ...
local S, util, Motion, UI, Config, Window, Controls = B.S, B.util, B.Motion, B.UI, B.Config, B.Window, B.Controls
local DH = B.DaHood

local KEPT = 120             -- messages kept for the tab
local SHOWN = 8              -- lines of the log on screen at once
local SLOTS = 8              -- emotes that have a button (and so can have a key)

local social = { messages = {}, heard = 0, emotes = {}, playing = nil, SLOTS = SLOTS }
DH.social = social

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  local map = {}
  for id, default in pairs({ chatWindow = false, chatLog = false, chatStay = 12, emoteLoop = true, emoteStop = true, emoteSpeed = 100 }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  Config.define("dahood.emotes", {})
  O = Config.mirror(map)
  social.options = O
  -- (an emote's key is lit in the key list for as long as that emote plays)
  for index = 1, SLOTS do
    Config.actionState("dahood.emote" .. index, function() return social.playing ~= nil and social.playing.slot == index end)
  end

  -- ---------------------------------------------------------------- chat
  local onMessage = B.Signal.new()
  social.onMessage = onMessage
  local logFrame = UI.frame(api.gui, { Name = "ChatLog", AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, 14, 1, -150), Size = UDim2.fromOffset(460, 0),
    AutomaticSize = Enum.AutomaticSize.Y, Visible = false })
  UI.list(logFrame, "y", 2)
  local order = 0
  local function line(who, text, tint)
    if not O.chatLog then return end
    order += 1
    local row = UI.frame(logFrame, { Name = "Said", Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X, LayoutOrder = order,
      BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 0.5 })
    local label = UI.new("TextLabel", { Name = "Text", BackgroundTransparency = 1, Position = UDim2.fromOffset(7, 0), Size = UDim2.fromOffset(0, 18), AutomaticSize = Enum.AutomaticSize.X,
      FontFace = B.F.text500, TextSize = 12, RichText = false, Text = who .. ":  " .. text .. "   ", TextColor3 = tint or Color3.new(1, 1, 1),
      TextXAlignment = Enum.TextXAlignment.Left, Parent = row })
    local rows = {}
    for _, child in ipairs(logFrame:GetChildren()) do
      if child:IsA("Frame") then rows[#rows + 1] = child end
    end
    table.sort(rows, function(a, b) return a.LayoutOrder < b.LayoutOrder end)
    for index = 1, #rows - SHOWN do rows[index]:Destroy() end
    task.delay(math.max(O.chatStay, 2), function()
      if not (B.alive and row.Parent) then return end
      Motion.tween(0.5, Motion.ease.linear, function(p)
        if row.Parent then row.BackgroundTransparency = 0.5 + 0.5 * p; label.TextTransparency = p end
      end, function() if row.Parent then row:Destroy() end end)
    end)
  end
  local function heard(who, text, userId)
    if type(text) ~= "string" or text == "" then return end
    social.heard += 1
    local messages = social.messages
    messages[#messages + 1] = { who = who, text = text, at = os.clock(), userId = userId }
    if #messages > KEPT then table.remove(messages, 1) end
    line(who, text, userId == LP.UserId and Color3.fromRGB(170, 200, 255) or nil)
    onMessage:fire()
  end
  social.heardFrom = heard
  local chat = S.TextChatService
  local ok = pcall(function()
    B.connect(chat.MessageReceived, function(message)
      -- (the same message is told twice when it is one's own: once as it is sent, once as the server has it)
      if message.Status ~= Enum.TextChatMessageStatus.Success and message.Status ~= Enum.TextChatMessageStatus.Unknown then return end
      local source = message.TextSource
      local who = "System"
      local userId
      if source then
        userId = source.UserId
        local player = S.Players:GetPlayerByUserId(userId)
        who = player and player.DisplayName or source.Name
      end
      heard(who, message.Text, userId)
    end, "dahood.chat")
  end)
  social.listening = ok
  -- the window itself: the game switches it off, and this switches it back on for as long as it is asked for
  local windowWas
  local function windowConfig() return chat:FindFirstChildOfClass("ChatWindowConfiguration") end
  local function tendWindow()
    local config = windowConfig()
    if not config then return end
    if O.chatWindow then
      if windowWas == nil then windowWas = config.Enabled end
      if not config.Enabled then config.Enabled = true end
    elseif windowWas ~= nil then
      config.Enabled = windowWas
      windowWas = nil
    end
  end
  Motion.every(tendWindow, 1, "dahood.chatwindow")
  Config.on("dahood.chatWindow", function() task.defer(tendWindow) end)
  Config.on("dahood.chatLog", function(on) logFrame.Visible = on == true end, true)
  B.onUnload:connect(function()
    local config = windowConfig()
    if config and windowWas ~= nil then config.Enabled = windowWas end
  end)

  -- ---------------------------------------------------------------- emotes
  local resolved = {}
  -- the id of the animation an id stands for: its own, or the one inside a catalogue emote
  local function animationOf(id)
    id = tostring(id)
    if resolved[id] then return resolved[id] end
    local found
    if type(game.GetObjects) == "function" then
      local got, objects = pcall(function() return game:GetObjects("rbxassetid://" .. id) end)
      if got and type(objects) == "table" then
        for _, object in ipairs(objects) do
          local animation = object:IsA("Animation") and object or object:FindFirstChildWhichIsA("Animation", true)
          if animation and animation.AnimationId ~= "" then found = animation.AnimationId; break end
        end
      end
    end
    resolved[id] = found or ("rbxassetid://" .. id)
    return resolved[id]
  end
  local function stop()
    local playing = social.playing
    social.playing = nil
    if playing then
      pcall(function() playing.track:Stop(0.2) end)
      pcall(function() playing.track:Destroy() end)
    end
  end
  social.stop = stop
  -- play one by its place in the list, or by its id
  function social.play(which)
    local saved = Config.get("dahood.emotes")
    -- (a small whole number is a place in the list; anything else is an id. An empty place is
    -- nothing to play: found by the spec, it was taken for the id 5 and asked of the game.)
    local emote
    if type(which) == "number" and which >= 1 and which <= 64 and which % 1 == 0 then
      emote = saved[which]
    else
      emote = { id = which, name = tostring(which) }
    end
    if not emote then return false, "Nothing is saved there." end
    local id = string.match(tostring(emote.id), "%d+")
    if not id then return false, "That is not an id." end
    local humanoid = B.humanoid()
    local animator = humanoid and humanoid:FindFirstChildOfClass("Animator")
    if not animator or humanoid.Health <= 0 then return false, "You have no body just now." end
    -- the same one again stops it
    if social.playing and social.playing.id == id then stop(); return true end
    stop()
    local animation = Instance.new("Animation")
    animation.AnimationId = animationOf(id)
    local made, track = pcall(function() return animator:LoadAnimation(animation) end)
    if not made or not track then return false, "The game would not load that animation." end
    track.Priority = Enum.AnimationPriority.Action
    track.Looped = O.emoteLoop
    track:Play(0.15, 1, math.clamp(O.emoteSpeed / 100, 0.1, 4))
    social.playing = { id = id, track = track, name = emote.name, at = os.clock(), slot = type(which) == "number" and which or nil }
    return true
  end
  -- walking off ends it, if that is asked for; so does a new body
  B.connect(S.RunService.Heartbeat, function()
    local playing = social.playing
    if not playing then return end
    local humanoid = B.humanoid()
    if not humanoid or humanoid.Health <= 0 then stop(); return end
    if O.emoteStop and os.clock() - playing.at > 0.25 and humanoid.MoveDirection.Magnitude > 0.1 then stop(); return end
    if not O.emoteLoop and not playing.track.IsPlaying and os.clock() - playing.at > 0.4 then stop() end
  end, "dahood.emote")
  function social.save(name, id)
    id = string.match(tostring(id or ""), "%d+")
    if not id then return false, "Type the number of an emote or an animation." end
    name = string.gsub(tostring(name or ""), "^%s+", "")
    name = string.gsub(name, "%s+$", "")
    if name == "" then name = "Emote " .. id end
    local saved = table.clone(Config.get("dahood.emotes"))
    for _, emote in ipairs(saved) do
      if tostring(emote.id) == id then emote.name = name; Config.set("dahood.emotes", saved); return true end
    end
    saved[#saved + 1] = { name = string.sub(name, 1, 24), id = id }
    Config.set("dahood.emotes", saved)
    return true
  end
  function social.remove(index)
    local saved = table.clone(Config.get("dahood.emotes"))
    if not saved[index] then return end
    table.remove(saved, index)
    Config.set("dahood.emotes", saved)
  end
  B.onUnload:connect(stop)
end

local function page(hub)
  hub:page({ id = "social", title = "Social", icon = "message-circle", build = function(page)
    local social = B.DaHood.social
    local chat = page:section({ title = "Chat", icon = "message-circle", desc = "The game hides the chat window. These bring it back." })
    chat:toggle({ id = "dahood.chatWindow", label = "Chat window", desc = "Roblox's own window, switched back on.", default = false })
    chat:toggle({ id = "dahood.chatLog", label = "Chat log", desc = "Every message you are sent, bottom left.", default = false, children = function(sub)
      sub:slider({ id = "dahood.chatStay", label = "A line stays for", min = 3, max = 60, step = 1, default = 12, suffix = " s" })
    end })
    local last = chat:note({ icon = "info", text = "Whispers between other players never reach you: nothing can show those." })
    Motion.every(function()
      if not (last.frame.Parent and Window.anyOpen()) then return end
      local messages = social.messages
      if #messages == 0 then return end
      local lines = {}
      for index = math.max(1, #messages - 5), #messages do lines[#lines + 1] = messages[index].who .. ": " .. string.sub(messages[index].text, 1, 70) end
      last.set(table.concat(lines, "\n"))
    end, 2, "dahood.chat.last")

    local moves = page:section({ title = "Emotes", icon = "music", desc = "Save an emote or animation by its id, then play it." })
    local nameBox = moves:input({ label = "Name", placeholder = "Griddy", width = 170 })
    local idBox = moves:input({ label = "Emote or animation id", placeholder = "3360689775", width = 170 })
    moves:button({ label = "Save it", text = "Save", bindable = false, run = function()
      local ok, why = social.save(nameBox.box.Text, idBox.box.Text)
      if ok then
        nameBox.box.Text, idBox.box.Text = "", ""
        Window.toast({ title = "Emote saved", icon = "circle-check", tone = "ok", time = 2 })
      else
        Window.toast({ title = "Not saved", text = why, icon = "triangle-alert", tone = "warn" })
      end
    end })
    moves:toggle({ id = "dahood.emoteLoop", label = "Loop emote", desc = "Off: once through.", default = true })
    moves:toggle({ id = "dahood.emoteStop", label = "Stop on walk", default = true })
    moves:slider({ id = "dahood.emoteSpeed", label = "Speed", min = 10, max = 300, step = 5, default = 100, suffix = "%" })
    moves:button({ id = "dahood.emoteStopNow", label = "Stop emote", text = "Stop", run = function() social.stop() end })

    -- one button for each of the first few saved: a button can have a key
    local slots = page:section({ title = "Your emotes", icon = "star", desc = "Right-click one to give it a key." })
    local buttons = {}
    for index = 1, social.SLOTS do
      buttons[index] = slots:button({ id = "dahood.emote" .. index, label = "Empty", text = "Play", run = function()
        local ok, why = social.play(index)
        if not ok then Window.toast({ title = "Not played", text = why, icon = "triangle-alert", tone = "warn" }) end
      end })
    end
    slots:custom({ name = "Saved", build = function(frame)
      local list = UI.frame(frame, { Name = "List", Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y })
      UI.list(list, "y", 0)
      local function rebuild()
        for _, child in ipairs(list:GetChildren()) do
          if child:IsA("Frame") then child:Destroy() end
        end
        local saved = Config.get("dahood.emotes")
        for index, button in ipairs(buttons) do
          local emote = saved[index]
          local label = button.row and button.row.label
          if label then label.Text = emote and (index .. "  ·  " .. emote.name) or (index .. "  ·  empty") end
          -- (and what the list of keys calls it)
          local bindable = Controls.bindables["dahood.emote" .. index]
          if bindable then bindable.label = emote and ("Emote: " .. emote.name) or ("Emote " .. index) end
        end
        for index, emote in ipairs(saved) do
          local row = UI.frame(list, { Name = "Emote", Size = UDim2.new(1, 0, 0, 34), LayoutOrder = index })
          UI.text(row, emote.name, "label", "ink", { Position = UDim2.new(0, 14, 0.5, 0), AnchorPoint = Vector2.new(0, 0.5), TextSize = 13 })
          UI.text(row, tostring(emote.id), "mono", "faint", { Position = UDim2.new(1, -164, 0.5, 0), AnchorPoint = Vector2.new(1, 0.5), TextSize = 11 })
          local play = Controls.pillButton(row, "Play", nil, function() social.play(index) end)
          play.AnchorPoint, play.Position = Vector2.new(1, 0.5), UDim2.new(1, -96, 0.5, 0)
          local remove = Controls.pillButton(row, "Remove", nil, function() social.remove(index) end)
          remove.Name = "Remove"
          remove.AnchorPoint, remove.Position = Vector2.new(1, 0.5), UDim2.new(1, -14, 0.5, 0)
        end
      end
      Config.on("dahood.emotes", function() if list.Parent then rebuild() end end)
      rebuild()
    end })
  end })
end

DH.parts[#DH.parts + 1] = { id = "social", start = start, page = page }
end
do -- dahood_supply.lua
-- ============================================================================
--  Da Hood     supplies: armour, fire armour, a mask, food, ammo and reloads,
--              bought and used by themselves
--
--  A buy is a quick errand: the body is put over the pad, held there until the
--  server has it there, the pad is clicked, and the body goes back where it
--  stood. Only while nothing else here has the body (the ragebot buys its own,
--  the void and the cash round are left alone).
--
--  Measured on the live server (2026-10-21, version 3275, two accounts):
--    * A pad bought at clicks 0.13 s apart every time (10 of 10), 0.12 s apart
--      8 of 10, 0.10 s apart every other one: the server takes one about every
--      0.125 s. The old gap was 0.25 s: ammo now comes in at twice the rate.
--    * A mask bought is a "[Mask]" tool and BodyEffects.Mask holds which one.
--      In the hand and used, it is worn 0.25 s later (In-gameMask on the
--      body) and stays on when the tool goes back to the bag.
--    * A taco in the hand and used heals 11.8 a bite; a bite counts about
--      every 1.45 s (one 0.75 s after the last did nothing). The taco is kept.
--    * Armour: [Medium Armor] $1,126, [High-Medium Armor] $3,377 (130),
--      [Fire Armor] $4,501. Masks $28 to $68. Food $2 to $14.
-- ============================================================================
local B = B or ...
local S, Config, Window = B.S, B.Config, B.Window
local DH = B.DaHood

local CLICK_GAP = 0.135      -- s between clicks on one pad (the server takes one each 0.125 s)
local SETTLE = 0.05          -- s on top of the lag before the first click counts (arrived: 0.17 s and after bought)
local ANSWER = 0.7           -- s to wait for a purchase to show before clicking again
local BITE = 1.48            -- s between bites of food
local MASKS = { "Surgeon", "Ninja", "Hockey", "Skull", "Paintball", "Pumpkin", "Riot", "Breathing" }
local FOODS = { "Taco", "Pizza", "Hamburger", "Chicken", "Donut", "Lettuce", "Popcorn", "HotDog", "Meat", "IceCream", "Popsicle" }

local supply = { runs = 0, bought = 0, last = nil, busy = false }
DH.supply = supply

local function start()
  local api = DH.api
  local LP = B.LP
  local O
  local map = {}
  for id, default in pairs({ autoArmor2 = false, armorKind = "high", armorAt = 100, fireArmor = false, autoMask = false, maskKind = "Surgeon",
    autoHeal = false, healBelow = 70, healFood = "Taco", autoAmmo2 = false, ammoBoxes = 4, autoReload = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  O = Config.mirror(map)
  supply.options = O

  local failedAt = {}            -- item -> when it last could not be bought (waited out before trying again)
  local function effects() return api.effectsOf(B.character()) end
  local function value(name)
    local e = effects()
    local v = e and e:FindFirstChild(name)
    return v and v.Value
  end
  -- the body is ours to take to the shop: standing, loaded, and nothing else here moving it
  local function free()
    if supply.busy or api.moving() or DH.job then return false end
    local me, root, humanoid = B.character(), B.root(), B.humanoid()
    if not (me and root and humanoid) or humanoid.Health <= 0 or not me:FindFirstChild("FULLY_LOADED_CHAR") then return false end
    if api.flagOf(effects(), "K.O") or api.flagOf(effects(), "Dead") or root.Anchored then return false end
    local flight = B.Flight
    if flight and (flight.state == "flying" or flight.state == "landing" or flight.state == "charging") then return false end
    return true
  end
  supply.free = free
  local function padFor(item)
    if failedAt[item] and os.clock() - failedAt[item] < 8 then return nil end
    local root = B.root()
    local pad = DH.findPad(item, root and root.Position)
    if not pad then return nil end
    local price = tonumber(string.match(pad.Name, "%$(%d+)")) or math.huge
    if price > api.cash() then return nil end
    return pad
  end
  -- One errand: each { pad, done = fn, count = n } bought in turn, then back where the body stood.
  -- `count` clicks a pad that many times, one each CLICK_GAP (ammo); else it is clicked until done.
  local function errand(list, why)
    if #list == 0 or not free() then return false end
    if not api.arm() then return false end
    supply.busy, DH.errand = true, true
    supply.runs += 1
    supply.last = why
    api.setStatus("buying: " .. why)
    local ok = true
    for _, job in ipairs(list) do
      local head, detector = job.pad:FindFirstChild("Head"), job.pad:FindFirstChildOfClass("ClickDetector")
      if head and detector and B.alive then
        api.pin("spot", head.Position + Vector3.new(0, 4, 0))
        local arrived = os.clock()
        while B.alive and os.clock() - arrived < api.lag() + SETTLE do task.wait() end
        if job.count then
          for _ = 1, job.count do
            fireclickdetector(detector)
            supply.bought += 1
            local clicked = os.clock()
            while os.clock() - clicked < CLICK_GAP do task.wait() end
          end
          local waited = os.clock()
          while os.clock() - waited < ANSWER and not job.done() do task.wait() end
        else
          local got = false
          for _ = 1, 4 do
            fireclickdetector(detector)
            local clicked = os.clock()
            while os.clock() - clicked < ANSWER do
              if job.done() then got = true; break end
              task.wait()
            end
            if got then break end
          end
          if got then supply.bought += 1 else ok = false; failedAt[job.item] = os.clock() end
        end
      end
    end
    supply.busy, DH.errand = false, false
    api.release()
    return ok
  end
  supply.errand = errand

  -- ---------------------------------------------------------------- armour
  local function armourJob()
    local item = O.armorKind == "medium" and "[Medium Armor]" or "[High-Medium Armor]"
    local pad = padFor(item)
    if not pad then return nil end
    local before = api.armorOf(B.character())
    return { pad = pad, item = item, done = function() return api.armorOf(B.character()) > before end }
  end
  local function fireJob()
    local pad = padFor("[Fire Armor]")
    if not pad then return nil end
    local before = tonumber(value("FireArmor")) or 0
    return { pad = pad, item = "[Fire Armor]", done = function() return (tonumber(value("FireArmor")) or 0) > before end }
  end
  -- ---------------------------------------------------------------- the mask
  local function maskItem() return "[" .. tostring(O.maskKind) .. " Mask]" end
  local function maskTool()
    local me = B.character()
    return (me and me:FindFirstChild("[Mask]")) or LP.Backpack:FindFirstChild("[Mask]")
  end
  local function wearing() local me = B.character(); return me ~= nil and me:FindFirstChild("In-gameMask") ~= nil end
  -- The tool turns the mask on and off (measured: with one on, a use took it off and the next put
  -- the newly bought kind on). So a new kind is worn by two uses, an old one kept by none.
  local worn = { character = nil, kind = nil }
  local function use(tool, me)
    pcall(function() tool:Activate() end)
    task.wait(0.05)
    pcall(function() tool:Deactivate() end)
    local began, was = os.clock(), wearing()
    while os.clock() - began < 0.8 and wearing() == was do task.wait() end
    local _ = me
  end
  local function wear()
    local tool = maskTool()
    local me = B.character()
    if not (tool and me) or supply.wearing then return false end
    supply.wearing = true
    tool.Parent = me
    task.wait(0.12)
    if wearing() then use(tool, me) end              -- the old kind off first
    if not wearing() then use(tool, me) end
    if tool.Parent == me then tool.Parent = LP.Backpack end
    if wearing() then worn.character, worn.kind = me, value("Mask") end
    supply.wearing = false
    return wearing()
  end
  local function wornRight()
    return wearing() and worn.character == B.character() and worn.kind == maskItem()
  end
  local function maskJob()
    local item = maskItem()
    if value("Mask") == item and maskTool() then return nil end
    local pad = padFor(item)
    if not pad then return nil end
    return { pad = pad, item = item, done = function() return value("Mask") == item and maskTool() ~= nil end }
  end
  -- ---------------------------------------------------------------- food
  local function foodItem() return "[" .. tostring(O.healFood) .. "]" end
  local function foodTool()
    local me = B.character()
    local name = foodItem()
    return (me and me:FindFirstChild(name)) or LP.Backpack:FindFirstChild(name)
  end
  local function foodJob()
    if foodTool() then return nil end
    local item = foodItem()
    local pad = padFor(item)
    if not pad then return nil end
    return { pad = pad, item = item, done = function() return foodTool() ~= nil end }
  end
  local lastBite, eating = -math.huge, false
  local function bite()
    local tool = foodTool()
    local me = B.character()
    if not (tool and me) then return false end
    if tool.Parent ~= me then tool.Parent = me; eating = true; lastBite = os.clock() - BITE + 0.15; return true end
    if os.clock() - lastBite < BITE then return true end
    lastBite = os.clock()
    pcall(function() tool:Activate() end)
    task.delay(0.05, function() pcall(function() tool:Deactivate() end) end)
    return true
  end
  local function stopEating()
    if not eating then return end
    eating = false
    local tool = foodTool()
    if tool and tool.Parent == B.character() then tool.Parent = LP.Backpack end
  end
  -- ---------------------------------------------------------------- ammo
  local function ammoJobs()
    local jobs = {}
    local me = B.character()
    if not me then return jobs end
    for _, tool in ipairs(me:GetChildren()) do
      local gun = tool:IsA("Tool") and api.GUN[tool.Name]
      if gun and tool:FindFirstChild("MaxAmmo") and api.reserve(tool.Name) == 0 and api.numberOf(tool, "Ammo", 0) == 0 then
        local item = string.gsub(tool.Name, "%]$", " Ammo]")
        local pad = padFor(item)
        if pad then
          local name, before = tool.Name, api.reserve(tool.Name)
          jobs[#jobs + 1] = { pad = pad, item = item, count = math.clamp(O.ammoBoxes, 1, 20), done = function() return api.reserve(name) > before end }
        end
      end
    end
    return jobs
  end
  local reloadAt = -math.huge
  local function reload()
    local me = B.character()
    local remote = api.mainEvent()
    if not (me and remote) or api.flagOf(effects(), "Reload") or os.clock() - reloadAt < 1 then return end
    for _, tool in ipairs(me:GetChildren()) do
      if tool:IsA("Tool") and api.GUN[tool.Name] and api.numberOf(tool, "Ammo", 0) == 0 and api.reserve(tool.Name) > 0 then
        reloadAt = os.clock()
        remote:FireServer("Reload", tool)
        return
      end
    end
  end

  -- ---------------------------------------------------------------- the loop
  local spawnedFor = nil
  local function step()
    local me, humanoid = B.character(), B.humanoid()
    if not (me and humanoid) or humanoid.Health <= 0 then stopEating(); return end
    if O.autoReload and not api.moving() then reload() end
    if O.autoHeal and not api.moving() and humanoid.Health < O.healBelow and not api.flagOf(effects(), "K.O") then
      if not bite() then
        local job = foodJob()
        if job and free() then task.spawn(errand, { job }, "food") end
      end
    else
      stopEating()
    end
    if not free() then return end
    local list, why = {}, {}
    if O.autoArmor2 and api.armorOf(me) < O.armorAt then
      local job = armourJob()
      if job then list[#list + 1] = job; why[#why + 1] = "armour" end
    end
    if O.fireArmor and (tonumber(value("FireArmor")) or 0) <= 0 then
      local job = fireJob()
      if job then list[#list + 1] = job; why[#why + 1] = "fire armour" end
    end
    if O.autoMask and value("Mask") ~= maskItem() then
      local job = maskJob()
      if job then list[#list + 1] = job; why[#why + 1] = "mask" end
    end
    if O.autoAmmo2 then
      for _, job in ipairs(ammoJobs()) do list[#list + 1] = job end
      if #list > #why then why[#why + 1] = "ammo" end
    end
    if #list > 0 then
      task.spawn(function()
        errand(list, table.concat(why, ", "))
        if O.autoMask and maskTool() and not wornRight() then wear() end
      end)
    elseif O.autoMask and maskTool() and value("Mask") == maskItem() and not wornRight() and not supply.wearing then
      -- (a body worn by hand, or a new life: wearing what it should, or put on)
      if wearing() and worn.character ~= me then worn.character, worn.kind = me, value("Mask") end
      if not wornRight() then task.spawn(wear) end
    end
    local _ = spawnedFor
  end
  B.Motion.every(step, 10, "dahood.supply")
  Config.on("dahood.autoMask", function(on) if on then spawnedFor = nil end end)
  Config.on("dahood.maskKind", function() spawnedFor = nil end)
end

local function loadout(page)
  local Motion = B.Motion
  local box = page:section({ title = "Supplies", icon = "package", desc = "Bought and used by themselves, while the ragebot is off." })
  box:toggle({ id = "dahood.autoArmor2", label = "Auto armour", desc = "Buys armour the moment you lose some.", default = false, children = function(sub)
    sub:segmented({ id = "dahood.armorKind", label = "Armour", options = { { "high", "High" }, { "medium", "Medium" } }, default = "high", width = 160 })
    sub:slider({ id = "dahood.armorAt", label = "Below", desc = "Buys when armour is under this.", min = 1, max = 130, step = 1, default = 100 })
  end })
  box:toggle({ id = "dahood.fireArmor", label = "Auto fire armour", desc = "Keeps fire armour on.", default = false })
  local masks = {}
  for _, kind in ipairs(MASKS) do masks[#masks + 1] = { kind, kind } end
  box:toggle({ id = "dahood.autoMask", label = "Auto mask", desc = "Buys one and wears it, every life.", default = false, children = function(sub)
    sub:dropdown({ id = "dahood.maskKind", label = "Mask", options = masks, default = "Surgeon" })
  end })
  local foods = {}
  for _, kind in ipairs(FOODS) do foods[#foods + 1] = { kind, kind } end
  box:toggle({ id = "dahood.autoHeal", label = "Auto heal", desc = "Eats until you are back up.", default = false, children = function(sub)
    sub:slider({ id = "dahood.healBelow", label = "Below", min = 10, max = 99, step = 1, default = 70, suffix = " hp" })
    sub:dropdown({ id = "dahood.healFood", label = "Food", options = foods, default = "Taco" })
  end })
  box:toggle({ id = "dahood.autoAmmo2", label = "Auto ammo", desc = "Buys ammo for the gun in your hand when it runs dry.", default = false, children = function(sub)
    sub:slider({ id = "dahood.ammoBoxes", label = "Boxes", min = 1, max = 20, step = 1, default = 4 })
  end })
  box:toggle({ id = "dahood.autoReload", label = "Auto reload", desc = "Reloads an empty gun.", default = false })
  local line = box:note({ icon = "info", text = "" })
  Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local s = DH.supply
    line.set(s.runs == 0 and "Nothing bought yet." or string.format("%d runs to the shop, %d bought. Last: %s.", s.runs, s.bought, s.last or "-"))
  end, 2, "dahood.supply.line")
end

DH.parts[#DH.parts + 1] = { id = "supply", start = start, loadout = loadout }
end
do -- dahood_who.lua
-- ============================================================================
--  Da Hood     who the ragebot hunts, besides the marked
--
--  Everyone (but the players you spare), anyone who comes near where you
--  stood, and whoever hurts you. The game names that one itself. Measured on
--  2026-10-14 with two accounts: a shot from one at the other set the victim's
--  BodyEffects.LastDamager to the shooter's character 26 ms after the victim's
--  health dropped (the victim's own client sees it). Every player's
--  LastGunShotAt (the server's own time of their last shot) and LastFiredGun
--  attributes reach every client 0.04 s after the shot, and BodyEffects.MousePos
--  is where each player's mouse points. Health comes back by itself, about one
--  a second.
--
--  Fight back by itself: hurt with the ragebot off, it switches the ragebot on,
--  kills whoever did it, and switches it off again (the body goes back where it
--  stood). It only ever switches off what it switched on.
--
--  Whoever aims at you (2026-10-14 evening): a gun out and the mouse held on this
--  body is taken as a hit, before there is one: hunted, and fought back.
-- ============================================================================
local B = B or ...
local S, Config, Window, Motion = B.S, B.Config, B.Window, B.Motion
local DH = B.DaHood

local LOOK_FOR = 0.4         -- s after a loss of health in which the game's word on who did it is waited for
local GIVE_UP = 90           -- s a fight it started by itself is kept up without a kill before it stops
local FLOOR = 1.5            -- health at or under which a body is taken to be knocked (the game drops it to 1)
local AIM_NEAR = 6           -- studs from this body that someone's mouse point has to be (as the ESP's AIMING AT YOU)
local AIM_HOLD = 0.3         -- s it has to stay there: a mouse swept across the body is not aiming at it

local who = { grudges = {}, hurtBy = 0, fought = 0, aimedBy = 0, auto = nil }
DH.who = who

local function start()
  local api = DH.api
  local LP = B.LP
  local Players = S.Players
  local map = {}
  for id, default in pairs({ everyone = false, zone = 0, revenge = false, revengeFor = 120, bodyguard = false, bodyguardKills = 1, aimed = false }) do
    Config.define("dahood." .. id, default)
    map[id] = "dahood." .. id
  end
  local O = Config.mirror(map)
  who.options = O

  local function friend(player)
    local roster = B.Roster
    local entry = roster and roster.byPlayer[player]
    return entry ~= nil and roster.isFriend(entry)
  end
  local function grudge(player, now)
    local untilAt = who.grudges[player.UserId]
    return untilAt ~= nil and now < untilAt
  end
  -- within the zone round where the body stood when the ragebot was switched on
  local function near(player)
    if O.zone <= 0 then return false end
    local home = api.home()
    local character = player.Character
    local torso = character and api.torsoOf(character)
    return home ~= nil and torso ~= nil and (torso.Position - home.Position).Magnitude <= O.zone
  end
  table.insert(DH.spares, friend)
  table.insert(DH.wants, function(player, now) return O.everyone or grudge(player, now) or near(player) end)
  -- (whoever has hurt this body lately goes before anyone else that can be shot as quickly)
  table.insert(DH.weighs, function(player, _, now) return grudge(player, now) and 1.5 or 0 end)
  DH.huntingAlso = DH.huntingAlso or {}
  table.insert(DH.huntingAlso, function() return O.everyone or O.zone > 0 or next(who.grudges) ~= nil end)

  -- ---------------------------------------------------------------- fighting back
  local auto                      -- the fight this started by itself: { at, players = { [userId] = kills it wants } , kills = {} }
  local function stopAuto(why)
    if not auto then return end
    auto = nil
    who.auto = nil
    if DH.on then Config.set("dahood.on", false, true) end
    if why then Window.toast({ title = "Fight over", text = why, icon = "swords", time = 3 }) end
  end
  local function fightBack(player, now)
    if auto then
      auto.players[player.UserId] = auto.players[player.UserId] or 0
      return
    end
    if not O.bodyguard or DH.on or DH.hiding or DH.farming then return end
    -- (knocked or dead: there is no body to fight with yet; it starts once there is. A knocked body's
    -- health is at the floor before the flag that says so comes: 0.04 to 0.10 s, measured)
    local me, humanoid = B.character(), B.humanoid()
    local effects = api.effectsOf(me)
    if not (me and humanoid and humanoid.Health > FLOOR and effects and me:FindFirstChild("FULLY_LOADED_CHAR")) or api.flagOf(effects, "K.O") or api.flagOf(effects, "Dead") then
      who.waiting = player
      return
    end
    auto = { at = now, players = { [player.UserId] = 0 } }
    Config.set("dahood.on", true, true)
    if not DH.on then
      -- (no body to hunt with yet: it is tried again once there is one)
      auto, who.waiting = nil, player
      return
    end
    who.auto = auto
    who.fought += 1
    Window.toast({ title = "Fighting back", text = player.DisplayName .. " hurt you.", icon = "swords", tone = "warn", time = 3 })
  end
  local function hurtBy(player, now)
    if not player or player == LP or friend(player) then return end
    local fresh = not grudge(player, now)
    who.grudges[player.UserId] = now + O.revengeFor
    who.last, who.lastAt = player, now
    if fresh then
      who.hurtBy += 1
      DH.onTargets:fire()
    end
    fightBack(player, now)
  end
  local function attackerOf(model)
    if typeof(model) ~= "Instance" then return nil end
    local player = Players:GetPlayerFromCharacter(model)
    -- (a body its player has since left behind: by its name)
    if not player then
      local named = Players:FindFirstChild(model.Name)
      if named and named:IsA("Player") then player = named end
    end
    if player == LP then return nil end
    return player
  end
  local lastLife, lossAt
  local aiming = setmetatable({}, { __mode = "k" })   -- per player: since when its mouse has been on this body
  B.connect(S.RunService.Heartbeat, function()
    local now = os.clock()
    -- someone holding a gun with the mouse on this body: (not while the body is away: in the void
    -- nobody aims at it, and where it strikes, it is already there to kill)
    if O.aimed and not api.moving() then
      local root = B.root()
      for _, player in ipairs(Players:GetPlayers()) do
        local character = player ~= LP and root and player.Character
        local effects = character and api.effectsOf(character)
        local mouse = effects and effects:FindFirstChild("MousePos")
        local tool = character and character:FindFirstChildOfClass("Tool")
        -- (up: a knocked or dead body keeps its gun and its mouse point where they were)
        if mouse and tool and tool:FindFirstChild("Ammo") and typeof(mouse.Value) == "Vector3" and (mouse.Value - root.Position).Magnitude <= AIM_NEAR
          and not friend(player) and DH.stateOf(player) == "up" then
          aiming[player] = aiming[player] or now
          if now - aiming[player] >= AIM_HOLD then
            aiming[player] = now
            if not grudge(player, now) then who.aimedBy += 1 end
            hurtBy(player, now)
          end
        else
          aiming[player] = nil
        end
      end
    end
    for id, untilAt in pairs(who.grudges) do
      if now >= untilAt then who.grudges[id] = nil end
    end
    -- the fight it started: over once every one of them has died as often as asked, or has gone
    if auto then
      local done = true
      for userId, kills in pairs(auto.players) do
        local player = Players:GetPlayerByUserId(userId)
        if player and kills < O.bodyguardKills then done = false end
      end
      if done then stopAuto("Everyone who hurt you is dead.")
      elseif now - (auto.lastKill or auto.at) > GIVE_UP then stopAuto("Nobody to hit for a minute and a half.") end
    end
    if who.waiting then
      local me, humanoid = B.character(), B.humanoid()
      local effects = api.effectsOf(me)
      if me and humanoid and humanoid.Health > FLOOR and me:FindFirstChild("FULLY_LOADED_CHAR") and not api.flagOf(effects, "K.O") and not api.flagOf(effects, "Dead") then
        local player = who.waiting
        who.waiting = nil
        if player.Parent then fightBack(player, now) end
      end
    end
    -- (health is followed all the time, so a hit the moment either is switched on is not missed)
    local me = B.character()
    local humanoid = me and me:FindFirstChildOfClass("Humanoid")
    local effects = api.effectsOf(me)
    if not (humanoid and effects) then lastLife, lossAt = nil, nil; return end
    local life = math.max(humanoid.Health, 0) + api.armorOf(me)
    if lastLife and life < lastLife - 0.5 then lossAt = now end
    lastLife = life
    if not (O.revenge or O.bodyguard) then lossAt = nil; return end
    if lossAt then
      local named = effects:FindFirstChild("LastDamager")
      local attacker = named and attackerOf(named.Value)
      if attacker then
        hurtBy(attacker, now)
        lossAt = nil
      elseif now - lossAt > LOOK_FOR then
        lossAt = nil
      end
    end
  end, "dahood.who")
  -- its kills of those it is fighting (with Stomp off, its knocks: there will be no kill to count)
  DH.onKill:connect(function(player)
    if auto and player and auto.players[player.UserId] and api.O.stomp then
      auto.players[player.UserId] += 1
      auto.lastKill = os.clock()
    end
  end)
  DH.onKnocked:connect(function(player)
    if auto and player and auto.players[player.UserId] and not api.O.stomp then
      auto.players[player.UserId] += 1
      auto.lastKill = os.clock()
    end
  end)
  -- switched off by hand: whatever it was doing by itself is over, and stays over
  Config.on("dahood.on", function(on) if not on and auto then auto, who.auto = nil, nil end end)
  Config.on("dahood.bodyguard", function(on) if not on then stopAuto(nil) end end)
  B.connect(Players.PlayerRemoving, function(player) who.grudges[player.UserId] = nil end, "dahood.who.left")
end

local function ragebot(page)
  local hunt = page:section({ title = "Targets", icon = "users", desc = "The marked always. These add more; Spare keeps a player out." })
  hunt:toggle({ id = "dahood.everyone", label = "Everyone", desc = "Every player but the ones you spare.", default = false })
  hunt:slider({ id = "dahood.zone", label = "Zone", desc = "Within this of where you stood. 0: off.", min = 0, max = 5000, step = 10, default = 0, curve = 2, suffix = " st" })
  hunt:toggle({ id = "dahood.revenge", label = "Revenge", desc = "The game says who it was.", default = false, children = function(sub)
    sub:slider({ id = "dahood.revengeFor", label = "Revenge time", desc = "From their last hit.", min = 30, max = 3600, step = 10, default = 120, curve = 2, suffix = " s" })
  end })
  hunt:toggle({ id = "dahood.aimed", label = "Aimed at me", desc = "Gun out, mouse on you: taken as a hit, before there is one.", default = false })
  hunt:toggle({ id = "dahood.bodyguard", label = "Fight back", desc = "Hit while the ragebot is off: it starts, kills them, and stops.", default = false, children = function(sub)
    sub:slider({ id = "dahood.bodyguardKills", label = "Grudge kills", desc = "Knocks, with Stomp off.", min = 1, max = 10, step = 1, default = 1 })
  end })
  local line = hunt:note({ icon = "activity", text = "" })
  B.Motion.every(function()
    if not (line.frame.Parent and Window.anyOpen()) then return end
    local w = B.DaHood.who
    local now, held = os.clock(), {}
    for userId, untilAt in pairs(w.grudges) do
      local player = S.Players:GetPlayerByUserId(userId)
      if player and untilAt > now then held[#held + 1] = player.DisplayName .. string.format(" (%ds)", math.ceil(untilAt - now)) end
    end
    if #held == 0 and w.hurtBy == 0 then line.set("Nobody has hurt you yet.")
    else line.set((#held > 0 and ("Hunting for hurting you: " .. table.concat(held, ", ") .. ".") or "Nobody is held to account now.")
      .. string.format("    Fought back %d time%s.", w.fought, w.fought == 1 and "" or "s")) end
  end, 2, "dahood.who.line")
  local _ = Motion
end

DH.parts[#DH.parts + 1] = { id = "who", start = start, ragebot = ragebot }
end
do -- 90_boot.lua
-- ============================================================================
--  90 boot     order of operations
-- ============================================================================
local S, util, Motion, Theme, T, UI, Config, Window, Assets = B.S, B.util, B.Motion, B.Theme, B.T, B.UI, B.Config, B.Window, B.Assets
local UIS = S.UserInputService

local function boot()
  if not game:IsLoaded() then game.Loaded:Wait() end
  Config.init()
  Assets.init()
  if B.Prefs then B.Prefs.define() end
  if B.Prefs then B.Prefs.apply() end
  if B.Unnamed then B.Unnamed.start() end
  if B.Novoline then B.Novoline.start() end
  Window.build()
  -- the game is looked up first: its module can ask for Universal not to be loaded at all
  if B.Registry then B.try("registry.pick", B.Registry.pick) end
  for _, register in ipairs(B.pages or {}) do
    local name = B.universalPages and B.universalPages[register]
    if not name or not B.Registry or B.Registry.keeps(name) then B.try("pages", register) end
  end
  if B.Registry then B.try("registry", B.Registry.resolve) end
  Window.rebuildNav()
  Config.listen()

  -- the menu key, the palette, and the panic key
  B.connect(UIS.InputBegan, function(input)
    if Config.capturing then return end
    if input.UserInputType ~= Enum.UserInputType.Keyboard then return end
    local name = input.KeyCode.Name
    if UIS:GetFocusedTextBox() then return end
    if name == Config.get("app.key.menu") then
      if B.Loader and B.Loader.active then return end
      Window.toggleActive()
    elseif name == Config.get("app.key.panic") then
      B.unload()
    elseif input.KeyCode == Enum.KeyCode.K and (UIS:IsKeyDown(Enum.KeyCode.LeftControl) or UIS:IsKeyDown(Enum.KeyCode.RightControl)) and Window.open then
      Window.palette()
    end
  end, "boot.keys")

  local function reveal()
    Window.showActive(true)
    if B.Hud then B.try("hud", B.Hud.start) end
    if B.Unnamed then B.try("unnamed.watermark", B.Unnamed.watermark) end
    if B.Novoline and B.Novoline.active() then B.try("novoline.island", B.Novoline.island) end
    if B.Keys then B.try("keys.hud", B.Keys.hud) end
    if B.Registry then B.try("registry.announce", B.Registry.announce) end
  end
  -- the other tabs are assembled a card per frame in the background: under the intro when there
  -- is one, so the hub is complete the moment it appears
  task.delay(0.7, function() if B.alive then Window.prebuild() end end)
  -- The first launch on this machine: which look to open in is asked once, when the intro is done
  -- (not when an intro is forced off for one launch: that is a test or a reload)
  local function begin()
    if Config.firstRun and B.Picker and B.genv.BASED_INTRO ~= "off" and not B.genv.BASED_NO_PICKER then
      B.Picker.show(function(look)
        if look then Config.set("app.gui", look) end
        B.try("reveal", reveal)
      end)
    else
      reveal()
    end
  end
  if B.Loader then B.Loader.run(begin) else begin() end
  B.bootMs = math.floor((os.clock() - B.bootClock) * 1000)
end

task.spawn(function()
  local ok, err = xpcall(boot, function(e) return tostring(e) .. "\n" .. debug.traceback("", 2) end)
  if not ok then
    B.fault("boot", err)
    pcall(function()
      S.StarterGui:SetCore("SendNotification", { Title = "BASED Hub", Text = "Failed to start: " .. string.sub(tostring(err), 1, 120), Duration = 8 })
    end)
  end
end)
end
return B
